-- Mars's Expanded Kanto
-- Main mod script: gameplay data, quests, compatibility fixes, and custom
-- battle effects remain in one replacement main.lua for easy installation.
-- Comments describe current behavior instead of carrying a patch-history log.

return function(mod)

  mod.log:info("Mars Expanded Kanto v1.0.0 loaded")

  ---------------------------------------------------------------------------
  -- GOLD / SILVER SPRITES COMPATIBILITY
  --
  -- Gold_Silver_Sprites 1.4.3 uses SpriteRenderer.obpImage() for special
  -- overworld sprites such as Pewter Pokemon Center's singing Jigglypuff.
  -- The user's current Gen1Recomp build predates the engine export of that
  -- helper, even though the rest of the SpriteRenderer API is compatible.
  -- Supply the same helper contract used by newer Gen1Recomp builds instead
  -- of replacing/hiding the Jigglypuff or disabling the sprite pack.
  ---------------------------------------------------------------------------
  do
    local SpriteRenderer = require("src.render.SpriteRenderer")

    if type(SpriteRenderer.obpImage) ~= "function" then
      local Assets = require("src.render.Assets")
      local marsObpCache = {}

      local function component(color, i)
        local value = color and color[i] or 0
        if type(value) ~= "number" then value = 0 end
        -- Palette entries in Gen1Recomp are byte RGB values.
        if value > 1 then value = value / 255 end
        if value < 0 then value = 0 elseif value > 1 then value = 1 end
        return value
      end

      SpriteRenderer.obpImage = function(path, colors, group)
        if type(path) ~= "string" or type(colors) ~= "table" then
          return type(path) == "string" and Assets.image(path) or nil
        end

        local key = path .. "#mars-obp#" .. tostring(group or "default")
        if marsObpCache[key] then return marsObpCache[key] end

        local image
        if love.image and love.image.newImageData then
          local imageData = Assets.imageData(path)
          imageData:mapPixel(function(_, _, r, g, b, a)
            if a == 0 then return r, g, b, a end

            -- OBJ palette color 0 is transparent on Game Boy hardware.
            if r > 0.83 then return r, g, b, 0 end

            local color
            if r > 0.5 then
              color = colors[2]
            elseif r > 0.17 then
              color = colors[3]
            else
              color = colors[4]
            end

            return component(color, 1), component(color, 2), component(color, 3), a
          end)
          image = love.graphics.newImage(imageData)
        else
          image = Assets.image(path)
        end

        marsObpCache[key] = image
        return image
      end

      mod.log:info(
        "installed SpriteRenderer.obpImage compatibility for Gold_Silver_Sprites 1.4.3"
      )
    end
  end

  ---------------------------------------------------------------------------
  -- HELPERS
  ---------------------------------------------------------------------------

  local function copyAnimation(newMoveId, candidateAnimations)
    for _, sourceId in ipairs(candidateAnimations) do
      local animation = mod.content.battle_anims:get(sourceId)

      if animation then
        mod.content.battle_anims:register(newMoveId, animation)
        mod.log:info("Copied animation %s to %s", sourceId, newMoveId)
        return
      end
    end

    mod.log:warn("Could not find an animation for %s", newMoveId)
  end

  local function appendMessages(destination, source)
    for _, message in ipairs(source or {}) do
      destination[#destination + 1] = message
    end
  end

  local function patchLearnset(speciesId, level, moveId)
    mod.content.pokemon:patch(speciesId, {
      learnset = {
        __append = {
          {
            level = level,
            move = moveId,
          },
        },
      },
    })
  end

  local function patchTMHM(speciesId, moveIds)
    if type(moveIds) == "string" then
      moveIds = { moveIds }
    end

    mod.content.pokemon:patch(speciesId, {
      tmhm = {
        __append = moveIds,
      },
    })
  end

  local function copyTable(source)
    local result = {}
    for key, value in pairs(source or {}) do
      result[key] = value
    end
    return result
  end

  local function typeMultiplier(data, attackType, defenderTypes)
    local multiplier = 10
    local chart = data and data.type_chart
    local matchups = chart and chart.matchups or {}

    for _, matchup in ipairs(matchups) do
      if matchup.attacker == attackType then
        for _, defenderType in ipairs(defenderTypes or {}) do
          if matchup.defender == defenderType then
            multiplier = math.floor(multiplier * matchup.multiplier / 10)
            break
          end
        end
      end
    end

    return multiplier
  end

  local function currentHP(battler)
    return battler and battler.mon and (battler.mon.hp or 0) or 0
  end

  local function maxHP(battler)
    return battler and battler.mon and (battler.mon.stats.hp or 1) or 1
  end


