  do
    local NPC = require("src.world.NPC")

    -- Keep the registry outside the one-time wrapper so dev hot reloads and
    -- later updates can replace the conditions without stacking draw wrappers.
    NPC._marsQuestMarkerRegistry = marsQuestMarkerRegistry

    if not NPC._marsQuestMarkerDrawPatch then
      NPC._marsQuestMarkerDrawPatch = true

      local Game = require("src.core.Game")
      local Assets = require("src.render.Assets")
      local Font = require("src.render.Font")
      local baseDraw = NPC.draw

      local questMarkerImage = nil
      local questMarkerQuad = nil
      local questMarkerPath = nil

      local function npcMapId(npc)
        -- Most ordinary overworld NPCs use string ids such as
        -- "PEWTER_CITY_obj_3", but some special actors use a non-string id.
        -- Never call string methods on those actors; they simply cannot have
        -- one of this mod's map-scoped quest markers.
        local id = npc and npc.id
        if type(id) ~= "string" then
          return nil
        end
        return id:match("^(.*)_obj_%d+$")
      end

      local function markerMatches(npc, marker)
        if marker.objectIndex
           and npc.def
           and npc.def.index ~= marker.objectIndex
        then
          return false
        end

        if marker.objectName
           and npc.def
           and npc.def.name ~= marker.objectName
        then
          return false
        end

        if marker.textId
           and npc.def
           and npc.def.text ~= marker.textId
        then
          return false
        end

        return true
      end

      local function markerIsActive(npc)
        local registry = NPC._marsQuestMarkerRegistry
        local mapId = npcMapId(npc)
        local list = registry and mapId and registry[mapId]

        if not list then return false end

        local save = Game.save
        local flags = save and save.flags or {}

        for _, marker in ipairs(list) do
          if markerMatches(npc, marker) then
            if marker.active then
              local ok, active = pcall(marker.active, save, npc)
              if ok and active then
                return true
              end
            elseif not marker.completeFlag
               or not flags[marker.completeFlag]
            then
              return true
            end
          end
        end

        return false
      end

      -- Same OBP0 remap the engine uses for its regular emotion bubbles.
      -- This keeps the `!` bubble's inside white instead of medium gray.
      local function loadQuestMarkerBubble()
        local field = Game.data and Game.data.field
        local bubble = field and field.emotionBubbles
        local rect = bubble
          and bubble.bubbles
          and bubble.bubbles[1]

        if not bubble or not bubble.path or not rect then
          return nil, nil
        end

        if questMarkerImage
           and questMarkerQuad
           and questMarkerPath == bubble.path
        then
          return questMarkerImage, questMarkerQuad
        end

        local ok, img = pcall(function()
          if love.image and love.image.newImageData then
            local id = Assets.imageData(bubble.path)

            id:mapPixel(function(_, _, r, _, _, a)
              local v = 0

              if r > 0.5 then
                v = 1
              elseif r > 0.17 then
                v = 170 / 255
              end

              return v, v, v, a
            end)

            return love.graphics.newImage(id)
          end

          return love.graphics.newImage(Assets.resolve(bubble.path))
        end)

        if not ok or not img then
          return nil, nil
        end

        questMarkerImage = img
        questMarkerPath = bubble.path
        questMarkerQuad = love.graphics.newQuad(
          rect.x,
          rect.y,
          rect.w,
          rect.h,
          img:getDimensions()
        )

        return questMarkerImage, questMarkerQuad
      end

      local function drawQuestMarker(npc, camX, camY)
        -- If this exact NPC is currently displaying a real scripted emote,
        -- let the native bubble own the space for that short moment.
        local ow = Game.overworld
        if ow
           and ow.emote
           and ow.emote.npc == npc
        then
          return
        end

        local ex = npc.px - camX + 4
        local ey = npc.py - camY - 14
        local img, quad = loadQuestMarkerBubble()

        if img and quad then
          love.graphics.setColor(1, 1, 1, 1)
          love.graphics.draw(img, quad, ex, ey)
          return
        end

        -- Safe fallback if a version/asset pack does not expose emotes.png.
        love.graphics.setColor(1, 1, 1, 1)
        love.graphics.rectangle("fill", ex, ey, 10, 12)
        love.graphics.setColor(0, 0, 0, 1)
        love.graphics.rectangle(
          "line",
          ex + 0.5,
          ey + 0.5,
          10,
          12
        )
        Font.draw("!", ex + 1, ey + 2)
        love.graphics.setColor(1, 1, 1, 1)
      end

      -- Some maps contain special overworld Pokemon actors rather than
      -- ordinary walking NPC sheets.  Pewter's singing JIGGLYPUFF is the first
      -- one encountered in a normal playthrough, and a sprite/render wrapper
      -- from any enabled mod can fail on that actor during the first frame.
      -- Keep one bad actor from killing the whole overworld, and log enough
      -- identity to make the real offending sprite obvious if it happens.
      local drawFailureLogged = {}

      local function drawFailureKey(npc, kind)
        return tostring(kind) .. ":" .. tostring(npc and npc.id or npc)
      end

      local function logDrawFailureOnce(npc, kind, err)
        local key = drawFailureKey(npc, kind)
        if drawFailureLogged[key] then return end
        drawFailureLogged[key] = true

        local def = npc and npc.def or nil
        mod.log:warn(
          "NPC " .. tostring(kind)
            .. " failure: id=" .. tostring(npc and npc.id)
            .. " map=" .. tostring(npcMapId(npc))
            .. " index=" .. tostring(def and def.index)
            .. " name=" .. tostring(def and def.name)
            .. " sprite=" .. tostring(def and def.sprite)
            .. " error=" .. tostring(err)
        )
      end

      local function safeBaseDraw(npc, camX, camY)
        local ok, err = xpcall(
          function()
            baseDraw(npc, camX, camY)
          end,
          function(e)
            if debug and debug.traceback then
              return debug.traceback(tostring(e), 2)
            end
            return tostring(e)
          end
        )

        if not ok then
          logDrawFailureOnce(npc, "base draw", err)
          return false
        end
        return true
      end

      NPC.draw = function(self, camX, camY)
        local mapId = npcMapId(self)
        local isInvisibleMarkerAnchor =
          self
          and self.def
          and self.def.name == "MARS_ROCKET_REMNANT_PANEL_MARKER"

        if not isInvisibleMarkerAnchor then
          if not safeBaseDraw(self, camX, camY) then
            -- Do not run marker drawing against an actor whose native draw
            -- already failed; leave that actor invisible for this frame.
            return
          end
        end

        -- Pewter Center has no Expanded-Kanto quest markers.  Bypass every
        -- marker-specific render path there so its special JIGGLYPUFF receives
        -- only the engine/other-mod base draw above.
        if mapId == "PEWTER_POKECENTER" then
          return
        end

        local ok, err = xpcall(
          function()
            if markerIsActive(self) then
              drawQuestMarker(self, camX, camY)
            end
          end,
          function(e)
            if debug and debug.traceback then
              return debug.traceback(tostring(e), 2)
            end
            return tostring(e)
          end
        )

        if not ok then
          logDrawFailureOnce(self, "quest-marker draw", err)
        end
      end
    end
  end


  end)()

  ---------------------------------------------------------------------------
  -- CUSTOM MOVE EFFECTS AND BATTLE HOOKS
  ---------------------------------------------------------------------------
  ;(function()
  -- Gen 1 does not carry a built-in contact flag, so Conduct uses an
  -- explicit list of moves that physically strike the opponent.
  local CONTACT_MOVES = {
    POUND = true, KARATE_CHOP = true, DOUBLESLAP = true,
    COMET_PUNCH = true, MEGA_PUNCH = true, FIRE_PUNCH = true,
    ICE_PUNCH = true, THUNDERPUNCH = true, SCRATCH = true,
    VICEGRIP = true, GUILLOTINE = true, CUT = true,
    WING_ATTACK = true, FLY = true, BIND = true, SLAM = true,
    VINE_WHIP = true, STOMP = true, DOUBLE_KICK = true,
    MEGA_KICK = true, JUMP_KICK = true, ROLLING_KICK = true,
    HEADBUTT = true, HORN_ATTACK = true, FURY_ATTACK = true,
    HORN_DRILL = true, TACKLE = true, BODY_SLAM = true,
    WRAP = true, TAKE_DOWN = true, THRASH = true,
    DOUBLE_EDGE = true, BITE = true, PECK = true,
    DRILL_PECK = true, SUBMISSION = true, LOW_KICK = true,
    COUNTER = true, SEISMIC_TOSS = true, STRENGTH = true,
    QUICK_ATTACK = true, RAGE = true, DIG = true, LICK = true,
    WATERFALL = true, CLAMP = true, SKULL_BASH = true,
    CONSTRICT = true, HI_JUMP_KICK = true, LEECH_LIFE = true,
    SKY_ATTACK = true, DIZZY_PUNCH = true, CRABHAMMER = true,
    FURY_SWIPES = true, HYPER_FANG = true, SUPER_FANG = true,
    SLASH = true, STRUGGLE = true,

    -- Moves added by this mod.
    MACH_PUNCH = true, FLAME_CLAW = true, PHOENIX_STRIKE = true,
    PALEOZOIC_SLASH = true, JURASSIC_SLAM = true,
    HAYMAKER = true, DIVE_BOMB = true, RAGING_CHARGE = true,
    INSECTISLASH = true, ACCELEROCK = true, ACROBATICS = true,
    AQUA_TAIL = true, BLAZE_KICK = true, BREAKING_SWIPE = true,
    FLYING_PRESS = true, FORCE_PALM = true, OUTRAGE = true,
    POISON_FANG = true, POISON_JAB = true, RETALIATE = true,
    SHADOW_SNEAK = true,
    METEOR_MASH = true, STEEL_WING = true, ASSURANCE = true,
    NIGHT_SLASH = true, CRUNCH = true, DRAINING_KISS = true, PLAY_ROUGH = true,
    SPIRIT_FIST = true, MERCURY_MASH = true, SACRED_FIRE = true,
  }

  local function battlerName(battler)
    if battler.isPlayer then
      return battler.name
    end

    return "Enemy " .. battler.name
  end

  -- Conduct needs to apply paralysis outside a normal move-effect handler.
  -- This follows the merged PAR status record's immunity and message rules.
  local function paralyzeFromConduct(battle, battler)
    if not battle or not battler or not battler.mon then
      return false
    end

    if battler.mon.status then
      return false
    end

    local statuses = battle.data and battle.data.statuses
    local record = statuses and statuses.PAR
    local options = {
      moveType = "ELECTRIC",
      source = "CONDUCT",
    }

    if record and record.canInflict
       and not record.canInflict(battler, options) then
      return false
    end

    battler.mon.status = "PAR"

    local messages
    if record and record.onInflict then
      messages = record.onInflict(
        battle,
        battler,
        options,
        battlerName(battler)
      )
    else
      messages = {
        battlerName(battler) .. "\nwas paralyzed!",
      }
    end

    for _, message in ipairs(messages or {}) do
      battle:sayNext(message)
    end

    return true
  end


  ---------------------------------------------------------------------------
  -- CUSTOM MOVE EFFECTS
  ---------------------------------------------------------------------------

  -- 108 SEALS is meant to be a true low-accuracy instant-KO signature
  -- for Spiritomb. Reusing Gen 1's OHKO_EFFECT also inherited the vanilla
  -- speed gate: an OHKO automatically fails when the user is slower. With
  -- Spiritomb's base 35 Speed, that made the move look broken against most
  -- opponents even after the 30%-accuracy roll succeeded.
  --
  -- Keep normal damaging-move accuracy/evasion handling and Ghost immunity,
  -- but remove ONLY the vanilla OHKO speed restriction. A successful hit on
  -- a non-immune target deals the engine's canonical OHKO damage and retains
  -- its one-hit-KO result flag/messages.
  do
    local TypeChart = require("src.battle.TypeChart")

    mod.content.move_effects:register("SEALS_108_EFFECT", {
      kind = "full",

      gate = function(ctx)
        if TypeChart.effectiveness(ctx.move.type, ctx.target.curTypes) == 0 then
          local targetName = ctx.target.isPlayer
            and ctx.target.name
            or ("Enemy " .. ctx.target.name)
          return false, "It doesn't affect\n" .. targetName .. "!"
        end
        return true
      end,

      chooseDamage = function(ctx)
        return 65535, {
          crit = false,
          typeMult = 10,
          ohko = true,
        }
      end,
    })
  end

  -- Mind Melter: approximately 30% chance to confuse after dealing damage.
  mod.content.move_effects:register("MIND_MELTER_EFFECT", {
    kind = "secondary",

    run = function(ctx)
      if ctx.target.confusedTurns then
        return {}
      end

      if ctx.rng(0, 255) >= 77 then
        return {}
      end

      ctx.target.confusedTurns = ctx.rng(2, 5)

      local targetName = ctx.target.isPlayer
        and ctx.target.name
        or ("Enemy " .. ctx.target.name)

      return {
        targetName .. "\nbecame confused!",
      }
    end,
  })

  -- Primordial Ooze: approximately 30% chance to poison.
  mod.content.move_effects:register("PRIMORDIAL_OOZE_EFFECT", {
    kind = "secondary",

    run = function(ctx)
      if ctx.rng(0, 255) >= 77 then
        return {}
      end

      return ctx.inflict(ctx.target, "PSN", {
        secondary = true,
        source = ctx.move.id,
        moveType = ctx.move.type,
      })
    end,
  })

  -- Paleozoic Slash: lowers the foe's Defense and Speed by one stage.
  mod.content.move_effects:register("PALEOZOIC_SLASH_EFFECT", {
    kind = "secondary",

    run = function(ctx)
      local messages = {}

      appendMessages(
        messages,
        ctx.changeStage(ctx.target, "defense", -1, true)
      )

      appendMessages(
        messages,
        ctx.changeStage(ctx.target, "speed", -1, true)
      )

      return messages
    end,
  })

  -- Jurassic Slam: lowers the user's Defense by one stage after a hit.
  mod.content.move_effects:register("JURASSIC_SLAM_EFFECT", {
    kind = "secondary",

    run = function(ctx)
      return ctx.changeStage(ctx.user, "defense", -1, false)
    end,
  })


  -- Haymaker: 30% chance to confuse after dealing damage.
  mod.content.move_effects:register("HAYMAKER_EFFECT", {
    kind = "secondary",

    run = function(ctx)
      if ctx.target.confusedTurns then
        return {}
      end

      if ctx.rng(0, 255) >= 77 then
        return {}
      end

      ctx.target.confusedTurns = ctx.rng(2, 5)

      return {
        battlerName(ctx.target) .. "\nbecame confused!",
      }
    end,
  })

  -- Toxic Waste: 30% chance to poison.
  mod.content.move_effects:register("TOXIC_WASTE_EFFECT", {
    kind = "secondary",

    run = function(ctx)
      if ctx.rng(0, 255) >= 77 then
        return {}
      end

      return ctx.inflict(ctx.target, "PSN", {
        secondary = true,
        source = ctx.move.id,
        moveType = ctx.move.type,
      })
    end,
  })

  -- Boulder Dash: 30% chance to lower the target's Speed one stage.
  mod.content.move_effects:register("BOULDER_DASH_EFFECT", {
    kind = "secondary",

    run = function(ctx)
      if ctx.target.substituteHP or ctx.rng(0, 255) >= 77 then
