  -- Pathetic Plea has a 30% chance to reduce the target's Attack to -6.
  mod.content.move_effects:register("PATHETIC_PLEA_EFFECT", {
    kind = "primary",
    accuracyChecked = true,

    run = function(ctx)
      if ctx.rng(0, 255) >= 77 then
        return { "But, it failed!" }
      end

      return ctx.changeStage(ctx.target, "attack", -12, true)
    end,
  })

  mod.content.move_effects:register("AQUA_RING_EFFECT", {
    kind = "primary",

    run = function(ctx)
      if ctx.user.marsAquaRing then
        return { "But, it failed!" }
      end

      ctx.user.marsAquaRing = true
