  mod.content.move_effects:register("BELLY_DRUM_EFFECT", {
    kind = "primary",

    run = function(ctx)
      local cost = math.floor(maxHP(ctx.user) / 2)
      local attackStage = ctx.user.stages and (ctx.user.stages.attack or 0) or 0

      if attackStage >= 6 or currentHP(ctx.user) <= cost then
        return { "But, it failed!" }
