      ctx.damage(ctx.user, cost)
      ctx.drain()

      local messages = {
        battlerName(ctx.user) .. " cut its own HP\nto maximize ATTACK!",
      }
      appendMessages(messages, ctx.changeStage(ctx.user, "attack", 12, false))
      return messages
    end,
  })

  mod.content.move_effects:register("BITTER_MALICE_EFFECT", {
