  mod.content.move_effects:register("ME_FIRST_EFFECT", {
    kind = "primary",

    run = function(ctx)
      local battle = ctx.battle
      local targetAction = ctx.user.isPlayer
        and battle.marsEnemyAction
        or battle.marsPlayerAction

      local moveId = targetAction and targetAction.id
      local copiedMove = moveId and ctx.data.moves[moveId]

      if not ctx.user.marsActsFirst
         or not copiedMove
         or copiedMove.id == "ME_FIRST"
         or (copiedMove.power or 0) <= 0 then
        return { "But, it failed!" }
      end

      ctx.user.marsMeFirstBoostMove = moveId
      ctx.callMove(moveId)
      ctx.user.marsMeFirstBoostMove = nil
      return {}
    end,
  })

  mod.content.move_effects:register("MIRACLE_EYE_EFFECT", {
    kind = "primary",
    accuracyChecked = true,

    run = function(ctx)
      if ctx.target.marsMiracleEye then
        return { "But, it failed!" }
      end

      ctx.target.marsMiracleEye = true
      if ctx.target.stages then
        ctx.target.stages.evasion = math.min(0, ctx.target.stages.evasion or 0)
      end

      return { battlerName(ctx.target) .. "\nwas identified!" }
    end,
