  -- Witch's Curse is a Ghost-type Future Sight analogue. The cast itself
  -- does no immediate damage; a 120-power hit lands after two end-of-turn
  -- ticks on whichever battler is occupying the targeted side.
  mod.content.move_effects:register("WITCHS_CURSE_EFFECT", {
    kind = "primary",
    accuracyChecked = true,
    run = function(ctx)
      local battle = ctx.battle
      local sideKey = ctx.target.isPlayer and "player" or "enemy"
      battle.marsWitchCurse = battle.marsWitchCurse or {}

      if battle.marsWitchCurse[sideKey] then
        return { "But, it failed!" }
      end

      battle.marsWitchCurse[sideKey] = {
        turns = 2,
        user = ctx.user,
      }

      if type(battle.animationsOn) ~= "function" or battle:animationsOn() then
        battle.marsWitchCurseVisualArmed = {
          target = ctx.target,
          targetIsPlayer = ctx.target and ctx.target.isPlayer == true,
        }
      end

      return { "A curse was cast\ninto the future!" }
    end,
  })


