  mod.content.move_effects:register("DRAINING_KISS_EFFECT", {
    kind = "full",
    afterDamage = function(ctx, totalDealt)
      if totalDealt <= 0 then return end
      local mon = ctx.user.mon
      if not mon or mon.hp <= 0 or mon.hp >= mon.stats.hp then return end
      local healing = math.max(1, math.floor(totalDealt * 3 / 4))
      mon.hp = math.min(mon.stats.hp, mon.hp + healing)
      ctx.drain()
      ctx.say(battlerName(ctx.user) .. " regained health!")
    end,
  })

