  -- Charity's unique move. KINDNESS places a deterministic five-turn
  -- side effect on the target. Physical-category actions are blocked at
  -- BattleState.executeAction, before they can reach performMove.
  mod.content.move_effects:register("KINDNESS_EFFECT", {
    kind = "primary",
    accuracyChecked = true,

    run = function(ctx)
      local battle = ctx.battle
      local sideKey = ctx.target.isPlayer and "player" or "enemy"

      battle.marsKindness = battle.marsKindness or {}

      local existing = battle.marsKindness[sideKey]
      if existing and existing.mon == ctx.target.mon then
        return { "But, it failed!" }
      end

      battle.marsKindness[sideKey] = {
        turns = 5,
        mon = ctx.target.mon,
      }

      if type(battle.animationsOn) ~= "function" or battle:animationsOn() then
        battle.marsV444KindnessArmed = {
          target = ctx.target,
          targetIsPlayer = ctx.target and ctx.target.isPlayer == true,
        }
      end

      return {
        battlerName(ctx.target) .. "\nwas soothed by KINDNESS!",
      }
    end,
  })


