  ---------------------------------------------------------------------------
  -- BATTLE HOOKS AND LONG-LIVED EFFECTS
  ---------------------------------------------------------------------------

  mod.hooks:wrap("battle.damage", function(next, ctx)
    local workingCtx = ctx

    if ctx.move and ctx.move.id == "EVO_POWER" then
      local activeType = "NORMAL"
      if ctx.user and ctx.user.curTypes and ctx.user.curTypes[1] then
        activeType = ctx.user.curTypes[1]
      end

      local moveCopy = copyTable(ctx.move)
      moveCopy.type = activeType
      local ctxCopy = copyTable(ctx)
      ctxCopy.move = moveCopy
      workingCtx = ctxCopy
    end

    local damage, info = next(workingCtx)
    if not damage or not info then return damage, info end

    local moveId = workingCtx.move and workingCtx.move.id

    -- Gen 1 has no held items, so Acrobatics normally receives this boost.
    if moveId == "ACROBATICS"
       and not (workingCtx.user.mon and workingCtx.user.mon.heldItem) then
      damage = math.min(65535, damage * 2)
    end

    if workingCtx.user.marsMeFirstBoostMove == moveId then
      damage = math.min(65535, math.floor(damage * 1.5))
    end

    if moveId == "RETALIATE" then
      local sideKey = workingCtx.user.isPlayer and "player" or "enemy"
      local turns = workingCtx.battle.marsRetaliateTurns or {}
      if turns[sideKey] == (workingCtx.battle.turnCount or 0) then
        damage = math.min(65535, damage * 2)
      end
    end

    -- Assurance doubles if this target already took damage this turn.
    if moveId == "ASSURANCE"
       and workingCtx.target.marsTookDamageTurn == (workingCtx.battle.turnCount or 0) then
      damage = math.min(65535, damage * 2)
    end

    -- Flying Press is Fighting-type for STAB but also applies Flying's
    -- effectiveness against every defending type.
    if moveId == "FLYING_PRESS" then
      local flyingMult = typeMultiplier(
        workingCtx.battle.data,
        "FLYING",
        workingCtx.target.curTypes
      )

      damage = math.floor(damage * flyingMult / 10)
      info.typeMult = math.floor((info.typeMult or 10) * flyingMult / 10)
      if damage <= 0 then info.missed = true end
    end

    -- Spirit Fist gains one additional 50-power chunk for every time its
    -- user has been damaged in this battle, capped at seven total chunks.
    if moveId == "SPIRIT_FIST" then
      local hits = 0
      if workingCtx.battle.marsSpiritFistHits and workingCtx.user.mon then
        hits = workingCtx.battle.marsSpiritFistHits[workingCtx.user.mon] or 0
      end
      damage = math.min(65535, damage * (1 + math.min(6, hits)))
    end

    -- Oil Spill doubles the next successful Fire attack and is consumed.
    if workingCtx.move
       and workingCtx.move.type == "FIRE"
       and workingCtx.target
       and workingCtx.target.marsOiled
       and damage > 0
       and (info.typeMult or 0) > 0 then
      damage = math.min(65535, damage * 2)
      workingCtx.target.marsOiled = nil
      workingCtx.battle:sayNext(
        "The oil around " .. battlerName(workingCtx.target) .. " ignited!"
      )
    end

    return damage, info
  end)

  -- Miracle Eye cancels positive evasion while its target remains active.
  mod.hooks:wrap("battle.accuracy", function(next, ctx)
    if ctx.move and (ctx.move.id == "MAGNET_BOMB"
       or ctx.move.id == "DISARMING_VOICE"
       or ctx.move.id == "KINDNESS") then
      return true
    end

    local target = ctx.target
    if target
       and target.marsMiracleEye
       and target.stages
       and (target.stages.evasion or 0) > 0 then
      local oldEvasion = target.stages.evasion
      target.stages.evasion = 0
      local hit = next(ctx)
      target.stages.evasion = oldEvasion
      return hit
    end

    return next(ctx)
  end)

  -- KINDNESS is enforced at executeAction, the common choke point for normal
  -- selected moves. This makes the block deterministic: if the affected side
  -- attempts a physical move while KINDNESS is active, that action cannot
  -- reach performMove.
  do
    local BattleState = require("src.battle.BattleState")
    local TypeChart = require("src.battle.TypeChart")

    if not BattleState._marsKindnessExecuteActionBlock then
      BattleState._marsKindnessExecuteActionBlock = true

      local baseExecuteAction = BattleState.executeAction

      local function kindnessMoveCategory(move)
        if not move then return nil end

        local category = move.category or TypeChart.category(move.type)
        if category == nil and (move.power or 0) > 0 then
          category = "physical"
        end

        return category
      end

      local function kindnessStateFor(battle, user)
        local states = battle.marsKindness
        if not states or not user then return nil end

        local sideKey = user.isPlayer and "player" or "enemy"
        local state = states[sideKey]

        -- If the active Pokemon changed without the switch hook seeing it,
        -- discard the stale effect rather than applying it to a replacement.
        if state and state.mon ~= user.mon then
          states[sideKey] = nil
          return nil
        end

        return state
      end

      local function finishKindnessBlockedAction(battle, user, target)
        -- Mirror executeAction's normal post-action bookkeeping. The move
        -- itself never reaches performMove, so it cannot announce, animate,
        -- spend PP, or deal damage.
        battle:actNext(function()
          battle:syncShownStatus()
        end)

        local ruleset = battle.ruleset
        local residualAfterMove =
          not ruleset or ruleset.residualAfterMove ~= false

        if residualAfterMove then
          battle:actNext(function()
            battle:residualFor(user, target)
          end)
        end
      end

      BattleState.executeAction = function(self, user, target, action)
        local state = kindnessStateFor(self, user)

        -- Only ordinary move actions have an id here. Trainer items/switches,
        -- recharge, trapping continuations, etc. keep their native behavior.
        if state and action and action.id then
          local move = self:moveDef(action)

          if move and kindnessMoveCategory(move) == "physical" then
            -- Preserve Gen1Recomp's normal status-condition precedence.
            -- Sleep/freeze/flinch/confusion/full paralysis can consume the
            -- turn first; otherwise KINDNESS deterministically blocks it.
            if self:statusInterrupt(user, target, action.id) then
              finishKindnessBlockedAction(self, user, target)
              return
            end

            self:sayNext(
              battlerName(user) .. "\nwas stopped by KINDNESS!"
            )
            finishKindnessBlockedAction(self, user, target)
            return
          end
        end

        return baseExecuteAction(self, user, target, action)
      end
    end
  end

  -- Embargo blocks the opposing trainer's item action. Gen 1 has no held
  -- items, so this is the part of the modern effect that exists in battle.
  mod.hooks:wrap("battle.enemy_action", function(next, battle)
    local action = next(battle)
    if battle.enemy
       and battle.enemy.marsEmbargoTurns
       and action
       and action.special == "aiItem" then
      for _, moveInst in ipairs(battle.enemy.curMoves or {}) do
        if (moveInst.pp or 0) > 0 then
          return moveInst
        end
      end
      return { id = "STRUGGLE", pp = 1, struggle = true }
    end
    return action
  end)

  -- Me First must know which battler really won turn order.
  mod.hooks:wrap("battle.turn_order", function(
    next, playerBattler, playerMove, enemyBattler, enemyMove, ctx
  )
    local playerFirst = next(
      playerBattler,
      playerMove,
      enemyBattler,
      enemyMove,
      ctx
    )

    playerBattler.marsActsFirst = playerFirst
    enemyBattler.marsActsFirst = not playerFirst
    return playerFirst
  end)

  local function forceStruggle(action)
    if not action then return end
    for key in pairs(action) do action[key] = nil end
    action.id = "STRUGGLE"
    action.pp = 1
    action.struggle = true
  end

  local function applyTauntToAction(battle, battler, action)
    if not battler or not battler.marsTauntTurns or not action or not action.id then
      return
    end
    local move = battle.data.moves[action.id]
    if move and (move.category == "status" or (move.power or 0) == 0) then
      forceStruggle(action)
    end
  end

  mod.events:on("battle.turn_started", function(event)
    local battle = event.battle
    battle.marsPlayerAction = event.playerAction
    battle.marsEnemyAction = event.enemyAction

    if battle.player then battle.player.marsTookDamageTurn = nil end
    if battle.enemy then battle.enemy.marsTookDamageTurn = nil end

    applyTauntToAction(battle, battle.player, event.playerAction)
    applyTauntToAction(battle, battle.enemy, event.enemyAction)
  end)

  -- Conduct checks completed damage so only successful contact attacks count.
  mod.events:on("battle.damage_dealt", function(event)
    if not event
       or not event.target
       or not event.target.marsConduct
       or not event.move
       or not CONTACT_MOVES[event.move.id]
       or not event.damage
       or event.damage <= 0 then
      return
    end

    paralyzeFromConduct(event.battle, event.user)
  end)

  -- Spirit Fist remembers hits taken by each party member for the duration
  -- of the battle, including hits taken before Annihilape switches in again.
  mod.events:on("battle.damage_dealt", function(event)
    if not event or not event.target or not event.target.mon
       or not event.damage or event.damage <= 0 then
      return
    end
    local battle = event.battle
    battle.marsSpiritFistHits = battle.marsSpiritFistHits or {}
    battle.marsSpiritFistHits[event.target.mon] =
      (battle.marsSpiritFistHits[event.target.mon] or 0) + 1
  end)

  -- Assurance checks whether its target was damaged earlier in this turn.
  mod.events:on("battle.damage_dealt", function(event)
    if event and event.target and event.damage and event.damage > 0 then
      event.target.marsTookDamageTurn = event.battle.turnCount or 0
    end
  end)

  -- Aqua Ring recovery and Infestation chip damage occur after normal
  -- end-of-turn processing.
  mod.events:on("battle.turn_ended", function(event)
    local battle = event and event.battle
    if not battle or battle.result then return end

    if battle.marsWitchCurse then
      for sideKey, curse in pairs(battle.marsWitchCurse) do
        curse.turns = (curse.turns or 1) - 1
        if curse.turns <= 0 then
          local target = sideKey == "player" and battle.player or battle.enemy
          if target and target.mon and target.mon.hp > 0 and curse.user then
            local delayedMove = copyTable(battle.data.moves.WITCHS_CURSE or {})
            delayedMove.id = "WITCHS_CURSE"
            delayedMove.type = "GHOST"
            delayedMove.category = "special"
            delayedMove.power = 120
            delayedMove.effect = "NO_ADDITIONAL_EFFECT"

            local damage, info = battle:computeDamage(
              curse.user,
              target,
              delayedMove,
              { delayed = true }
            )

            if damage and damage > 0 and info and not info.missed then
              battle:sayNext("WITCH'S CURSE\nstruck from the future!")
              battle:applyDamage(target, damage)
              if target.mon.hp <= 0 then battle:onFaint(target) end
            else
              battle:sayNext("WITCH'S CURSE\nhad no effect!")
            end
          end
          battle.marsWitchCurse[sideKey] = nil
        end
      end
    end

    if battle.marsKindness then
      for sideKey, state in pairs(battle.marsKindness) do
        state.turns = (state.turns or 1) - 1

        if state.turns <= 0 then
          battle.marsKindness[sideKey] = nil
          battle:sayNext("KINDNESS wore off!")
        end
      end
    end

    for _, battler in ipairs({ battle.player, battle.enemy }) do
      if battler then
        if battler.marsTauntTurns then
          battler.marsTauntTurns = battler.marsTauntTurns - 1
          if battler.marsTauntTurns <= 0 then battler.marsTauntTurns = nil end
        end
        if battler.marsEmbargoTurns then
          battler.marsEmbargoTurns = battler.marsEmbargoTurns - 1
          if battler.marsEmbargoTurns <= 0 then battler.marsEmbargoTurns = nil end
        end
      end

      if battler and battler.mon and battler.mon.hp > 0 then
        if battler.marsInfestationTurns then
          local damage = math.max(1, math.floor(maxHP(battler) / 8))
          battler.mon.hp = math.max(0, battler.mon.hp - damage)
          battle:sayNext(battlerName(battler) .. " is hurt\nby infestation!")
          battle:drainNext()

          battler.marsInfestationTurns = battler.marsInfestationTurns - 1
          if battler.marsInfestationTurns <= 0 then
            battler.marsInfestationTurns = nil
          end

          if battler.mon.hp <= 0 then
            battle:onFaint(battler)
          end
        end

        if battler.mon.hp > 0
           and battler.marsAquaRing
           and battler.mon.hp < maxHP(battler) then
          local healing = math.max(1, math.floor(maxHP(battler) / 16))
          battler.mon.hp = math.min(maxHP(battler), battler.mon.hp + healing)
          battle:sayNext(battlerName(battler) .. " restored HP\nwith AQUA RING!")
          battle:drainNext()
        end
      end
    end
  end)

  -- Retaliate is doubled on the side's next turn after one of its Pokémon
  -- faints.
  mod.events:on("battle.fainted", function(event)
    local battle = event and event.battle
    local battler = event and event.battler
    if not battle or not battler then return end

    battle.marsRetaliateTurns = battle.marsRetaliateTurns or {}
    local sideKey = battler.isPlayer and "player" or "enemy"
    battle.marsRetaliateTurns[sideKey] = (battle.turnCount or 0) + 1
  end)

  -- These are volatile effects and disappear when their user/target leaves.
  mod.events:on("battle.battler_switched", function(event)
    local previous = event and event.previous
    if not previous then return end

    previous.marsConduct = nil
    previous.marsOiled = nil
    previous.marsAquaRing = nil
    previous.marsInfestationTurns = nil
    previous.marsMiracleEye = nil
    previous.marsMeFirstBoostMove = nil
    previous.marsActsFirst = nil
    previous.marsEmbargoTurns = nil
    previous.marsTauntTurns = nil
    previous.marsTookDamageTurn = nil

    local battle = event and event.battle
    if battle and battle.marsKindness then
      local sideKey = previous.isPlayer and "player" or "enemy"
      battle.marsKindness[sideKey] = nil
    end
  end)


  end)()

