  ---------------------------------------------------------------------------
  -- GUARANTEE LEGENDARY/MYTHICAL SIGNATURE MOVES ON CAPTURE
  --
  -- The encounter learnsets already place these moves at the legendary's
  -- intended level, but Gen1Recomp rebuilds a caught monster's move list from
  -- species data during the capture flow. Make the ownership moment explicit:
  -- every newly caught legendary that has one of our authored signature moves
  -- leaves the battle knowing it, whether it goes to the party or straight to
  -- a PC box. If all four move slots are occupied, replace slot 1 (the oldest
  -- generated move) and preserve the other three.
  ---------------------------------------------------------------------------

  local LEGENDARY_CAPTURE_SIGNATURE = {
    ARTICUNO = "ABSOLUTE_ZERO",
    ZAPDOS = "ELECTROCUTION",
    MOLTRES = "PHOENIX_STRIKE",
    MEWTWO = "MIND_MELTER",
    HO_OH = "SACRED_FIRE",
    LUGIA = "AEROBLAST",
    CELEBI = "TIME_TWISTER",
    ARCEUS = "JUDGMENT",
  }

  local function ensureLegendaryCaptureSignature(game, mon)
    if not game or not game.data or not mon then return false end

    local moveId = LEGENDARY_CAPTURE_SIGNATURE[mon.species]
    if not moveId then return false end

    local moveDef = game.data.moves and game.data.moves[moveId]
    if not moveDef then
      mod.log:warn(
        "legendary signature move %s is missing for %s",
        tostring(moveId),
        tostring(mon.species)
      )
      return false
    end

    mon.moves = mon.moves or {}

    -- If the generated capture set already contains the signature, simply
    -- restore its PP and leave the player's other three moves untouched.
    for _, move in ipairs(mon.moves) do
      if move and move.id == moveId then
        move.pp = moveDef.pp
        return false
      end
    end

    local signature = { id = moveId, pp = moveDef.pp }
    if #mon.moves < 4 then
      table.insert(mon.moves, signature)
    else
      mon.moves[1] = signature
    end

    return true
  end

  mod.events:on("pokemon.caught", function(event)
    local game = event and (event.game or (event.battle and event.battle.game))
    local mon = event and event.mon
    if ensureLegendaryCaptureSignature(game, mon) then
      mod.log:info(
        "capture signature applied: %s learned %s",
        tostring(mon.species),
        tostring(LEGENDARY_CAPTURE_SIGNATURE[mon.species])
      )
    end
  end)

  -- Existing saves may already own one or more of these legendaries/mythicals
  -- from an earlier build. This migration uses its own flag so existing saves
  -- still receive TIME TWISTER on Celebi and
  -- JUDGMENT on Arceus. It runs once, so players can replace the moves later.
  mod.events:on("game.ready", function(event)
    local game = event and event.game
    local save = game and game.save
    if not save then return end

    save.flags = save.flags or {}
    local migrationFlag = "EVENT_MARS_LEGENDARY_CAPTURE_SIGNATURES_V370"
    if save.flags[migrationFlag] then return end

    for _, mon in ipairs(save.party or {}) do
      ensureLegendaryCaptureSignature(game, mon)
    end

    local Boxes = require("src.pokemon.Boxes")
    local boxes = Boxes.ensure(save)
    for _, box in ipairs(boxes or {}) do
      for _, mon in ipairs(box or {}) do
        ensureLegendaryCaptureSignature(game, mon)
      end
    end

    save.flags[migrationFlag] = true
  end)

