  -- Reusable evolution items.
  --
  -- Gen1Recomp's stock ItemEffects module keeps the five vanilla evolution
  -- stones in a private hard-coded table. Custom item records alone therefore
  -- cannot enter ItemUseEvoStone, even when needsTarget is true. Patch the
  -- public ItemEffects dispatch directly so our added evolution items behave
  -- exactly like field-used stones and return the same evolveTo payload that
  -- BagMenu already understands.
  local marsEvolutionItems = {
    SUN_STONE = true,
    KINGS_ROCK = true,
    METAL_COAT = true,
    DRAGON_SCALE = true,
    UPGRADE = true,
    DUSK_STONE = true,
    DUBIOUS_DISC = true,
    ICE_STONE = true,
    FAE_STONE = true,
  }

  local ItemEffects = require("src.inventory.ItemEffects")
  if not ItemEffects._marsExpandedKantoEvolutionPatch then
    ItemEffects._marsExpandedKantoEvolutionPatch = true

    local originalUse = ItemEffects.use
    local originalNeedsTarget = ItemEffects.needsTarget
    local originalIsStone = ItemEffects.isStone

    ItemEffects.needsTarget = function(id, itemDef)
      if marsEvolutionItems[id] then return true end
      return originalNeedsTarget(id, itemDef)
    end

    ItemEffects.isStone = function(id)
      if marsEvolutionItems[id] then return true end
      return originalIsStone and originalIsStone(id) or false
    end

    ItemEffects.use = function(data, save, itemId, target, battle, moveIndex, ow)
      if marsEvolutionItems[itemId] then
        if battle then
          local playerName = save and save.player and save.player.name or "PLAYER"
          return "failed", {
            "OAK: " .. playerName .. "!\nThis isn't the\ntime to use that!"
          }
        end

        if not target then
          return "failed", { "It won't have\nany effect." }
        end

        local speciesDef = data and data.pokemon and data.pokemon[target.species]
        for _, evo in ipairs((speciesDef and speciesDef.evolutions) or {}) do
          if evo.method == "ITEM" and evo.item == itemId then
            return "consumed", nil, { evolveTo = evo.species }
          end
        end

        return "failed", { "It won't have\nany effect." }
      end

      return originalUse(data, save, itemId, target, battle, moveIndex, ow)
    end
  end

