  -- Tyrogue chooses an evolution by its calculated Attack and Defense.
  local function readTyrogueStat(mon, statName)
    local possibleTables = {
      mon and mon.stats,
      mon and mon.calculatedStats,
      mon and mon.computedStats,
      mon and mon.battleStats,
    }

    for _, values in ipairs(possibleTables) do
      if values and type(values[statName]) == "number" then
        return values[statName]
      end
    end

    if mon and type(mon[statName]) == "number" then
      return mon[statName]
    end

    return 35
  end

  local function tyrogueCanEvolve(mon, evo, trigger)
    return trigger
      and trigger.kind == "levelup"
      and mon
      and (mon.level or 0) >= (evo.level or 20)
  end

  mod.content.evolution_methods:register("TYROGUE_ATTACK", {
    check = function(game, mon, evo, trigger)
      if not tyrogueCanEvolve(mon, evo, trigger) then
        return false
      end

      return readTyrogueStat(mon, "attack")
        > readTyrogueStat(mon, "defense")
    end,
  })

  mod.content.evolution_methods:register("TYROGUE_DEFENSE", {
    check = function(game, mon, evo, trigger)
      if not tyrogueCanEvolve(mon, evo, trigger) then
        return false
      end

      return readTyrogueStat(mon, "defense")
        > readTyrogueStat(mon, "attack")
    end,
  })

  mod.content.evolution_methods:register("TYROGUE_BALANCE", {
    check = function(game, mon, evo, trigger)
      if not tyrogueCanEvolve(mon, evo, trigger) then
        return false
      end

      return readTyrogueStat(mon, "attack")
        == readTyrogueStat(mon, "defense")
    end,
  })

  local function appendUnique(destination, values)
    local present = {}

    for _, value in ipairs(destination) do
      present[value] = true
    end

    for _, value in ipairs(values or {}) do
      if not present[value] then
        destination[#destination + 1] = value
        present[value] = true
      end
    end
  end

