  -- Gen1Recomp's DexEntryMenu expects pokemon.dexEntry.text to contain a
  -- TEXT ID, not the description itself.  Earlier Expanded Kanto builds put
  -- the literal description in that field, so the menu tried to look the
  -- entire sentence up in game.data.text and fell back to "Data unknown."
  --
  -- Keep the descriptions authored beside each species, but register them as
  -- proper text records here before the Pokemon definition is installed.
  local function wrapDexDescription(text, maxChars)
    maxChars = maxChars or 18
    if type(text) ~= "string" then return text end

    local lines = {}
    local line = ""

    local function flush()
      if line ~= "" then
        lines[#lines + 1] = line
        line = ""
      end
    end

    -- The Gen 1 Dex description area is 18 text tiles wide.  Wrap on words
    -- so custom entries fit the same screen instead of clipping horizontally.
    for word in text:gmatch("%S+") do
      if line == "" then
        line = word
      elseif #line + 1 + #word <= maxChars then
        line = line .. " " .. word
      else
        flush()
        line = word
      end
    end
    flush()

    -- DexEntryMenu draws description text at y=88, 104, and 120, so one
    -- entry page has room for exactly three lines. Gen1Recomp already treats
    -- form-feed as the original Gen 1 <PAGE> marker; split longer custom
    -- descriptions into proper pages instead of letting line 4 clip offscreen.
    local pages = {}
    for i = 1, #lines, 3 do
      local pageLines = {}
      for j = i, math.min(i + 2, #lines) do
        pageLines[#pageLines + 1] = lines[j]
      end
      pages[#pages + 1] = table.concat(pageLines, "\n")
    end

    return table.concat(pages, "\f")
  end

  ---------------------------------------------------------------------------
  -- 64x32 HORIZONTAL CUSTOM PARTY ICON SUPPORT
  --
  -- Gen1Recomp's stock PartyMenu.drawIcon() treats a custom image taller than
  -- 16px as a vertical stack of 16x16 frames. Expanded Kanto's icon artwork
  -- instead uses the common later-gen format:
  --
  --     64x32 total
  --     [ 32x32 frame 1 ][ 32x32 frame 2 ]
  --
  -- Intercept only custom table entries using that layout. Each active 32x32
  -- frame is drawn into Gen 1's native 16x16 icon box using nearest-neighbor
  -- scaling. Built-in Gen 1 icons and any differently formatted mod icons go
  -- straight through the original renderer.
  ---------------------------------------------------------------------------

  do
    local PartyMenu = require("src.ui.PartyMenu")

    if not PartyMenu._marsHorizontal32IconSupport then
      PartyMenu._marsHorizontal32IconSupport = true

      local Assets = require("src.render.Assets")
      local Sprites = require("src.pokemon.Sprites")
      local baseDrawIcon = PartyMenu.drawIcon
      local marsIconImages = {}

      local function marsLoadIcon(path)
        if marsIconImages[path] ~= nil then
          return marsIconImages[path] or nil
        end

        local ok, image = pcall(
          love.graphics.newImage,
          Assets.resolve(path)
        )

        if ok and image then
          -- Critical for pixel art: 32 -> 16 must select hard pixels rather
          -- than blur neighboring colors together.
          if image.setFilter then
            image:setFilter("nearest", "nearest")
          end
          marsIconImages[path] = image
          return image
        end

        marsIconImages[path] = false
        return nil
      end

      local function marsIconAltFrame(mon, selected, counter, forceAlt)
        local alt = forceAlt or false

        -- Match Gen1Recomp's normal AnimatePartyMon timing exactly:
        -- healthy = 5 frames, yellow HP = 16, red HP = 32.
        if selected and mon and mon.stats then
          local maxHP = math.max(1, mon.stats.hp or 1)
          local px = math.floor((mon.hp or 0) * 48 / maxHP)
          local speed = px >= 27 and 5 or px >= 10 and 16 or 32
          alt = math.floor((counter or 0) / speed) % 2 == 1
        end

        return alt
      end

      local function drawingAdvancedBoxRow()
        if not debug or type(debug.getinfo) ~= "function" then
          return false
        end

        for level = 2, 12 do
          local info = debug.getinfo(level, "S")
          if not info then break end

          local source = string.lower(
            tostring(info.short_src or info.source or "")
          )
          if source:find("advanced_box", 1, true) then
            return true
          end
        end

        return false
      end

      function PartyMenu.drawIcon(game, mon, x, y, selected, counter, forceAlt)
        -- Advanced Box System uses a compact text row. Leaving its icon slot
        -- empty keeps long custom species names and level/HP columns readable.
        if drawingAdvancedBoxRow() then
          return true
        end

        local data = game and game.data
        local icons = data and data.icons
        local def = data and data.pokemon and data.pokemon[mon.species]

        if icons then
          local entry =
            (icons.bySpecies and icons.bySpecies[mon.species])
            or (def and def.icon)

          if type(entry) == "table" and entry.image then
            local path = Sprites.iconPath(
              data,
              mon,
              entry.image,
              { name = nil }
            )

            if path then
              local image = marsLoadIcon(path)

              if image then
                local iw, ih = image:getDimensions()

                -- Metadata is preferred, but recognize both the old 64x32
                -- source sheet and the runtime-halved 32x16 derivative.
                local horizontal =
                  entry.layout == "horizontal"
                  or (iw == 64 and ih == 32)
                  or (iw == 32 and ih == 16)

                local frames = entry.frames or 2
                local frameW = entry.frameWidth
                  or (horizontal and math.floor(iw / math.max(1, frames)))
                local frameH = entry.frameHeight or ih
                local drawW = entry.drawWidth or 16
                local drawH = entry.drawHeight or 16

                if horizontal
                   and frames >= 2
                   and frameW
                   and frameW > 0
                   and frameH > 0
                   and iw >= frameW * 2
                   and ih >= frameH
                then
                  local alt = marsIconAltFrame(
                    mon, selected, counter, forceAlt
                  )
                  local frame = alt and 1 or 0

                  local quad = love.graphics.newQuad(
                    frame * frameW,
                    0,
                    frameW,
                    frameH,
                    iw,
                    ih
                  )

                  love.graphics.draw(
                    image,
                    quad,
                    x,
                    y,
                    0,
                    drawW / frameW,
                    drawH / frameH
                  )

                  return true
                end
              end
            end
          end
        end

        return baseDrawIcon(
          game, mon, x, y, selected, counter, forceAlt
        )
      end
    end
  end

  local function registerExpandedSpecies(def)
    local placeholder = mod.content.pokemon:get(def.placeholder)

    if not placeholder then
      error(
        ("Missing related species %s for %s")
          :format(tostring(def.placeholder), tostring(def.id))
      )
    end

    local tmhm = copyTable(placeholder.tmhm)
    appendUnique(tmhm, def.extraTMHM)

    local dexEntry = nil
    if def.dexEntry then
      dexEntry = {}
      for key, value in pairs(def.dexEntry) do
        dexEntry[key] = value
      end

      if type(dexEntry.text) == "string" and dexEntry.text ~= "" then
        local dexTextId = "_MARS_DEX_ENTRY_" .. def.id
        mod.content.text:register(
          dexTextId,
          wrapDexDescription(dexEntry.text, 18)
        )
        dexEntry.text = dexTextId
      end
    end

    -- Every added species uses its own bundled artwork. Do not silently
    -- fall back to a related Gen 1 placeholder if the asset probe fails.
    -- Expected layout:
    -- assets/pokemon/<species>/front.png
    -- assets/pokemon/<species>/back.png
    -- assets/pokemon/<species>/icon.png
    local assetRoot = "assets/pokemon/" .. string.lower(def.id)
    local frontSprite = mod.assets:path(assetRoot .. "/front.png")
    local backSprite = mod.assets:path(assetRoot .. "/back.png")
    local speciesPalette = "MARS_" .. def.id

    -- these source files are full-color Pokemon Essentials GSC artwork.
    -- The runtime sprite hook below creates half-size true-color/grayscale
    -- derivatives inside LÖVE's save directory. Keep trueColor enabled for
    -- BOTH modes so neither result is forced through Gen1's 4-shade palette.
    local speciesTrueColor = true
    local battleScaleBack = 1
    local speciesFrontSize = def.frontSize

    mod.content.icons:register(def.id, {
      image = mod.assets:path(assetRoot .. "/icon.png"),

      -- frame dimensions are inferred from the image actually returned
      -- by pokemon.icon. A full-size 64x32 GSC icon sheet becomes 32x16 at
      -- runtime, i.e. two native 16x16 frames.
      frames = 2,
      layout = "horizontal",
      drawWidth = 16,
      drawHeight = 16,
    })

    -- Keep using a related Gen 1 cry until custom cries are added later.
    mod.content.cries:register(def.id, { base = def.placeholder })

    mod.content.pokemon:register(def.id, {
      id = def.id,
      name = def.name,
      dex = def.dex,
      types = def.types,
      baseStats = def.baseStats,
      catchRate = def.catchRate,
      baseExp = def.baseExp,
      growthRate = def.growthRate,
      level1Moves = def.level1Moves,
      learnset = def.learnset,
      evolutions = def.evolutions,
      tmhm = tmhm,

      spriteFront = frontSprite,
      spriteBack = backSprite,
      frontSize = speciesFrontSize,

      battleScaleBack = battleScaleBack,

      cry = def.id,
      palette = speciesPalette,
      trueColor = speciesTrueColor,

      dexEntry = dexEntry,
    })
  end

