  ---------------------------------------------------------------------------
  -- IN-GAME GSC SPRITE PROCESSOR + TRUE COLOR / GRAYSCALE OPTION
  --
  -- No external conversion step is required.
  --
  -- Put the ORIGINAL, full-size Pokemon Essentials GSC images directly at:
  --   assets/pokemon/<species>/front.png
  --   assets/pokemon/<species>/back.png
  --   assets/pokemon/<species>/icon.png
  --
  -- The first time one is requested during a game session, this code:
  --   1. loads the original PNG;
  --   2. creates an exact 50%-width / 50%-height nearest-neighbor copy;
  --   3. creates a grayscale copy of that half-size image;
  --   4. caches both under the game's LÖVE save directory.
  --
  -- The source PNG in the mod is never altered. The generated files are only
  -- a runtime cache and are overwritten from the source again next launch.
  ---------------------------------------------------------------------------

  local MARS_SPRITE_COLOR_KEY = "sprite_color_mode"
  local MARS_SPRITE_TRUE_COLOR = "true_color"
  local MARS_SPRITE_GRAYSCALE = "grayscale"
  local MARS_SPRITE_RUNTIME_CACHE = "mars_expanded_kanto_sprite_cache_v383"

  mod.options:define({
    {
      key = MARS_SPRITE_COLOR_KEY,
      type = "choice",
      label = "SPRITE COLOR",
      default = MARS_SPRITE_TRUE_COLOR,
      choices = {
        { "TRUE COLOR", MARS_SPRITE_TRUE_COLOR },
        { "GRAYSCALE", MARS_SPRITE_GRAYSCALE },
      },
    },
  })

  local function marsSpriteMode(value)
    if value == MARS_SPRITE_GRAYSCALE then
      return MARS_SPRITE_GRAYSCALE
    end
    return MARS_SPRITE_TRUE_COLOR
  end

  local marsActiveSpriteMode =
    marsSpriteMode(mod.options:get(MARS_SPRITE_COLOR_KEY))

  local function marsOptionBucket(game)
    local options = game and game.save and game.save.options
    if not options then return nil end

    options.modOptions = options.modOptions or {}
    options.modOptions[mod.id] = options.modOptions[mod.id] or {}

    return options.modOptions[mod.id]
  end

  local function marsSetSpriteMode(game, value)
    value = marsSpriteMode(value)
    marsActiveSpriteMode = value

    local bucket = marsOptionBucket(game)
    if bucket then
      bucket[MARS_SPRITE_COLOR_KEY] = value
    end

    -- Keep the loader's live option table synchronized too. The Options menu
    -- will call game:writeOptions() because this row returns true from step().
    if game and game.mods then
      game.mods.modOptions = game.mods.modOptions or {}
      game.mods.modOptions[mod.id] = game.mods.modOptions[mod.id] or {}
      game.mods.modOptions[mod.id][MARS_SPRITE_COLOR_KEY] = value
    end

    return value
  end

  local function marsSpriteModeLabel()
    return marsActiveSpriteMode == MARS_SPRITE_GRAYSCALE
      and "GRAYSCALE"
      or "TRUE COLOR"
  end

  -- Put the toggle directly into the game's normal OPTIONS screen. The same
  -- value also appears in the mod manager because it is a real mod option.
  mod.hooks:wrap("ui.options.rows", function(next, game, rows)
    rows = next(game, rows) or rows

    local spriteRow = {
      id = "marsSpriteColor",
      label = "SPRITE COLOR",

      value = function()
        return marsSpriteModeLabel()
      end,

      step = function(g, dir)
        local newValue =
          marsActiveSpriteMode == MARS_SPRITE_GRAYSCALE
          and MARS_SPRITE_TRUE_COLOR
          or MARS_SPRITE_GRAYSCALE

        marsSetSpriteMode(g, newValue)
        return true
      end,
    }

    local out = {}
    local inserted = false

    for _, row in ipairs(rows or {}) do
      out[#out + 1] = row

      -- Keep the art option beside the engine's COLORS option.
      if not inserted and row.id == "colors" then
        out[#out + 1] = spriteRow
        inserted = true
      end
    end

    if not inserted then
      out[#out + 1] = spriteRow
    end

    return out
  end, 90)

  -- Changing the copy in the mod manager should take effect for the next
  -- sprite resolution exactly like changing the main OPTIONS row.
  mod.events:on("mod.options_changed", function(payload)
    if payload
       and payload.mod == mod.id
       and payload.key == MARS_SPRITE_COLOR_KEY
    then
      marsActiveSpriteMode = marsSpriteMode(payload.value)
    end
  end)

  local marsExpandedSpeciesArt = {}
  for _, speciesDef in ipairs(expandedSpecies) do
    marsExpandedSpeciesArt[speciesDef.id] = true
  end

  local MarsRuntimeAssets = require("src.render.Assets")

  -- source path -> { color = <cache path>, gray = <cache path> }
  -- This is deliberately per-session. Even if a cache PNG exists from a
  -- previous run, the first request this run rebuilds it from the current
  -- source so replacing an asset while developing never leaves stale art.
  local marsProcessedSpritePaths = {}

  local function marsSafeName(value)
    return tostring(value or "unknown")
      :lower()
      :gsub("[^%w_%-]", "_")
  end

  local function marsWriteImageData(imageData, relPath)
    if not imageData or not relPath then return false end

    local dir = relPath:match("^(.*)/[^/]+$")
    if dir and dir ~= "" then
      local okDir = pcall(love.filesystem.createDirectory, dir)
      if not okDir then return false end
    end

    local fileData = imageData:encode("png")
    if not fileData then return false end

    return love.filesystem.write(relPath, fileData:getString()) and true or false
  end

  local function marsHalfSizeDerivatives(sourcePath, species, kind)
    if type(sourcePath) ~= "string" or sourcePath == "" then
      return nil
    end

    local cached = marsProcessedSpritePaths[sourcePath]
    if cached then return cached end

    local ok, result = pcall(function()
      local source = MarsRuntimeAssets.imageData(sourcePath)
      if not source then return nil end

      local sw, sh = source:getDimensions()
      if not sw or not sh or sw < 2 or sh < 2 then return nil end

      local dw = math.max(1, math.floor(sw / 2))
      local dh = math.max(1, math.floor(sh / 2))

      local color = love.image.newImageData(dw, dh)
      local gray = love.image.newImageData(dw, dh)

      -- Exact nearest-neighbor 2:1 downsample. Pokemon Essentials GSC art is
      -- normally integer-scaled pixel art, so selecting the upper-left pixel
      -- of each 2x2 source block restores the intended smaller pixel grid.
      for y = 0, dh - 1 do
        for x = 0, dw - 1 do
          local r, g, b, a = source:getPixel(x * 2, y * 2)

          color:setPixel(x, y, r, g, b, a)

          local luma =
            math.max(0, math.min(1, 0.299 * r + 0.587 * g + 0.114 * b))

          gray:setPixel(x, y, luma, luma, luma, a)
        end
      end

      local safeSpecies = marsSafeName(species)
      local safeKind = marsSafeName(kind)
      local base =
        MARS_SPRITE_RUNTIME_CACHE
        .. "/"
        .. safeSpecies
        .. "/"
        .. safeKind

      local colorPath = base .. "_color.png"
      local grayPath = base .. "_gray.png"

      if not marsWriteImageData(color, colorPath) then return nil end
      if not marsWriteImageData(gray, grayPath) then return nil end

      return {
        color = colorPath,
        gray = grayPath,
        sourceWidth = sw,
        sourceHeight = sh,
        width = dw,
        height = dh,
      }
    end)

    if not ok or not result then
      mod.log:warn(
        "Could not runtime-process GSC sprite %s for %s (%s)",
        tostring(kind),
        tostring(species),
        tostring(result)
      )
      marsProcessedSpritePaths[sourcePath] = false
      return nil
    end

    marsProcessedSpritePaths[sourcePath] = result

    mod.log:info(
      "Runtime-processed %s %s sprite: %sx%s -> %sx%s",
      tostring(species),
      tostring(kind),
      tostring(result.sourceWidth),
      tostring(result.sourceHeight),
      tostring(result.width),
      tostring(result.height)
    )

    return result
  end

  -- quest battles that deliberately use a Pokemon front sprite as an
  -- uncatchable trainer-style opponent can ask the runtime sprite processor for the exact processed
  -- path selected by the live TRUE COLOR / GRAYSCALE option.
  mod._marsRuntimePokemonArtPath = function(sourcePath, species, kind)
    local processed =
      marsHalfSizeDerivatives(sourcePath, species, kind or "front")

    if not processed then return sourcePath end

    if marsActiveSpriteMode == MARS_SPRITE_GRAYSCALE then
      return processed.gray
    end

    return processed.color
  end

  -- Every major Pokemon-art consumer resolves front/back artwork through this
  -- hook: battle, Pokedex, summary, evolution, Hall of Fame, trade, title, etc.
  mod.hooks:wrap("pokemon.sprite", function(next, path, ctx)
    path = next(path, ctx)

    local species = ctx and ctx.species
    if not marsExpandedSpeciesArt[species]
       or type(path) ~= "string"
    then
      return path
    end

    -- Both processed variants are literal RGB/gray PNGs, so never palette-map.
    ctx.trueColor = true

    local side = (ctx and ctx.side == "back") and "back" or "front"
    local processed = marsHalfSizeDerivatives(path, species, side)

    if not processed then return path end

    if marsActiveSpriteMode == MARS_SPRITE_GRAYSCALE then
      return processed.gray
    end

    return processed.color
  end, 200)

  -- Party icons have their own resolver and need the same runtime processing.
  mod.hooks:wrap("pokemon.icon", function(next, path, ctx)
    path = next(path, ctx)

    local species = ctx and ctx.species
    if not marsExpandedSpeciesArt[species]
       or type(path) ~= "string"
    then
      return path
    end

    local processed = marsHalfSizeDerivatives(path, species, "icon")
    if not processed then return path end

    if marsActiveSpriteMode == MARS_SPRITE_GRAYSCALE then
      return processed.gray
    end

    return processed.color
  end, 200)


