  ---------------------------------------------------------------------------
  -- FULL LEARNSET MODERNIZATION
  --
  -- Gen 1's level-up learnsets are one of the biggest weak points of the
  -- original games: many species go dozens of levels without meaningful STAB,
  -- stone evolutions often stop learning moves, and several otherwise-good
  -- Pokemon are stuck with low-power attacks well into the late game.
  --
  -- This pass does NOT erase the original learnsets. It layers a modern
  -- progression on top of them:
  --   * every species in the 235-Pokemon Regional Dex gets useful level-up
  --     options from its actual type(s);
  --   * exact duplicates already present in level-1 moves / learnsets are
  --     skipped;
  --   * stone/item evolutions continue learning worthwhile moves;
  --   * species with distinctive roles receive extra curated moves;
  --   * signature moves already authored elsewhere remain untouched.
  ---------------------------------------------------------------------------

  local function v414AppendLearnset(speciesId, entries)
    local species = mod.content.pokemon:get(speciesId)
    if not species then
      mod.log:warn("learnset: missing species %s", tostring(speciesId))
      return 0
    end

    local knownMoves = {}

    for _, moveId in ipairs(species.level1Moves or {}) do
      knownMoves[moveId] = true
    end

    for _, row in ipairs(species.learnset or {}) do
      if row and row.move then
        knownMoves[row.move] = true
      end
    end

    local additions = {}

    for _, row in ipairs(entries or {}) do
      local moveId = row.move
      local level = row.level

      if moveId
         and level
         and not knownMoves[moveId]
         and mod.content.moves:get(moveId)
      then
        additions[#additions + 1] = {
          level = level,
          move = moveId,
        }
        knownMoves[moveId] = true
      end
    end

    if #additions > 0 then
      mod.content.pokemon:patch(speciesId, {
        learnset = {
          __append = additions,
        },
      })
    end

    return #additions
  end

