  local V414_BASELINE_EXCEPTIONS = {
    CATERPIE = true,
    METAPOD = true,
    WEEDLE = true,
    KAKUNA = true,
    MAGIKARP = true,
    DITTO = true,
  }

  local v414SpeciesTouched = 0
  local v414MovesAdded = 0

  for _, speciesId in ipairs(regionalDexOrder) do
    if not V414_BASELINE_EXCEPTIONS[speciesId] then
      local species = mod.content.pokemon:get(speciesId)
      local before = v414MovesAdded

      if species then
        for _, typeId in ipairs(species.types or {}) do
          v414MovesAdded = v414MovesAdded
            + v414AppendLearnset(
                speciesId,
                V414_TYPE_BASELINE[typeId] or {}
              )
        end
      end

      if v414MovesAdded > before then
        v414SpeciesTouched = v414SpeciesTouched + 1
      end
    end
  end

  v414MovesAdded = v414MovesAdded + v414AppendLearnset("CATERPIE", {
    { level = 12, move = "INFESTATION" },
  })
  v414MovesAdded = v414MovesAdded + v414AppendLearnset("METAPOD", {
    { level = 10, move = "IRON_DEFENSE" },
  })
  v414MovesAdded = v414MovesAdded + v414AppendLearnset("WEEDLE", {
