  ---------------------------------------------------------------------------
  -- OBTAINABILITY: CELADON EVOLUTION-ITEM COUNTER
  --
  -- Rather than adding a map object that would require edited map data and a
  -- new overworld sprite, extend the existing evolution-stone clerk's mart on
  -- Celadon Department Store 4F. The lookup searches the merged text-pointer
  -- data for the clerk that already sells the four Kanto evolution stones, so
  -- it remains compatible with Red, Blue, and Yellow data imports.
  ---------------------------------------------------------------------------

  local expandedEvolutionStock = {
    "SUN_STONE",
    "KINGS_ROCK",
    "METAL_COAT",
    "DRAGON_SCALE",
    "UPGRADE",
    "DUSK_STONE",
    "DUBIOUS_DISC",
    "ICE_STONE",
    "FAE_STONE",
  }

  local function martContains(mart, itemId)
    for _, existingId in ipairs(mart or {}) do
      if existingId == itemId then
        return true
      end
    end

    return false
  end

  local evolutionVendorAdded = false

  if mod.content.text_pointers then
    for mapId, pointerTable in mod.content.text_pointers:each() do
      if type(pointerTable) == "table" then
        for pointerId, binding in pairs(pointerTable) do
          local mart = type(binding) == "table" and binding.mart or nil

          if type(mart) == "table" then
            local originalStoneCount = 0

            for _, stoneId in ipairs({
              "FIRE_STONE",
              "THUNDER_STONE",
              "WATER_STONE",
              "LEAF_STONE",
            }) do
              if martContains(mart, stoneId) then
                originalStoneCount = originalStoneCount + 1
              end
            end

            -- The Celadon 4F evolution-stone clerk is the only vanilla mart
            -- carrying at least three of these four stones.
            if originalStoneCount >= 3 then
              local additions = {}

              for _, itemId in ipairs(expandedEvolutionStock) do
                if not martContains(mart, itemId) then
                  additions[#additions + 1] = itemId
                end
              end

              if #additions > 0 then
                mod.content.text_pointers:patch(mapId, {
                  [pointerId] = {
                    mart = {
                      __append = additions,
                    },
                  },
                })
              end

              evolutionVendorAdded = true

              mod.log:info(
                "Added Expanded-Kanto evolution items to %s / %s",
                tostring(mapId),
                tostring(pointerId)
              )

              break
            end
          end
        end
      end

      if evolutionVendorAdded then
        break
      end
    end
  end

  if not evolutionVendorAdded then
    mod.log:warn(
      "Could not locate the Celadon evolution-stone mart; new evolution items remain registered but unsold"
    )
  end


  ---------------------------------------------------------------------------
  -- ONE-SAVE POKEDEX: REWORKED IN-GAME TRADES
  --
  -- Keep the two especially useful original trades (Lickitung and Jynx),
  -- and repurpose seven low-impact trade slots. The four trade evolutions
  -- ask for the pre-evolution and return its final form; Gen1Recomp's normal
  -- NPC-trade command creates the received species directly, so this is the
  -- reliable way to make Gengar / Alakazam / Machamp / Golem obtainable
  -- without link trading.
  --
  -- The NPC scripts still use their original completion flags. Those flag
  -- names are historical save-format labels; the trade contents come from
  -- field.trades and are safely replaced here.
  ---------------------------------------------------------------------------

  local oneSaveTradeReplacements = {
    -- Route 11 Gate 2F: originally Nidorino -> Nidorina.
    [1] = {
      give = "ODDISH",
      get = "BULBASAUR",
      dialogset = 1,
      nickname = "Audrey II",
    },

    -- Route 2 Trade House: keep the mime-family theme, but now receive
    -- Mime Jr. so Mr. Mime can be raised naturally.
    [2] = {
      give = "ABRA",
      get = "MIME_JR",
      dialogset = 1,
      nickname = "Marcel",
    },

    -- Cerulean trade house: the old Jynx slot now supplies the second
    -- starter trade because Jynx is already obtainable through Smoochum.
    [3] = {
      give = "GROWLITHE",
      get = "CHARMANDER",
      dialogset = 1,
      nickname = "Fenrir",
    },

    -- Cinnabar Lab Fossil Room scientist: originally Ponyta -> Seel.
    [4] = {
      give = "HAUNTER",
      get = "GENGAR",
      dialogset = 1,
      nickname = "Thanatos",
    },

    -- Vermilion Trade House: originally Spearow -> Farfetch'd.
    [5] = {
      give = "KADABRA",
      get = "ALAKAZAM",
      dialogset = 1,
      nickname = "Uri",
    },

    -- Cinnabar Lab Trade Room Gramps: originally Raichu -> Electrode.
    [8] = {
      give = "MACHOKE",
      get = "MACHAMP",
      dialogset = 1,
      nickname = "Hogan",
    },

    -- Cinnabar Lab Trade Room Beauty: originally Venonat -> Tangela.
    [9] = {
      give = "GRAVELER",
      get = "GOLEM",
      dialogset = 1,
      nickname = "Angelo",
    },

    -- Underground Path Route 5: originally Nidoran M -> Nidoran F.
    [10] = {
      give = "POLIWAG",
      get = "SQUIRTLE",
      dialogset = 1,
      nickname = "Leonardo",
    },
  }

  local rewrittenTradeCount = 0
  local alabasterTradeIndex

  if mod.content.field then
    local existingTrades = mod.content.field:get("trades")

    if type(existingTrades) == "table" and #existingTrades > 0 then
      local updatedTrades = {}

      for index, row in ipairs(existingTrades) do
        if type(row) == "table" then
          updatedTrades[index] = {
            give = row.give,
            get = row.get,
            dialogset = row.dialogset,
            nickname = row.nickname,
            texts = row.texts,
          }
        else
          updatedTrades[index] = row
        end
      end

      for index, replacement in pairs(oneSaveTradeReplacements) do
        if updatedTrades[index] ~= nil then
          updatedTrades[index] = replacement
          rewrittenTradeCount = rewrittenTradeCount + 1
        else
          mod.log:warn(
            "Could not replace in-game trade slot %d; slot does not exist",
            index
          )
        end
      end

      -- Add one new Alabaster Town trade without consuming another vanilla
      -- trade slot. The collector rewards the Route 26's 1% Smoochum encounter
      -- with an early Amaura, giving the snowy side area a worthwhile prize.
      alabasterTradeIndex = #updatedTrades + 1
      updatedTrades[alabasterTradeIndex] = {
        give = "SMOOCHUM",
        get = "AMAURA",
        dialogset = 1,
        nickname = "Aurora",
        texts = {
          wannaTrade = "_MARS_ALABASTER_TRADE_WANNA",
          noTrade = "_MARS_ALABASTER_TRADE_NO",
          wrongMon = "_MARS_ALABASTER_TRADE_WRONG",
          thanks = "_MARS_ALABASTER_TRADE_THANKS",
          afterTrade = "_MARS_ALABASTER_TRADE_AFTER",
        },
      }

      -- field is a deep registry, where a list patch would append. Override
      -- replaces the trade list instead, preserving the untouched slots.
      mod.content.field:override("trades", updatedTrades)

      mod.log:info(
        "Reworked %d in-game trades and added Alabaster trade at slot %d",
        rewrittenTradeCount,
        alabasterTradeIndex
      )
    else
      mod.log:warn(
        "Could not read field.trades; one-save trade replacements were skipped"
      )
    end
  end


