  )
  end)()


  ---------------------------------------------------------------------------
  -- OBTAINABILITY: EXPANDED-KANTO WILD ENCOUNTERS
  --
  -- Encounter tables retain their original rate and ten-slot weighting. Each
  -- addition replaces one of the rarest duplicate slots, preferentially a
  -- duplicate belonging to the same evolutionary family. If that relative
  -- only occupies one slot, another duplicated species is replaced so the
  -- original relative remains catchable on the map.
  ---------------------------------------------------------------------------

  local function normalizeEncounterId(id)
    return tostring(id):upper():gsub("[^A-Z0-9]", "")
  end

  local encounterIdsByNormalizedName = {}

  if mod.content.encounters then
    for encounterId in mod.content.encounters:each() do
      encounterIdsByNormalizedName[normalizeEncounterId(encounterId)] = encounterId
    end
  end

  local function copyEncounterSlots(slots)
    local copied = {}

    for index, slot in ipairs(slots or {}) do
      copied[index] = {
        level = slot.level,
        species = slot.species,
      }
    end

    return copied
  end

  local function chooseFamilyReplacementSlot(slots, relatedSpecies)
    local counts = {}
    local related = {}

    for _, speciesId in ipairs(relatedSpecies or {}) do
      related[speciesId] = true
    end

    for _, slot in ipairs(slots) do
      counts[slot.species] = (counts[slot.species] or 0) + 1
    end

    -- Prefer the rarest duplicate belonging to the same family.
    for index = #slots, 1, -1 do
      local speciesId = slots[index].species

      if related[speciesId] and (counts[speciesId] or 0) > 1 then
        return index
      end
    end

    -- Otherwise replace a rare duplicate of another species, preserving the
    -- sole existing encounter for the relative we are expanding.
    for index = #slots, 1, -1 do
      local speciesId = slots[index].species

      if (counts[speciesId] or 0) > 1 then
        return index
      end
    end

    -- Every species is unique: use the table's rarest slot.
    return #slots
  end

  local expandedEncounterCount = 0

  local function addExpandedEncounter(config)
    if not mod.content.encounters then
      return false
    end

    local addedAny = false
    local defaultBuckets = { 51, 102, 141, 166, 191, 216, 229, 242, 253, 256 }

    local function appendRareSlot(slots, terrainData, species, level, weight)
      local updatedSlots = copyEncounterSlots(slots)
      updatedSlots[#updatedSlots + 1] = {
        level = math.max(1, level),
        species = species,
      }

      local sourceBuckets = terrainData.buckets or defaultBuckets
      local weights = {}
      local previous = 0
      for i = 1, #sourceBuckets do
        weights[i] = sourceBuckets[i] - previous
        previous = sourceBuckets[i]
      end

      -- If a modded table has slots but no matching bucket list, fall back to
      -- a simple proportional set before carving out the new rare slot.
      if #weights ~= #slots then
        weights = {}
        local each = math.floor(256 / #slots)
        local used = 0
        for i = 1, #slots do
          weights[i] = (i == #slots) and (256 - used) or each
          used = used + weights[i]
        end
      end

      local rareWeight = math.max(1, math.min(weight or 3, 16))
      local donorIndex, donorWeight = 1, weights[1] or 0
      for i = 2, #weights do
        if weights[i] > donorWeight then
          donorIndex, donorWeight = i, weights[i]
        end
      end
      rareWeight = math.min(rareWeight, math.max(1, donorWeight - 1))
      weights[donorIndex] = donorWeight - rareWeight
      weights[#weights + 1] = rareWeight

      local buckets, cumulative = {}, 0
      for i, w in ipairs(weights) do
        cumulative = cumulative + w
        buckets[i] = cumulative
      end
      buckets[#buckets] = 256
      return updatedSlots, buckets
    end

    -- Every map in config.maps is a real destination. If the vanilla table
    -- still has a duplicate slot, replace one of the rare duplicates. If a
    -- crowded map has no duplicate left, append a new low-weight slot instead
    -- of silently dropping the requested species.
    for _, requestedMapId in ipairs(config.maps) do
      local encounterId = encounterIdsByNormalizedName[
        normalizeEncounterId(requestedMapId)
      ]

      if encounterId then
        local encounter = mod.content.encounters:get(encounterId)
        local terrainData = encounter and encounter[config.terrain]
        local slots = terrainData and terrainData.slots

        if type(slots) == "table" and #slots > 0 then
          local replacementIndex = chooseFamilyReplacementSlot(
            slots,
            config.relatedSpecies
          )

          local updatedSlots
          local updatedBuckets
          local adjustedLevel

          if replacementIndex then
            updatedSlots = copyEncounterSlots(slots)
            local oldSlot = updatedSlots[replacementIndex]
            adjustedLevel = (oldSlot.level or config.minimumLevel or 1)
              + (config.levelAdjustment or 0)

            if config.minimumLevel then
              adjustedLevel = math.max(config.minimumLevel, adjustedLevel)
            end
            if config.maximumLevel then
              adjustedLevel = math.min(config.maximumLevel, adjustedLevel)
            end

            updatedSlots[replacementIndex] = {
              level = math.max(1, adjustedLevel),
              species = config.species,
            }
          else
            adjustedLevel = config.minimumLevel or (slots[#slots].level or 1)
            if config.maximumLevel then
              adjustedLevel = math.min(config.maximumLevel, adjustedLevel)
            end
            updatedSlots, updatedBuckets = appendRareSlot(
              slots, terrainData, config.species, adjustedLevel, config.rareWeight
            )
          end

          local patch = { slots = updatedSlots }
          if updatedBuckets then patch.buckets = updatedBuckets end
          mod.content.encounters:patch(encounterId, {
            [config.terrain] = patch,
          })

          expandedEncounterCount = expandedEncounterCount + 1
          addedAny = true

          mod.log:info(
            "Added wild %s to %s %s%s",
            config.species,
            encounterId,
            config.terrain,
            replacementIndex and (" slot " .. tostring(replacementIndex)) or " as a new rare slot"
          )
        end
      end
    end

    if not addedAny then
      mod.log:warn(
        "Could not add wild %s; no compatible encounter table was found",
        config.species
      )
    end

    return addedAny
  end

  -- Early-game baby Pokémon replace rare duplicate slots near their families.
  addExpandedEncounter({
    species = "PICHU",
    maps = { "VIRIDIAN_FOREST" },
    terrain = "grass",
    relatedSpecies = { "PIKACHU" },
    levelAdjustment = -1,
    minimumLevel = 2,
  })

  addExpandedEncounter({
    species = "IGGLYBUFF",
    maps = { "ROUTE_3", "ROUTE_4" },
    terrain = "grass",
    relatedSpecies = { "JIGGLYPUFF" },
    levelAdjustment = -1,
    minimumLevel = 3,
  })

  -- Tyrogue remains wild in Indigo Highlands.
  -- Hitmontop is now obtained by evolving Tyrogue rather than appearing
  -- directly in Victory Road.

  addExpandedEncounter({
