  -- vanilla water encounter rate is zero.
  local function installWaterHabitat(mapId, rate, slots)
    local normalized = normalizeEncounterId(mapId)
    local encounterId =
      encounterIdsByNormalizedName[normalized]
      or mapId

    local existing =
      mod.content.encounters:get(encounterId)

    if existing then
      mod.content.encounters:patch(encounterId, {
        water = {
          rate = rate,
          slots = copyEncounterSlots(slots),
        },
      })
    else
      mod.content.encounters:register(encounterId, {
        id = encounterId,
        water = {
          rate = rate,
          slots = copyEncounterSlots(slots),
        },
      })
    end

    mod.log:info(
      "installed water habitat on %s",
      encounterId
    )
  end

