  -------------------------------------------------------------------------
  -- MT. MOON CLEFFA / CLEFAIRY
  --
  -- Guarantee the family distribution on every Mt. Moon floor:
  -- slot 9 = Cleffa (~4%)
  -- slot 10 = Clefairy (~1%)
  --
  -- Any older Cleffa/Clefairy placement in slots 1-8 is removed first so
  -- those are the ONLY Cleffa/Clefairy probabilities on each floor.
  -------------------------------------------------------------------------

  local function installMtMoonBabySlots(mapId)
    local encounterId =
      encounterIdsByNormalizedName[
        normalizeEncounterId(mapId)
      ]

    if not encounterId then
      mod.log:warn(
        "Mt. Moon encounter table missing: %s",
        mapId
      )
      return
    end

    local encounter =
      mod.content.encounters:get(encounterId)
    local grass = encounter and encounter.grass
    local slots = grass and grass.slots

    if type(slots) ~= "table" or #slots < 10 then
      mod.log:warn(
        "Mt. Moon slots unavailable: %s",
        encounterId
      )
      return
    end

    local updated = copyEncounterSlots(slots)

    -- Clear any family members from the first eight slots. This mainly
    -- matters on B2F, where vanilla Clefairy also occupies a 5% slot.
    for i = 1, 8 do
      if updated[i].species == "CLEFAIRY"
         or updated[i].species == "CLEFFA"
      then
        updated[i] = {
          level = updated[i].level,
          species = "ZUBAT",
        }
      end
    end

    local slot9Level =
      updated[9] and updated[9].level or 8
    local slot10Level =
      updated[10] and updated[10].level or 8

    updated[9] = {
      level = math.max(5, slot9Level - 2),
      species = "CLEFFA",
    }

    updated[10] = {
      level = math.max(6, slot10Level),
      species = "CLEFAIRY",
    }

    mod.content.encounters:patch(encounterId, {
      grass = {
        slots = updated,
      },
    })

    mod.log:info(
      "%s: CLEFFA ~4%% / CLEFAIRY ~1%%",
      encounterId
    )
  end

  for _, mapId in ipairs({
    "MT_MOON_1F",
    "MT_MOON_B1F",
    "MT_MOON_B2F",
  }) do
    installMtMoonBabySlots(mapId)
  end


  end)()


  ---------------------------------------------------------------------------
  -- COMPLETE BABY-POKEMON ENCOUNTER REPLACEMENTS
  ---------------------------------------------------------------------------

  local function replaceAllEncounterSpecies(
    requestedMapId,
    terrain,
    oldSpecies,
    newSpecies,
    levelAdjustment,
    minimumLevel
  )
    local encounterId = encounterIdsByNormalizedName[
      normalizeEncounterId(requestedMapId)
    ]

    if not encounterId then
      mod.log:warn(
        "Could not replace %s with %s on %s; encounter table not found",
        oldSpecies, newSpecies, requestedMapId
      )
      return 0
    end

    local encounter = mod.content.encounters:get(encounterId)
    local terrainData = encounter and encounter[terrain]
    local slots = terrainData and terrainData.slots

    if type(slots) ~= "table" then
      mod.log:warn(
        "Could not replace %s with %s on %s; %s slots unavailable",
        oldSpecies, newSpecies, encounterId, terrain
      )
      return 0
    end

    local updatedSlots = copyEncounterSlots(slots)
    local replacements = 0

    for i, slot in ipairs(updatedSlots) do
      if slot.species == oldSpecies then
        local level = (slot.level or minimumLevel or 1)
          + (levelAdjustment or 0)

        if minimumLevel then
          level = math.max(minimumLevel, level)
        end

        updatedSlots[i] = {
          level = math.max(1, level),
          species = newSpecies,
        }
        replacements = replacements + 1
      end
    end

    if replacements > 0 then
      mod.content.encounters:patch(encounterId, {
        [terrain] = {
          slots = updatedSlots,
        },
      })

      mod.log:info(
        "Replaced all %s with %s on %s (%d slots)",
        oldSpecies, newSpecies, encounterId, replacements
      )
    else
      mod.log:info(
        "No remaining %s slots found on %s",
        oldSpecies, encounterId
      )
    end

    return replacements
  end

  -- Viridian Forest now represents Pikachu's family with Pichu exclusively.
  -- Viridian Deepwood is intentionally untouched.
  replaceAllEncounterSpecies(
    "VIRIDIAN_FOREST",
    "grass",
    "PIKACHU",
    "PICHU",
    -1,
    2
  )

  -- Route 3's Jigglypuff population is now entirely Igglybuff.
  -- Route 4 remains unchanged.
  replaceAllEncounterSpecies(
    "ROUTE_3",
    "grass",
    "JIGGLYPUFF",
    "IGGLYBUFF",
    -1,
    3
  )


  ---------------------------------------------------------------------------
  -- ROUTE 3 TOGEPI CARETAKER
  --
  -- Togepi is no longer a random Route 1/2/22 encounter. A caretaker near
  -- Route 3's Pewter entrance is looking for a proven trainer to take over
  -- responsibility for a rare Pokemon they can no longer care for.
  --
  -- The BOULDERBADGE is the proof they require. The gift is a Lv.5 TOGEPI.
  -- If the party is full, TOGEPI is sent to a PC box. If party and PC are
  -- both full, no completion flag is set so the player can make room and
  -- retry later.
  ---------------------------------------------------------------------------

  ;(function()
    local TEXT_ROUTE3_TOGEPI_CARETAKER =
      "TEXT_ROUTE3_TOGEPI_CARETAKER"

    local TOGEPI_GIFT_FLAG = "EVENT_ROUTE3_TOGEPI_RECEIVED"

    mod.content.maps:patch("ROUTE_3", {
      objects = {
        __append = {
          {
            index = 90,
            name = "ROUTE3_TOGEPI_CARETAKER",
            sprite = "SPRITE_MIDDLE_AGED_WOMAN",
            movement = "STAY",
            range = "RIGHT",
            x = 6,
            y = 8,
            text = TEXT_ROUTE3_TOGEPI_CARETAKER,
          },
        },
      },
    })

    local function togepiSay(game, text, done)
      local TextBox = require("src.render.TextBox")
      game.stack:push(TextBox.new(game, text, done))
    end

    local function togepiHasBoulderBadge(game)
      local Badges = require("src.inventory.Badges")
      local badges = Badges.list(game.data)
      local firstBadge = badges and badges[1]
      if not firstBadge then return false end

      local itemId = Badges.itemFor(firstBadge)
      return game.save.inventory
        and game.save.inventory[itemId]
        and true
        or false
    end

    local function buildGiftTogepi(game)
      local Pokemon = require("src.pokemon.Pokemon")
      local Party = require("src.pokemon.Party")
      local Boxes = require("src.pokemon.Boxes")
      local BattleState = require("src.battle.BattleState")

      local mon = Pokemon.new(game.data, "TOGEPI", 5)
      BattleState.stampOT(game.save, mon)

      local addedToParty = Party.add(game.save.party, mon)
      local boxNum = nil

      if not addedToParty then
        boxNum = Boxes.deposit(game.save, mon)
        if not boxNum then
          return false
        end
      end

      local dex = game.save.pokedex
      if dex then
        dex.seen = dex.seen or {}
        dex.owned = dex.owned or {}
        dex.seen.TOGEPI = true
        dex.owned.TOGEPI = true
      end

      return true, boxNum
    end

    local function caretakerTalk(game, ow, npc, done)
      if npc and npc.facePlayer and ow and ow.player then
        npc:facePlayer(ow.player)
      end

      local flags = game.save.flags or {}

      if flags[TOGEPI_GIFT_FLAG] then
        togepiSay(
          game,
          "Please take good care\nof TOGEPI.\f"
            .. "I know I chose the\nright TRAINER.",
          done
        )
        return
      end

      if not togepiHasBoulderBadge(game) then
        togepiSay(
          game,
          "I'm looking for a\nresponsible TRAINER.\f"
            .. "I have a rare\nPOKEMON I can't take\ncare of anymore.\f"
            .. "I need to know its\nnew TRAINER can be\ntrusted.\f"
            .. "Come back after\nyou've proven\nyourself.",
          done
        )
        return
      end

      togepiSay(
        game,
        "I'm looking for a\nresponsible TRAINER.\f"
          .. "I have a rare\nPOKEMON I can't take\ncare of anymore.\f"
          .. "Wait...\f"
          .. "That's the\nBOULDERBADGE!\f"
          .. "Then you must be\nthe TRAINER I've been\nwaiting for.\f"
          .. "Please look after\nthis POKEMON for me.",
        function()
          local ok, boxNum = buildGiftTogepi(game)

          if not ok then
            togepiSay(
              game,
              "Your party and PC\nare both full!\f"
                .. "Please make some\nroom and come back.\f"
                .. "I'll keep TOGEPI\nsafe until then.",
              done
            )
            return
          end

          flags[TOGEPI_GIFT_FLAG] = true

          local Sound = require("src.core.Sound")
          Sound.play(game.data, "Get_Item1")

          if boxNum then
            togepiSay(
              game,
              "You received a\nLv.5 TOGEPI!\f"
                .. "TOGEPI was sent to\nPOKEMON BOX "
                .. tostring(boxNum)
                .. ".\f"
                .. "CARETAKER: Please\ntake good care of it.",
              done
            )
          else
            togepiSay(
              game,
              "You received a\nLv.5 TOGEPI!\f"
                .. "CARETAKER: Please\ntake good care of it.",
              done
            )
          end
        end
      )
    end

    if mod.content.map_scripts then
      mod.content.map_scripts:register("ROUTE_3", {
        priority = 135,
        talk = {
          [TEXT_ROUTE3_TOGEPI_CARETAKER] = caretakerTalk,
        },
      })
    end
  end)()


