          { "show_text", "_MARS_CATACOMBS_GRAVE1" },
        },
        TEXT_LAVENDER_CATACOMBS_GRAVE2 = {
          { "show_text", "_MARS_CATACOMBS_GRAVE2" },
        },
        TEXT_LAVENDER_CATACOMBS_GRAVE3 = {
          { "show_text", "_MARS_CATACOMBS_GRAVE3" },
        },

        -- Custom handler so BURIEDALIVE's loss line is displayed BEFORE the
        -- normal blackout/warp. Commands.start_battle blackouts immediately
        -- on a loss, which would otherwise skip the requested escape text.
        TEXT_LAVENDER_CATACOMBS_BURIEDALIVE = function(game, ow, npc, done)
          local TextBox = require("src.render.TextBox")
          local BattleState = require("src.battle.BattleState")
          local flags = game.save.flags or {}

          if flags.EVENT_BEAT_BURIED_ALIVE then
            if done then done() end
            return
          end

          game.stack:push(TextBox.new(
            game,
            game.data.text._MARS_BURIEDALIVE_PREBATTLE,
            function()
              local battle = BattleState.newTrainer(game, "OPP_BURIEDALIVE", 1)
              battle.onFinish = function(result)
                if result == "win" then
                  flags.EVENT_BEAT_BURIED_ALIVE = true
                  game.stack:push(TextBox.new(
                    game,
                    game.data.text._MARS_BURIEDALIVE_WIN,
                    function()
                      ow:queueScript({
                        { "hide_object", "LAVENDER_CATACOMBS", "MARS_BURIEDALIVE" },
                      })
                      if done then done() end
                      ow:afterBattle(result, battle)
                    end
                  ))
                else
                  game.stack:push(TextBox.new(
                    game,
                    game.data.text._MARS_BURIEDALIVE_LOSE,
                    function()
                      if done then done() end
                      ow:afterBattle(result, battle)
                    end
                  ))
                end
              end
              ow:pushBattle(battle)
            end
          ))
        end,
      },
    })
  end


  ---------------------------------------------------------------------------
  -- "108 VOICES" -- REVAMPED SPIRITOMB SIDE QUEST
  --
  -- Unlock: after Mr. Fuji has been rescued from Pokemon Tower.
  --
  -- Flow:
  --   1. The possessed Lavender man resists when the player tries to knock
  --      away the Odd Keystone. A violent force throws the player backward.
  --      The man flees to Pokemon Tower 7F and drops the Keystone.
  --   2. Pick up the Keystone and take it to Mr. Fuji.
  --   3. Calm three powerful fragments in Pokemon Tower:
  --        3F = Anger  (Haunter battle)
  --        5F = Sorrow (soothed with the Poke Flute)
  --        6F = Malice (Banette lures the player before its battle)
  --   4. Return to Mr. Fuji so he can bless the damaged Keystone.
  --   5. Return to 7F and use the seals to pull Spiritomb out of the man.
  --      Spiritomb is retriable until CAUGHT.
  --   6. The man is saved. Return to Mr. Fuji for the epilogue.
  --
  -- The Odd Keystone and spirit fragments use custom event sprites rather
  -- than Poke Ball item graphics.
  ---------------------------------------------------------------------------
  ;(function()

  local FLAGS = {
    started = "EVENT_MARS_SPIRITOMB_STARTED",
    manFled = "EVENT_MARS_SPIRITOMB_MAN_FLED",
    keystoneTaken = "EVENT_MARS_SPIRITOMB_KEYSTONE_TAKEN",
    briefed = "EVENT_MARS_SPIRITOMB_FUJI_BRIEFED",
    anger = "EVENT_MARS_SPIRITOMB_ANGER_CALMED",
    sorrow = "EVENT_MARS_SPIRITOMB_SORROW_CALMED",
    maliceLured = "EVENT_MARS_SPIRITOMB_MALICE_LURED",
    malice = "EVENT_MARS_SPIRITOMB_MALICE_CALMED",
    blessed = "EVENT_MARS_SPIRITOMB_KEYSTONE_BLESSED",
    caught = "EVENT_CAUGHT_MARS_SPIRITOMB",
    complete = "EVENT_MARS_SPIRITOMB_108_COMPLETE",
  }

  -- one-time post-Mew epilogue with Mr. Fuji.
  local MEW_FUJI_EPILOGUE_FLAG = "EVENT_MARS_MEW_FUJI_EPILOGUE_SEEN"
  local MEW_FUJI_MEW_NAME = "MARS_MEW_FUJI_MEW"
  local MEW_FUJI_MEWTWO_NAME = "MARS_MEW_FUJI_MEWTWO"

  -- do NOT leave the possessed man on his vanilla Lavender text id.
  -- TEXT_LAVENDERTOWN_COOLTRAINER_M is connected to vanilla Mr. Fuji rescue
  -- behavior, which can replay Fuji's pre-rescue scene and warp the player.
  local VANILLA_TEXT_MAN = "TEXT_LAVENDERTOWN_COOLTRAINER_M"
  local TEXT_MAN = "TEXT_MARS_SPIRITOMB_POSSESSED_MAN"
  local TEXT_KEYSTONE = "TEXT_MARS_SPIRITOMB_KEYSTONE"
  local TEXT_TOWER_MAN = "TEXT_MARS_SPIRITOMB_TOWER_MAN"
  local TEXT_FINAL = "TEXT_MARS_SPIRITOMB_FINAL"
  local TEXT_ANGER = "TEXT_MARS_SPIRITOMB_ANGER"
  local TEXT_SORROW = "TEXT_MARS_SPIRITOMB_SORROW"
  local TEXT_MALICE = "TEXT_MARS_SPIRITOMB_MALICE"

  local lavenderDef = mod.content.maps:get("LAVENDER_TOWN")
  local fujiHouseDef = mod.content.maps:get("MR_FUJIS_HOUSE")
  local tower3Def = mod.content.maps:get("POKEMON_TOWER_3F")
  local tower5Def = mod.content.maps:get("POKEMON_TOWER_5F")
  local tower6Def = mod.content.maps:get("POKEMON_TOWER_6F")
  local tower7Def = mod.content.maps:get("POKEMON_TOWER_7F")

  if not lavenderDef
     or not fujiHouseDef
     or not tower3Def
     or not tower5Def
     or not tower6Def
     or not tower7Def
  then
    mod.log:error(
      "108 Voices requires Lavender, Mr. Fuji's house, and Tower 3F/5F/6F/7F"
    )
    return
  end

  ---------------------------------------------------------------------------
  -- LOCATE/NAMING VANILLA NPCS
  ---------------------------------------------------------------------------

  local possessedManDef = nil
  for _, obj in ipairs(lavenderDef.objects or {}) do
    if obj.text == VANILLA_TEXT_MAN then
      possessedManDef = obj

      -- leave the vanilla NPC's text/script completely untouched before
      -- Mr. Fuji is rescued. Give it a name only so we can swap it out after
      -- the main-story rescue is finished.
      obj.name = "MARS_SPIRITOMB_VANILLA_MAN"
      break
    end
  end

  if not possessedManDef then
    mod.log:error("could not locate the Lavender NPC used for 108 Voices")
    return
  end

  mod.log:info(
    "108 Voices: vanilla Lavender NPC preserved until Fuji rescue"
  )

  local fujiDef = nil

  -- target the actual Mr. Fuji old-man NPC, not whichever object happens
  -- to have "FUJI" in its generated map/object name. In vanilla Red he stands
  -- at cell (3,1) in MR_FUJIS_HOUSE.
  for _, obj in ipairs(fujiHouseDef.objects or {}) do
    if obj.x == 3 and obj.y == 1 then
      fujiDef = obj
      break
    end
  end

  -- Defensive fallback in case another map edit moves him later.
  if not fujiDef then
    for _, obj in ipairs(fujiHouseDef.objects or {}) do
      if obj.sprite == "SPRITE_MR_FUJI" then
        fujiDef = obj
        break
      end
    end
  end

  if fujiDef then
    fujiDef.name = "MARS_SPIRITOMB_MR_FUJI"
    mod.log:info(
      "108 Voices: Mr. Fuji bound to old-man NPC at (%s,%s)",
      tostring(fujiDef.x), tostring(fujiDef.y)
    )
  else
    mod.log:error("could not locate the old-man Mr. Fuji in MR_FUJIS_HOUSE")
    return
  end

  local fujiTextId = fujiDef.text
  if not fujiTextId then
    mod.log:error("Mr. Fuji object has no text id")
    return
  end

  ---------------------------------------------------------------------------
  -- SMALL SAFE-SPOT HELPER FOR THE NEW TOWER OBJECTS
  ---------------------------------------------------------------------------

  local MapDef = require("src.world.Map")

  local function key(x, y)
    return tostring(x) .. ":" .. tostring(y)
  end

  local function walkable(def, x, y)
    local tileset = mod.content.tilesets:get(def.tileset)
    return tileset
      and x >= 0 and y >= 0
      and x < def.width * 2 and y < def.height * 2
      and MapDef.defIsWalkableCell(def, tileset, x, y)
      and not MapDef.defIsWaterCell(def, tileset, x, y)
  end

  local function usedCells(def)
    local used = {}
    for _, obj in ipairs(def.objects or {}) do
      if obj.x ~= nil and obj.y ~= nil then
        used[key(obj.x, obj.y)] = true
      end
    end
    for _, warp in ipairs(def.warps or {}) do
      if warp.x ~= nil and warp.y ~= nil then
        used[key(warp.x, warp.y)] = true
      end
    end
    return used
  end

  local function nearestOpen(def, preferredX, preferredY, used)
    local bestX, bestY, bestScore = nil, nil, math.huge
    for y = 1, def.height * 2 - 2 do
      for x = 1, def.width * 2 - 2 do
        local k = key(x, y)
        if not used[k] and walkable(def, x, y) then
          local score =
            math.abs(x - preferredX) + math.abs(y - preferredY)
          if score < bestScore then
            bestScore = score
            bestX, bestY = x, y
          end
        end
      end
    end
    if bestX then used[key(bestX, bestY)] = true end
    return bestX or preferredX, bestY or preferredY
  end

  local used3 = usedCells(tower3Def)
  local used5 = usedCells(tower5Def)
  local used6 = usedCells(tower6Def)
  local used7 = usedCells(tower7Def)

  local angerX, angerY = nearestOpen(
    tower3Def,
    math.floor(tower3Def.width),
    math.floor(tower3Def.height * 1.15),
    used3
  )

  local sorrowX, sorrowY = nearestOpen(
    tower5Def,
    math.floor(tower5Def.width * 1.45),
    math.floor(tower5Def.height),
    used5
  )

  local maliceX, maliceY = nearestOpen(
    tower6Def,
    math.floor(tower6Def.width * 0.65),
    math.floor(tower6Def.height * 1.15),
    used6
  )

  -- Malice first slips away to a second open point on 6F before Banette
  -- finally turns on the player.
  local maliceLureX, maliceLureY = nearestOpen(
    tower6Def,
    maliceX + 4,
    maliceY + 2,
    used6
  )

  -- Put the possessed man near the place Mr. Fuji occupied on 7F if that
  -- vanilla object still exists in the imported map definition.
  local towerFuji = nil
  for _, obj in ipairs(tower7Def.objects or {}) do
    if obj.sprite == "SPRITE_MR_FUJI" then
      towerFuji = obj
      break
    end
  end

  local preferredManX = towerFuji and towerFuji.x
    or math.floor(tower7Def.width)
  local preferredManY = towerFuji and towerFuji.y
    or 4

  -- The vanilla Mr. Fuji object is gone by the time this quest can start, so
  -- allow the new possessed man to occupy that same dramatic spot.
  if towerFuji then
    used7[key(towerFuji.x, towerFuji.y)] = nil
  end

  local towerManX, towerManY =
    nearestOpen(tower7Def, preferredManX, preferredManY, used7)

  local finalX, finalY =
    nearestOpen(tower7Def, towerManX + 1, towerManY, used7)

  ---------------------------------------------------------------------------
  -- CUSTOM EVENT SPRITES
  ---------------------------------------------------------------------------

  mod.content.sprites:register("SPRITE_MARS_ODD_KEYSTONE", {
    image = mod.assets:path("assets/spiritomb_odd_keystone.png"),
    frames = 1,
    walker = false,
  })

  mod.content.sprites:register("SPRITE_MARS_SPIRIT_FRAGMENT", {
    image = mod.assets:path("assets/spiritomb_fragment.png"),
    frames = 1,
    walker = false,
  })

  ---------------------------------------------------------------------------
  -- NEW OBJECTS
  ---------------------------------------------------------------------------

  local possessedManIndex = #(lavenderDef.objects or {}) + 1
  local keystoneIndex = possessedManIndex + 1
  local angerIndex = #(tower3Def.objects or {}) + 1
  local sorrowIndex = #(tower5Def.objects or {}) + 1
  local maliceIndex = #(tower6Def.objects or {}) + 1
  local towerManIndex = #(tower7Def.objects or {}) + 1
  local finalIndex = towerManIndex + 1

  ---------------------------------------------------------------------------
  -- MEW / MEWTWO EPILOGUE STAGING IN MR. FUJI'S HOUSE
  ---------------------------------------------------------------------------

  local fujiMaxObjectIndex = 0
  for _, obj in ipairs(fujiHouseDef.objects or {}) do
    fujiMaxObjectIndex = math.max(fujiMaxObjectIndex, obj.index or 0)
  end

  local mewFujiMewIndex = fujiMaxObjectIndex + 1
  local mewFujiMewtwoIndex = fujiMaxObjectIndex + 2

  -- Keep the tile immediately below Fuji clear for the player. The two Pokemon
  -- settle into the nearest open cells on either side of that conversation lane.
  local fujiUsed = usedCells(fujiHouseDef)
  fujiUsed[key(fujiDef.x, fujiDef.y + 1)] = true

  local mewFujiMewX, mewFujiMewY = nearestOpen(
    fujiHouseDef,
    fujiDef.x - 1,
    fujiDef.y + 1,
    fujiUsed
  )

  local mewFujiMewtwoX, mewFujiMewtwoY = nearestOpen(
    fujiHouseDef,
    fujiDef.x + 1,
    fujiDef.y + 1,
    fujiUsed
  )

  mod.content.maps:patch("MR_FUJIS_HOUSE", {
    objects = {
      __append = {
        {
          index = mewFujiMewIndex,
          name = MEW_FUJI_MEW_NAME,
          sprite = "SPRITE_MONSTER",
          movement = "STAY",
          range = "NONE",
          x = mewFujiMewX,
          y = mewFujiMewY,
          hidden = true,
        },
        {
          index = mewFujiMewtwoIndex,
          name = MEW_FUJI_MEWTWO_NAME,
          sprite = "SPRITE_MONSTER",
          movement = "STAY",
          range = "NONE",
          x = mewFujiMewtwoX,
