  ---------------------------------------------------------------------------
  -- TALK / CUTSCENE HELPERS
  ---------------------------------------------------------------------------

  local TextBox = require("src.render.TextBox")

  local function say(game, textId, done)
    game.stack:push(
      TextBox.new(game, game.data.text[textId] or textId, done)
    )
  end

  local function faceNpc(ow, npc)
    if npc and npc.facePlayer and ow and ow.player then
      npc:facePlayer(ow.player)
    end
  end

  local function allFragments(flags)
    return flags[FLAGS.anger]
      and flags[FLAGS.sorrow]
      and flags[FLAGS.malice]
  end

  local function knockbackDirection(ow, npc)
    local player = ow and ow.player
    if not player or not npc then return "down" end

    local nx = npc.cellX or npc.x or possessedManDef.x
    local ny = npc.cellY or npc.y or possessedManDef.y
    local dx = player.cellX - nx
    local dy = player.cellY - ny

    if math.abs(dx) > math.abs(dy) then
      return dx < 0 and "left" or "right"
    end
    return dy < 0 and "up" or "down"
  end

  local function possessedManTalk(game, ow, npc, done)
    local flags = game.save.flags or {}

    if flags[FLAGS.complete] or flags[FLAGS.caught] then
      faceNpc(ow, npc)
      say(game, "_MARS_108_MAN_THANKS", done)
      return
    end

    if not flags.EVENT_RESCUED_MR_FUJI then
      faceNpc(ow, npc)
      say(
        game,
        "This town is known for\nPOKEMON graves.\f"
          .. "POKEMON TOWER watches over\nthem.",
        done
      )
      return
    end

    if flags[FLAGS.started] then
      if done then done() end
      return
    end

    faceNpc(ow, npc)

    say(game, "_MARS_108_MAN_POSSESSED", function()
      game.stack:push(TextBox.new(
        game,
        game.data.text._MARS_108_KNOCK_ASK,
        nil,
        {
          choice = function(yes)
            if not yes then
              say(game, "_MARS_108_DECLINE", done)
              return
            end

            local away = knockbackDirection(ow, npc)

            if done then done() end
            ow:queueScript({
              { "show_text", "_MARS_108_FORCE" },
              { "play_cry", "SPIRITOMB" },
              { "move_player", away, 1 },
              { "show_text", "_MARS_108_THROWN" },
              { "fade", "out", 20 },
              { "set_flag", FLAGS.started },
              { "set_flag", FLAGS.manFled },

              -- Keep the legacy flag meaningful for old saves/tools.
              { "set_flag", "EVENT_MARS_SPIRITOMB_RELEASED" },

              {
                "hide_object",
                "LAVENDER_TOWN",
                "MARS_SPIRITOMB_POSSESSED_MAN",
              },
              {
                "show_object",
                "LAVENDER_TOWN",
                "MARS_SPIRITOMB_KEYSTONE",
              },
              { "fade", "in", 20 },
            })
          end,
        }
      ))
    end)
  end

  local function mewFujiPartyHas(save, species)
    for _, mon in ipairs((save and save.party) or {}) do
      if mon and mon.species == species then
        return true
      end
    end
    return false
  end

  local function mewFujiDirectionToward(fromX, fromY, toX, toY)
    local dx = toX - fromX
    local dy = toY - fromY

    if math.abs(dx) > math.abs(dy) then
      return dx >= 0 and "right" or "left"
    end

    if dy ~= 0 then
      return dy >= 0 and "down" or "up"
    end

    return "down"
  end

  local function mewFujiOpposite(direction)
    return ({
      up = "down",
      down = "up",
      left = "right",
      right = "left",
    })[direction] or "down"
  end

  local function mewFujiEpilogueReady(game)
    local save = game and game.save
    local flags = save and save.flags or {}

    return flags.EVENT_CAUGHT_MARS_MEW
      and not flags[MEW_FUJI_EPILOGUE_FLAG]
      and mewFujiPartyHas(save, "MEW")
      and mewFujiPartyHas(save, "MEWTWO")
  end

  local function runMewFujiEpilogue(game, ow, done)
    local player = ow and ow.player
    local playerX = player and player.cellX or (fujiDef.x)
    local playerY = player and player.cellY or (fujiDef.y + 2)

    local mewFaceFuji = mewFujiDirectionToward(
      mewFujiMewX, mewFujiMewY, fujiDef.x, fujiDef.y
    )
    local mewtwoFaceFuji = mewFujiDirectionToward(
      mewFujiMewtwoX, mewFujiMewtwoY, fujiDef.x, fujiDef.y
    )
    local mewFaceMewtwo = mewFujiDirectionToward(
      mewFujiMewX, mewFujiMewY, mewFujiMewtwoX, mewFujiMewtwoY
    )
    local mewtwoFaceMew = mewFujiDirectionToward(
      mewFujiMewtwoX, mewFujiMewtwoY, mewFujiMewX, mewFujiMewY
    )

    if done then done() end

    ow:queueScript({
      { "show_text", "_MARS_MEW_FUJI_RELEASE" },

      -- MEW emerges first and approaches Fuji.
      { "show_object", "MR_FUJIS_HOUSE", MEW_FUJI_MEW_NAME },
      { "place_npc", mewFujiMewIndex, playerX, playerY, "up" },
      { "play_cry", "MEW" },
      { "move_npc_to", mewFujiMewIndex, mewFujiMewX, mewFujiMewY },
      { "face_object", mewFujiMewIndex, mewFaceFuji },
      { "wait", 8 },

      -- MEWTWO follows, but keeps a more guarded posture.
      { "show_object", "MR_FUJIS_HOUSE", MEW_FUJI_MEWTWO_NAME },
      { "place_npc", mewFujiMewtwoIndex, playerX, playerY, "up" },
      { "play_cry", "MEWTWO" },
      { "move_npc_to", mewFujiMewtwoIndex, mewFujiMewtwoX, mewFujiMewtwoY },
      { "face_object", mewFujiMewtwoIndex, mewtwoFaceFuji },
      { "wait", 10 },

      { "show_text", "_MARS_MEW_FUJI_SHOCK" },
      { "show_text", "_MARS_MEW_FUJI_CONFESSION_1" },
      { "show_text", "_MARS_MEW_FUJI_CONFESSION_2" },
      { "show_text", "_MARS_MEW_FUJI_DESTRUCTION" },
      { "show_text", "_MARS_MEW_FUJI_APOLOGY" },

      { "play_cry", "MEW" },
      { "show_text", "_MARS_MEW_FUJI_MEW_RESPONSE" },
      { "show_text", "_MARS_MEW_FUJI_MEWTWO_RESPONSE" },

      -- The two Pokemon silently regard one another before deciding to return.
      { "face_object", mewFujiMewIndex, mewFaceMewtwo },
      { "face_object", mewFujiMewtwoIndex, mewtwoFaceMew },
      { "wait", 30 },
      { "show_text", "_MARS_MEW_FUJI_SILENCE" },
      { "face_object", mewFujiMewtwoIndex, mewFujiOpposite(mewtwoFaceFuji) },
      { "wait", 12 },

      { "show_text", "_MARS_MEW_FUJI_RETURN" },
      { "hide_object", "MR_FUJIS_HOUSE", MEW_FUJI_MEW_NAME },
      { "hide_object", "MR_FUJIS_HOUSE", MEW_FUJI_MEWTWO_NAME },

      { "show_text", "_MARS_MEW_FUJI_REDEMPTION" },
      { "set_flag", MEW_FUJI_EPILOGUE_FLAG },
    })
  end

  local function fujiTalk(game, ow, npc, done)
    local flags = game.save.flags or {}
    local inventory = game.save.inventory or {}

    faceNpc(ow, npc)

    -- Preserve Mr. Fuji's required main-story Poke Flute reward before using
    -- him for the side quest.
    if flags.EVENT_RESCUED_MR_FUJI and not inventory.POKE_FLUTE then
      say(game, "_MARS_108_FUJI_FLUTE_INTRO", function()
        local Bag = require("src.inventory.Bag")
        if not Bag.add(game.save, "POKE_FLUTE", 1, game.data) then
          say(game, "_MARS_108_FUJI_FLUTE_FULL", done)
          return
        end

        local Sound = require("src.core.Sound")
        Sound.play(game.data, "Get_Item1")
        say(game, "_MARS_108_FUJI_FLUTE_GOT", done)
      end)
      return
    end

    -- Mew's Faraway Island epilogue. The main-story Poke Flute remains
    -- higher priority, but this scene takes precedence over optional side-quest
    -- dialogue once both MEW and MEWTWO are physically in the player's party.
    if mewFujiEpilogueReady(game) then
      runMewFujiEpilogue(game, ow, done)
      return
    end

    if flags[FLAGS.caught] and not flags[FLAGS.complete] then
      say(game, "_MARS_108_FUJI_EPILOGUE", function()
        flags[FLAGS.complete] = true

        if done then done() end
        ow:queueScript({
          {
            "hide_object",
            "POKEMON_TOWER_7F",
            "MARS_SPIRITOMB_TOWER_MAN",
          },
          {
            "show_object",
            "LAVENDER_TOWN",
            "MARS_SPIRITOMB_POSSESSED_MAN",
          },
        })
      end)
      return
    end

    if flags[FLAGS.keystoneTaken] and not flags[FLAGS.briefed] then
      flags[FLAGS.briefed] = true
      say(game, "_MARS_108_FUJI_BRIEF", done)
      return
    end

    if flags[FLAGS.briefed]
       and allFragments(flags)
       and not flags[FLAGS.blessed]
    then
      flags[FLAGS.blessed] = true
      say(game, "_MARS_108_FUJI_BLESS", done)
      return
    end

    if flags[FLAGS.briefed] and not allFragments(flags) then
      say(game, "_MARS_108_FUJI_PROGRESS", done)
      return
    end

    if flags[FLAGS.blessed] and not flags[FLAGS.caught] then
      say(game, "_MARS_108_FUJI_BLESSED_REMINDER", done)
      return
    end

    say(game, "_MARS_108_FUJI_NORMAL", done)
  end

  local function towerManTalk(game, ow, npc, done)
    local flags = game.save.flags or {}
    faceNpc(ow, npc)

    if flags[FLAGS.caught] then
      say(game, "_MARS_108_MAN_SAVED", done)
    elseif flags[FLAGS.blessed] then
      say(game, "_MARS_108_TOWER_MAN_READY", done)
    else
      say(game, "_MARS_108_TOWER_MAN_EARLY", done)
    end
  end

