  ---------------------------------------------------------------------------
  -- RED / BLUE VERSION EXCLUSIVES
  --
  -- The imported ROM keeps its native encounter tables, then this section
  -- fills in whichever counterpart is missing. Existing native encounters are
  -- left alone, so Red and Blue both end up with access to both exclusives.
  ---------------------------------------------------------------------------

  local function encounterHasSpecies(requestedMapId, terrain, speciesId)
    local encounterId = encounterIdsByNormalizedName[
      normalizeEncounterId(requestedMapId)
    ]

    if not encounterId then return false end

    local encounter = mod.content.encounters:get(encounterId)
    local terrainData = encounter and encounter[terrain]
    local slots = terrainData and terrainData.slots

    if type(slots) ~= "table" then return false end

    for _, slot in ipairs(slots) do
      if slot.species == speciesId then
        return true
      end
    end

    return false
  end

  local function speciesAlreadyAvailable(config)
    for _, requestedMapId in ipairs(config.maps or {}) do
      if encounterHasSpecies(requestedMapId, config.terrain, config.species) then
        return true
      end
    end

    return false
  end

  local versionExclusiveCount = 0

  local function ensureVersionExclusive(config)
    if speciesAlreadyAvailable(config) then
      mod.log:info(
        "%s is already available in this ROM's encounter tables",
        config.species
      )
      return false
    end

    if addExpandedEncounter(config) then
      versionExclusiveCount = versionExclusiveCount + 1
      return true
    end

    return false
  end

  -- Ekans / Sandshrew occupy analogous early and mid-game route niches.
  ensureVersionExclusive({
    species = "EKANS",
    maps = { "ROUTE_4", "ROUTE_8", "ROUTE_9", "ROUTE_10", "ROUTE_11" },
    terrain = "grass",
    relatedSpecies = { "SANDSHREW", "RATTATA", "SPEAROW" },
