  ---------------------------------------------------------------------------
  -- FOSSILS, GAME CORNER, AND POSTGAME LEGENDARIES
  ---------------------------------------------------------------------------
  ;(function()
  ---------------------------------------------------------------------------
  -- FOSSILS: JAW FOSSIL + SAIL FOSSIL
  ---------------------------------------------------------------------------

  -- The Jaw Fossil remains a hidden Rock Tunnel pickup. The Sail Fossil has
  -- moved to Alabaster Cave B1F as a normal visible map object, so Seafoam no
  -- longer receives a second hidden copy.
  --
  -- JAW FOSSIL: Rock Tunnel B1F, cell (11,14), immediately in front of the
  -- stationary Cooltrainer F at (11,13).
  if mod.content.field then
    local hidden = mod.content.field:get("hiddenItems")
    local updatedHidden = {}

    if type(hidden) == "table" then
      for mapId, rows in pairs(hidden) do
        updatedHidden[mapId] = {}
        for i, row in ipairs(rows or {}) do
          updatedHidden[mapId][i] = {
            x = row.x,
            y = row.y,
            item = row.item,
          }
        end
      end
    end

    local function addHidden(mapId, x, y, itemId)
      updatedHidden[mapId] = updatedHidden[mapId] or {}
      local rows = updatedHidden[mapId]

      -- A hidden-item pickup is keyed by map + coordinate. Remove any prior
      -- row at our chosen cell so another item cannot steal the persistent
      -- "taken" flag.
      for i = #rows, 1, -1 do
        if rows[i].x == x and rows[i].y == y then
          table.remove(rows, i)
        end
      end

      rows[#rows + 1] = { x = x, y = y, item = itemId }
      mod.log:info("Placed %s at %s (%d,%d)", itemId, mapId, x, y)
    end

    addHidden("ROCK_TUNNEL_B1F", 11, 14, "JAW_FOSSIL")
    mod.content.field:override("hiddenItems", updatedHidden)
  end

  -- Extend the normal Cinnabar resurrection scientist to recognize all five
  -- fossils. This function intentionally mirrors the base interaction so the
  -- existing leave-and-return revival timing remains intact.
  local expandedFossilMons = {
    DOME_FOSSIL = "KABUTO",
    HELIX_FOSSIL = "OMANYTE",
    OLD_AMBER = "AERODACTYL",
    JAW_FOSSIL = "TYRUNT",
    SAIL_FOSSIL = "AMAURA",
  }
  local expandedFossilOrder = {
    "DOME_FOSSIL", "HELIX_FOSSIL", "OLD_AMBER", "JAW_FOSSIL", "SAIL_FOSSIL",
  }

  local function fillMarsFossilText(s, subs)
    s = s:gsub("{PLAYER}", subs.player or "")
    s = s:gsub("{RAM:([^}]*)}", function(name)
      return subs[name] or subs.ram or ""
    end)
    return s
  end

  if mod.content.map_scripts then
    mod.content.map_scripts:register("CINNABAR_LAB_FOSSIL_ROOM", {
      priority = 100,
      talk = {
        TEXT_CINNABARLABFOSSILROOM_SCIENTIST1 = function(game, ow, npc, done)
          local TextBox = require("src.render.TextBox")
          local t = game.data.text
          local f = game.save.flags
          local subs = { player = game.save.player.name }

          if f.EVENT_GAVE_FOSSIL_TO_LAB then
            if f.EVENT_LAB_STILL_REVIVING_FOSSIL then
              game.stack:push(TextBox.new(game,
                t._CinnabarLabFossilRoomScientist1GoForAWalkText or
                "I take a little\ntime!\fYou go for walk a\nlittle while!", done))
              return
            end

            local speciesId = game.save.labFossilMon
            subs.ram = speciesId and game.data.pokemon[speciesId]
              and game.data.pokemon[speciesId].name or ""
            f.EVENT_LAB_HANDING_OVER_FOSSIL_MON = true
            game.stack:push(TextBox.new(game,
              fillMarsFossilText(
                t._CinnabarLabFossilRoomScientist1FossilIsBackToLifeText or
                "Where were you?\fYour fossil is\nback to life!\fIt was {RAM:x}\nlike I think!",
                subs),
              function()
                if speciesId then
                  local Commands = require("src.script.Commands")
                  local ctx = { save = game.save, game = game, overworld = ow }
                  Commands.give_pokemon(ctx, speciesId, 30)
                  if not ctx.lastCheck then
                    game.stack:push(TextBox.new(game,
                      t._BoxIsFullText or "Box is full!", done))
                    return
                  end
                end
                game.save.labFossilMon = nil
                f.EVENT_GAVE_FOSSIL_TO_LAB = nil
                f.EVENT_LAB_STILL_REVIVING_FOSSIL = nil
                f.EVENT_LAB_HANDING_OVER_FOSSIL_MON = nil
                done()
              end))
            return
          end

          game.stack:push(TextBox.new(game,
            t._CinnabarLabFossilRoomScientist1Text or
            "Hiya!\fI study rare\nPOKEMON fossils!\fYou! Have you a\nfossil for me?",
            function()
              local carried = {}
              for _, fossilId in ipairs(expandedFossilOrder) do
                if (game.save.inventory[fossilId] or 0) > 0 then
                  carried[#carried + 1] = fossilId
                end
              end
              if #carried == 0 then
                game.stack:push(TextBox.new(game,
                  t._CinnabarLabFossilRoomScientist1NoFossilsText or
                  "No! Is too bad!", done))
                return
              end

              local function comeAgain()
                game.stack:push(TextBox.new(game,
                  t._CinnabarLabFossilRoomScientist1ComeAgainText or
                  "Aiyah! You come\nagain!", done))
              end

              local items = {}
              for _, fossilId in ipairs(carried) do
                local selectedFossil = fossilId
                items[#items + 1] = {
                  label = game.data.items[selectedFossil].name,
                  onSelect = function()
                    local speciesId = expandedFossilMons[selectedFossil]
                    local def = game.data.pokemon[speciesId]
                    subs.wNameBuffer = game.data.items[selectedFossil].name
                    subs.wStringBuffer = def and def.name or speciesId
                    game.stack:push(TextBox.new(game,
                      fillMarsFossilText(
                        t._CinnabarLabFossilRoomScientist1SeesFossilText or
                        "Oh! That is\n{RAM:wNameBuffer}!\fIt is fossil of\n{RAM:wStringBuffer}!\fMy Resurrection\nMachine will make\nthat POKEMON live\nagain!",
                        subs), nil, { choice = function(yes)
                          if not yes then comeAgain() return end
                          require("src.inventory.Bag").remove(game.save, selectedFossil, 1)
                          game.save.labFossilMon = speciesId
                          f.EVENT_GAVE_FOSSIL_TO_LAB = true
                          f.EVENT_LAB_STILL_REVIVING_FOSSIL = true
                          game.stack:push(TextBox.new(game,
                            fillMarsFossilText(
                              t._CinnabarLabFossilRoomScientist1TakesFossilText or
                              "{PLAYER} handed\nover {RAM:wNameBuffer}!", subs),
                            function()
                              game.stack:push(TextBox.new(game,
                                t._CinnabarLabFossilRoomScientist1GoForAWalkText2 or
                                "I take a little\ntime!\fYou go for walk a\nlittle while!", done))
                            end))
                        end }))
                  end,
                }
              end

              local Menu = require("src.ui.Menu")
              game.stack:push(Menu.new(game, items,
                { tx = 0, ty = 0, tw = 15, onCancel = comeAgain }))
            end))
        end,
      },
    })
  end

  ---------------------------------------------------------------------------
  -- GAME CORNER: REPEATABLE EEVEE + MELTAN
  ---------------------------------------------------------------------------

  if mod.content.map_scripts then
    mod.content.map_scripts:register("GAME_CORNER_PRIZE_ROOM", {
      priority = 100,
      talk = {
        TEXT_GAMECORNERPRIZEROOM_PRIZE_VENDOR_2 = function(game, ow, npc, done)
          local ListMenu = require("src.ui.ListMenu")
          local Commands = require("src.script.Commands")
          local TextBox = require("src.render.TextBox")
          local GameVersion = require("src.core.GameVersion")
          local t = game.data.text

          if not game.save.inventory.COIN_CASE then
            game.stack:push(TextBox.new(game,
              t._RequireCoinCaseText or "A COIN CASE is\nrequired!", done))
            return
          end

          local prizes
          if GameVersion.isBlue() then
            prizes = {
              { species = "PINSIR", level = 20, cost = 2500 },
              { species = "DRATINI", level = 24, cost = 4600 },
              { species = "PORYGON", level = 18, cost = 6500 },
            }
          elseif GameVersion.isYellow() then
            prizes = {
              { species = "SCYTHER", level = 30, cost = 6500 },
              { species = "PINSIR", level = 30, cost = 6500 },
              { species = "PORYGON", level = 26, cost = 9999 },
            }
          else
            prizes = {
              { species = "DRATINI", level = 18, cost = 2800 },
              { species = "SCYTHER", level = 25, cost = 5500 },
              { species = "PORYGON", level = 26, cost = 9999 },
            }
          end
          prizes[#prizes + 1] = { species = "EEVEE", level = 25, cost = 3000 }
          prizes[#prizes + 1] = { species = "MELTAN", level = 25, cost = 6500 }

          game.stack:push(TextBox.new(game,
            t._ExchangeCoinsForPrizesText or "We exchange your\ncoins for prizes.",
            function()
              local entries = {}
              for _, prize in ipairs(prizes) do
                entries[#entries + 1] = {
                  label = ("%s L%d"):format(game.data.pokemon[prize.species].name, prize.level),
                  right = tostring(prize.cost),
                  value = prize,
                }
              end
              entries[#entries + 1] = { label = "NO THANKS" }

              local list
              local function finish(message)
                list:close()
                game.stack:push(TextBox.new(game, message, done))
              end
              local function buy(prize)
                if (game.save.coins or 0) < prize.cost then
                  finish(t._SorryNeedMoreCoinsText or "Sorry, you need\nmore coins.")
                  return
                end
                local ctx = { save = game.save, game = game }
                Commands.give_pokemon(ctx, prize.species, prize.level)
                if not ctx.lastCheck then
                  finish(t._OopsYouDontHaveEnoughRoomText or "Oops! You don't\nhave enough room.")
                  return
                end
                game.save.coins = game.save.coins - prize.cost
                list:close()
                done()
              end

              list = ListMenu.new(game, "PRIZES (COINS)", entries, {
                footer = ("COINS %d"):format(game.save.coins or 0),
                onChoose = function(item)
                  local prize = item.value
                  if not prize then list:close(); done(); return end
                  local name = game.data.pokemon[prize.species].name
                  local ask = (t._SoYouWantPrizeText or "So, you want\n{RAM:wNameBuffer}?")
                    :gsub("{RAM:wNameBuffer}", name)
                  game.stack:push(TextBox.new(game, ask, nil, {
                    choice = function(yes)
                      if not yes then
                        finish(t._OhFineThenText or "Oh, fine then.")
                        return
                      end
                      buy(prize)
                    end,
                  }))
                end,
                onCancel = done,
              })
              game.stack:push(list)
            end))
        end,
      },
    })
  end


  ---------------------------------------------------------------------------
  -- ROUTE 11 / DAWN TRAIL POSTGAME APPROACH
  --
  -- Route 11 uses the user's revised TMJ, including the new north-side
  -- clearing/opening. Dawn Trail is the authored 10x18 approach map that
  -- leads toward the future Dawn Tower dungeon.
  --
  -- Access rule:
  --   * Before Champion: one guard blocks the new Route 11 opening.
  --   * After Champion: the guard disappears permanently and Dawn Trail is
  --     freely explorable, even if the Ho-Oh quest has not started yet.
  --
  -- Himiko rule:
  --   * Himiko is NOT a normal Dawn Trail resident.
  --   * She only appears here after EVENT_HO_OH_QUEST_STARTED, representing
  --     the meeting she asks the player to attend after starting her quest.
  ---------------------------------------------------------------------------
  do
