         31,  31,  31,  30, 109,  39,  11,  11,  39,  11,  11,  39,  11,  11,  11,  39,  11,  11,  39,  11,  11,  11,   1,   1,   1,  55, 125, 125, 126,  10,
         67,  67,  67, 100, 109,  68,  35,  35,  69,  11,  11,  68,  35,  35,  35,  34,  11,  11,  39,  11,  11,  11,  93, 108, 108,  10,  10,  10,  15,  15,
         67,  67,  67, 100, 109,  11,  11,  11,  11,  11,  11,  11,  11,  11,  11,  39,  11,  11,  39,  11,  11,  11,  39,  10,  10,  10,  10,  10,  15,  15,
         15,  15,  15,  15, 109,  93,  11,  11,  11,  11,  11,  11,  11,  11,  11,  38,  35,  35,  34,  11,  11,  11,  39,  10,  10,  10,  10,  10,  15,  15,
         15,  15,  15,  15,  15,  68,  35,  35,  35,  35,  35,  35,  35,  35,  35,  69,  11,  11,  68,  35,  35,  35,  69,  10,  10,  10,  10,  10,  15,  15,
      }

      local marsDawnTrailBlocks = {
         15,  15,  15,  15, 104, 105,  15,  15,  15,  15,
         15,  15,  15,  15, 104, 105,  15,  15,  15,  15,
         15, 122, 122,  15, 124, 126,  15, 122, 122,  15,
         15, 122, 122, 122, 122,   8, 122, 122, 122,  15,
         15, 122, 122, 122, 122, 122, 122, 122,  54,  15,
         15,  15,  15,  15,  15, 111,  15,  15,  76,  15,
         15, 122,  76, 110,  15,  15, 122, 122, 122,  15,
         15,  76,  15, 122,  15, 122, 122,  54,  76,  15,
         15,  10,  15, 122, 110, 110,  15,  10, 108,  15,
         15, 109,  15, 108, 110,  15,  15,  15, 122,  15,
         15, 122,  15, 122,  15,  15, 122,  15, 122,  15,
         15, 122,  15, 122,  76, 122, 122, 122, 111,  15,
         15, 122,  15,  10, 108, 109,  15,  15, 109,  15,
         15, 110,  15, 108, 108, 108, 108, 109,  10,  15,
         15, 122, 108, 108,  54, 110,  76, 122, 109,  15,
         15, 122, 108, 108, 108, 110, 108, 108, 109,  15,
         15, 110, 108, 108, 108, 108,  10, 109, 122,  15,
         15,  15,  15,  15,  15,  10,  15,  15,  15,  15,
      }

      -- The authored openings are one 32px block wide, i.e. two 16px
      -- movement cells. Mirror the paired-edge-warp setup already used by
      -- Celadon Woods so either half of the opening transitions correctly.
      local ROUTE11_DAWN_X1 = 48
      local ROUTE11_DAWN_X2 = 49
      local ROUTE11_DAWN_Y  = 0

      -- the visible Route 11 guard belongs at the narrow approach into
      -- the new clearing, not on the north-edge warp itself. This is the tile
      -- the player was standing on in the user's test screenshot.
      local ROUTE11_GUARD_X = 49
      local ROUTE11_GUARD_Y = 1

      local DAWN_RETURN_X1 = 10
      local DAWN_RETURN_X2 = 11
      local DAWN_RETURN_Y  = 35

      local route11DawnWarp1 = #(route11Def.warps or {}) + 1
      local route11DawnWarp2 = route11DawnWarp1 + 1
      local route11GuardIndex = #(route11Def.objects or {}) + 1

      local TEXT_GUARD = "TEXT_MARS_ROUTE11_DAWN_GUARD"
      local TEXT_HIMIKO = "TEXT_MARS_DAWN_TRAIL_HIMIKO"

      mod.content.text:register(
