      -----------------------------------------------------------------------
      -- Route 11 revised terrain + paired Dawn Trail entrance.
      -----------------------------------------------------------------------
      mod.content.maps:patch("ROUTE_11", {
        width = 30,
        height = 9,
        borderBlock = 15,
        blocks = marsRoute11DawnBlocks,

        warps = {
          __append = {
