            {
              x = ROUTE11_DAWN_X2,
              y = ROUTE11_DAWN_Y,
              destMap = "DAWN_TRAIL",
              destWarp = 2,
            },
          },
        },

        objects = {
          __append = {
            {
              index = route11GuardIndex,
              name = "MARS_ROUTE11_DAWN_GUARD",
              sprite = "SPRITE_GUARD",
              movement = "STAY",
              range = "DOWN",
              x = ROUTE11_GUARD_X,
              y = ROUTE11_GUARD_Y,
              text = TEXT_GUARD,
            },
          },
        },
      })

      -----------------------------------------------------------------------
      -- Dawn Trail authored map.
      -----------------------------------------------------------------------
      local dawnProbe = {
        id = "DAWN_TRAIL",
        tileset = "OVERWORLD",
        width = 10,
        height = 18,
        borderBlock = 15,
        blocks = marsDawnTrailBlocks,
      }

      local usedDawnCells = {}

      local function dawnCellKey(x, y)
        return tostring(x) .. ":" .. tostring(y)
      end

      local function nearestDawnOpen(preferredX, preferredY, radius)
        radius = radius or 10

        for r = 0, radius do
          for dy = -r, r do
            for dx = -r, r do
              if r == 0 or math.max(math.abs(dx), math.abs(dy)) == r then
                local x = preferredX + dx
                local y = preferredY + dy
                local key = dawnCellKey(x, y)

                if x >= 1 and y >= 1
                   and x < dawnProbe.width * 2 - 1
                   and y < dawnProbe.height * 2 - 1
                   and not usedDawnCells[key]
                   and MapDef.defIsWalkableCell(
                     dawnProbe,
                     overworldTileset,
                     x,
                     y
                   )
                then
                  usedDawnCells[key] = true
                  return x, y
                end
              end
            end
          end
        end

        usedDawnCells[dawnCellKey(preferredX, preferredY)] = true
        return preferredX, preferredY
      end

      -- User-marked staging: Himiko immediately below the tower, one item in
      -- the lower half of the trail. Exact cells are nudged only if authored
      -- terrain says the preferred cell is not walkable.
      local himikoX, himikoY = nearestDawnOpen(10, 6, 8)
      local itemX, itemY = nearestDawnOpen(10, 28, 8)

      ---------------------------------------------------------------------
      -- Dawn Trail trainer placement.
      --
      -- Trainer approach movement in Gen 1 is scripted, so each trainer is
      -- deliberately placed where at least two movement cells directly in
      -- front of them are continuously walkable. This keeps normal trainer
      -- sight behavior without letting them walk through terrain.
      ---------------------------------------------------------------------
      usedDawnCells[dawnCellKey(9, 5)] = true   -- Dawn Tower door
      usedDawnCells[dawnCellKey(11, 7)] = true  -- Dawn Tower sign
      usedDawnCells[dawnCellKey(DAWN_RETURN_X1, DAWN_RETURN_Y)] = true
      usedDawnCells[dawnCellKey(DAWN_RETURN_X2, DAWN_RETURN_Y)] = true

      local dawnDirections = {
        { name = "DOWN",  dx = 0,  dy = 1 },
        { name = "UP",    dx = 0,  dy = -1 },
        { name = "RIGHT", dx = 1,  dy = 0 },
        { name = "LEFT",  dx = -1, dy = 0 },
      }

      local function dawnSightLength(x, y, dir, maxRange)
        local clear = 0

        for step = 1, maxRange do
          local tx = x + dir.dx * step
          local ty = y + dir.dy * step

          if tx < 1 or ty < 1
             or tx >= dawnProbe.width * 2 - 1
             or ty >= dawnProbe.height * 2 - 1
             or usedDawnCells[dawnCellKey(tx, ty)]
             or not MapDef.defIsWalkableCell(
               dawnProbe,
               overworldTileset,
               tx,
               ty
             )
          then
            break
          end

          clear = clear + 1
        end

        return clear
      end

      ---------------------------------------------------------------------
      -- Dawn Trail trainer placement now protects traversal, not just
      -- trainer sight lines.
      --
      -- only checked whether the tiles IN FRONT of a trainer were
      -- walkable. A trainer could therefore still stand in a one-cell choke
      -- point, or walk one tile forward after spotting the player and become
      -- a new choke point after the battle.
      --
      -- requires:
      --   1. the trainer's starting cell is in an open area;
      --   2. the first approach cell is also in an open area;
      --   3. blocking either cell still leaves a walkable route between the
      --      lower Route 11 entrance and the Dawn Tower entrance.
      ---------------------------------------------------------------------
      local function dawnIsOpenCell(x, y)
        return x >= 1
          and y >= 1
          and x < dawnProbe.width * 2 - 1
          and y < dawnProbe.height * 2 - 1
          and MapDef.defIsWalkableCell(
            dawnProbe,
            overworldTileset,
            x,
            y
          )
      end

      local function dawnWalkableNeighbors(x, y)
        local count = 0
        for _, dir in ipairs(dawnDirections) do
          if dawnIsOpenCell(x + dir.dx, y + dir.dy) then
            count = count + 1
          end
        end
        return count
      end

      local function dawnNearestOpenTo(x, y)
        for radius = 0, 4 do
          for dy = -radius, radius do
            for dx = -radius, radius do
              if radius == 0
                 or math.max(math.abs(dx), math.abs(dy)) == radius
              then
                local tx = x + dx
                local ty = y + dy
                if dawnIsOpenCell(tx, ty) then
                  return tx, ty
                end
              end
            end
          end
        end
        return nil, nil
      end

      -- Use interior cells immediately beside the two authored endpoints.
      local dawnBottomX, dawnBottomY = dawnNearestOpenTo(
        DAWN_RETURN_X1,
        DAWN_RETURN_Y - 1
      )
      local dawnTopX, dawnTopY = dawnNearestOpenTo(9, 6)

      local function dawnRouteExistsWithBlocked(blockedX, blockedY)
        if not dawnBottomX or not dawnTopX then
          return false
        end

        local function blocked(x, y)
          return x == blockedX and y == blockedY
        end

        if blocked(dawnBottomX, dawnBottomY)
           or blocked(dawnTopX, dawnTopY)
        then
          return false
        end

        local queue = {
          { x = dawnBottomX, y = dawnBottomY },
        }
        local head = 1
        local seen = {
          [dawnCellKey(dawnBottomX, dawnBottomY)] = true,
        }

        while head <= #queue do
          local cell = queue[head]
          head = head + 1

          if cell.x == dawnTopX and cell.y == dawnTopY then
            return true
          end

          for _, dir in ipairs(dawnDirections) do
            local nx = cell.x + dir.dx
            local ny = cell.y + dir.dy
            local key = dawnCellKey(nx, ny)

            if not seen[key]
               and not blocked(nx, ny)
               and dawnIsOpenCell(nx, ny)
            then
              seen[key] = true
              queue[#queue + 1] = { x = nx, y = ny }
            end
          end
        end

        return false
      end

      local function dawnTrainerCellSafe(x, y)
        -- Three or four neighbors means the trainer is standing in an open
        -- patch/intersection instead of filling a narrow one-tile lane.
        return dawnIsOpenCell(x, y)
          and dawnWalkableNeighbors(x, y) >= 3
          and dawnRouteExistsWithBlocked(x, y)
      end

      local function findDawnTrainerSpot(preferredX, preferredY, radius)
        radius = radius or 10

        for r = 0, radius do
          for dy = -r, r do
            for dx = -r, r do
              if r == 0 or math.max(math.abs(dx), math.abs(dy)) == r then
                local x = preferredX + dx
                local y = preferredY + dy
                local key = dawnCellKey(x, y)

                if not usedDawnCells[key]
                   and dawnTrainerCellSafe(x, y)
                then
                  local bestDir = nil
                  local bestRange = 0

                  for _, dir in ipairs(dawnDirections) do
                    local clear = dawnSightLength(x, y, dir, 2)
                    local approachX = x + dir.dx
                    local approachY = y + dir.dy

                    -- With trainer range 2, the trainer can finish a battle
                    -- either on the start cell or one step toward the player.
                    -- Both positions must be safe to occupy permanently.
                    if clear >= 2
                       and not usedDawnCells[
                         dawnCellKey(approachX, approachY)
                       ]
                       and dawnTrainerCellSafe(approachX, approachY)
                       and clear > bestRange
                    then
                      bestDir = dir.name
                      bestRange = clear
                    end
                  end

                  if bestDir then
                    usedDawnCells[key] = true
                    return x, y, bestDir
                  end
                end
              end
            end
          end
        end

        -- If an authored change ever leaves no large open patch near the
        -- preferred region, search the entire movement grid before falling
        -- back. This still applies the same anti-chokepoint rules.
        for y = 1, dawnProbe.height * 2 - 2 do
          for x = 1, dawnProbe.width * 2 - 2 do
            local key = dawnCellKey(x, y)

            if not usedDawnCells[key]
               and dawnTrainerCellSafe(x, y)
            then
              for _, dir in ipairs(dawnDirections) do
                local approachX = x + dir.dx
                local approachY = y + dir.dy

                if dawnSightLength(x, y, dir, 2) >= 2
                   and not usedDawnCells[
                     dawnCellKey(approachX, approachY)
                   ]
                   and dawnTrainerCellSafe(approachX, approachY)
                then
                  usedDawnCells[key] = true
                  return x, y, dir.name
                end
              end
            end
          end
        end

        error(
          "could not find a non-blocking Dawn Trail trainer position"
        )
      end

      local dawnHikerX, dawnHikerY, dawnHikerFacing =
        findDawnTrainerSpot(4, 12, 8)
      local dawnBirdX, dawnBirdY, dawnBirdFacing =
        findDawnTrainerSpot(15, 18, 8)
      local dawnCoolX, dawnCoolY, dawnCoolFacing =
        findDawnTrainerSpot(5, 24, 8)
      local dawnManiacX, dawnManiacY, dawnManiacFacing =
        findDawnTrainerSpot(15, 31, 8)

      mod.content.maps:register("DAWN_TRAIL", {
        id = "DAWN_TRAIL",
        label = "DawnTrail",
        index = 1025,
        tileset = "OVERWORLD",
        palette = "ROUTE",
        outdoor = true,
        width = 10,
        height = 18,
        borderBlock = 15,
        blocks = marsDawnTrailBlocks,
        connections = {},

        warps = {
          {
            x = DAWN_RETURN_X1,
            y = DAWN_RETURN_Y,
            destMap = "ROUTE_11",
            destWarp = route11DawnWarp1,
          },
          {
            x = DAWN_RETURN_X2,
            y = DAWN_RETURN_Y,
            destMap = "ROUTE_11",
            destWarp = route11DawnWarp2,
          },
        },

        signs = {
          { x = 11, y = 7, text = "TEXT_MARS_DAWN_TOWER_SIGN" },
        },

        objects = {
          {
            index = 1,
            name = "DAWN_TRAIL_ITEM",
            sprite = "SPRITE_POKE_BALL",
            movement = "STAY",
            range = "NONE",
            x = itemX,
            y = itemY,
            item = "MAX_REVIVE",
          },
          {
            index = 2,
            name = "MARS_DAWN_TRAIL_HIMIKO",
            sprite = "SPRITE_BEAUTY",
            movement = "STAY",
            range = "DOWN",
            x = himikoX,
            y = himikoY,
            text = TEXT_HIMIKO,
          },
          {
            index = 3,
            name = "DAWN_TRAIL_HIKER",
            sprite = "SPRITE_HIKER",
            movement = "STAY",
            range = dawnHikerFacing,
            x = dawnHikerX,
            y = dawnHikerY,
            trainerClass = "OPP_DAWN_TRAIL_HIKER",
            trainerParty = 1,
          },
          {
            index = 4,
            name = "DAWN_TRAIL_BIRD_KEEPER",
            sprite = "SPRITE_COOLTRAINER_M",
            movement = "STAY",
            range = dawnBirdFacing,
            x = dawnBirdX,
            y = dawnBirdY,
            trainerClass = "OPP_DAWN_TRAIL_BIRD_KEEPER",
            trainerParty = 1,
          },
          {
            index = 5,
            name = "DAWN_TRAIL_COOLTRAINER",
            sprite = "SPRITE_COOLTRAINER_F",
            movement = "STAY",
            range = dawnCoolFacing,
            x = dawnCoolX,
            y = dawnCoolY,
            trainerClass = "OPP_DAWN_TRAIL_COOLTRAINER",
            trainerParty = 1,
          },
          {
            index = 6,
            name = "DAWN_TRAIL_POKEMANIAC",
            sprite = "SPRITE_SUPER_NERD",
            movement = "STAY",
            range = dawnManiacFacing,
            x = dawnManiacX,
            y = dawnManiacY,
            trainerClass = "OPP_DAWN_TRAIL_POKEMANIAC",
            trainerParty = 1,
          },
        },
      })

