      -----------------------------------------------------------------------
      -- DAWN TRAIL POSTGAME ENCOUNTERS — CAVE-STYLE
      --
      -- Dawn Trail deliberately has no tall-grass tiles. Gen1Recomp stores
      -- both grass encounters and cave/tower/Mansion floor encounters in the
      -- encounter record's `grass` table; the difference is WHERE the engine
      -- rolls that table.
      --
      -- Because DAWN_TRAIL uses a custom high map index (1025) and the
      -- OVERWORLD tileset rather than the indoor-excluded FOREST tileset, the
      -- engine's vanilla indoor/cave fallback rolls this table on ordinary
      -- walkable ground. In other words: these are cave-style encounters and
      -- can happen anywhere along the trail, with no grass tile required.
      --
      -- Normal Gen 1 ten-slot weighting:
      -- 20%, 20%, 15%, 10%, 10%, 10%, 5%, 5%, 4%, 1%.
      -----------------------------------------------------------------------
      mod.content.encounters:register("DAWN_TRAIL", {
        id = "DAWN_TRAIL",
        grass = {
          rate = 15,
          slots = {
            { level = 46, species = "FEAROW"    }, -- 20%
            { level = 47, species = "RAPIDASH"  }, -- 20%
            { level = 47, species = "MURKROW"   }, -- 15%
            { level = 48, species = "MAGMAR"    }, -- 10%
            { level = 49, species = "SKARMORY"  }, -- 10%
            { level = 49, species = "PIDGEOT"   }, -- 10%
            { level = 50, species = "HONCHKROW" }, -- 5%
            { level = 51, species = "NINETALES" }, -- 5%
            { level = 52, species = "TOGETIC"   }, -- 4%
            { level = 54, species = "ARCANINE"  }, -- 1%
          },
        },
      })

      -----------------------------------------------------------------------
      -- Visibility and dialogue.
      -----------------------------------------------------------------------
      if mod.content.map_scripts then
        mod.content.map_scripts:register("ROUTE_11", {
          priority = 255,

          onEnter = function(game, ow)
            local flags = game.save.flags or {}
            ow:queueScript({
              {
                flags.EVENT_BEAT_CHAMPION_RIVAL
                  and "hide_object"
                  or "show_object",
                "ROUTE_11",
                "MARS_ROUTE11_DAWN_GUARD",
              },
            })
          end,

          talk = {
            [TEXT_GUARD] = {
              { "face_player" },
              { "show_text", "_MARS_ROUTE11_DAWN_GUARD" },
            },
          },
        })

        mod.content.map_scripts:register("DAWN_TRAIL", {
          priority = 255,

          onEnter = function(game, ow)
            local flags = game.save.flags or {}
            local showHimiko =
              flags.EVENT_HO_OH_QUEST_STARTED
              and not flags.EVENT_CAUGHT_MARS_HO_OH

            ow:queueScript({
              {
                showHimiko and "show_object" or "hide_object",
                "DAWN_TRAIL",
                "MARS_DAWN_TRAIL_HIMIKO",
              },
            })
          end,

          talk = {
            [TEXT_HIMIKO] = {
              { "face_player" },
              { "show_text", "_MARS_DAWN_TRAIL_HIMIKO" },
              { "set_flag", "EVENT_HO_OH_MET_HIMIKO_DAWN_TRAIL" },
            },
          },
        })
      end

      -----------------------------------------------------------------------
      -- Before the Champion, keep the north-edge Dawn Trail transition
      -- disabled as a second layer behind the visible guard. Once
      -- EVENT_BEAT_CHAMPION_RIVAL is set, the guard disappears AND these edge
      -- cells become usable. Thus a pre-Champion test save will intentionally
      -- be unable to enter Dawn Trail.
      -----------------------------------------------------------------------
      mod.hooks:wrap("movement.collision", function(next, allowed, ctx)
        if allowed
           and ctx
           and ctx.map
           and ctx.map.id == "ROUTE_11"
        then
          local Game = require("src.core.Game")
          local flags = Game.save and Game.save.flags or {}

          if not flags.EVENT_BEAT_CHAMPION_RIVAL
             and ctx.toY == ROUTE11_DAWN_Y
             and (
               ctx.toX == ROUTE11_DAWN_X1
               or ctx.toX == ROUTE11_DAWN_X2
             )
          then
            ctx.reason = "entity"
            return false
          end
        end

        return next(allowed, ctx)
      end, 27)

      mod.log:info(
        "installed revised Route 11 + Dawn Trail and registered the new MARS_DAWN_TOWER grayscale/Advanced Color tileset for upcoming Dawn Tower floors"
      )
    end
  end

