  local function farawayNear(x, y, tx, ty, radius)
    return math.max(math.abs(x - tx), math.abs(y - ty)) <= (radius or 4)
  end

  local function farawayFaceToward(fromX, fromY, toX, toY)
    local dx = toX - fromX
    local dy = toY - fromY
    if math.abs(dx) > math.abs(dy) then
      return dx >= 0 and "right" or "left"
    end
    if dy ~= 0 then
      return dy >= 0 and "down" or "up"
    end
    return "down"
  end

  local function farawaySightingRows(sx, sy, playerX, playerY, linger)
    local facing = farawayFaceToward(sx, sy, playerX, playerY)
    local away = ({ up = "down", down = "up", left = "right", right = "left" })[facing]
      or "up"
    return {
      { "show_object", "MARS_FARAWAY_ISLAND", FARAWAY_MEW_NAME },
      { "place_npc", FARAWAY_MEW_INDEX, sx, sy, facing },
      { "face_object", FARAWAY_MEW_INDEX, facing },
      { "play_cry", "MEW" },
      { "wait", linger },
      -- Mew turns away before slipping back into the grass. Hiding the actor here
      -- is intentionally safer than forcing a blind movement path across the
      -- authored terrain; the next sighting makes it clear where it went.
      { "face_object", FARAWAY_MEW_INDEX, away },
      { "wait", 12 },
      { "hide_object", "MARS_FARAWAY_ISLAND", FARAWAY_MEW_NAME },
      { "wait", 10 },
    }
  end

  ---------------------------------------------------------------------------
  -- CINNABAR LAB ARCHIVE RESEARCHER
  ---------------------------------------------------------------------------

  local FARAWAY_RESEARCHER_NAME = "MARS_FARAWAY_RESEARCHER"
  local FARAWAY_RESEARCHER_TEXT = "TEXT_MARS_FARAWAY_RESEARCHER"
  local farawayResearcherIndex = 1
  local farawayResearcherX, farawayResearcherY = 5, 5
  local farawayLabDef = mod.content.maps:get("CINNABAR_LAB")

  if farawayLabDef then
    local MapDef = require("src.world.Map")
    local labTileset = mod.content.tilesets:get(farawayLabDef.tileset)
    local occupied = {}
    local maxIndex = 0
    local function reserve(x, y)
      if x ~= nil and y ~= nil then
        occupied[tostring(x) .. ":" .. tostring(y)] = true
      end
    end

    for _, obj in ipairs(farawayLabDef.objects or {}) do
      reserve(obj.x, obj.y)
      maxIndex = math.max(maxIndex, obj.index or 0)
    end
    for _, sign in ipairs(farawayLabDef.signs or {}) do reserve(sign.x, sign.y) end
    for _, warp in ipairs(farawayLabDef.warps or {}) do reserve(warp.x, warp.y) end
    farawayResearcherIndex = maxIndex + 1

    local maxX = (farawayLabDef.width or 10) * 2 - 2
    local maxY = (farawayLabDef.height or 8) * 2 - 2
    local preferredX = math.max(2, math.floor((farawayLabDef.width or 10)))
    local preferredY = math.max(2, math.floor((farawayLabDef.height or 8)))

    local function usable(x, y)
      if x < 1 or y < 1 or x > maxX or y > maxY then return false end
      if occupied[tostring(x) .. ":" .. tostring(y)] then return false end
      if not labTileset then return true end
      if not MapDef.defIsWalkableCell(farawayLabDef, labTileset, x, y) then
        return false
      end
      if MapDef.defIsWaterCell
         and MapDef.defIsWaterCell(farawayLabDef, labTileset, x, y)
      then
        return false
      end
      return true
    end

    local found = false
    for radius = 0, 12 do
      for dy = -radius, radius do
        for dx = -radius, radius do
          if radius == 0 or math.max(math.abs(dx), math.abs(dy)) == radius then
            local x, y = preferredX + dx, preferredY + dy
            if usable(x, y) then
              farawayResearcherX, farawayResearcherY = x, y
              found = true
              break
            end
          end
        end
        if found then break end
      end
      if found then break end
    end

    mod.content.maps:patch("CINNABAR_LAB", {
      objects = {
        __append = {
          {
            index = farawayResearcherIndex,
            name = FARAWAY_RESEARCHER_NAME,
            sprite = "SPRITE_SCIENTIST",
            movement = "STAY",
            range = "ANY_DIR",
            x = farawayResearcherX,
            y = farawayResearcherY,
            text = FARAWAY_RESEARCHER_TEXT,
            hidden = true,
          },
        },
      },
    })
  else
    mod.log:error("Faraway Island quest requires CINNABAR_LAB")
  end

