  ---------------------------------------------------------------------------
  -- FARAWAY ISLAND OFF-MAP VOID IS WATER
  --
  -- Gen1Recomp's OVERWORLD renderer normally ignores a map's borderBlock for
  -- the space beyond the authored map and instead uses the player's global
  -- VOID FILL option (trees by default). That is why the authored water edge
  -- still ended in a large green/tree-filled rectangle at the screen border.
  --
  -- Force only Faraway Island's off-map fill to water for the duration of its
  -- border draw, then restore the player's global option immediately. This
  -- keeps every other OVERWORLD map using the player's chosen void fill.
  ---------------------------------------------------------------------------
  do
    local TileRenderer = require("src.render.TileRenderer")

    if not TileRenderer._marsFarawayWaterVoidV376 then
      TileRenderer._marsFarawayWaterVoidV376 = true
      local baseDrawBorderFill = TileRenderer.drawBorderFill

      function TileRenderer:drawBorderFill(camX, camY, viewW, viewH)
        local map = self and self.map
        if not map or map.id ~= "MARS_FARAWAY_ISLAND" then
          return baseDrawBorderFill(self, camX, camY, viewW, viewH)
        end

        local previousVoidFill = TileRenderer.voidFill
        TileRenderer.voidFill = "water"

        local ok, result = pcall(
          baseDrawBorderFill,
          self,
          camX,
          camY,
          viewW,
          viewH
        )

        TileRenderer.voidFill = previousVoidFill

        if not ok then
          error(result, 0)
        end

        return result
      end
    end
  end


