        { level = 45, species = "KINGLER"    }, -- 15%
        { level = 46, species = "SEADRA"     }, -- 10%
        { level = 46, species = "TENTACRUEL" }, -- 10%
        { level = 47, species = "PELIPPER"   }, -- 10%
        { level = 48, species = "STARMIE"    }, -- 5%
        { level = 48, species = "LANTURN"    }, -- 5%
        { level = 49, species = "KINGLER"    }, -- 4%
        { level = 50, species = "STARMIE"    }, -- 1%
      },
    },
  })

  -- Super Rod groups are native per-map field data. Registering Faraway here
  -- means the engine treats the island as a real fishing location, including
  -- the normal Super Rod bite/no-bite messaging and rejection roll.
  mod.content.field:patch("superRod", {
    MARS_FARAWAY_ISLAND = {
      { species = "KINGLER", level = 45 },
      { species = "SEADRA", level = 46 },
      { species = "STARYU", level = 47 },
      { species = "LANTURN", level = 49 },
    },
  })

  -- Old/Good Rod data is global in Gen 1, so customize only Faraway through the
  -- public fishing hook. Good Rod still delegates to the engine so its native
  -- rejection-loop bite odds are preserved. Old Rod is an always-bite rod by
  -- design, so its island-specific catch is returned directly.
  mod.hooks:wrap("encounter.fishing", function(next, rod, mapId, candidates)
    if mapId ~= "MARS_FARAWAY_ISLAND" then
      return next(rod, mapId, candidates)
    end

    if rod == "OLD_ROD" then
      return { species = "MAGIKARP", level = 35 }
    end

    if rod == "GOOD_ROD" then
      return next(rod, mapId, {
        { species = "KRABBY", level = 39 },
        { species = "HORSEA", level = 40 },
      })
    end

    return next(rod, mapId, candidates)
  end, 120)

  if mod.content.map_scripts then
    -------------------------------------------------------------------------
    -- Cinnabar archive handoff. MEWTWO ownership is read from the Pokedex so
    -- the event cannot begin from merely defeating or seeing it.
    -------------------------------------------------------------------------
    mod.content.map_scripts:register("CINNABAR_LAB", {
      priority = 120,

      onEnter = function(game, ow)
        local flags = game.save.flags or {}
        local inventory = game.save.inventory or {}

        -- Normalize old/test saves where the key item exists but the new flag
        -- was introduced later.
        if (inventory.OLD_SEA_MAP or 0) > 0 then
          flags[FARAWAY_FLAGS.mapReceived] = true
        end

        local show = flags.EVENT_BEAT_CHAMPION_RIVAL
          and farawayOwnsMewtwo(game.save)
        ow:queueScript({
          {
            show and "show_object" or "hide_object",
            "CINNABAR_LAB",
            FARAWAY_RESEARCHER_NAME,
          },
        })
      end,

      talk = {
        [FARAWAY_RESEARCHER_TEXT] = function(game, ow, npc, done)
          local flags = game.save.flags or {}

          if not farawayOwnsMewtwo(game.save) then
            if done then done() end
            return
          end

          if flags[FARAWAY_FLAGS.caught] then
            if done then done() end
            ow:queueScript({
              { "face_player" },
              { "show_text", "_MARS_FARAWAY_RESEARCHER_EPILOGUE" },
            })
            return
          end

          if flags[FARAWAY_FLAGS.mapReceived] then
            if done then done() end
            ow:queueScript({
              { "face_player" },
              { "show_text", "_MARS_FARAWAY_RESEARCHER_REMINDER" },
            })
            return
          end

          if done then done() end
          ow:queueScript({
            { "face_player" },
            { "show_text", "_MARS_FARAWAY_RESEARCHER_INTRO" },
            {
              "give_item",
              "OLD_SEA_MAP",
              1,
              "_MARS_FARAWAY_GOT_OLD_SEA_MAP",
            },
            { "set_flag", FARAWAY_FLAGS.mapReceived },
            { "show_text", "_MARS_FARAWAY_RESEARCHER_MAP" },
          })
        end,
      },
    })

    -------------------------------------------------------------------------
    -- The Vermilion sailor is transport, not the quest giver. Before the Old
    -- Sea Map exists he keeps his actual vanilla dialogue. Once shown the map,
    -- he recognizes Faraway Island and offers passage.
    -------------------------------------------------------------------------
    mod.content.map_scripts:register("VERMILION_CITY", {
      priority = 110,
      talk = {
        TEXT_VERMILIONCITY_SAILOR2 = function(game, ow, npc, done)
          local TextBox = require("src.render.TextBox")
          local MapScripts = require("src.script.MapScripts")
          local flags = game.save.flags or {}
          local inventory = game.save.inventory or {}

          if (inventory.OLD_SEA_MAP or 0) > 0 then
            flags[FARAWAY_FLAGS.mapReceived] = true
          end

          if not flags[FARAWAY_FLAGS.mapReceived] then
            local base = MapScripts.baseTalk(
              "VERMILION_CITY",
              "TEXT_VERMILIONCITY_SAILOR2"
            )
            if type(base) == "table" then
              if done then done() end
              ow:queueScript(base, { npc = npc })
            elseif type(base) == "function" then
              base(game, ow, npc, done)
            elseif done then
              done()
            end
            return
          end

          local promptId
          if flags[FARAWAY_FLAGS.caught] then
            promptId = "_MARS_VERMILION_SAILOR_AFTER_MEW"
          elseif not flags[FARAWAY_FLAGS.sailorBriefed] then
            flags[FARAWAY_FLAGS.sailorBriefed] = true
            promptId = "_MARS_VERMILION_SAILOR_MAP_FIRST"
          else
            promptId = "_MARS_VERMILION_SAILOR_MAP_REPEAT"
          end

          game.stack:push(TextBox.new(
            game,
            game.data.text[promptId],
            nil,
            {
              choice = function(yes)
                if not yes then
                  game.stack:push(TextBox.new(
                    game,
                    game.data.text._MARS_VERMILION_SAILOR_DECLINE,
                    done
                  ))
                  return
                end

                if done then done() end
                ow:queueScript({
                  { "fade", "out", 20 },
                  {
                    "warp",
                    "MARS_FARAWAY_ISLAND",
                    FARAWAY_PLAYER_X,
                    FARAWAY_PLAYER_Y,
                    "UP",
                  },
                  { "fade", "in", 20 },
                })
              end,
            }
          ))
        end,
      },
    })

    mod.content.map_scripts:register("MARS_FARAWAY_ISLAND", {
      priority = 110,

      onEnter = function(game, ow)
        -- Faraway Island is intentionally silent. Stop whatever map music
        -- carried over from Vermilion as soon as the island finishes loading.
        local Music = require("src.core.Music")
        Music.stop()

        local flags = game.save.flags or {}
        local rows = {}

        -- The arrival card is a first-visit beat, not something that repeats every
        -- time the player returns after a failed capture attempt.
        if not flags[FARAWAY_FLAGS.visited] then
          flags[FARAWAY_FLAGS.visited] = true
          rows[#rows + 1] = { "show_text", "_MARS_FARAWAY_ARRIVAL" }
        end

        if flags[FARAWAY_FLAGS.caught] then
          rows[#rows + 1] = {
            "hide_object", "MARS_FARAWAY_ISLAND", FARAWAY_MEW_NAME
          }
        elseif flags[FARAWAY_FLAGS.final] then
          -- Once the chase is finished, Mew stays in the final clearing for every
          -- retry until caught. Running away or knocking it out never restarts the
          -- three sightings.
          rows[#rows + 1] = {
            "show_object", "MARS_FARAWAY_ISLAND", FARAWAY_MEW_NAME
          }
          rows[#rows + 1] = {
            "place_npc", FARAWAY_MEW_INDEX, FARAWAY_FINAL_X, FARAWAY_FINAL_Y - 1, "down"
          }
        else
          -- Before the final reveal, the same Mew actor exists only during its
          -- scripted glimpses.
          rows[#rows + 1] = {
            "hide_object", "MARS_FARAWAY_ISLAND", FARAWAY_MEW_NAME
          }
        end

        if #rows > 0 then ow:queueScript(rows) end
      end,

      onStep = function(game, ow, x, y)
        local flags = game.save.flags or {}
        if flags[FARAWAY_FLAGS.caught] then return false end

        -- let the player get noticeably closer before each glimpse begins.
        -- The earlier radius of 4 made Mew vanish while the player still felt far
        -- away; radius 2 keeps the sighting forgiving without making it an exact
        -- trigger tile.
        if not flags[FARAWAY_FLAGS.sighting1]
           and farawayNear(x, y, FARAWAY_MEW_SIGHTING_1_X, FARAWAY_MEW_SIGHTING_1_Y, 2)
        then
          flags[FARAWAY_FLAGS.sighting1] = true
          ow:queueScript(farawaySightingRows(
            FARAWAY_MEW_SIGHTING_1_X, FARAWAY_MEW_SIGHTING_1_Y, x, y, 35
          ))
          return true
        end

        if flags[FARAWAY_FLAGS.sighting1]
           and not flags[FARAWAY_FLAGS.sighting2]
           and farawayNear(x, y, FARAWAY_MEW_SIGHTING_2_X, FARAWAY_MEW_SIGHTING_2_Y, 2)
        then
          flags[FARAWAY_FLAGS.sighting2] = true
          ow:queueScript(farawaySightingRows(
            FARAWAY_MEW_SIGHTING_2_X, FARAWAY_MEW_SIGHTING_2_Y, x, y, 55
          ))
          return true
        end

        if flags[FARAWAY_FLAGS.sighting2]
           and not flags[FARAWAY_FLAGS.sighting3]
           and farawayNear(x, y, FARAWAY_MEW_SIGHTING_3_X, FARAWAY_MEW_SIGHTING_3_Y, 2)
        then
          flags[FARAWAY_FLAGS.sighting3] = true
          ow:queueScript(farawaySightingRows(
            FARAWAY_MEW_SIGHTING_3_X, FARAWAY_MEW_SIGHTING_3_Y, x, y, 75
          ))
          return true
        end

        -- After the third glimpse, entering the northern clearing ends the chase.
        -- Mew finally stops disappearing and waits one cell above the clearing
        -- center so the player can approach and talk to it normally.
        if flags[FARAWAY_FLAGS.sighting3]
           and not flags[FARAWAY_FLAGS.final]
           and farawayNear(x, y, FARAWAY_FINAL_X, FARAWAY_FINAL_Y, 5)
        then
          flags[FARAWAY_FLAGS.final] = true
          local facing = farawayFaceToward(
            FARAWAY_FINAL_X, FARAWAY_FINAL_Y - 1, x, y
          )
          ow:queueScript({
            { "show_object", "MARS_FARAWAY_ISLAND", FARAWAY_MEW_NAME },
            {
              "place_npc", FARAWAY_MEW_INDEX,
              FARAWAY_FINAL_X, FARAWAY_FINAL_Y - 1, facing
            },
            { "face_object", FARAWAY_MEW_INDEX, facing },
            { "play_cry", "MEW" },
            { "wait", 45 },
          })
          return true
        end

        return false
      end,

      talk = {
        TEXT_MARS_FARAWAY_SAILOR = {
          { "face_player" },
          { "ask", "_MARS_FARAWAY_RETURN_ASK" },
          { "jump_if_false", "stay" },
          { "fade", "out", 20 },
          { "warp", "VERMILION_CITY", 25, 27, "UP" },
          { "fade", "in", 20 },
          { "jump", "end" },
          { "label", "stay" },
          { "show_text", "_MARS_VERMILION_SAILOR_DECLINE" },
          { "label", "end" },
        },

        TEXT_MARS_FARAWAY_MEW = {
          { "check_flag", "EVENT_CAUGHT_MARS_MEW" },
          { "jump_if_true", "already" },
          { "show_text", "_MARS_FARAWAY_MEW_TEXT" },
          { "play_cry", "MEW" },
          { "start_battle", "wild", "MEW", 50 },
          { "check_battle_result", "caught" },
          { "jump_if_false", "end" },
          { "set_flag", "EVENT_CAUGHT_MARS_MEW" },
          { "hide_object", "MARS_FARAWAY_ISLAND", FARAWAY_MEW_NAME },
          { "jump", "end" },
          { "label", "already" },
          { "show_text", "_MARS_FARAWAY_MEW_CAUGHT" },
          { "label", "end" },
        },
      },
    })
  end

  mod.log:info(
    "Faraway Island start: catch MEWTWO -> Cinnabar archive researcher -> OLD SEA MAP -> Vermilion sailor -> Faraway Island"
  )


  end)()

