  local function copyTrainerParty(party)
    local copied = {}

    for index, slot in ipairs(party or {}) do
      copied[index] = {
        level = slot.level,
        species = slot.species,
      }

      if slot.moves then
        copied[index].moves = {}
        for moveIndex, moveId in ipairs(slot.moves) do
          copied[index].moves[moveIndex] = moveId
        end
      end
    end

    return copied
  end

  mod.hooks:wrap("trainer.party", function(next, oppClass, partyIndex, partyDef)
    local key = tostring(oppClass) .. "#" .. tostring(partyIndex or 1)
    local replacement = bossTeams[key]

    if not replacement then
      return next(oppClass, partyIndex, partyDef)
    end

    mod.log:info("Using Expanded-Kanto trainer team for %s", key)
    return next(oppClass, partyIndex, copyTrainerParty(replacement))
  end, 25)


