  ---------------------------------------------------------------------------
  -- dedicated trainer records for rematches.
  --
  -- Do not append a synthetic party to the vanilla leader record. A dedicated
  -- record has exactly one party, reuses the leader's portrait/AI/money data,
  -- and cannot collide with imported party counts or the normal badge battle.
  ---------------------------------------------------------------------------
  for _, spec in ipairs(gymRematchSpecs) do
    local original = mod.content.trainers:get(spec.trainerClass) or {}

    spec.rematchTrainerClass =
      "OPP_MARS_REMATCH_" .. tostring(spec.leader):gsub("[^%w]", "_")
    spec.partyIndex = 1

    mod.content.trainers:register(spec.rematchTrainerClass, {
      id = spec.rematchTrainerClass,
      name = original.name or spec.leader,
      basePic = spec.trainerClass,
      pic = original.pic,
      trueColor = original.trueColor,
      paletteSource = original.paletteSource,
      baseMoney = original.baseMoney or 0,

      -- Preserve the vanilla leader's AI behavior. If the trainer record does
      -- not explicitly redirect AI, the vanilla class id is the correct
      -- ai_classes lookup key.
      aiClass = original.aiClass or spec.trainerClass,
      aiMods = original.aiMods,

      parties = {
        copyTrainerParty(spec.team),
      },
    })

    mod.content.text:register(spec.askId, spec.ask)
    mod.content.text:register(spec.declineId, spec.decline)
    mod.content.text:register(spec.wonId, spec.won)
  end

  -- BattleState.computeMusicKind checks victories.lua by exact class#party.
  -- Mark only the dedicated rematch class as a Gym Leader fight. No item or
  -- reward fields are supplied, and the custom onFinish never calls
  -- checkVictoryRewards.
  local gymRematchVictories = require("data.scripts.victories")
  for _, spec in ipairs(gymRematchSpecs) do
    gymRematchVictories[
      spec.rematchTrainerClass .. "#1"
    ] = {
      badge = spec.badge,
    }
  end

  if mod.content.map_scripts then
    local MapScripts = require("src.script.MapScripts")
    local BattleState = require("src.battle.BattleState")

    local function rematchTalk(spec)
      -- Preserve the engine's original leader script whenever the rematch
      -- is not yet available. IMPORTANT: resolve baseTalk at interaction time,
      -- not while the mod is registering. During early mod initialization the
      -- engine's hand-ported gym scripts may not have been attached to
      -- MapScripts yet; caching nil here made leaders such as Brock silently
      -- ignore the A button before their first battle.
      return function(game, ow, npc, done)
        local flags = game.save.flags or {}
        local rematchUnlocked =
          flags.EVENT_BEAT_CHAMPION_RIVAL
          and flags[spec.beatFlag]
          and flags[spec.gotTmFlag]

        if not rematchUnlocked then
          local baseTalk = MapScripts.baseTalk(spec.map, spec.textConst)
          if baseTalk then
            return baseTalk(game, ow, npc, done)
          end

          -- Defensive fallback: the stock gym module itself contains the
          -- leader talk handlers. This should normally be unnecessary once
          -- MapScripts has attached the base contributions, but it prevents a
          -- load-order edge case from making a Gym Leader completely inert.
          local ok, gyms = pcall(require, "data.scripts.gyms")
          local gym = ok and gyms and gyms[spec.map]
          local fallbackTalk =
            gym and gym.talk and gym.talk[spec.textConst] or nil

          if fallbackTalk then
            return fallbackTalk(game, ow, npc, done)
          end

          if done then done() end
          return
        end

        local TextBox = require("src.render.TextBox")

        game.stack:push(TextBox.new(
          game,
          game.data.text[spec.askId] or spec.ask,
          nil,
          {
            choice = function(yes)
              if not yes then
                game.stack:push(TextBox.new(
                  game,
                  game.data.text[spec.declineId] or spec.decline,
                  done
                ))
                return
              end

              -- build the rematch directly, matching the stable Benji
              -- rematch path. The dedicated class has one known-good party and
              -- does not depend on the vanilla leader's imported party count.
              local battleClass =
                spec.rematchTrainerClass or spec.trainerClass

              local ok, battleOrError = pcall(
                BattleState.newTrainer,
                game,
                battleClass,
                1
              )

              if not ok then
                mod.log:error(
                  "Gym rematch failed to build: leader=%s class=%s error=%s",
                  tostring(spec.leader),
                  tostring(battleClass),
                  tostring(battleOrError)
                )

                game.stack:push(TextBox.new(
                  game,
                  "The rematch could not\nbe started.\f"
                    .. "Check latest.log for\nthe exact error.",
                  done
                ))
                return
              end

              local battle = battleOrError

              -- This is the leader's loss line shown on the battle screen
              -- before the prize-money message.
              battle.endBattleText = TextBox.substitute(
                game,
                game.data.text[spec.wonId] or spec.won
              )

              battle.onFinish = function(result)
                -- No checkVictoryRewards here: rematches award only normal EXP
                -- and prize money. Match the known-good Benji ordering:
                -- restore the overworld first, then release the talk callback.
                ow:afterBattle(result, battle)
                if done then done() end
              end

              ow:pushBattle(battle)
            end,
          }
        ))
      end
    end

    local function withBlaineAftershock(spec, nextTalk)
      if spec.leader ~= "BLAINE" then
        return nextTalk
      end

      return function(game, ow, npc, done)
        local flags = game.save.flags or {}

        -- Do not interrupt Blaine's original badge/TM38 handoff. Aftershock
        -- becomes his next conversation once that normal Gym flow is finished.
        if not flags.EVENT_BEAT_BLAINE or not flags.EVENT_GOT_TM38 then
          return nextTalk(game, ow, npc, done)
        end

        if flags.EVENT_CINNABAR_AFTERSHOCK_COMPLETE then
          return nextTalk(game, ow, npc, done)
        end

        local TextBox = require("src.render.TextBox")
        local function say(textId, callback)
          game.stack:push(TextBox.new(
            game,
            game.data.text[textId] or textId,
            callback
          ))
        end

        -- Aftershock is no longer started by talking to Blaine in the Gym.
        -- The automatic exterior scene on CINNABAR_ISLAND owns that transition.
        if not flags.EVENT_CINNABAR_AFTERSHOCK_STARTED then
          return nextTalk(game, ow, npc, done)
        end

        if not flags.EVENT_CINNABAR_AFTERSHOCK_BRIEFED then
          say("_MARS_AFTERSHOCK_BLAINE_LAB_REMINDER", done)
          return
        end

        local allDone = flags.EVENT_CINNABAR_AFTERSHOCK_V190_REPAIR_FLOW
          and flags.EVENT_CINNABAR_AFTERSHOCK_SENSOR_REPAIRED
          and flags.EVENT_CINNABAR_AFTERSHOCK_PRESSURE_REPAIRED
          and flags.EVENT_CINNABAR_AFTERSHOCK_CONTROL_REPAIRED
          and flags.EVENT_CINNABAR_AFTERSHOCK_SCIENTIST_DEFEATED

        if not allDone then
          say("_MARS_AFTERSHOCK_BLAINE_PROGRESS", done)
          return
        end

        if not flags.EVENT_CINNABAR_AFTERSHOCK_TM57_RECEIVED then
          say("_MARS_AFTERSHOCK_BLAINE_FINISH", function()
            local Bag = require("src.inventory.Bag")
            if not Bag.add(game.save, "TM57", 1, game.data) then
              say("_MARS_AFTERSHOCK_BLAINE_BAG_FULL", done)
              return
            end

            flags.EVENT_CINNABAR_AFTERSHOCK_TM57_RECEIVED = true
            flags.EVENT_CINNABAR_AFTERSHOCK_COMPLETE = true

            local Sound = require("src.core.Sound")
            Sound.play(game.data, "Get_Item1")
            say("_MARS_AFTERSHOCK_GOT_TM57", done)
          end)
          return
        end

        flags.EVENT_CINNABAR_AFTERSHOCK_COMPLETE = true
        return nextTalk(game, ow, npc, done)
      end
    end

    local function withErikaFlowerAcknowledgment(spec, nextTalk)
      if spec.leader ~= "ERIKA" then
        return nextTalk
      end

      return function(game, ow, npc, done)
        local flags = game.save.flags or {}

        if flags.EVENT_CELADON_WOODS_FLOWER_GYM_SCENE_SEEN
           and not flags.EVENT_CELADON_WOODS_ERIKA_ACK
        then
          flags.EVENT_CELADON_WOODS_ERIKA_ACK = true

          local TextBox = require("src.render.TextBox")
          game.stack:push(TextBox.new(
            game,
            game.data.text._MARS_ERIKA_FLOWER_ACK
              or "Someone recently\ngave me a lovely\nflower.\fThank you.",
            function()
              nextTalk(game, ow, npc, done)
            end
          ))
          return
        end

        return nextTalk(game, ow, npc, done)
      end
    end

    local function withBrockMoonfallEpilogue(spec, nextTalk)
      if spec.leader ~= "BROCK" then
        return nextTalk
      end

      return function(game, ow, npc, done)
        local flags = game.save.flags or {}

        if flags.EVENT_MOONFALL_COMPLETE
           and not flags.EVENT_MOONFALL_BROCK_EPILOGUE_SEEN
        then
          flags.EVENT_MOONFALL_BROCK_EPILOGUE_SEEN = true

          local TextBox = require("src.render.TextBox")
          game.stack:push(TextBox.new(
            game,
            "That business in\nMT. MOON taught me\nsomething.\f"
              .. "A rare stone can\ntell us a lot.\f"
              .. "But sometimes you\nneed to know when to\nleave it where it belongs.",
            done
          ))
          return
        end

        return nextTalk(game, ow, npc, done)
      end
    end

    for _, spec in ipairs(gymRematchSpecs) do
      local talkHandler = rematchTalk(spec)
      talkHandler = withBlaineAftershock(spec, talkHandler)
      talkHandler = withErikaFlowerAcknowledgment(spec, talkHandler)
      talkHandler = withBrockMoonfallEpilogue(spec, talkHandler)

      mod.content.map_scripts:register(spec.map, {
        priority = 200,
        talk = {
          [spec.textConst] = talkHandler,
        },
      })
    end

    -- Giovanni's original post-badge farewell hides him permanently. Once
    -- the player becomes Champion, put him back in Viridian Gym so the
    -- repeatable rematch handler above can take over.
    mod.content.map_scripts:register("VIRIDIAN_GYM", {
      priority = 210,
      onEnter = function(game, ow)
        local flags = game.save.flags or {}
        if flags.EVENT_BEAT_CHAMPION_RIVAL and flags.EVENT_BEAT_GIOVANNI then
          ow:queueScript({
            { "show_object", "VIRIDIAN_GYM", "VIRIDIANGYM_GIOVANNI" },
          })
        end
      end,
    })
  end

  mod.events:on("game.ready", function(event)
    local game = event and event.game
    if not game or not game.data or not game.data.trainers then return end

    for _, spec in ipairs(gymRematchSpecs) do
      local trainer = game.data.trainers[spec.rematchTrainerClass]
      local party = trainer and trainer.parties and trainer.parties[1]

      mod.log:info(
        "Gym rematch ready: %s class=%s party=%s",
        tostring(spec.leader),
        tostring(spec.rematchTrainerClass),
        tostring(party and #party or 0)
      )
    end
  end)

  mod.log:info(
    "rebuilt official Gym Leader rematches around dedicated trainer records and the stable direct battle-start path"
  )


