  ---------------------------------------------------------------------------
  -- MARS_SNOW ADVANCED COLOR
  ---------------------------------------------------------------------------

  -- Advanced Color colors raw 8x8 tile graphics individually. The first
  -- 32 MARS_SNOW blocks are the 32 direct 4x4 source chunks from the
  -- 128x256 sheet, so they classify all 512 raw graphics without overlap.
  -- Later custom blocks reuse those graphics and inherit the same colors.
  local marsSnowTileset = mod.content.tilesets:get("MARS_SNOW")
  local marsSnowTileGroups = {}

  local function marsSnowAssignSourceBlocks(blockIds, group)
    for _, blockId in ipairs(blockIds) do
      local block = marsSnowTileset and marsSnowTileset.blocks[blockId + 1]
      for _, tileId in ipairs(block or {}) do
        marsSnowTileGroups[tileId] = group
      end
    end
  end

  -- Snow fields / borders.
  marsSnowAssignSourceBlocks({ 0, 1, 30 }, 7)

  -- Snowy vegetation.
  marsSnowAssignSourceBlocks({ 2 }, 2)

  -- Dark gray paths.
  marsSnowAssignSourceBlocks({ 3, 4, 5, 6, 7, 8 }, 0)

  -- Brown mountain faces, cliff edges, and cave rock.
  marsSnowAssignSourceBlocks({ 9, 10, 11, 12, 13, 14 }, 5)
  marsSnowAssignSourceBlocks({ 20, 21, 22, 23, 24 }, 5)

  -- Gray boulders / stone details.
  marsSnowAssignSourceBlocks({ 15, 17, 18, 19, 31 }, 0)

  -- Wood signs / standalone wood detail.
  marsSnowAssignSourceBlocks({ 16 }, 4)

  -- The walkable stair face lives inside the otherwise-brown mountain block.
  -- Keep its center run gray so it visually joins the path.
  local marsSnowStairs = marsSnowTileset and marsSnowTileset.blocks[15]
  if marsSnowStairs then
    for _, cell in ipairs({ 6, 7, 10, 11, 14, 15 }) do
      marsSnowTileGroups[marsSnowStairs[cell]] = 0
    end
  end

  -- Tree stumps sit on snowy background tiles. Give only the 8x8 tiles that
  -- actually contain stump pixels a special wood-on-white palette so the snow
  -- around them remains white instead of tinting brown.
  local marsSnowStumpTiles = {
    -- block 30: cells 11, 12, 15, 16
    490, 491, 506, 507,
    -- block 31: cells 1, 2, 5, 6
    460, 461, 476, 477,
  }
  for _, tileId in ipairs(marsSnowStumpTiles) do
    marsSnowTileGroups[tileId] = 1
  end

  -- Building source blocks: top two raw-tile rows are slate roofs, lower two
  -- rows are warm wood / wall colors.
  if marsSnowTileset then
    for blockId = 25, 29 do
      local block = marsSnowTileset.blocks[blockId + 1]
      if block then
        for cell = 1, 16 do
          marsSnowTileGroups[block[cell]] = (cell <= 8) and 6 or 4
        end
      end
    end
  end

  -- Add our custom sheet to the mutable world-palette tables used by
  -- Gen1Recomp's built-in Advanced Color tilesets.
  local MarsSnowPaletteFX = require("src.render.PaletteFX")
  local marsSnowGbcPack = MarsSnowPaletteFX.gbcPack()
  if marsSnowGbcPack and marsSnowGbcPack.world then
    marsSnowGbcPack.world.tileGroups = marsSnowGbcPack.world.tileGroups or {}
    marsSnowGbcPack.world.groupColors = marsSnowGbcPack.world.groupColors or {}

    marsSnowGbcPack.world.tileGroups.MARS_SNOW = marsSnowTileGroups
    marsSnowGbcPack.world.groupColors.MARS_SNOW = {
      -- 0: path / stone gray
      {
        { 245, 248, 250 }, { 158, 166, 176 },
        {  92, 100, 110 }, {  42,  46,  52 },
      },
      -- 1: tree stump wood on snow
      -- Keep the brightest shade pure white so snow/background pixels stay
      -- white while the darker stump pixels become tan/brown.
      {
        { 255, 255, 255 }, { 205, 186, 158 },
        { 139, 100,  65 }, {  61,  43,  30 },
      },
      -- 2: snowy vegetation
      {
        { 250, 255, 250 }, { 174, 207, 161 },
        {  86, 132,  78 }, {  44,  65,  43 },
      },
      -- 3: ice blue (reserved)
      {
        { 248, 255, 255 }, { 176, 212, 240 },
        {  96, 143, 185 }, {  45,  65,  86 },
      },
      -- 4: wood / buildings
      {
        { 250, 244, 232 }, { 210, 172, 120 },
        { 142, 101,  61 }, {  61,  45,  35 },
      },
      -- 5: mountain / cliff brown
      {
        { 250, 242, 229 }, { 191, 151, 104 },
        { 124,  86,  52 }, {  56,  43,  35 },
      },
      -- 6: slate roof
      {
        { 247, 250, 252 }, { 160, 174, 190 },
        {  91, 108, 128 }, {  43,  52,  66 },
      },
      -- 7: snow
      {
        { 255, 255, 255 }, { 226, 238, 246 },
        { 172, 190, 204 }, {  68,  78,  88 },
      },
    }

    mod.log:info("Installed MARS_SNOW Advanced Color tile groups")
  else
    mod.log:warn(
      "Advanced Color palette pack unavailable; MARS_SNOW will use its fallback palette"
    )
  end

  -- Gen1Recomp's stock Map:isGrassCell supports one grassTile per tileset.
  -- MARS_SNOW deliberately uses several visual grass variants, all carrying
  -- the Tiled "grass" flag, so teach the runtime to recognize grassTiles when
  -- a custom tileset provides that list.
  local MarsMap = require("src.world.Map")
  if not MarsMap._marsMultiGrassTileSupport then
    MarsMap._marsMultiGrassTileSupport = true
    local originalIsGrassCell = MarsMap.isGrassCell

    MarsMap.isGrassCell = function(self, cx, cy)
      if self.tileset and self.tileset.grassTiles then
        if not self:inBounds(cx, cy) then return false end
        local tile = self:cellTile(cx, cy)
        for _, grassTile in ipairs(self.tileset.grassTiles) do
          if tile == grassTile then return true end
        end
        return false
      end

      return originalIsGrassCell(self, cx, cy)
    end
  end

  -- Route 26 keeps Route 25's normal route music, while Alabaster Town
  -- uses Pallet Town's town theme.
  local route25Song = mod.content.map_songs:get("ROUTE_25")
  if route25Song then
    mod.content.map_songs:register("ROUTE_26", route25Song)
