  if ceruleanMartSong then
    mod.content.map_songs:register("ALABASTER_MART", ceruleanMartSong)
  end

  local pewterHouseSong = mod.content.map_songs:get("PEWTER_SPEECH_HOUSE")
  if pewterHouseSong then
    mod.content.map_songs:register("ALABASTER_HOUSE_1", pewterHouseSong)
    mod.content.map_songs:register("ALABASTER_HOUSE_2", pewterHouseSong)
  end

  -- Append three Route 26 parties without replacing any vanilla trainer
  -- parties.  Calculating the new indices from the imported data keeps this
