      { x = 10, y = 13, destMap = "CELADON_MART_1F",          destWarp = 3 },
      { x = 24, y =  9, destMap = "CELADON_MANSION_1F",       destWarp = 1 },
      { x = 24, y =  3, destMap = "CELADON_MANSION_1F",       destWarp = 3 },
      { x = 25, y =  3, destMap = "CELADON_MANSION_1F",       destWarp = 3 },
      { x = 41, y =  9, destMap = "CELADON_POKECENTER",       destWarp = 1 },
      { x = 12, y = 27, destMap = "CELADON_GYM",              destWarp = 1 },
      { x = 28, y = 19, destMap = "GAME_CORNER",              destWarp = 1 },
      { x = 39, y = 19, destMap = "CELADON_MART_5F",          destWarp = 1 },
      { x = 33, y = 19, destMap = "GAME_CORNER_PRIZE_ROOM",   destWarp = 1 },
      { x = 31, y = 27, destMap = "CELADON_DINER",            destWarp = 1 },
      { x = 35, y = 27, destMap = "CELADON_CHIEF_HOUSE",      destWarp = 1 },
      { x = 43, y = 27, destMap = "CELADON_HOTEL",            destWarp = 1 },

      -- north-edge gate. These are map-edge warps, so they belong on
      -- y=0 rather than the lower row of block 10. Pressing UP from these
      -- cells uses Gen1Recomp's normal Warp.onEdge path.
      { x = 32, y =  0, destMap = "CELADON_WOODS",             destWarp = 1 },
      { x = 33, y =  0, destMap = "CELADON_WOODS",             destWarp = 2 },
    },
  })

  ---------------------------------------------------------------------------
  -- CELADON FOOD THIEF / MUNCHLAX RESCUE QUEST
  --
  -- The Celadon Diner cook is treated as the restaurant owner. After he
  -- reports repeated food thefts, a Munchlax appears near the restaurant.
  -- Finding it makes it flee east to Route 7. There, three Spearow are trying
  -- to steal its food. After the rescue, Munchlax follows the player back to
  -- the restaurant. The owner finally meets the culprit, feeds it, and only
  -- then does Munchlax choose to join the player's party.
  ---------------------------------------------------------------------------

  do
    local MapDef = require("src.world.Map")

    local FLAGS = {
      started = "EVENT_CELADON_MUNCHLAX_STARTED",
      fled = "EVENT_CELADON_MUNCHLAX_FLED",
      spearow = "EVENT_ROUTE7_SPEAROW_DEFEATED",
      fed = "EVENT_CELADON_MUNCHLAX_FED",
      received = "EVENT_CELADON_MUNCHLAX_RECEIVED",
      complete = "EVENT_CELADON_MUNCHLAX_COMPLETE",
    }

    local TEXT_CELADON_MUNCHLAX_THIEF =
      "TEXT_CELADON_MUNCHLAX_THIEF"
    local TEXT_ROUTE7_MUNCHLAX =
      "TEXT_ROUTE7_MUNCHLAX"
    local TEXT_ROUTE7_SPEAROW_GANG =
      "TEXT_ROUTE7_SPEAROW_GANG"
    local TEXT_DINER_MUNCHLAX =
      "TEXT_CELADON_DINER_MUNCHLAX"

    -------------------------------------------------------------------------
    -- Find safe nearby cells from the actual map/tileset rather than hard
    -- assuming every preferred coordinate is walkable.
    -------------------------------------------------------------------------

    local function questNearestWalkable(mapId, preferredX, preferredY, used)
      local def = mod.content.maps:get(mapId)
      local tileset = def and mod.content.tilesets:get(def.tileset)

      if not def or not tileset then
        return preferredX, preferredY
      end

      used = used or {}

      for radius = 0, 8 do
        for dy = -radius, radius do
          for dx = -radius, radius do
            if radius == 0
               or math.max(math.abs(dx), math.abs(dy)) == radius
            then
              local x = preferredX + dx
              local y = preferredY + dy
              local key = tostring(x) .. ":" .. tostring(y)

              if x >= 1 and y >= 1
                 and x < def.width * 2 - 1
                 and y < def.height * 2 - 1
                 and not used[key]
                 and MapDef.defIsWalkableCell(def, tileset, x, y)
              then
                used[key] = true
                return x, y
              end
            end
          end
        end
      end

      return preferredX, preferredY
    end

    -- Just north-west of the Diner entrance.
    local cityUsed = {}
    local cityMunchX, cityMunchY =
      questNearestWalkable("CELADON_CITY", 29, 25, cityUsed)

    -- Route 7 is object-free in vanilla. Stage the rescue around its western
    -- half, away from the gate/Underground Path warps.
    local route7Used = {}
    local route7MunchX, route7MunchY =
      questNearestWalkable("ROUTE_7", 7, 7, route7Used)
    local spear1X, spear1Y =
      questNearestWalkable("ROUTE_7", 6, 7, route7Used)
    local spear2X, spear2Y =
      questNearestWalkable("ROUTE_7", 7, 6, route7Used)
    local spear3X, spear3Y =
      questNearestWalkable("ROUTE_7", 8, 7, route7Used)

    -- after the rescue, Munchlax physically waits inside the Diner beside
    -- the owner until the meal/adoption scene is finished.
    local dinerDef = mod.content.maps:get("CELADON_DINER")
    local dinerOwner = nil
    for _, obj in ipairs((dinerDef and dinerDef.objects) or {}) do
      if obj.text == "TEXT_CELADONDINER_COOK" then
        dinerOwner = obj
        break
      end
    end

    local dinerUsed = {}
    for _, obj in ipairs((dinerDef and dinerDef.objects) or {}) do
      if obj.x ~= nil and obj.y ~= nil then
        dinerUsed[tostring(obj.x) .. ":" .. tostring(obj.y)] = true
      end
    end
    for _, warp in ipairs((dinerDef and dinerDef.warps) or {}) do
      if warp.x ~= nil and warp.y ~= nil then
        dinerUsed[tostring(warp.x) .. ":" .. tostring(warp.y)] = true
      end
    end

    local dinerOwnerX = dinerOwner and dinerOwner.x or 3
    local dinerOwnerY = dinerOwner and dinerOwner.y or 3
    local dinerMunchX, dinerMunchY =
      questNearestWalkable(
        "CELADON_DINER",
        dinerOwnerX + 1,
        dinerOwnerY,
        dinerUsed
      )
    local dinerMunchIndex =
      #((dinerDef and dinerDef.objects) or {}) + 1

    -------------------------------------------------------------------------
    -- Quest objects
    -------------------------------------------------------------------------

    mod.content.maps:patch("CELADON_DINER", {
      objects = {
        __append = {
          {
            index = dinerMunchIndex,
            name = "CELADON_DINER_MUNCHLAX",
            sprite = "SPRITE_MONSTER",
            movement = "STAY",
            range = "LEFT",
            x = dinerMunchX,
            y = dinerMunchY,
            text = TEXT_DINER_MUNCHLAX,
            hidden = true,
          },
        },
      },
    })

    mod.content.maps:patch("CELADON_CITY", {
      objects = {
        __append = {
          {
            index = 94,
            name = "CELADON_MUNCHLAX_THIEF",
            sprite = "SPRITE_MONSTER",
            movement = "STAY",
            range = "DOWN",
            x = cityMunchX,
            y = cityMunchY,
            text = TEXT_CELADON_MUNCHLAX_THIEF,
          },
        },
      },
    })

    mod.content.maps:patch("ROUTE_7", {
      objects = {
        __append = {
          {
            index = 90,
            name = "ROUTE7_MUNCHLAX",
            sprite = "SPRITE_MONSTER",
            movement = "STAY",
            range = "DOWN",
            x = route7MunchX,
            y = route7MunchY,
            text = TEXT_ROUTE7_MUNCHLAX,
          },
          {
            index = 91,
            name = "ROUTE7_SPEAROW_1",
            sprite = "SPRITE_BIRD",
            movement = "STAY",
            range = "RIGHT",
            x = spear1X,
            y = spear1Y,
            text = TEXT_ROUTE7_SPEAROW_GANG,
          },
          {
            index = 92,
            name = "ROUTE7_SPEAROW_2",
            sprite = "SPRITE_BIRD",
            movement = "STAY",
            range = "DOWN",
            x = spear2X,
            y = spear2Y,
            text = TEXT_ROUTE7_SPEAROW_GANG,
          },
          {
            index = 93,
            name = "ROUTE7_SPEAROW_3",
            sprite = "SPRITE_BIRD",
            movement = "STAY",
            range = "LEFT",
            x = spear3X,
            y = spear3Y,
            text = TEXT_ROUTE7_SPEAROW_GANG,
          },
        },
      },
    })

    -------------------------------------------------------------------------
    -- Three-Spearow gang battle. It is implemented as a trainer-style battle
    -- so the Spearow cannot be caught or fled from. The opponent portrait is
    -- Spearow's own battle sprite and the battle awards no trainer money.
    -------------------------------------------------------------------------

    local spearowDef = mod.content.pokemon:get("SPEAROW")
    mod.content.trainers:register("OPP_ROUTE7_SPEAROW_GANG", {
      id = "OPP_ROUTE7_SPEAROW_GANG",
      name = "SPEAROW",
      basePic = "OPP_BIRD_KEEPER",
      pic = spearowDef and spearowDef.spriteFront,
      baseMoney = 0,
      aiClass = (mod.content.trainers:get("OPP_BIRD_KEEPER") or {}).aiClass,
      aiMods = (mod.content.trainers:get("OPP_BIRD_KEEPER") or {}).aiMods,
      parties = {
        {
          { level = 21, species = "SPEAROW" },
          { level = 22, species = "SPEAROW" },
          { level = 23, species = "SPEAROW" },
        },
      },
    })

    -------------------------------------------------------------------------
    -- Helpers
    -------------------------------------------------------------------------

    local function munchSay(game, text, done)
      local TextBox = require("src.render.TextBox")
      game.stack:push(TextBox.new(game, text, done))
    end

    -------------------------------------------------------------------------
    -- transition helpers
    --
    -- The normal fade command leaves its overlay fully opaque after the
    -- fade-out completes, and script `wait` continues ticking underneath it.
    -- Hold black for 60 frames, make the object changes invisibly, then fade
    -- back in.
    -------------------------------------------------------------------------

    local munchTransitionCallbacks = setmetatable({}, { __mode = "k" })

    mod.commands:register("mars_munch_transition_done", function(ctx)
      local callback = munchTransitionCallbacks[ctx.game]
      munchTransitionCallbacks[ctx.game] = nil

      if callback then
        callback()
      end
    end)

    mod.commands:register("mars_munchlax_face_player", function(ctx, objIndex)
      local ow = ctx.overworld
      if not ow then return end

      local npc = ow:npcByIndex(objIndex or 90)
      if npc and ow.player then
        npc:facePlayer(ow.player)
      end
    end)

    local function queueMunchTransition(game, ow, rows, done)
      munchTransitionCallbacks[game] = done

      local script = {}
      for _, row in ipairs(rows) do
        script[#script + 1] = row
      end

      script[#script + 1] = { "mars_munch_transition_done" }
      ow:queueScript(script)
    end

    local function tryGiveMunchlax(game)
      local Party = require("src.pokemon.Party")
      local Pokemon = require("src.pokemon.Pokemon")
      local BattleState = require("src.battle.BattleState")

      if #(game.save.party or {}) >= 6 then
        return false
      end

      local mon = Pokemon.new(game.data, "MUNCHLAX", 20)
      BattleState.stampOT(game.save, mon)

      if not Party.add(game.save.party, mon) then
        return false
      end

      local dex = game.save.pokedex
      if dex then
        dex.seen = dex.seen or {}
        dex.owned = dex.owned or {}
        dex.seen.MUNCHLAX = true
        dex.owned.MUNCHLAX = true
      end

      return true
    end

    local function offerMunchlaxFromDiner(game, ow, done)
      local flags = game.save.flags or {}

      if flags[FLAGS.received] then
        if done then done() end
        return
      end

      munchSay(
        game,
        "MUNCHLAX finishes every\nlast bite.\f"
          .. "It pats its belly, then\nwalks over to your side.\f"
          .. "MUNCHLAX looks up at\nyou expectantly.",
        function()
          if not tryGiveMunchlax(game) then
            munchSay(
              game,
              "MUNCHLAX wants to go\nwith you, but your\nparty is full!\f"
                .. "Make room and come\nback. It will wait\nhere with the OWNER.",
              done
            )
            return
          end

          flags[FLAGS.received] = true
          flags[FLAGS.complete] = true

          local Sound = require("src.core.Sound")
          Sound.play(game.data, "Get_Item1")

          ow:queueScript({
            {
              "hide_object",
              "CELADON_DINER",
              "CELADON_DINER_MUNCHLAX",
            },
          })

          munchSay(
            game,
            "MUNCHLAX joined\nyour party!\f"
              .. "OWNER: Ha! Looks like\nit made its choice.\f"
              .. "Take good care of it!",
            done
          )
        end
      )
    end

    local function startSpearowGangBattle(game, ow, done)
      local TextBox = require("src.render.TextBox")
      local BattleState = require("src.battle.BattleState")
      local flags = game.save.flags or {}

      munchSay(
        game,
        "Three SPEAROW are\nganging up on\nMUNCHLAX!\f"
          .. "They're trying to\nsteal all the food\nit took!\f"
          .. "The SPEAROW turn\non you!",
        function()
          local battle = BattleState.newTrainer(
            game,
            "OPP_ROUTE7_SPEAROW_GANG",
            1
          )

          battle.endBattleText = "The SPEAROW scattered!"

          battle.onFinish = function(result)
            if result ~= "win" then
              if done then done() end
              ow:afterBattle(result, battle)
              return
            end

            flags[FLAGS.spearow] = true

            queueMunchTransition(
              game,
              ow,
              {
                { "fade", "out", 20 },
                { "wait", 60 },

                -- Make the defeated Spearow disappear while the screen is
                -- fully black.
                { "hide_object", "ROUTE_7", "ROUTE7_SPEAROW_1" },
                { "hide_object", "ROUTE_7", "ROUTE7_SPEAROW_2" },
                { "hide_object", "ROUTE_7", "ROUTE7_SPEAROW_3" },

                -- Munchlax leaves Route 7 with the player after the rescue.
                { "hide_object", "ROUTE_7", "ROUTE7_MUNCHLAX" },

                { "fade", "in", 20 },
              },
              function()
                munchSay(
                  game,
                  "The three SPEAROW\nfly away!\f"
                    .. "MUNCHLAX clutches\nthe food and looks\nback toward CELADON.\f"
                    .. "When you start back,\nMUNCHLAX follows close\nbehind.",
                  function()
                    if done then done() end
                    ow:afterBattle("win", battle)
                  end
                )
              end
            )
          end

          ow:pushBattle(battle)
        end
      )
    end

    -------------------------------------------------------------------------
    -- Celadon restaurant reunion / adoption
    -------------------------------------------------------------------------

    local function dinerMunchlaxTalk(game, ow, npc, done)
      local flags = game.save.flags or {}

      if flags[FLAGS.fed] then
        munchSay(
          game,
          "MUNCHLAX pats its belly\nhappily.\f"
            .. "It keeps glancing\nbetween you and the\nOWNER.",
          done
        )
      else
        munchSay(
          game,
          "MUNCHLAX sniffs the air\naround the kitchen.\f"
            .. "Its stomach growls\nloudly...",
          done
        )
      end
    end

    local function restaurantOwnerTalk(game, ow, npc, done)
      if npc and npc.facePlayer and ow and ow.player then
        npc:facePlayer(ow.player)
      end

      local flags = game.save.flags or {}

      if flags[FLAGS.complete] then
        munchSay(
          game,
          "OWNER: Thanks again!\f"
            .. "Just keep an eye on\nthat MUNCHLAX around\nanything edible!",
          done
        )
        return
      end

      if flags[FLAGS.received] then
        flags[FLAGS.complete] = true

        munchSay(
          game,
          "OWNER: Thanks again!\f"
            .. "Just keep an eye on\nthat MUNCHLAX around\nanything edible!",
          done
        )
        return
      end

      if flags[FLAGS.spearow] then
        if flags[FLAGS.fed] then
          offerMunchlaxFromDiner(game, ow, done)
          return
        end

        munchSay(
          game,
          "OWNER: So THAT'S the\nfood thief!\f"
            .. "A MUNCHLAX... I guess\nthat explains a lot.\f"
            .. "And you brought all\nthat food back too?\f"
            .. "Well... I can't stay\nmad at a hungry\nPOKEMON.",
          function()
            munchSay(
              game,
              "OWNER: Come on, little\nguy. Sit down.\f"
                .. "This meal is on the\nhouse.",
              function()
                flags[FLAGS.fed] = true

                munchSay(
                  game,
                  "MUNCHLAX devours the\nmeal in seconds!\f"
                    .. "It gives a delighted\ncry.",
                  function()
                    offerMunchlaxFromDiner(game, ow, done)
                  end
                )
              end
            )
          end
        )
        return
      end

      if flags[FLAGS.fled] then
        munchSay(
          game,
          "OWNER: It ran toward\nROUTE 7?\f"
            .. "Please go after it!\f"
            .. "I'd like my food\nback, but make sure\nthat POKEMON is safe.",
          done
        )
        return
      end

      if flags[FLAGS.started] then
        munchSay(
          game,
          "OWNER: The thief\ncan't have gone far.\f"
            .. "Take a look around\noutside the restaurant.",
          done
        )
        return
      end

      flags[FLAGS.started] = true

      munchSay(
        game,
        "OWNER: I've got a\nserious problem.\f"
          .. "Someone keeps\nstealing food from\nmy restaurant!\f"
          .. "Every time I turn\nmy back, something\nelse disappears.\f"
          .. "Could you look around\nCELADON and find out\nwhat's doing it?",
        done
      )
    end

    -------------------------------------------------------------------------
    -- City Munchlax: discovery -> flees to Route 7
    -------------------------------------------------------------------------

    local function cityMunchlaxTalk(game, ow, npc, done)
      local flags = game.save.flags or {}

      if not flags[FLAGS.started] or flags[FLAGS.fled] then
        if done then done() end
        return
      end

      munchSay(
        game,
        "There it is!\f"
          .. "MUNCHLAX is stuffing\nits face with food\nfrom the restaurant!\f"
          .. "MUNCHLAX notices you!\f"
          .. "It grabs the food\nand bolts toward\nROUTE 7!",
        function()
          flags[FLAGS.fled] = true

          queueMunchTransition(
            game,
            ow,
            {
              { "fade", "out", 20 },
              { "wait", 60 },

              -- Munchlax does not vanish in front of the player. It is only
              -- removed once the screen has been held fully black.
              {
                "hide_object",
                "CELADON_CITY",
                "CELADON_MUNCHLAX_THIEF",
              },

              { "fade", "in", 20 },
            },
            function()
              if done then done() end
            end
          )
        end
      )
    end

    -------------------------------------------------------------------------
    -- Route 7 interaction
    -------------------------------------------------------------------------

    local function route7MunchlaxTalk(game, ow, npc, done)
      local flags = game.save.flags or {}

      if not flags[FLAGS.fled] or flags[FLAGS.received] then
        if done then done() end
        return
      end

      if not flags[FLAGS.spearow] then
        startSpearowGangBattle(game, ow, done)
        return
      end

      if done then done() end
    end

    local function route7SpearowTalk(game, ow, npc, done)
      local flags = game.save.flags or {}

      if flags[FLAGS.spearow] then
        if done then done() end
        return
      end

      startSpearowGangBattle(game, ow, done)
    end

    -------------------------------------------------------------------------
    -- Visibility / state
    -------------------------------------------------------------------------

    if mod.content.map_scripts then
      mod.content.map_scripts:register("CELADON_DINER", {
        priority = 136,
        onEnter = function(game, ow)
          local flags = game.save.flags or {}
          local showDinerMunchlax =
            flags[FLAGS.spearow]
            and not flags[FLAGS.received]

          ow:queueScript({
            {
              showDinerMunchlax and "show_object" or "hide_object",
              "CELADON_DINER",
              "CELADON_DINER_MUNCHLAX",
            },
          })
        end,
        talk = {
          ["TEXT_CELADONDINER_COOK"] = restaurantOwnerTalk,
          [TEXT_DINER_MUNCHLAX] = dinerMunchlaxTalk,
        },
      })

      mod.content.map_scripts:register("CELADON_CITY", {
        priority = 136,
        onEnter = function(game, ow)
          local flags = game.save.flags or {}

          if flags[FLAGS.started] and not flags[FLAGS.fled] then
            ow:queueScript({
              { "show_object", "CELADON_CITY", "CELADON_MUNCHLAX_THIEF" },
            })
          else
            ow:queueScript({
              { "hide_object", "CELADON_CITY", "CELADON_MUNCHLAX_THIEF" },
            })
          end
        end,
        talk = {
          [TEXT_CELADON_MUNCHLAX_THIEF] = cityMunchlaxTalk,
        },
      })

      mod.content.map_scripts:register("ROUTE_7", {
        priority = 136,
        onEnter = function(game, ow)
          local flags = game.save.flags or {}
          local rows = {}

          local active =
            flags[FLAGS.fled]
            and not flags[FLAGS.spearow]
            and not flags[FLAGS.received]

          if active then
            rows[#rows + 1] =
              { "show_object", "ROUTE_7", "ROUTE7_MUNCHLAX" }

            if flags[FLAGS.spearow] then
              rows[#rows + 1] =
                { "hide_object", "ROUTE_7", "ROUTE7_SPEAROW_1" }
              rows[#rows + 1] =
                { "hide_object", "ROUTE_7", "ROUTE7_SPEAROW_2" }
              rows[#rows + 1] =
                { "hide_object", "ROUTE_7", "ROUTE7_SPEAROW_3" }
            else
              rows[#rows + 1] =
                { "show_object", "ROUTE_7", "ROUTE7_SPEAROW_1" }
              rows[#rows + 1] =
                { "show_object", "ROUTE_7", "ROUTE7_SPEAROW_2" }
              rows[#rows + 1] =
                { "show_object", "ROUTE_7", "ROUTE7_SPEAROW_3" }
            end
          else
            rows[#rows + 1] =
              { "hide_object", "ROUTE_7", "ROUTE7_MUNCHLAX" }
            rows[#rows + 1] =
              { "hide_object", "ROUTE_7", "ROUTE7_SPEAROW_1" }
            rows[#rows + 1] =
              { "hide_object", "ROUTE_7", "ROUTE7_SPEAROW_2" }
            rows[#rows + 1] =
              { "hide_object", "ROUTE_7", "ROUTE7_SPEAROW_3" }
          end

          ow:queueScript(rows)
        end,
        talk = {
          [TEXT_ROUTE7_MUNCHLAX] = route7MunchlaxTalk,
          [TEXT_ROUTE7_SPEAROW_GANG] = route7SpearowTalk,
        },
      })
    end
  end

  local marsCeladonWoodsDef = {
    id = "CELADON_WOODS",
    label = "CeladonWoods",
    index = 1013,
    tileset = "FOREST",
    palette = "ROUTE",
    outdoor = true,
    width = 18,
    height = 18,
    borderBlock = 3,
    blocks = marsCeladonWoodsBlocks,
  }

  local function marsCeladonWoodsNearestWalkable(preferredX, preferredY)
    if not celadonWoodsForestTileset then
      return preferredX, preferredY
    end

    if celadonWoodsMapDef.defIsWalkableCell(
        marsCeladonWoodsDef, celadonWoodsForestTileset,
        preferredX, preferredY
      )
    then
      return preferredX, preferredY
    end

    for radius = 1, 6 do
      for dy = -radius, radius do
        for dx = -radius, radius do
          if math.max(math.abs(dx), math.abs(dy)) == radius then
            local x, y = preferredX + dx, preferredY + dy
            if x >= 1 and y >= 1
               and x < marsCeladonWoodsDef.width * 2 - 1
               and y < marsCeladonWoodsDef.height * 2 - 1
               and celadonWoodsMapDef.defIsWalkableCell(
                 marsCeladonWoodsDef, celadonWoodsForestTileset, x, y
               )
            then
              return x, y
            end
          end
        end
      end
    end

    return preferredX, preferredY
  end

