  -- The tree is the authored FOREST block pair 20/24 at blocks (9,1)/(9,2).
  -- Cell (18,5) is the walkable base of that tree — the same relative cell
  -- used by Deepwood's lone-tree pickup — so do not move this to the eastern
  -- approach corridor.
  local celadonPrettyFlowerX, celadonPrettyFlowerY =
    marsCeladonWoodsNearestWalkable(18, 5)

  -- Trainer placements follow the authored TMJ points but are
  -- validated at runtime so a small terrain edit cannot strand an NPC inside
  -- a tree or lake tile.
  local celadonWoodsFisherX, celadonWoodsFisherY =
    marsCeladonWoodsNearestWalkable(19, 28)
  local celadonWoodsBugCatcherX, celadonWoodsBugCatcherY =
    marsCeladonWoodsNearestWalkable(25, 26)
  local celadonWoodsLassX, celadonWoodsLassY =
    marsCeladonWoodsNearestWalkable(33, 4)

  -- The user placed a signpost beside the lake in FOREST block (8,15).
  -- Find which 16px quadrant uses the same sign graphic as Viridian Forest's
  -- real signs; this avoids guessing the sign's quadrant.
  local celadonLakeSignX, celadonLakeSignY = 17, 31
  do
    local viridian = mod.content.maps:get("VIRIDIAN_FOREST")
    local knownSignTiles = {}

    if viridian and celadonWoodsForestTileset then
      for _, sign in ipairs(viridian.signs or {}) do
        local tile = celadonWoodsMapDef.defCellTile(
          viridian, celadonWoodsForestTileset, sign.x, sign.y
        )
        if tile ~= nil then knownSignTiles[tile] = true end
      end

      for cy = 30, 31 do
        for cx = 16, 17 do
          local tile = celadonWoodsMapDef.defCellTile(
            marsCeladonWoodsDef, celadonWoodsForestTileset, cx, cy
          )
          if tile ~= nil and knownSignTiles[tile] then
            celadonLakeSignX, celadonLakeSignY = cx, cy
          end
        end
      end
    end
  end

