  -- Celadon Woods remains Tangela/Murkrow's main midgame habitat.
  -- Remove legacy placements elsewhere without touching the two deliberately
  -- authored postgame exceptions:
  --   * Tangela on Faraway Island
  --   * Murkrow on Dawn Trail
  if mod.content.encounters then
    for encounterId in mod.content.encounters:each() do
      if encounterId ~= "CELADON_WOODS" then
        local encounter = mod.content.encounters:get(encounterId)

        for _, terrain in ipairs({ "grass", "water" }) do
          local terrainDef = encounter and encounter[terrain]
          if terrainDef and type(terrainDef.slots) == "table" then
            local slots = copyEncounterSlots(terrainDef.slots)
            local changed = false

            for _, slot in ipairs(slots) do
              if slot.species == "TANGELA"
                 and encounterId ~= "MARS_FARAWAY_ISLAND"
              then
                slot.species = "EXEGGCUTE"
                changed = true
              elseif slot.species == "MURKROW"
                 and encounterId ~= "DAWN_TRAIL"
              then
                slot.species = "PIDGEY"
                changed = true
              end
            end

            if changed then
              mod.content.encounters:patch(encounterId, {
                [terrain] = { slots = slots },
              })
            end
          end
        end
      end
    end
  end

