  local flowerGymDef = mod.content.maps:get("CELADON_GYM")
  local flowerGymErika = nil
  local flowerGymErikaIndex = nil
  local flowerGymGirlIndex = nil
  local flowerGymGirlStartX, flowerGymGirlStartY = nil, nil
  local flowerGymGirlTargetX, flowerGymGirlTargetY = nil, nil

  local function flowerGymDirectionToward(fromX, fromY, toX, toY)
    local dx, dy = toX - fromX, toY - fromY
    if math.abs(dx) > math.abs(dy) then
      return dx >= 0 and "right" or "left"
    end
    if dy ~= 0 then
      return dy >= 0 and "down" or "up"
    end
    return "down"
  end

  if flowerGymDef then
    for listIndex, obj in ipairs(flowerGymDef.objects or {}) do
      if obj.trainerClass == "OPP_ERIKA"
         or obj.text == "TEXT_CELADONGYM_ERIKA"
      then
        flowerGymErika = obj
        flowerGymErikaIndex = obj.index or listIndex
        break
      end
    end

    if flowerGymErika then
      local flowerGymTileset =
        mod.content.tilesets:get(flowerGymDef.tileset)
      local flowerGymUsed = {}

      for _, obj in ipairs(flowerGymDef.objects or {}) do
        if obj.x ~= nil and obj.y ~= nil then
          flowerGymUsed[tostring(obj.x) .. ":" .. tostring(obj.y)] = true
        end
      end
      for _, warp in ipairs(flowerGymDef.warps or {}) do
        if warp.x ~= nil and warp.y ~= nil then
          flowerGymUsed[tostring(warp.x) .. ":" .. tostring(warp.y)] = true
        end
      end

      local function flowerGymOpen(preferredX, preferredY)
        for radius = 0, 8 do
          for dy = -radius, radius do
            for dx = -radius, radius do
              if radius == 0
                 or math.max(math.abs(dx), math.abs(dy)) == radius
              then
                local x = preferredX + dx
                local y = preferredY + dy
                local k = tostring(x) .. ":" .. tostring(y)

                if flowerGymTileset
                   and x >= 1 and y >= 1
                   and x < flowerGymDef.width * 2 - 1
                   and y < flowerGymDef.height * 2 - 1
                   and not flowerGymUsed[k]
                   and celadonWoodsMapDef.defIsWalkableCell(
                     flowerGymDef,
                     flowerGymTileset,
                     x,
                     y
                   )
                   and not celadonWoodsMapDef.defIsWaterCell(
                     flowerGymDef,
                     flowerGymTileset,
                     x,
                     y
                   )
                then
                  flowerGymUsed[k] = true
                  return x, y
                end
              end
            end
          end
        end
        return preferredX, preferredY
      end

      flowerGymGirlTargetX, flowerGymGirlTargetY =
        flowerGymOpen(flowerGymErika.x, flowerGymErika.y + 2)
      flowerGymGirlStartX, flowerGymGirlStartY =
        flowerGymOpen(
          flowerGymGirlTargetX,
          flowerGymGirlTargetY + 3
        )

      flowerGymGirlIndex = #(flowerGymDef.objects or {}) + 1

      mod.content.maps:patch("CELADON_GYM", {
        objects = {
          __append = {
            {
              index = flowerGymGirlIndex,
              name = "MARS_PRETTY_FLOWER_GYM_GIRL",
              sprite = "SPRITE_GIRL",
              movement = "STAY",
              range = "UP",
              x = flowerGymGirlStartX,
              y = flowerGymGirlStartY,
              text = "TEXT_CELADON_WOODS_FLOWER_GYM_GIRL",
              hidden = true,
            },
          },
        },
      })
    end
  end

