          { "label", "end" },
        },

        TEXT_CELADON_WOODS_PRETTY_FLOWER = {
          { "check_flag", "EVENT_CELADON_WOODS_QUEST_COMPLETE" },
          { "jump_if_true", "end" },
          { "check_item", "PRETTY_FLOWER" },
          { "jump_if_true", "end" },

          { "check_flag", "EVENT_CELADON_WOODS_QUEST_STARTED" },
          { "jump_if_false", "idle" },

          { "show_text", "_MARS_CELADON_WOODS_FLOWER_FOUND" },
