          { "start_battle", "wild", "BEEDRILL", 27 },
          { "check_battle_result", "win", "caught" },
          { "jump_if_false", "end" },
          { "give_item", "PRETTY_FLOWER", 1, "_MARS_CELADON_WOODS_GOT_FLOWER" },
          { "set_flag", "EVENT_GOT_PRETTY_FLOWER" },
          { "hide_object", "CELADON_WOODS", "CELADON_WOODS_PRETTY_FLOWER" },
          { "jump", "end" },

          { "label", "idle" },
          { "show_text", "_MARS_CELADON_WOODS_FLOWER_IDLE" },

          { "label", "end" },
        },

        TEXT_CELADON_WOODS_LAKE_SIGN = {
          { "show_text", "_MARS_CELADON_WOODS_LAKE_SIGN" },
        },
      },
    })

    if flowerGymGirlIndex and flowerGymErikaIndex then
      mod.content.map_scripts:register("CELADON_GYM", {
        priority = 250,

        onEnter = function(game, ow)
          local flags = game.save.flags or {}
          local pending =
            flags.EVENT_CELADON_WOODS_QUEST_COMPLETE
            and not flags.EVENT_CELADON_WOODS_FLOWER_GYM_SCENE_SEEN

          if not pending then
            ow:queueScript({
              {
                "hide_object",
                "CELADON_GYM",
                "MARS_PRETTY_FLOWER_GYM_GIRL",
              },
