            flowerGymErika.x,
            flowerGymErika.y
          )
          local erikaFacesGirl = flowerGymDirectionToward(
            flowerGymErika.x,
            flowerGymErika.y,
            flowerGymGirlTargetX,
            flowerGymGirlTargetY
          )

          ow:queueScript({
            {
              "place_npc",
              flowerGymGirlIndex,
              flowerGymGirlStartX,
              flowerGymGirlStartY,
              "up",
            },
            {
              "show_object",
              "CELADON_GYM",
              "MARS_PRETTY_FLOWER_GYM_GIRL",
            },
            {
              "move_npc_to",
              flowerGymGirlIndex,
              flowerGymGirlTargetX,
              flowerGymGirlTargetY,
            },
            { "face_object", flowerGymGirlIndex, girlFacesErika },
            { "face_object", flowerGymErikaIndex, erikaFacesGirl },
            { "show_text", "_MARS_PRETTY_FLOWER_GYM_GIRL" },
            { "show_text", "_MARS_PRETTY_FLOWER_GYM_ERIKA" },
            { "show_text", "_MARS_PRETTY_FLOWER_GYM_GIRL_2" },
