  -- Pick nearby walkable cells for authored object markers while keeping
  -- every placement within its intended portion of the long route.
  local indigoReservedCells = {}

  local function marsIndigoNearestWalkable(preferredX, preferredY, maxRadius)
    maxRadius = maxRadius or 7

    local function available(x, y)
      if x < 1 or y < 1
         or x >= marsIndigoHighlandsDef.width * 2 - 1
         or y >= marsIndigoHighlandsDef.height * 2 - 1
      then
        return false
      end

      local key = tostring(x) .. ":" .. tostring(y)
      if indigoReservedCells[key] then return false end

      if not indigoOverworldTileset then return true end
      return indigoMapDef.defIsWalkableCell(
        marsIndigoHighlandsDef, indigoOverworldTileset, x, y
      )
    end

    if available(preferredX, preferredY) then
      indigoReservedCells[tostring(preferredX) .. ":" .. tostring(preferredY)] = true
      return preferredX, preferredY
    end

    for radius = 1, maxRadius do
      for dy = -radius, radius do
        for dx = -radius, radius do
          if math.max(math.abs(dx), math.abs(dy)) == radius then
            local x, y = preferredX + dx, preferredY + dy
            if available(x, y) then
              indigoReservedCells[tostring(x) .. ":" .. tostring(y)] = true
              return x, y
            end
          end
        end
      end
    end

    -- Retain the authored marker if the tileset definition is unavailable.
    return preferredX, preferredY
  end

