  ---------------------------------------------------------------------------
  -- ROUTE 22 CUT GATE
  --
  -- The new south connection is visible from Route 22 immediately, but its
  -- actual threshold is blocked by a native Cut-tree overlay until the player
  -- has used Cut there once.
  ---------------------------------------------------------------------------

  do
    local OverworldState = require("src.world.OverworldController")

    if not OverworldState._marsIndigoHighlandsCutGateV62 then
      OverworldState._marsIndigoHighlandsCutGateV62 = true

      local baseUseCutFieldMove = OverworldState.useCutFieldMove
      local baseTryCut = OverworldState.tryCut
      local baseDrawWorld = OverworldState.drawWorld

      local GATE_BX = 2
      local GATE_BY = 8
      local GATE_FLAG = "EVENT_OPENED_INDIGO_HIGHLANDS"

      local function gateCell(self)
        if not self.map or self.map.id ~= "ROUTE_22" then
          return nil, nil
        end

        -- Route 22's south-edge entrance block covers cells x=4..5, y=16..17.
        -- The tree belongs on whichever SOUTH-edge cell is walkable.
        local southY = GATE_BY * 2 + 1
        local x0 = GATE_BX * 2

        if self.map:isWalkableCell(x0, southY) then
          return x0, southY
        end
        if self.map:isWalkableCell(x0 + 1, southY) then
          return x0 + 1, southY
        end

        return x0, southY
      end

      local function gateClosed()
        local Game = require("src.core.Game")
        local flags = Game.save and Game.save.flags or {}
        return not flags[GATE_FLAG]
      end

      local function isIndigoGate(self, fx, fy)
        if not gateClosed() then return false end
        local gx, gy = gateCell(self)
        return gx ~= nil and fx == gx and fy == gy
      end

      function OverworldState:useCutFieldMove()
        local fx, fy = self.player:facingCell()

        if isIndigoGate(self, fx, fy) then
          if not self:partyKnows("CUT") then
            return "no_badge"
          end
          return "ok"
        end

        return baseUseCutFieldMove(self)
      end

      function OverworldState:tryCut(fx, fy)
        if not isIndigoGate(self, fx, fy) then
          return baseTryCut(self, fx, fy)
        end

        local Game = require("src.core.Game")
        local mon = self:partyKnows("CUT")
        if not mon then return false end

        local TextBox = require("src.render.TextBox")
        local monDef = Game.data.pokemon[mon.species]
        local name = mon.nickname or (monDef and monDef.name) or mon.species
        local usedText =
          (Game.data.text._UsedCutText
            or "{RAM:wNameBuffer} hacked\naway with CUT!")
          :gsub("{RAM:wNameBuffer}", name)

        Game.stack:push(TextBox.new(Game, usedText, function()
          Game.save.flags = Game.save.flags or {}
          Game.save.flags[GATE_FLAG] = true

          local finish = function()
            require("src.core.Sound").play(Game.data, "Cut")
          end

          if self.startCutTreeAnim then
            self:startCutTreeAnim(fx, fy, finish)
          else
            finish()
          end
        end))

        return true
      end

      function OverworldState:drawWorld()
        if self.map
           and self.map.id == "ROUTE_22"
           and gateClosed()
           and not self.cutAnim
        then
          local gx, gy = gateCell(self)
          if gx then
            self.cutAnim = {
              x = gx,
              y = gy,
              frames = 8,
              total = 8,
              marsStaticIndigoGate = true,
            }

            baseDrawWorld(self)

            if self.cutAnim and self.cutAnim.marsStaticIndigoGate then
              self.cutAnim = nil
            end
            return
          end
        end

        return baseDrawWorld(self)
      end
    end
  end

  mod.hooks:wrap("movement.collision", function(next, allowed, ctx)
    local Game = require("src.core.Game")
    local flags = Game.save and Game.save.flags or {}

    if allowed
       and not flags.EVENT_OPENED_INDIGO_HIGHLANDS
       and ctx
       and ctx.map
       and ctx.map.id == "ROUTE_22"
    then
      local southY = 17
      local gateX

      if ctx.map:isWalkableCell(4, southY) then
        gateX = 4
      elseif ctx.map:isWalkableCell(5, southY) then
        gateX = 5
      else
        gateX = 4
      end

      if ctx.toX == gateX and ctx.toY == southY then
        ctx.reason = "entity"
        return false
      end
    end

    return next(allowed, ctx)
  end, 26)

  ---------------------------------------------------------------------------
  -- INDIGO HIGHLANDS MOUNTAIN SURFACE / CAP COLLISION
  --
  -- Final intended rule:
  --
  --   * Fully tan plateau surface = walkable.
  --   * Tan portions of side-border pieces = walkable where the raw movement
  --     tile is the plateau tile (17).
  --   * The narrow HORIZONTAL TOP CAP is a border and must stay solid.
  --
  -- Authored OVERWORLD mountain top-cap blocks:
  --   62 = left top-cap piece
  --   63 = middle top-cap piece
  --   59 = right top-cap piece
  --
  -- Each block contains a 2x2 grid of 16x16 movement cells. Only the UPPER
  -- row (local cell Y=0) of these top-cap blocks is forced solid. The lower
  -- row can still behave as tan plateau surface.
  ---------------------------------------------------------------------------

  mod.hooks:wrap("movement.collision", function(next, allowed, ctx)
    if ctx
       and ctx.map
       and ctx.map.id == "INDIGO_HIGHLANDS"
       and ctx.toX ~= nil
       and ctx.toY ~= nil
    then
      local map = ctx.map
      local bx = math.floor(ctx.toX / 2)
      local by = math.floor(ctx.toY / 2)
      local localY = ctx.toY % 2

      local okBlock, blockId = pcall(function()
        return map:blockAt(bx, by)
      end)

      -- HARD BORDER:
      -- The upper movement-cell row of a horizontal mountain cap is never
      -- walkable, even if vanilla collision or the shared raw tile says yes.
      if okBlock
         and localY == 0
         and (blockId == 62 or blockId == 63 or blockId == 59)
      then
        ctx.reason = "tile"
        return false
      end

      -- WALKABLE TAN SURFACE:
      -- Raw tile 17 is the live tan plateau surface used by this map.
      -- Permit it everywhere inside the true outer map-block ring.
      if not allowed and ctx.reason == "tile" then
        local okTile, tileId = pcall(function()
          return map:cellTile(ctx.toX, ctx.toY)
        end)

        if okTile and tileId == 17 then
          local widthBlocks = map.def and map.def.width or 10
          local heightBlocks = map.def and map.def.height or 54

          local notOuterRing =
            bx > 0
            and by > 0
            and bx < widthBlocks - 1
            and by < heightBlocks - 1

          if notOuterRing then
            return next(true, ctx)
          end
        end
      end
    end

    return next(allowed, ctx)
  end, 998)

  -- Custom outdoor maps use indices above the vanilla indoor-map threshold.
  -- Without this guard, the stock overworld encounter fallback can treat
  -- high-index custom outdoor maps like cave/interior maps and roll on every
  -- walked tile. Suppress only that false indoor roll; genuine grass rolls
  -- continue normally.
  mod.hooks:wrap("encounter.roll", function(next, encDef, ctx)
    if ctx
      and (
        ctx.mapId == "ROUTE_26"
        or ctx.mapId == "ALABASTER_TOWN"
        or ctx.mapId == "VIRIDIAN_DEEPWOOD"
        or ctx.mapId == "CELADON_WOODS"
        or ctx.mapId == "INDIGO_HIGHLANDS"
        or ctx.mapId == "INDIGO_CITY"
      )
      and ctx.terrain == "indoor"
    then
      return nil
    end
    return next(encDef, ctx)
  end, 25)

