  ---------------------------------------------------------------------------
  -- VIRIDIAN DEEPWOOD FOREST CUT GATE
  --
  -- IMPORTANT: the authored Forest terrain remains untouched.
  -- VIRIDIAN_FOREST block (16,11) is the user's open entrance block 52.
  --
  -- The gate itself is now separate from the map:
  --   * Gen1Recomp's extracted native Cut-tree graphic is drawn over the
  --     walkable seam cell while the gate event is unset.
  --   * movement.collision treats that one cell as occupied.
  --   * the ordinary party-menu CUT flow removes the gate permanently.
  --
  -- Restoring vanilla block 59 here would accidentally
  -- erased the entrance the user had drawn in Tiled.
  ---------------------------------------------------------------------------

  do
    local OverworldState = require("src.world.OverworldController")

    if not OverworldState._marsViridianDeepwoodCutGateV47 then
      OverworldState._marsViridianDeepwoodCutGateV47 = true

      local baseUseCutFieldMove = OverworldState.useCutFieldMove
      local baseTryCut = OverworldState.tryCut
      local baseDrawWorld = OverworldState.drawWorld

      local GATE_BX = 16
      local GATE_BY = 11
      local GATE_FLAG = "EVENT_OPENED_VIRIDIAN_DEEPWOOD"

      -- The authored 32x32 entrance block covers cells x=32..33, y=22..23.
      -- Pick the east-edge cell that is actually walkable in the user's
      -- FOREST block. This keeps the code tied to the authored geometry
      -- instead of guessing whether the opening is the upper or lower half.
      local function gateCell(self)
        if not self.map or self.map.id ~= "VIRIDIAN_FOREST" then
          return nil, nil
        end

        local eastX = GATE_BX * 2 + 1
        local y0 = GATE_BY * 2

        if self.map:isWalkableCell(eastX, y0) then
          return eastX, y0
        end
        if self.map:isWalkableCell(eastX, y0 + 1) then
          return eastX, y0 + 1
        end

        -- Defensive fallback if a future FOREST collision-table change makes
        -- the edge cell report differently. The lower-right cell is the seam
        -- cell used by the authored entrance in the current map.
        return eastX, y0 + 1
      end

      local function gateClosed()
        local Game = require("src.core.Game")
        local flags = Game.save and Game.save.flags or {}
        return not flags[GATE_FLAG]
      end

      local function isDeepwoodGate(self, fx, fy)
        if not gateClosed() then return false end
        local gx, gy = gateCell(self)
        return gx ~= nil and fx == gx and fy == gy
      end

      function OverworldState:useCutFieldMove()
        local fx, fy = self.player:facingCell()

        if isDeepwoodGate(self, fx, fy) then
          -- partyKnows("CUT") carries Gen1Recomp's normal Cascade Badge gate.
          if not self:partyKnows("CUT") then
            return "no_badge"
          end
          return "ok"
        end

        return baseUseCutFieldMove(self)
      end

      function OverworldState:tryCut(fx, fy)
        if not isDeepwoodGate(self, fx, fy) then
          return baseTryCut(self, fx, fy)
        end

        local Game = require("src.core.Game")
        local mon = self:partyKnows("CUT")
        if not mon then return false end

        local TextBox = require("src.render.TextBox")
        local monDef = Game.data.pokemon[mon.species]
        local name = mon.nickname or (monDef and monDef.name) or mon.species
        local usedText =
          (Game.data.text._UsedCutText
            or "{RAM:wNameBuffer} hacked\naway with CUT!")
          :gsub("{RAM:wNameBuffer}", name)

        Game.stack:push(TextBox.new(Game, usedText, function()
          Game.save.flags = Game.save.flags or {}
          Game.save.flags[GATE_FLAG] = true

          local finish = function()
            require("src.core.Sound").play(Game.data, "Cut")
          end

          -- Run the engine's normal tree-split animation over the authored
          -- opening. There is no terrain swap because block 52 is already the
          -- correct post-Cut terrain.
          if self.startCutTreeAnim then
            self:startCutTreeAnim(fx, fy, finish)
          else
            finish()
          end
        end))

        return true
      end

      -- Reuse Gen1Recomp's own Cut-tree FX as a STATIC gate graphic before
      -- it is cut. drawWorld already knows how to render this correctly in
      -- flat, tilt, Advanced Color, and render-pipeline modes. We temporarily
      -- present a full, unmoving Cut animation only for the duration of draw.
      function OverworldState:drawWorld()
        if self.map
           and self.map.id == "VIRIDIAN_FOREST"
           and gateClosed()
           and not self.cutAnim
        then
          local gx, gy = gateCell(self)
          if gx then
            self.cutAnim = {
              x = gx,
              y = gy,
              frames = 8,
              total = 8,
              marsStaticDeepwoodGate = true,
            }

            baseDrawWorld(self)

            if self.cutAnim and self.cutAnim.marsStaticDeepwoodGate then
              self.cutAnim = nil
            end
            return
          end
        end

        return baseDrawWorld(self)
      end
    end
  end

  -- The authored block is walkable, so collision supplies the physical
  -- barrier while the native Cut-tree overlay is visible.
  mod.hooks:wrap("movement.collision", function(next, allowed, ctx)
    local Game = require("src.core.Game")
    local flags = Game.save and Game.save.flags or {}

    if allowed
       and not flags.EVENT_OPENED_VIRIDIAN_DEEPWOOD
       and ctx
       and ctx.map
       and ctx.map.id == "VIRIDIAN_FOREST"
    then
      local eastX = 33
      local y0 = 22
      local gateY

      if ctx.map:isWalkableCell(eastX, y0) then
        gateY = y0
      elseif ctx.map:isWalkableCell(eastX, y0 + 1) then
        gateY = y0 + 1
      else
        gateY = y0 + 1
      end

      if ctx.toX == eastX and ctx.toY == gateY then
        ctx.reason = "entity"
        return false
      end
    end

    return next(allowed, ctx)
  end, 25)

