  -- ALABASTER-ONLY ICY ADVANCED COLOR
  --
  -- Alabaster Cave still uses Seafoam/CAVERN's exact graphics, blocks,
  -- collision, animation and ordinary CAVE palette. For Advanced Color only,
  -- clone CAVERN under a unique tileset id and copy its per-tile GBC groups.
  -- We then cool every four-color group toward a pale blue/cyan ice ramp.
  --
  -- This is deliberately NOT applied to CAVERN globally, so Seafoam,
  -- Rock Tunnel, Mt. Moon and every other cave keep their normal colors.
  local alabasterCaveTilesetId = "CAVERN"
  local alabasterBaseCavern = mod.content.tilesets:get("CAVERN")

  if alabasterBaseCavern then
    local alabasterTileset = {}
    for key, value in pairs(alabasterBaseCavern) do
      alabasterTileset[key] = value
    end

    alabasterTileset.id = "CAVERN_ALABASTER"

    -- tilesets:get("CAVERN") can expose water/shore metadata in a
    -- normalized lookup-table form, while tilesets:register() expects a normal
    -- numeric list. A shallow copy therefore preserved the graphics but could
    -- silently lose Surf semantics on the clone.
    --
    -- Rebuild both lists explicitly before registration. 0x14 is CAVERN's
    -- canonical animated water graphic and is included defensively even if the
    -- runtime getter's waterTiles table is empty or set-shaped.
    local function rebuildTileList(source, required)
      local out = {}
      local seen = {}

      local function add(tileId)
        if type(tileId) ~= "number" or seen[tileId] then return end
        seen[tileId] = true
        out[#out + 1] = tileId
      end

      for key, value in pairs(source or {}) do
        if type(value) == "number" then
          add(value)
        elseif value == true and type(key) == "number" then
          add(key)
        end
      end

      for _, tileId in ipairs(required or {}) do
        add(tileId)
      end

      return out
    end

    alabasterTileset.waterTiles =
      rebuildTileList(alabasterBaseCavern.waterTiles, { 0x14 })

    alabasterTileset.shoreTiles =
      rebuildTileList(alabasterBaseCavern.shoreTiles)

    local ok, err = pcall(function()
      mod.content.tilesets:register("CAVERN_ALABASTER", alabasterTileset)
    end)

    if ok then
      alabasterCaveTilesetId = "CAVERN_ALABASTER"

      -- Surf checks the map's tileset id against field.waterTilesets
      -- separately from Map:isWaterCell(). Since this clone has a new id, it
      -- must be explicitly admitted to the Surf-capable tileset list.
      mod.content.field:patch("waterTilesets", {
        __append = { "CAVERN_ALABASTER" },
      })
    else
      mod.log:warn(
        "Could not register CAVERN_ALABASTER; Alabaster Cave will use normal CAVERN: "
          .. tostring(err)
      )
    end
  end

  if alabasterCaveTilesetId == "CAVERN_ALABASTER" then
    local AlabasterPaletteFX = require("src.render.PaletteFX")
    local pack = AlabasterPaletteFX.gbcPack()

    if pack and pack.world then
      pack.world.tileGroups = pack.world.tileGroups or {}
      pack.world.groupColors = pack.world.groupColors or {}

      local sourceGroups = pack.world.tileGroups.CAVERN or {}
      local sourceColors = pack.world.groupColors.CAVERN or {}

      local icyGroups = {}
      local icyColors = {}

      for tileId, group in pairs(sourceGroups) do
        icyGroups[tileId] = group
      end

      local function clampByte(v)
        v = math.floor((v or 0) + 0.5)
        if v < 0 then return 0 end
        if v > 255 then return 255 end
        return v
      end

      local function icyTint(rgb)
        local r = (rgb and rgb[1]) or 0
        local g = (rgb and rgb[2]) or 0
        local b = (rgb and rgb[3]) or 0

        -- Preserve the original luminance/detail, but shift the material away
        -- from CAVERN's purple/brown cast toward cold blue-gray/cyan.
        local lum = (r * 0.299) + (g * 0.587) + (b * 0.114)

        local iceR = 28 + (lum * 0.78)
        local iceG = 36 + (lum * 0.92)
        local iceB = 52 + (lum * 1.02)

        -- Keep a small amount of the source color so water/rock groups retain
        -- subtle material differences instead of all becoming one flat ramp.
        local preserve = 0.12
        local cool = 1.0 - preserve

        return {
          clampByte((iceR * cool) + (r * preserve)),
          clampByte((iceG * cool) + (g * preserve)),
          clampByte((iceB * cool) + (b * preserve)),
        }
      end

      for groupIndex, colors in ipairs(sourceColors) do
        local ramp = {}
        for shadeIndex, rgb in ipairs(colors or {}) do
          ramp[shadeIndex] = icyTint(rgb)
        end
        icyColors[groupIndex] = ramp
      end

      pack.world.tileGroups.CAVERN_ALABASTER = icyGroups
      pack.world.groupColors.CAVERN_ALABASTER = icyColors

      mod.log:info(
        "Installed Alabaster Cave icy Advanced Color groups on CAVERN_ALABASTER"
      )
    else
      mod.log:warn(
        "Advanced Color palette pack unavailable; Alabaster Cave will use normal CAVE colors"
      )
    end
  end

