  ---------------------------------------------------------------------------
  -- MT. CINNABAR COMPLETE — 1F + B1F + B2F
  --
  -- Cinnabar Island was expanded 8 blocks west (10 -> 18 blocks).
  -- Route 21 was expanded 6 blocks west (10 -> 16 blocks).
  --
  -- incorrectly left every north/south connection at offset 0.
  -- compensates for the authored westward shifts:
  --
  --   PALLET_TOWN south -> ROUTE_21 : -6
  --   ROUTE_21 north -> PALLET_TOWN : +6
  --   ROUTE_21 south -> CINNABAR    : -2
  --   CINNABAR north -> ROUTE_21    : +2
  --
  -- This keeps the original vanilla portions of all three maps aligned.
  -- The exterior cave mouth remains the authored OVERWORLD block at
  -- Cinnabar block (5,1).
  --
  -- Mt. Cinnabar 1F/B1F/B2F use indices 1010/1011/1012. Only 1F contains
  -- trainers. B2F uses a map-local magma tileset clone and now holds the
  -- relocated static Moltres encounter.
  ---------------------------------------------------------------------------

  local MarsMapDef = require("src.world.Map")
  local mtCinnabarOverworldTileset = mod.content.tilesets:get("OVERWORLD")
  local mtCinnabarCavernTileset = mod.content.tilesets:get("CAVERN")

  ---------------------------------------------------------------------------
  -- RESTORE VANILLA CAVERN COLLISION FOR MT. CINNABAR
  --
  -- added the ladder collision tile IDs to a Mt. Cinnabar-local
  -- walkable list. Those tile IDs are reused by ordinary cave rocks, so the
  -- change made unrelated rock cells passable. The current map setup removes that tileset
  -- mutation completely: 1F/B1F use the unmodified CAVERN tileset again.
  -- The internal ladders are handled later by a precise collision-attempt
  -- trigger and therefore require no passability changes at all.
  ---------------------------------------------------------------------------

  local mtCinnabarCaveTilesetId = "CAVERN"

  ---------------------------------------------------------------------------
  -- B2F-ONLY MAGMA TILESET
  --
  -- Clone CAVERN at runtime so no other cave is recolored. The clone shares
  -- the exact same image/block/collision data, but it is not Surf water.
  -- Advanced Color assigns the animated liquid graphic a dedicated
  -- yellow/orange/red magma ramp while all rock tiles keep CAVERN's groups.
  ---------------------------------------------------------------------------

  local mtCinnabarMagmaTilesetId = "CAVERN"
  local mtCinnabarMagmaWaterTiles = { 0x14 }

  if mtCinnabarCavernTileset then
    local magmaTileset = {}
    for key, value in pairs(mtCinnabarCavernTileset) do
      magmaTileset[key] = value
    end

    magmaTileset.id = "CAVERN_MAGMA"

    -- Capture every liquid graphic used by CAVERN before stripping Surf
    -- semantics from the clone.
    local seenMagmaTile = { [0x14] = true }
    mtCinnabarMagmaWaterTiles = { 0x14 }

    for key, value in pairs(mtCinnabarCavernTileset.waterTiles or {}) do
      local tileId = nil
      if type(value) == "number" then
        tileId = value
      elseif value == true and type(key) == "number" then
        tileId = key
      end
      if tileId ~= nil and not seenMagmaTile[tileId] then
        seenMagmaTile[tileId] = true
        mtCinnabarMagmaWaterTiles[#mtCinnabarMagmaWaterTiles + 1] = tileId
      end
    end

    -- Block 118 is the liquid block used throughout the revised B2F pool.
    -- Include every raw graphic it references so the full pool inherits the
    -- magma group even if a future import changes waterTiles metadata.
    local liquidBlock = mtCinnabarCavernTileset.blocks
      and mtCinnabarCavernTileset.blocks[118 + 1]
    for _, tileId in ipairs(liquidBlock or {}) do
      if not seenMagmaTile[tileId] then
        seenMagmaTile[tileId] = true
        mtCinnabarMagmaWaterTiles[#mtCinnabarMagmaWaterTiles + 1] = tileId
      end
    end

    -- Magma is a visual barrier, not Surfable water.
    magmaTileset.waterTiles = {}
    magmaTileset.shoreTiles = {}

    local ok, err = pcall(function()
      mod.content.tilesets:register("CAVERN_MAGMA", magmaTileset)
    end)

    if ok then
      mtCinnabarMagmaTilesetId = "CAVERN_MAGMA"
    else
      mod.log:warn("Could not register CAVERN_MAGMA; B2F will fall back to CAVERN: " .. tostring(err))
    end
  end

  -- RED++ / Advanced Color: duplicate CAVERN's groups, then replace only the
  -- B2F liquid graphics with a magma palette. Animated water uses these same
  -- resolved tile-group colors, so the magma keeps the normal ripple motion.
  if mtCinnabarMagmaTilesetId == "CAVERN_MAGMA" then
    local MagmaPaletteFX = require("src.render.PaletteFX")
    local pack = MagmaPaletteFX.gbcPack()

    if pack and pack.world then
      pack.world.tileGroups = pack.world.tileGroups or {}
      pack.world.groupColors = pack.world.groupColors or {}

      local sourceGroups = pack.world.tileGroups.CAVERN or {}
      local sourceColors = pack.world.groupColors.CAVERN or {}
      local magmaGroups = {}
      local magmaColors = {}

      local maxGroup = -1
      for tileId, group in pairs(sourceGroups) do
        magmaGroups[tileId] = group
        if type(group) == "number" and group > maxGroup then
          maxGroup = group
        end
      end
      for i, colors in ipairs(sourceColors) do
        magmaColors[i] = colors
      end

      local magmaGroup = maxGroup + 1
      for _, tileId in ipairs(mtCinnabarMagmaWaterTiles) do
        magmaGroups[tileId] = magmaGroup
      end

      magmaColors[magmaGroup + 1] = {
        { 255, 244, 150 },
        { 255, 166,  48 },
        { 205,  65,  25 },
        {  78,  18,  12 },
      }

      pack.world.tileGroups.CAVERN_MAGMA = magmaGroups
      pack.world.groupColors.CAVERN_MAGMA = magmaColors
      mod.log:info("Installed Mt. Cinnabar B2F magma Advanced Color groups")
    else
      mod.log:warn("Advanced Color pack unavailable; B2F magma uses normal CAVE colors")
    end
  end

  local marsCinnabarExpandedBlocks = {
       87,  87,  87,  87,  87,  87,  37,  41,  24, 100,  12,  13,  14,  85, 123,  12,  13,  14,
       87,  87,  87,  87,  87,   6,  87,  37,  24, 100,  16,  58,   0,  85, 121,  16,  17,  18,
       24,  67,  84,  84,  74,  92,  75, 123,  27,  85,  85,  85, 121,  85, 123, 123, 123,  85,
       24,  67, 120,  84,  84,  84, 123, 123,  27,  85,  32,  13,  33,  85,  85,  85,  85,  85,
