  -- Determine which lower 16px cell of the user's cave-mouth block actually
  -- carries the OVERWORLD door/warp tile. Route 4's Mt. Moon entrance uses
  -- this same one-cell cave-mouth convention. Fall back to the left cell if
  -- a stale tileset cache does not expose doorTiles/warpTiles.
  local function marsDefIsWarpCell(def, tilesetDef, cx, cy)
    if not (def and tilesetDef) then return false end
    local tile = MarsMapDef.defCellTile(def, tilesetDef, cx, cy)
    if tile == nil then return false end
    for _, t in ipairs(tilesetDef.doorTiles or {}) do
      if t == tile then return true end
    end
    for _, t in ipairs(tilesetDef.warpTiles or {}) do
      if t == tile then return true end
    end
    return false
  end

