  ---------------------------------------------------------------------------
  -- MT. CINNABAR INTERNAL LADDER HANDLING
  --
  -- These authored ladders are visual CAVERN blocks, but their standing
  -- cells are not guaranteed to use vanilla CAVERN collision/warp tiles.
  -- Do not mutate the shared CAVERN tileset globally.  Internal floor
  -- changes are handled explicitly below with a collision exception plus
  -- scripted world warps.
  ---------------------------------------------------------------------------

  -- Find the actual warp-bearing 16px cell inside an authored ladder block.
  -- It is allowed to be solid: the entry handler triggers when the player ATTEMPTS to
  -- enter this cell, before ordinary collision can reject the step.
  local function marsMtCinnabarWarpCell(def, blockX, blockY, fallbackX, fallbackY)
    if mtCinnabarCavernTileset then
      for cy = blockY * 2, blockY * 2 + 1 do
        for cx = blockX * 2, blockX * 2 + 1 do
          if marsDefIsWarpCell(def, mtCinnabarCavernTileset, cx, cy) then
            return cx, cy
          end
        end
      end
    end
    return fallbackX, fallbackY
  end

  local mtCinnabar1FDownX, mtCinnabar1FDownY =
    marsMtCinnabarWarpCell(marsMtCinnabar1FDef, 12, 1, 25, 3)
  local mtCinnabarB1FUpX, mtCinnabarB1FUpY =
    marsMtCinnabarWarpCell(marsMtCinnabarB1FDef, 12, 1, 25, 3)

  -- B1F's authored block-62 stair descends to B2F. The revised B2F uses its
  -- own block-62 stair at (12,9) to return.
  local mtCinnabarB1FDownX, mtCinnabarB1FDownY =
    marsMtCinnabarWarpCell(marsMtCinnabarB1FDef, 6, 10, 13, 21)
  local mtCinnabarB2FUpX, mtCinnabarB2FUpY =
    marsMtCinnabarWarpCell(marsMtCinnabarB2FDef, 12, 9, 25, 19)

  mod.log:info(
    "Mt. Cinnabar ladders resolved: 1F down=(%d,%d), B1F up=(%d,%d), B1F down=(%d,%d), B2F up=(%d,%d)",
    mtCinnabar1FDownX, mtCinnabar1FDownY,
    mtCinnabarB1FUpX, mtCinnabarB1FUpY,
    mtCinnabarB1FDownX, mtCinnabarB1FDownY,
    mtCinnabarB2FUpX, mtCinnabarB2FUpY
  )

  -- Trainer placements are authored near the start, middle, and deeper side
  -- of the floor. Validate against the actual imported CAVERN blockset so a
  -- decorative block variant cannot accidentally spawn a trainer in a wall.
  local function marsNearestMtCinnabarWalkable(preferredX, preferredY)
    if not mtCinnabarCavernTileset then
      return preferredX, preferredY
    end

    if MarsMapDef.defIsWalkableCell(
        marsMtCinnabar1FDef, mtCinnabarCavernTileset,
        preferredX, preferredY
      )
    then
      return preferredX, preferredY
    end

    for radius = 1, 6 do
      for dy = -radius, radius do
        for dx = -radius, radius do
          if math.max(math.abs(dx), math.abs(dy)) == radius then
            local x, y = preferredX + dx, preferredY + dy
            if x >= 1 and y >= 1
               and x < marsMtCinnabar1FDef.width * 2 - 1
               and y < marsMtCinnabar1FDef.height * 2 - 1
               and MarsMapDef.defIsWalkableCell(
                 marsMtCinnabar1FDef, mtCinnabarCavernTileset, x, y
               )
            then
              return x, y
            end
          end
        end
      end
    end

    return preferredX, preferredY
  end

  local function marsNearestMtCinnabarB1FWalkable(preferredX, preferredY)
    if not mtCinnabarCavernTileset then
      return preferredX, preferredY
    end

    if MarsMapDef.defIsWalkableCell(
        marsMtCinnabarB1FDef, mtCinnabarCavernTileset,
        preferredX, preferredY
      )
    then
      return preferredX, preferredY
    end

    for radius = 1, 6 do
      for dy = -radius, radius do
        for dx = -radius, radius do
          if math.max(math.abs(dx), math.abs(dy)) == radius then
            local x, y = preferredX + dx, preferredY + dy
            if x >= 1 and y >= 1
               and x < marsMtCinnabarB1FDef.width * 2 - 1
               and y < marsMtCinnabarB1FDef.height * 2 - 1
               and MarsMapDef.defIsWalkableCell(
                 marsMtCinnabarB1FDef, mtCinnabarCavernTileset, x, y
               )
            then
              return x, y
            end
          end
        end
      end
    end

    return preferredX, preferredY
  end

  local mtCinnabarB1FFireStoneX, mtCinnabarB1FFireStoneY =
    marsNearestMtCinnabarB1FWalkable(4, 19)
  local mtCinnabarB1FMaxEtherX, mtCinnabarB1FMaxEtherY =
    marsNearestMtCinnabarB1FWalkable(22, 13)

  local function marsNearestMtCinnabarB2FWalkable(preferredX, preferredY)
    local tilesetDef = mod.content.tilesets:get(mtCinnabarMagmaTilesetId)
      or mtCinnabarCavernTileset
    if not tilesetDef then
      return preferredX, preferredY
    end

    if MarsMapDef.defIsWalkableCell(
        marsMtCinnabarB2FDef, tilesetDef, preferredX, preferredY
      )
    then
      return preferredX, preferredY
    end

    -- Keep the legendary on or immediately beside the central dry island,
    -- rather than allowing a broad nearest-cell search to move it elsewhere.
    for radius = 1, 4 do
      for dy = -radius, radius do
        for dx = -radius, radius do
          if math.max(math.abs(dx), math.abs(dy)) == radius then
            local x, y = preferredX + dx, preferredY + dy
            if x >= 9 and x <= 18 and y >= 7 and y <= 17
               and MarsMapDef.defIsWalkableCell(
                 marsMtCinnabarB2FDef, tilesetDef, x, y
               )
            then
              return x, y
            end
          end
        end
      end
    end

    return preferredX, preferredY
  end

