    local sourceCenterScript = mod.content.map_scripts:get("CERULEAN_POKECENTER")
    local sourceCenterTalk = sourceCenterScript and sourceCenterScript.talk or {}

    local centerTalk = {
      TEXT_ALABASTER_POKECENTER_HIKER = {
