    mod.content.maps:register("INDIGO_TUTOR_HOUSE", {
      id = "INDIGO_TUTOR_HOUSE",
      label = "IndigoTutorHouse",
      index = 1018,
      tileset = "HOUSE",
      palette = "PEWTER",
      environment = "inside",
      width = 4,
      height = 4,
      borderBlock = 10,
      blocks = houseBlocks,
