      index = 1020,
      tileset = "HOUSE",
      palette = "PEWTER",
      environment = "inside",
      width = 4,
      height = 4,
      borderBlock = 10,
      blocks = houseBlocks,
      connections = {},
      warps = {
        { x = 2, y = 7, destMap = "INDIGO_CITY", destWarp = 5 },
