      },
      signs = {},
      objects = {
        {
          index = 1, name = "INDIGO_LAST_TEAM_OLD_MAN",
          sprite = "SPRITE_BALDING_GUY", movement = "STAY", range = "DOWN",
          x = 5, y = 3, text = "TEXT_INDIGO_LAST_TEAM_OLD_MAN",
        },
        {
          index = 2, name = "INDIGO_LAST_TEAM_DAUGHTER",
          sprite = "SPRITE_GIRL", movement = "STAY", range = "DOWN",
          x = 5, y = 3, text = "TEXT_INDIGO_LAST_TEAM_DAUGHTER",
        },
      },
    })

    -------------------------------------------------------------------------
    -- SKARMORY -> HERACROSS trade (ATLAS)
    -------------------------------------------------------------------------

    local indigoTradeIndex

    if mod.content.field then
      local trades = mod.content.field:get("trades")
      if type(trades) == "table" and #trades > 0 then
        local updated = {}
        for i, row in ipairs(trades) do
          if type(row) == "table" then
            updated[i] = {
              give = row.give,
              get = row.get,
              dialogset = row.dialogset,
              nickname = row.nickname,
              texts = row.texts,
            }
          else
            updated[i] = row
          end
        end

        indigoTradeIndex = #updated + 1
        updated[indigoTradeIndex] = {
          give = "SKARMORY",
          get = "HERACROSS",
          dialogset = 1,
          nickname = "Atlas",
          texts = {
            wannaTrade = "_MARS_INDIGO_TRADE_WANNA",
            noTrade = "_MARS_INDIGO_TRADE_NO",
            wrongMon = "_MARS_INDIGO_TRADE_WRONG",
            thanks = "_MARS_INDIGO_TRADE_THANKS",
            afterTrade = "_MARS_INDIGO_TRADE_AFTER",
          },
        }
        mod.content.field:override("trades", updated)
        mod.log:info(
          "added Indigo SKARMORY->HERACROSS trade at slot %d",
          indigoTradeIndex
        )
      else
        mod.log:warn("could not read field.trades; Indigo trade skipped")
      end
    end

    mod.content.text:register(
      "_MARS_INDIGO_TRADE_WANNA",
      "I'm a huge BUG POKEMON\nfan!\f"
        .. "I'd love a SKARMORY\nfrom the HIGHLANDS.\f"
        .. "Wanna trade your\n{RAM:wInGameTradeGiveMonName}\nfor my {RAM:wInGameTradeReceiveMonName}?"
    )
    mod.content.text:register(
      "_MARS_INDIGO_TRADE_NO",
      "No worries!\fMy offer isn't\ngoing anywhere."
    )
    mod.content.text:register(
      "_MARS_INDIGO_TRADE_WRONG",
      "That's not the\n{RAM:wInGameTradeGiveMonName}\nI'm looking for."
    )
    mod.content.text:register(
      "_MARS_INDIGO_TRADE_THANKS",
      "Perfect!\fTake good care of\nATLAS!"
    )
    mod.content.text:register(
      "_MARS_INDIGO_TRADE_AFTER",
      "How's ATLAS doing?\f"
        .. "This SKARMORY is\nawesome!"
    )

    -------------------------------------------------------------------------
    -- Reusable HONE CLAWS move tutor.
    -------------------------------------------------------------------------

    mod.content.text:register(
      "_MARS_INDIGO_TUTOR_ASK",
      "Training in INDIGO CITY\ntaught me a technique\nfor power and precision.\f"
        .. "I can teach a POKEMON\nHONE CLAWS.\fWant me to?"
    )
    mod.content.text:register(
      "_MARS_INDIGO_TUTOR_NO",
      "Keep training!\fI'll be here if you\nchange your mind."
    )
    mod.content.text:register(
      "_MARS_INDIGO_TUTOR_CANT",
      "That POKEMON can't\nget the hang of\nHONE CLAWS."
    )
    mod.content.text:register(
      "_MARS_INDIGO_TUTOR_ALREADY",
      "That POKEMON already\nknows HONE CLAWS!"
    )

    local function alreadyKnows(mon, moveId)
      for _, mv in ipairs(mon.moves or {}) do
        if mv.id == moveId then return true end
      end
      return false
    end

    local function speciesCanLearn(game, mon, moveId)
      local pdef = game.data.pokemon and game.data.pokemon[mon.species]
      if not pdef then return false end

      for _, row in ipairs(pdef.learnset or {}) do
        local learned = type(row) == "table" and (row.move or row[2]) or nil
        if learned == moveId then return true end
      end

      for _, learned in ipairs(pdef.level1Moves or {}) do
        if learned == moveId then return true end
      end

      return false
    end

    local function tutorTalk(game, ow, npc, done)
      local TextBox = require("src.render.TextBox")
      local PartyMenu = require("src.ui.PartyMenu")

      game.stack:push(TextBox.new(
        game,
        game.data.text._MARS_INDIGO_TUTOR_ASK,
        nil,
        {
          choice = function(yes)
            if not yes then
              game.stack:push(TextBox.new(
                game,
                game.data.text._MARS_INDIGO_TUTOR_NO,
                done
              ))
              return
            end

            game.stack:push(PartyMenu.new(game, {
              pickOnly = true,
              onCancel = done,
              onSwitch = function(mon)
                if alreadyKnows(mon, "HONE_CLAWS") then
                  game.stack:push(TextBox.new(
                    game,
                    game.data.text._MARS_INDIGO_TUTOR_ALREADY,
                    done
                  ))
                  return
                end

                if not speciesCanLearn(game, mon, "HONE_CLAWS") then
                  game.stack:push(TextBox.new(
                    game,
                    game.data.text._MARS_INDIGO_TUTOR_CANT,
                    done
                  ))
                  return
                end

                mon.moves = mon.moves or {}
                local mdef = game.data.moves.HONE_CLAWS
                local monDef = game.data.pokemon[mon.species]
                local monName = mon.nickname or (monDef and monDef.name) or mon.species

                if #mon.moves < 4 then
                  table.insert(mon.moves, {
                    id = "HONE_CLAWS",
                    pp = mdef.pp,
                  })
                  game.stack:push(TextBox.new(
                    game,
                    monName .. " learned\nHONE CLAWS!",
                    done
                  ))
                  return
                end

                local MoveLearnMenu = require("src.ui.MoveLearnMenu")
                game.stack:push(MoveLearnMenu.new(
                  game,
                  mon,
                  "HONE_CLAWS",
                  function()
                    if done then done() end
                  end
                ))
              end,
            }))
          end,
        }
      ))
    end

    if mod.content.map_scripts then
      mod.content.map_scripts:register("INDIGO_TUTOR_HOUSE", {
        priority = 125,
        talk = {
          TEXT_INDIGO_HONE_CLAWS_TUTOR = tutorTalk,
        },
      })

      local tradeTalk
      if indigoTradeIndex then
        tradeTalk = {
          { "face_player" },
          { "trade", indigoTradeIndex, "EVENT_INDIGO_SKARMORY_HERACROSS_TRADE" },
        }
      else
        tradeTalk = {
          { "face_player" },
          { "show_text", "_MARS_INDIGO_TRADE_NO" },
        }
      end

      mod.content.map_scripts:register("INDIGO_APARTMENT_TRADE", {
        priority = 125,
        talk = {
          TEXT_INDIGO_SKARMORY_TRADER = tradeTalk,
        },
      })
    end

    local houseSong = mod.content.map_songs:get("PEWTER_SPEECH_HOUSE")
    if houseSong then
      mod.content.map_songs:register("INDIGO_TUTOR_HOUSE", houseSong)
      mod.content.map_songs:register("INDIGO_APARTMENT_TRADE", houseSong)
      mod.content.map_songs:register("INDIGO_APARTMENT_OPEN", houseSong)
    end

    -- Locked decorative apartment doors stay solid.
    local lockedDoorCells = {
      ["7:21"] = true,
      ["17:21"] = true,
      ["25:21"] = true,
    }

    -- The authored Gym facade's visual doorway sits in the two center cells
    -- of the building, but those cells are not native OVERWORLD door tiles.
    -- Let the player step onto them when TILE collision is the only blocker;
    -- the Indigo City onStep handler below immediately performs the warp.
    local indigoGymEntranceCells = {
      ["22:7"] = true,
    }

    mod.hooks:wrap("movement.collision", function(next, allowed, ctx)
      if not ctx or not ctx.map then
        return next(allowed, ctx)
      end

      local key = tostring(ctx.toX) .. ":" .. tostring(ctx.toY)

      if ctx.map.id == "INDIGO_CITY" then
        if lockedDoorCells[key] then
          ctx.reason = "tile"
          return false
        end

        if indigoGymEntranceCells[key]
           and allowed == false
           and ctx.reason == "tile"
        then
          ctx.reason = nil
          return true
        end
      elseif ctx.map.id == "INDIGO_GYM" then
        -- Same fail-safe for the two authored exit cells in case the imported
        -- GYM tileset metadata does not mark them walkable in a stale cache.
        if (key == "8:17" or key == "9:17")
           and allowed == false
           and ctx.reason == "tile"
        then
          ctx.reason = nil
          return true
        end
      end

      return next(allowed, ctx)
    end, 997)
  end)()

  ;(function()
    -------------------------------------------------------------------------
    -- INDIGO CITY APARTMENT 4 — "THE LAST TEAM" + DETERMINISTIC KINDNESS
    --
    -- An elderly former trainer asks to see MACHOP, LITLEO, then PIKACHU
    -- so he can remember the companions he buried in POKEMON TOWER.
    -- After the final memory he gives the player a POKE DOLL. Once the
    -- player leaves Indigo City through the Highlands and later returns,
    -- his daughter replaces him and gifts CHARITY, a unique Blissey whose
    -- exclusive move KINDNESS prevents physical moves for five turns.
    -------------------------------------------------------------------------

    local function lastTeamSay(game, textId, done)
      local TextBox = require("src.render.TextBox")
      game.stack:push(TextBox.new(
        game,
        game.data.text[textId],
        done
      ))
    end

    local function lastTeamSayLiteral(game, text, done)
      local TextBox = require("src.render.TextBox")
      game.stack:push(TextBox.new(game, text, done))
    end

    local function lastTeamFacePlayer(ow, npc)
      if npc and npc.facePlayer and ow and ow.player then
        npc:facePlayer(ow.player)
      end
    end

    local function lastTeamPartyHas(save, species)
      for _, mon in ipairs((save and save.party) or {}) do
        if mon.species == species then return true end
      end
      return false
    end

    local function lastTeamPokeDollId(game)
      if game.data.items and game.data.items.POKE_DOLL then
        return "POKE_DOLL"
      end

      for id, def in pairs((game.data and game.data.items) or {}) do
        local name = def and def.name
        if name == "POKE DOLL" or name == "POKé DOLL" then
          return id
        end
      end

      return nil
    end

    local function lastTeamGivePokeDoll(game, done)
      local flags = game.save.flags or {}
      local itemId = lastTeamPokeDollId(game)

      if not itemId then
        mod.log:error(
          "Last Team quest could not resolve the POKE DOLL item id"
        )
        lastTeamSay(
          game,
          "_MARS_LAST_TEAM_DOLL_ERROR",
          done
        )
        return
      end

      local Bag = require("src.inventory.Bag")
      if not Bag.add(game.save, itemId, 1, game.data) then
        lastTeamSay(game, "_MARS_LAST_TEAM_BAG_FULL", done)
        return
      end

      flags.EVENT_INDIGO_LAST_TEAM_COMPLETE = true

      local Sound = require("src.core.Sound")
      Sound.play(game.data, "Get_Item1")

      lastTeamSay(game, "_MARS_LAST_TEAM_GOT_DOLL", done)
    end

    local function lastTeamOldManTalk(game, ow, npc, done)
      local flags = game.save.flags or {}
      lastTeamFacePlayer(ow, npc)

      if not flags.EVENT_INDIGO_LAST_TEAM_STARTED then
        flags.EVENT_INDIGO_LAST_TEAM_STARTED = true
        lastTeamSay(game, "_MARS_LAST_TEAM_INTRO", done)
        return
      end

      if not flags.EVENT_INDIGO_LAST_TEAM_MACHOP then
        if not lastTeamPartyHas(game.save, "MACHOP") then
          lastTeamSay(game, "_MARS_LAST_TEAM_NEED_MACHOP", done)
          return
        end

        flags.EVENT_INDIGO_LAST_TEAM_MACHOP = true
        lastTeamSay(game, "_MARS_LAST_TEAM_MACHOP_MEMORY", done)
        return
      end

      if not flags.EVENT_INDIGO_LAST_TEAM_LITLEO then
        if not lastTeamPartyHas(game.save, "LITLEO") then
          lastTeamSay(game, "_MARS_LAST_TEAM_NEED_LITLEO", done)
          return
        end

        flags.EVENT_INDIGO_LAST_TEAM_LITLEO = true
        lastTeamSay(game, "_MARS_LAST_TEAM_LITLEO_MEMORY", done)
        return
      end

      if not flags.EVENT_INDIGO_LAST_TEAM_PIKACHU then
        if not lastTeamPartyHas(game.save, "PIKACHU") then
          lastTeamSay(game, "_MARS_LAST_TEAM_NEED_PIKACHU", done)
          return
        end

        flags.EVENT_INDIGO_LAST_TEAM_PIKACHU = true
        lastTeamSay(
          game,
          "_MARS_LAST_TEAM_PIKACHU_MEMORY",
          function()
            lastTeamGivePokeDoll(game, done)
          end
        )
        return
      end

      if not flags.EVENT_INDIGO_LAST_TEAM_COMPLETE then
        -- The final memory has already been shared; this is only a retry
        -- path for a previously full bag.
        lastTeamGivePokeDoll(game, done)
        return
      end

      lastTeamSay(game, "_MARS_LAST_TEAM_OLD_MAN_AFTER", done)
    end

    local function lastTeamBuildCharity(game)
      local Pokemon = require("src.pokemon.Pokemon")
      local Party = require("src.pokemon.Party")
      local Boxes = require("src.pokemon.Boxes")
      local BattleState = require("src.battle.BattleState")

      local mon = Pokemon.new(game.data, "BLISSEY", 50)
      mon.nickname = "Charity"
      mon.marsCharity = true

      local moveIds = {
        "KINDNESS",
        "SOFTBOILED",
        "LIGHT_SCREEN",
        "DOUBLE_EDGE",
      }

      mon.moves = {}
      for _, moveId in ipairs(moveIds) do
        local def = game.data.moves and game.data.moves[moveId]
        if def then
          mon.moves[#mon.moves + 1] = {
            id = moveId,
            pp = def.pp,
          }
        else
          mod.log:warn(
            "CHARITY gift is missing move definition %s",
            tostring(moveId)
          )
        end
      end

      BattleState.stampOT(game.save, mon)

      local addedToParty = Party.add(game.save.party, mon)
      local boxNum = nil

      if not addedToParty then
        boxNum = Boxes.deposit(game.save, mon)
        if not boxNum then
          return false
        end
      end

      local dex = game.save.pokedex
      if dex then
        dex.seen = dex.seen or {}
        dex.owned = dex.owned or {}
        dex.seen.BLISSEY = true
        dex.owned.BLISSEY = true
      end

      return true, boxNum
    end

    local function lastTeamGiveCharity(game, done)
      local flags = game.save.flags or {}
      local ok, boxNum = lastTeamBuildCharity(game)

      if not ok then
        lastTeamSay(game, "_MARS_LAST_TEAM_STORAGE_FULL", done)
        return
      end

      flags.EVENT_INDIGO_LAST_TEAM_CHARITY_RECEIVED = true

      if boxNum then
        lastTeamSayLiteral(
          game,
          "CHARITY was sent\nto POKEMON BOX "
            .. tostring(boxNum)
            .. ".\fShe knows a special\nmove called KINDNESS.\f"
            .. "It can stop a foe\nfrom using physical\nmoves for a while.",
          done
        )
      else
        lastTeamSay(game, "_MARS_LAST_TEAM_CHARITY_JOINED", done)
      end
    end

    local function lastTeamDaughterTalk(game, ow, npc, done)
      local flags = game.save.flags or {}
      lastTeamFacePlayer(ow, npc)

      if flags.EVENT_INDIGO_LAST_TEAM_CHARITY_RECEIVED then
        lastTeamSay(game, "_MARS_LAST_TEAM_DAUGHTER_AFTER", done)
        return
      end

      if not flags.EVENT_INDIGO_LAST_TEAM_DAUGHTER_MET then
        flags.EVENT_INDIGO_LAST_TEAM_DAUGHTER_MET = true
        lastTeamSay(
          game,
          "_MARS_LAST_TEAM_DAUGHTER_INTRO",
          function()
            lastTeamGiveCharity(game, done)
          end
        )
        return
      end

      lastTeamSay(
        game,
        "_MARS_LAST_TEAM_DAUGHTER_RETRY",
        function()
          lastTeamGiveCharity(game, done)
        end
      )
    end

    -------------------------------------------------------------------------
    -- QUEST DIALOGUE
    -------------------------------------------------------------------------

    mod.content.text:register(
      "_MARS_LAST_TEAM_INTRO",
      "Ah... another\nTRAINER.\f"
        .. "I used to travel\nKANTO with a team\nof my own.\f"
        .. "They're all gone\nnow.\f"
        .. "I laid them to rest\nin POKEMON TOWER.\f"
        .. "Lately, I've wished\nI could see their\nfaces once more.\f"
        .. "Would you humor an\nold man?\f"
        .. "Bring me a MACHOP.\f"
        .. "I only want to see\none again."
    )

    mod.content.text:register(
      "_MARS_LAST_TEAM_NEED_MACHOP",
      "My first request was\na MACHOP.\f"
        .. "Just seeing one\nagain would mean\nmore than you know."
    )

    mod.content.text:register(
      "_MARS_LAST_TEAM_MACHOP_MEMORY",
      "MACHOP...\f"
        .. "Ha! Mine was always\ntrying to lift things\nfar too heavy.\f"
        .. "Rocks, crates...\neven my backpack\nwhile I wore it!\f"
        .. "It never knew when\nto quit.\f"
        .. "I called it stubborn\nback then.\f"
        .. "Now I'd give anything\nto see it try again.\f"
        .. "Thank you.\f"
        .. "There was another...\na LITLEO.\f"
        .. "Could you bring one\nto see me?"
    )

    mod.content.text:register(
      "_MARS_LAST_TEAM_NEED_LITLEO",
      "I'd like to see a\nLITLEO next.\f"
        .. "Mine was quite the\nlittle troublemaker."
    )

    mod.content.text:register(
      "_MARS_LAST_TEAM_LITLEO_MEMORY",
      "LITLEO...\f"
        .. "Mine thought it was\nking of KANTO before\nit could see over\nthe grass!\f"
        .. "It picked fights with\nanything bigger than\nit was.\f"
        .. "But if the team was\nin danger, it was\nalways first there.\f"
        .. "All that pride hid\na very loyal heart.\f"
        .. "Thank you, truly.\f"
        .. "Just one more.\f"
        .. "My oldest friend was\na PIKACHU.\f"
