    -------------------------------------------------------------------------
    -- MAP STATE / QUEST PROGRESSION
    -------------------------------------------------------------------------

    if mod.content.map_scripts then
      mod.content.map_scripts:register("INDIGO_APARTMENT_OPEN", {
        priority = 130,

        onEnter = function(game, ow)
          local flags = game.save.flags or {}

          if flags.EVENT_INDIGO_LAST_TEAM_AFTERMATH_READY then
            ow:queueScript({
              { "hide_object", "INDIGO_APARTMENT_OPEN", "INDIGO_LAST_TEAM_OLD_MAN" },
              { "show_object", "INDIGO_APARTMENT_OPEN", "INDIGO_LAST_TEAM_DAUGHTER" },
            })
          else
            ow:queueScript({
              { "show_object", "INDIGO_APARTMENT_OPEN", "INDIGO_LAST_TEAM_OLD_MAN" },
              { "hide_object", "INDIGO_APARTMENT_OPEN", "INDIGO_LAST_TEAM_DAUGHTER" },
            })
          end
        end,

        talk = {
          TEXT_INDIGO_LAST_TEAM_OLD_MAN = lastTeamOldManTalk,
          TEXT_INDIGO_LAST_TEAM_DAUGHTER = lastTeamDaughterTalk,
        },
      })

      -- Leaving Indigo City through the Highlands arms the aftermath, but
      -- simply stepping out of Apartment 4 and back in does not.
      mod.content.map_scripts:register("INDIGO_HIGHLANDS", {
        priority = 130,

        onEnter = function(game, ow)
          local flags = game.save.flags or {}

          if flags.EVENT_INDIGO_LAST_TEAM_COMPLETE
             and not flags.EVENT_INDIGO_LAST_TEAM_AFTERMATH_READY
          then
            flags.EVENT_INDIGO_LAST_TEAM_LEFT_CITY = true
          end
        end,
      })

      -- The daughter's replacement becomes active only after the player has
      -- actually left the city and then returned.
      mod.content.map_scripts:register("INDIGO_CITY", {
        priority = 130,

        onEnter = function(game, ow)
          local flags = game.save.flags or {}

          if flags.EVENT_INDIGO_LAST_TEAM_COMPLETE
             and flags.EVENT_INDIGO_LAST_TEAM_LEFT_CITY
             and not flags.EVENT_INDIGO_LAST_TEAM_AFTERMATH_READY
          then
            flags.EVENT_INDIGO_LAST_TEAM_AFTERMATH_READY = true
          end
        end,
      })
    end

    mod.log:info(
      "installed Last Team quest + deterministic CHARITY/KINDNESS action lock"
    )
  end)()


