  ;(function()
    -------------------------------------------------------------------------
    -- EXPANDED KANTO — A DOSE OF MERCY OPENING AND ABANDONMENT POLISH
    --
    -- Rules:
    --   * exactly 6 Pokemon required
    --   * legendary/mythical Pokemon banned
    --   * player's tournament copies are normalized to Lv.50
    --   * real party is never mutated
    --   * no EXP is awarded in tournament battles
    --   * tournament party is rebuilt/healed before every round
    --
    -- Bracket:
    --   Round 1      -> one of 20 class-only trainers
    --   Round of 16  -> another of those 20, no repeat
    --   Quarterfinal -> one of 8 named trainers
    --   Semifinal    -> another named trainer, no repeat
    --   Final        -> another named trainer, no repeat
    --   Leader Match -> MAEVIS
    --
    -- First Regular championship: Lv.15 MELTAN
    -- Repeat championships: ¥50,000
    -------------------------------------------------------------------------

    local BattleState = require("src.battle.BattleState")
    local Pokemon = require("src.pokemon.Pokemon")
    local Stats = require("src.pokemon.Stats")
    local Growth = require("src.pokemon.Growth")
    local Party = require("src.pokemon.Party")
    local Boxes = require("src.pokemon.Boxes")
    local TextBox = require("src.render.TextBox")
    local TrainerAI = require("src.battle.TrainerAI")
    local Bag = require("src.inventory.Bag")
    local ListMenu = require("src.ui.ListMenu")

    -------------------------------------------------------------------------
    -- HELPERS
    -------------------------------------------------------------------------

    local function tournamentDeepCopy(value, seen)
      if type(value) ~= "table" then return value end
      seen = seen or {}
      if seen[value] then return seen[value] end

      local out = {}
      seen[value] = out

      for k, v in pairs(value) do
        out[tournamentDeepCopy(k, seen)] = tournamentDeepCopy(v, seen)
      end

      return out
    end

    local function tournamentSay(game, text, done)
      game.stack:push(TextBox.new(game, text, done))
    end

    local function tournamentSayId(game, id, done)
      tournamentSay(game, game.data.text[id], done)
    end

    local function tournamentFacePlayer(ow, npc)
      if npc and npc.facePlayer and ow and ow.player then
        npc:facePlayer(ow.player)
      end
    end

    local function tournamentMakeParty(speciesList, level)
      local party = {}
      for _, member in ipairs(speciesList) do
        if type(member) == "table" then
          -- API 2's trainer registry schema currently accepts only species and
          -- level on a party slot. Keep authored Master moves out of the
          -- registry itself; they are injected through trainer.party below,
          -- after registry validation and before BattleState builds the mons.
          party[#party + 1] = {
            species = member.species,
            level = member.level or level,
          }
        else
          party[#party + 1] = {
            species = member,
            level = level,
          }
        end
      end
      return party
    end

    local MASTER_SETUP_MOVES = {
      CALM_MIND = true,
      BULK_UP = true,
      DRAGON_DANCE = true,
      SWORDS_DANCE = true,
      NASTY_PLOT = true,
      BELLY_DRUM = true,
      IRON_DEFENSE = true,
      AGILITY = true,
    }

    local function tournamentMasterBrain(maxRestores)
      return function(battle)
        local enemy = battle and battle.enemy
        local mon = enemy and enemy.mon

        if mon and mon.hp > 0 then
          local used = battle.marsMasterFullRestores or 0
          local maxHp = mon.stats and mon.stats.hp or 1
          local lowHp = mon.hp <= math.max(1, math.floor(maxHp / 3))
          local statused = mon.status ~= nil

          if used < (maxRestores or 0) and (lowHp or statused) then
            battle.marsMasterFullRestores = used + 1
            return { special = "aiItem", item = "FULL_RESTORE" }
          end

          -- Modern setup moves use custom effects that the faithful Gen 1 AI
          -- does not know how to score. Give each newly sent-out Pokemon one
          -- sensible chance to use a setup move while still healthy.
          battle.marsMasterSetupConsidered =
            battle.marsMasterSetupConsidered or {}

          if not battle.marsMasterSetupConsidered[mon]
             and mon.hp >= math.floor(maxHp * 2 / 3)
          then
            battle.marsMasterSetupConsidered[mon] = true
            if battle.rng(0, 255) < 96 then
              for _, moveInst in ipairs(enemy.curMoves or {}) do
                if MASTER_SETUP_MOVES[moveInst.id]
                   and (moveInst.pp or 0) > 0
                then
                  return moveInst
                end
              end
            end
          end
        end

        return TrainerAI.chooseMove(battle.enemy, battle.rng, battle)
      end
    end

    local function tournamentRegisterTrainer(
      id, displayName, baseClass, speciesList, opts
    )
      opts = opts or {}
      local baseTrainer = mod.content.trainers:get(baseClass) or {}

      mod.content.trainers:register(id, {
        id = id,
        name = displayName,
        basePic = baseClass,
        pic = opts.pic or baseTrainer.pic,
        trueColor = opts.trueColor ~= nil and opts.trueColor or baseTrainer.trueColor,
        paletteSource = opts.paletteSource or baseTrainer.paletteSource,
        baseMoney = 0,
        -- inherit the base trainer's real AI-class key. Many OPP_*
        -- trainer class ids are not entries in data.ai_classes, so falling back
        -- to baseClass here produced the unresolved-reference warnings.
        aiClass = opts.aiClass or baseTrainer.aiClass,
        aiMods = opts.aiMods or baseTrainer.aiMods,
        brain = opts.brain,
        parties = {
          tournamentMakeParty(speciesList, opts.level or 50),
        },
      })
    end

    -------------------------------------------------------------------------
    -- 20 CLASS-ONLY REGULAR-POOL TRAINERS
    -------------------------------------------------------------------------

    local regularPool = {
      {
        id = "OPP_TOURNEY_BLACKBELT",
        name = "BLACKBELT",
        base = "OPP_BLACKBELT",
