    -------------------------------------------------------------------------
    -- MASTER'S TOURNAMENT DIALOGUE FORMATTING
    --
    -- The engine does not word-wrap ordinary scripted battle text for us.
    -- Master entrant dialogue is authored as normal prose above, then wrapped
    -- here to the Game Boy text width. Existing form-feed page breaks remain
    -- meaningful, and any page that becomes longer than three lines is split
    -- into additional pages automatically.
    -------------------------------------------------------------------------

    local MASTER_DIALOGUE_WIDTH = 18
    local MASTER_DIALOGUE_LINES_PER_PAGE = 3

    local function masterWrapDialoguePage(page)
      page = tostring(page or ""):gsub("[\r\n]+", " ")

      local lines = {}
      local line = ""

      for word in page:gmatch("%S+") do
        if line == "" then
          line = word
        elseif #line + 1 + #word <= MASTER_DIALOGUE_WIDTH then
          line = line .. " " .. word
        else
          lines[#lines + 1] = line
          line = word
        end
      end

      if line ~= "" then
        lines[#lines + 1] = line
      end

      if #lines == 0 then
        return ""
      end

      local pages = {}
      local i = 1
      while i <= #lines do
        local pageLines = {}
        local last = math.min(i + MASTER_DIALOGUE_LINES_PER_PAGE - 1, #lines)
        for j = i, last do
          pageLines[#pageLines + 1] = lines[j]
        end
        pages[#pages + 1] = table.concat(pageLines, "\n")
        i = last + 1
      end

      return table.concat(pages, "\f")
    end

    local function masterFormatDialogue(text)
      local pages = {}
      local source = tostring(text or "") .. "\f"

      for page in source:gmatch("(.-)\f") do
        local wrapped = masterWrapDialoguePage(page)
        if wrapped ~= "" then
          pages[#pages + 1] = wrapped
        end
      end

      return table.concat(pages, "\f")
    end

    for _, entry in ipairs(masterEntries) do
      entry.intro = masterFormatDialogue(entry.intro)
      entry.defeat = masterFormatDialogue(entry.defeat)
    end

    masterMaevisEntry.intro = masterFormatDialogue(masterMaevisEntry.intro)
    masterMaevisEntry.defeat = masterFormatDialogue(masterMaevisEntry.defeat)

    local masterById = {}
    for _, entry in ipairs(masterEntries) do
      tournamentRegisterTrainer(
        entry.id,
        entry.name,
        entry.base,
        entry.team,
        {
          level = 100,
          pic = entry.pic,
          aiMods = { 1, 2, 3 },
          brain = tournamentMasterBrain(entry.restores),
        }
      )
      masterById[entry.id] = entry
    end

    tournamentRegisterTrainer(
      masterMaevisEntry.id,
      masterMaevisEntry.name,
      masterMaevisEntry.base,
      masterMaevisEntry.team,
      {
        level = 100,
        aiMods = { 1, 2, 3 },
        brain = tournamentMasterBrain(masterMaevisEntry.restores),
      }
    )
    masterById[masterMaevisEntry.id] = masterMaevisEntry

    -------------------------------------------------------------------------
    -- API-2-SAFE MASTER MOVESETS
    --
    -- BattleState.newTrainer intentionally honors an optional `moves` list
    -- returned by the trainer.party hook, but the API 2 trainer registry
    -- validator does not currently allow `moves` directly on registered party
    -- slots. Register only species/level above, then attach the authored four-
    -- move sets here at battle construction time. This keeps the full Master
    -- movesets without tripping mod-load validation.
    -------------------------------------------------------------------------

    local function tournamentMasterPartyWithMoves(partyDef, entry)
      local out = {}

      for i, slot in ipairs(partyDef or {}) do
        local copy = {
          species = slot.species,
          level = slot.level,
        }
        local authored = entry and entry.team and entry.team[i]

        if authored and authored.moves then
          copy.moves = {}
          for moveIndex, moveId in ipairs(authored.moves) do
            copy.moves[moveIndex] = moveId
          end
        end

        out[i] = copy
      end

      return out
    end

    mod.hooks:wrap("trainer.party", function(next, oppClass, partyIndex, partyDef)
      local entry = masterById[oppClass]

      if not entry or (partyIndex or 1) ~= 1 then
        return next(oppClass, partyIndex, partyDef)
      end

      return next(
        oppClass,
        partyIndex,
        tournamentMasterPartyWithMoves(partyDef, entry)
      )
    end, 90)

    do
      local victories = require("data.scripts.victories")
      victories["OPP_MASTER_MAEVIS#1"] = { badge = "EARTHBADGE" }
    end

    -------------------------------------------------------------------------
    -- TOURNAMENT PARTY VALIDATION / NORMALIZATION
    -------------------------------------------------------------------------

    local tournamentBannedSpecies = {
      ARTICUNO = true,
      ZAPDOS = true,
      MOLTRES = true,
      MEWTWO = true,
      MEW = true,
      LUGIA = true,
      HO_OH = true,
      CELEBI = true,
      MELTAN = true,
      MELMETAL = true,
      ARCEUS = true,
    }

    local function tournamentValidateParty(game, mode)
      local party = game.save.party or {}

      if #party ~= 6 then
        return false,
          mode == "master"
            and "_MARS_TOURNEY_MASTER_NEED_SIX"
            or "_MARS_TOURNEY_NEED_SIX"
      end

      for _, mon in ipairs(party) do
        if tournamentBannedSpecies[mon.species] then
          local def = game.data.pokemon and game.data.pokemon[mon.species]
          local name = (def and def.name) or mon.species
          return false, nil, name
        end
      end

      return true
    end

    local function tournamentNormalizeMon(game, sourceMon, level)
      local mon = tournamentDeepCopy(sourceMon)
      local def = game.data.pokemon[mon.species]

      mon.level = level
      mon.exp = Growth.expForLevel(def.growthRate, level, game.data.growth_rates)
      mon.stats = Stats.calc(
        def,
        level,
        mon.dvs or {},
        mon.statExp or {}
      )
      mon.hp = mon.stats.hp
      mon.status = nil

      for _, move in ipairs(mon.moves or {}) do
        local mdef = game.data.moves and game.data.moves[move.id]
        if mdef then
          local ppUps = move.ppUps or 0
          move.pp = mdef.pp + ppUps * math.floor(mdef.pp / 5)
        end
      end

      return mon
    end

    local function tournamentBuildTempParty(game, state)
      local party = {}

      for _, sourceMon in ipairs(state.team or {}) do
        party[#party + 1] = tournamentNormalizeMon(
          game,
          sourceMon,
          state.level or (state.mode == "master" and 100 or 50)
        )
      end

      return party
    end

    -------------------------------------------------------------------------
    -- RANDOM BRACKET GENERATION
    -------------------------------------------------------------------------

    local function tournamentPickUnique(pool, count)
      local indices = {}
      for i = 1, #pool do indices[i] = i end

      for i = #indices, 2, -1 do
        local j = love.math.random(1, i)
        indices[i], indices[j] = indices[j], indices[i]
      end

      local chosen = {}
      for i = 1, math.min(count, #indices) do
        chosen[#chosen + 1] = pool[indices[i]].id
      end

      return chosen
    end

    local function tournamentNewRegularState(game)
      return {
        active = true,
        mode = "regular",
        level = 50,
        round = 1,

        -- Snapshot the player's real six-Pokemon roster at registration.
        -- Every battle creates fresh Lv.50 copies from this snapshot.
        team = tournamentDeepCopy(game.save.party),

        generic = tournamentPickUnique(regularPool, 2),
        named = tournamentPickUnique(namedPool, 3),
      }
    end

    local function tournamentEligibleMasterEntries(game, tier)
      local flags = game.save.flags or {}
      local pool = {}

      for _, entry in ipairs(masterEntries) do
        if entry.tier == tier
           and (not entry.eligible or entry.eligible(flags))
        then
          pool[#pool + 1] = entry
        end
      end

      return pool
    end

    local function tournamentNewMasterState(game)
      local minors = tournamentEligibleMasterEntries(game, "minor")
      local majors = tournamentEligibleMasterEntries(game, "major")
      local elites = tournamentEligibleMasterEntries(game, "elite")
      local chosen = {}

      local function buildPool(...)
        local pool = {}
        local lists = { ... }
        for _, list in ipairs(lists) do
          for _, entry in ipairs(list) do
            if not chosen[entry.id] then
              pool[#pool + 1] = entry
            end
          end
        end
        return pool
      end

      local function chooseFrom(...)
        local pool = buildPool(...)
        local picked = tournamentPickUnique(pool, 1)[1]
        if picked then chosen[picked] = true end
        return picked
      end

      -- Broad strength bands keep the bracket escalating without making the
      -- sequence rigid. This allows runs such as MOM -> BILL -> SABRINA ->
      -- HANAKO -> LANCE, but also CAPTAIN -> COPYCAT -> MARCIE -> GIOVANNI
      -- -> OAK whenever those optional entrants are eligible.
      local opponents = {
        chooseFrom(minors),
        chooseFrom(minors, majors),
        chooseFrom(majors, elites),
        chooseFrom(majors, elites),
        chooseFrom(elites),
      }

      return {
        active = true,
        mode = "master",
        level = 100,
        round = 1,
        team = tournamentDeepCopy(game.save.party),
        opponents = opponents,
      }
    end

    local tournamentLayout = {
      maevisLobby = { x = 5, y = 3, facing = "down" },
      arenaPlayer = { x = 3, y = 6, facing = "right" },
      arenaMaevis = { x = 6, y = 6, facing = "left" },
      receptionist = { x = 5, y = 8 },
    }

    local function tournamentOpponentForRound(state)
      if state.mode == "master" then
        if state.round <= 5 then return state.opponents[state.round] end
        return "OPP_MASTER_MAEVIS"
      end

      if state.round == 1 then return state.generic[1] end
      if state.round == 2 then return state.generic[2] end
      if state.round == 3 then return state.named[1] end
      if state.round == 4 then return state.named[2] end
      if state.round == 5 then return state.named[3] end
      return "OPP_MAEVIS"
    end

    local function tournamentTrainerName(game, classId)
      if type(classId) == "string"
         and classId:match("^OPP_MASTER_RIVAL_")
      then
        return (game.save.player and game.save.player.rival) or "BLUE"
      end

      local trainer = game.data.trainers and game.data.trainers[classId]
      return (trainer and trainer.name) or classId
    end

    -------------------------------------------------------------------------
    -- BLANK TOURNAMENT BRACKET SCREEN
    --
    -- The bracket is intentionally presentation-only. Opponent names are
    -- announced by the normal textbox AFTER this screen closes.
    -------------------------------------------------------------------------

    mod.content.screens:register("MarsTournamentBracket", {
      new = function(game, opts)
        local Font = mod.ui.Font
        local self = {
          game = game,
          isOpaque = true,
        }

        function self:update(dt)
          -- Passive on purpose. This remains visible beneath the NEXT BATTLE
          -- textbox and is closed automatically by script right before the
          -- battle begins.
        end

        function self:draw()
          -- White Game Boy UI page.
          love.graphics.setColor(1, 1, 1, 1)
          love.graphics.rectangle("fill", 0, 0, 160, 144)

          -- Outer frame.
          love.graphics.setColor(0, 0, 0, 1)
          Font.drawBox(0, 0, 20, 18)

          local state = game.save and game.save.marsKantoTournament
          if state and state.mode == "master" then
            Font.draw("MASTER'S", 48, 10)
            Font.draw("TOURNAMENT", 40, 20)
          else
            Font.draw("KANTO FIGHTING", 24, 10)
            Font.draw("TOURNAMENT", 40, 20)
          end

          -- Blank slot boxes only.
          local openingYTiles = { 5, 8, 11, 14 }

          for _, y in ipairs(openingYTiles) do
            Font.drawBox(1, y, 4, 2)
            Font.drawBox(15, y, 4, 2)
          end

          -- Semifinal / quarterfinal-stage slots.
          Font.drawBox(6, 7, 3, 2)   -- upper left
          Font.drawBox(6, 12, 3, 2)  -- lower left
          Font.drawBox(11, 7, 3, 2)  -- upper right
          Font.drawBox(11, 12, 3, 2) -- lower right

          -- Championship slot.
          Font.drawBox(8, 9, 4, 2)

          love.graphics.setColor(1, 1, 1, 1)
        end

        return self
      end,
    })

    local function tournamentArenaIntroRows(ow)
      local rows = {
        { "show_text", "_MARS_TOURNEY_ARENA_CALL" },
      }

      local player = ow and ow.player
      local startX = player and player.cellX
        or tournamentLayout.receptionist.x
      local startY = player and player.cellY
        or (tournamentLayout.receptionist.y + 1)

      local targetX = tournamentLayout.arenaPlayer.x
      local targetY = tournamentLayout.arenaPlayer.y

      local dy = targetY - startY
      if dy < 0 then
        rows[#rows + 1] = { "move_player", "up", math.abs(dy) }
      elseif dy > 0 then
        rows[#rows + 1] = { "move_player", "down", dy }
      end

      local dx = targetX - startX
      if dx < 0 then
        rows[#rows + 1] = { "move_player", "left", math.abs(dx) }
      elseif dx > 0 then
        rows[#rows + 1] = { "move_player", "right", dx }
      end

      rows[#rows + 1] = {
        "face_player_dir",
        tournamentLayout.arenaPlayer.facing
      }

      return rows
    end

    -------------------------------------------------------------------------
    -- REWARD HELPERS
    -------------------------------------------------------------------------

    local function tournamentGiveMeltan(game, done)
      local flags = game.save.flags or {}

      local meltan = Pokemon.new(game.data, "MELTAN", 15)
      BattleState.stampOT(game.save, meltan)
      BattleState.markOwned(game, "MELTAN")

      local boxNum = nil
      local added = Party.add(game.save.party, meltan)

      if not added then
        boxNum = Boxes.deposit(game.save, meltan)
        if not boxNum then
          flags.EVENT_REGULAR_TOURNEY_MELTAN_PENDING = true
          tournamentSayId(
            game,
            "_MARS_TOURNEY_MELTAN_STORAGE_FULL",
            done
          )
          return
        end
      end

      flags.EVENT_REGULAR_TOURNEY_MELTAN_PENDING = nil
      flags.EVENT_REGULAR_TOURNEY_MELTAN_WON = true

      if boxNum then
        tournamentSay(
          game,
          "You received a\nLv.15 MELTAN!\f"
            .. "MELTAN was sent to\nPOKEMON BOX "
            .. tostring(boxNum)
            .. ".",
          done
        )
      else
        tournamentSayId(
          game,
          "_MARS_TOURNEY_MELTAN_RECEIVED",
          done
        )
      end
    end

    local function tournamentGiveCash(game, done)
      game.save.money = math.min(
        999999,
        (game.save.money or 0) + 50000
      )

      tournamentSayId(
        game,
        "_MARS_TOURNEY_CASH_PRIZE",
        done
      )
    end

    local function tournamentChampionshipReward(game, done)
      local flags = game.save.flags or {}

      if not flags.EVENT_REGULAR_TOURNEY_MELTAN_WON then
        tournamentSayId(
          game,
          "_MARS_TOURNEY_MAEVIS_PRIZE",
          function()
            tournamentGiveMeltan(game, done)
          end
        )
        return
      end

      tournamentGiveCash(game, done)
    end

    local function tournamentGiveMasterBall(game, done)
      local flags = game.save.flags or {}

      if not Bag.add(game.save, "MASTER_BALL", 1, game.data) then
        flags.EVENT_MASTER_TOURNEY_MASTER_BALL_PENDING = true
        tournamentSayId(
          game,
          "_MARS_TOURNEY_MASTER_BALL_FULL",
          done
        )
        return
      end

      flags.EVENT_MASTER_TOURNEY_MASTER_BALL_PENDING = nil
      flags.EVENT_MASTER_TOURNEY_MASTER_BALL_WON = true

      local Sound = require("src.core.Sound")
      Sound.play(game.data, "Get_Item1")
      tournamentSayId(game, "_MARS_TOURNEY_MASTER_BALL_RECEIVED", done)
    end

    local function tournamentGiveMasterCash(game, done)
      game.save.money = math.min(
        999999,
        (game.save.money or 0) + 100000
      )
      tournamentSayId(game, "_MARS_TOURNEY_MASTER_CASH_PRIZE", done)
    end

    local function tournamentMasterChampionshipReward(game, done)
      local flags = game.save.flags or {}

      if not flags.EVENT_MASTER_TOURNEY_MASTER_BALL_WON then
        tournamentSayId(
          game,
          "_MARS_TOURNEY_MASTER_MAEVIS_PRIZE",
          function()
            tournamentGiveMasterBall(game, done)
          end
        )
        return
      end

      tournamentGiveMasterCash(game, done)
    end

    -------------------------------------------------------------------------
    -- BATTLE ENGINE
    -------------------------------------------------------------------------

    local function tournamentCreateBattle(game, state, oppClass)
      local tempParty = tournamentBuildTempParty(game, state)
      local realParty = game.save.party

      -- Keep the normalized copies installed as the live party for the entire
      -- tournament battle. The real party is restored immediately after
      -- construction, which only works on engines that honor the newer
      -- playerPartyIndices option. Older builds then fell back to the real
      -- save party and displayed the player's original levels.
      game.save.party = tempParty

      local ok, battleOrErr = pcall(
        BattleState.newTrainer,
        game,
        oppClass,
        1,
        {
          playerPartyIndices = { 1, 2, 3, 4, 5, 6 },
        }
      )

      if not ok then
        game.save.party = realParty
        error(battleOrErr)
      end

      local battle = battleOrErr

      -- Current engines use this scoped view for HUDs, switching, faint
      -- replacement and EXP bookkeeping. Older engines simply keep reading
      -- game.save.party, which is also tempParty until this battle ends.
      battle.playerParty = tempParty
      battle.playerPartyIndices = { 1, 2, 3, 4, 5, 6 }

      battle.marsTournamentRealParty = realParty
      battle.marsTournamentTempParty = tempParty
      battle.marsTournamentBattle = true
      battle.marsTournamentMode = state.mode
      battle.marsTournamentRound = state.round

      -- Tournament trainers pay no ordinary per-battle prize. Replace the
      -- vanilla "got ¥0" line with a neutral tournament result message.
      local baseRomText = battle.romText

      battle.romText = function(self, label, fallback, ...)
        if label == "_MoneyForWinningText" then
          return "Tournament victory!"
        end

        return baseRomText(self, label, fallback, ...)
      end

      if state.mode == "master" then
        local entry = masterById[oppClass]
        if entry and entry.rival and battle.trainer then
          battle.trainer = setmetatable({
            name = (game.save.player and game.save.player.rival) or "BLUE",
          }, { __index = battle.trainer })
        end

        battle.endBattleText =
          (entry and entry.defeat)
          or "You earned that victory."
      elseif oppClass == "OPP_MAEVIS" then
        battle.endBattleText =
          "Congratulations. You've\nwon the tournament!"
      elseif state.round >= 3 then
        battle.endBattleText =
          "You earned that\nvictory."
      else
        battle.endBattleText =
          "Good match!"
      end

      return battle
    end

    local function tournamentRestoreRealParty(game, battle)
      if battle and battle.marsTournamentRealParty then
        game.save.party = battle.marsTournamentRealParty
        battle.marsTournamentRealParty = nil
      end
    end

    local function tournamentResetMaevis(game, ow)
      if not ow then return end

      local Commands = require("src.script.Commands")
      Commands.place_npc(
        {
          game = game,
          save = game.save,
          overworld = ow,
        },
        1,
        tournamentLayout.maevisLobby.x,
        tournamentLayout.maevisLobby.y,
        tournamentLayout.maevisLobby.facing
      )
    end

    local tournamentStartRound
    local tournamentAdvance
    local tournamentEliminate

    local function tournamentLaunchBattle(game, ow)
      local state = game.save.marsKantoTournament

      if not state or not state.active then
        return
      end

      local oppClass = tournamentOpponentForRound(state)
      local battle = tournamentCreateBattle(
        game,
        state,
        oppClass
      )

      battle.onFinish = function(result)
        tournamentRestoreRealParty(game, battle)

        if result == "win" then
          tournamentAdvance(game, ow)
        else
          tournamentEliminate(game, ow)
        end
      end

      ow:pushBattle(battle)
    end

    tournamentEliminate = function(game, ow, done)
      local state = game.save.marsKantoTournament

      if state and state.round >= 6 then
        tournamentResetMaevis(game, ow)
      end

      game.save.marsKantoTournament = nil

      tournamentSayId(
        game,
        "_MARS_TOURNEY_ELIMINATED",
        done
      )
    end

    tournamentAdvance = function(game, ow, done)
      local state = game.save.marsKantoTournament
      if not state then
        if done then done() end
        return
      end

      if state.round >= 6 then
        local mode = state.mode
        tournamentResetMaevis(game, ow)
        game.save.marsKantoTournament = nil

        local flags = game.save.flags or {}
        if mode == "master" then
          flags.EVENT_MASTER_TOURNEY_CHAMPION = true
          tournamentSayId(
            game,
            "_MARS_TOURNEY_MASTER_CHAMPION",
            function()
              tournamentMasterChampionshipReward(game, done)
            end
          )
        else
          flags.EVENT_REGULAR_TOURNEY_CHAMPION = true
          tournamentSayId(
            game,
            "_MARS_TOURNEY_CHAMPION",
            function()
              tournamentChampionshipReward(game, done)
            end
          )
        end
        return
      end

      state.round = state.round + 1

      local advanceText
      if state.mode == "master" then
        if state.round == 3 then
          advanceText =
            "You advanced to the\nMASTER'S QUARTERFINALS!"
        elseif state.round == 4 then
          advanceText =
            "You advanced to the\nMASTER'S SEMIFINALS!"
        elseif state.round == 5 then
          advanceText =
            "You advanced to the\nMASTER'S FINALS!"
        elseif state.round == 6 then
          advanceText =
            "You won the MASTER'S\nFINALS!\f"
              .. "The bracket is\ncomplete.\f"
              .. "TOURNAMENT LEADER\nMAEVIS enters the\narena!"
        else
          advanceText = "You advanced to the\nnext MASTER'S round!"
        end
      elseif state.round == 3 then
        advanceText =
          "You advanced to the\nQUARTERFINALS!\f"
            .. "The remaining field\nis made up of KANTO's\nstrongest contenders."
      elseif state.round == 4 then
        advanceText =
          "You advanced to the\nSEMIFINALS!"
      elseif state.round == 5 then
        advanceText =
          "You advanced to the\nFINALS!"
      elseif state.round == 6 then
        advanceText =
          "You won the FINALS!\f"
            .. "The tournament bracket\nis complete.\f"
            .. "TOURNAMENT LEADER\nMAEVIS enters the\narena!"
      else
        advanceText =
          "You advanced to the\nnext round!"
      end

      tournamentSay(
        game,
        advanceText,
        function()
          tournamentStartRound(game, ow, {
            fromDesk = false,
            done = done,
          })
        end
      )
    end

    tournamentStartRound = function(game, ow, opts)
      local state = game.save.marsKantoTournament

      if not state or not state.active then
        if opts and opts.done then opts.done() end
        return
      end

      local oppClass = tournamentOpponentForRound(state)
      local oppName = tournamentTrainerName(game, oppClass)
      local playerName =
        (game.save.player and game.save.player.name) or "PLAYER"
      local rows = {}

      if opts and opts.fromDesk then
        local introRows = tournamentArenaIntroRows(ow)
        for _, row in ipairs(introRows) do
          rows[#rows + 1] = row
        end
      end

      local isMaevis = oppClass == "OPP_MAEVIS"
        or oppClass == "OPP_MASTER_MAEVIS"

      if isMaevis then
        if state.mode == "master" then
          -- Keep the Master's bracket visible underneath every piece of
          -- pre-battle dialogue, including MAEVIS. Once the text is dismissed,
          -- close the bracket so her physical descent into the arena is visible.
          rows[#rows + 1] = { "mars_tourney_show_bracket" }
          rows[#rows + 1] = {
            "show_text",
            game.data.text._MARS_TOURNEY_MASTER_MAEVIS_DESCENDS
          }
          rows[#rows + 1] = {
            "show_text",
            masterFormatDialogue(
              "MASTER'S CHAMPIONSHIP!\f"
                .. playerName .. " vs. MAEVIS!\f"
                .. masterMaevisEntry.intro
            )
          }
          rows[#rows + 1] = { "mars_tourney_close_bracket" }

          rows[#rows + 1] = {
            "move_npc_to",
            1,
            tournamentLayout.arenaMaevis.x,
            tournamentLayout.arenaMaevis.y,
          }
          rows[#rows + 1] = {
            "face_object",
            1,
            tournamentLayout.arenaMaevis.facing
          }
          rows[#rows + 1] = {
            "face_player_dir",
            tournamentLayout.arenaPlayer.facing
          }
        else
          -- Regular Tournament keeps its existing MAEVIS entrance sequence.
          rows[#rows + 1] = {
            "show_text",
            "_MARS_TOURNEY_MAEVIS_DESCENDS"
          }
          rows[#rows + 1] = {
            "move_npc_to",
            1,
            tournamentLayout.arenaMaevis.x,
            tournamentLayout.arenaMaevis.y,
          }
          rows[#rows + 1] = {
            "face_object",
            1,
            tournamentLayout.arenaMaevis.facing
          }
          rows[#rows + 1] = {
            "face_player_dir",
            tournamentLayout.arenaPlayer.facing
          }
          rows[#rows + 1] = {
            "show_text",
            "CHAMPIONSHIP MATCH!\f"
              .. playerName .. " vs. MAEVIS!\f"
              .. "MAEVIS: You've made\nit through every\nchallenger that stood\nin your way.\f"
              .. "I stand as your\nfinal obstacle. Give me\nyour all!"
          }
        end
      else
        -- Keep the bracket live underneath the matchup announcement. In the
        -- Master's Tournament it now remains there for the opponent's unique
        -- pre-battle dialogue too, and closes only immediately before battle.
        rows[#rows + 1] = { "mars_tourney_show_bracket" }

        local matchupText =
          "NEXT BATTLE:\n"
            .. playerName
            .. " vs. "
            .. oppName
            .. "!"

        if state.mode == "master" then
          matchupText = masterFormatDialogue(matchupText)
        end

        rows[#rows + 1] = { "show_text", matchupText }

        if state.mode == "master" then
          local entry = masterById[oppClass]
          if entry and entry.intro then
            rows[#rows + 1] = { "show_text", entry.intro }
          end
        end

        rows[#rows + 1] = { "mars_tourney_close_bracket" }
      end

      rows[#rows + 1] = { "mars_tourney_begin_battle" }

      ow:queueScript(rows)
    end

    -------------------------------------------------------------------------
    -- NO EXP DURING TOURNAMENT BATTLES
    -------------------------------------------------------------------------

    mod.hooks:wrap("battle.exp_award", function(next, ctx)
      if ctx
         and ctx.battle
         and ctx.battle.marsTournamentBattle
      then
        ctx.battle.participants = {}
        return
      end

      return next(ctx)
    end)

