    -------------------------------------------------------------------------
    -- TOURNAMENT HALL MAP
    --
    -- Reuse the Fighting Dojo's authored interior layout, but replace all
    -- of its NPCs/warps with the tournament hall's own content.
    -------------------------------------------------------------------------

    local baseDojo = mod.content.maps:get("FIGHTING_DOJO")

    if baseDojo then
      local hall = tournamentDeepCopy(baseDojo)

      hall.id = "INDIGO_TOURNAMENT"
      hall.label = "IndigoTournament"
      hall.index = 1022
      hall.connections = {}
      hall.signs = {}

      -----------------------------------------------------------------------
      -- TOURNAMENT ARENA MAT
      --
      -- Clone the Fighting Dojo tileset and append six fully walkable mat
      -- blocks. The center of the room is already a 3x2 rectangle of plain
      -- floor blocks, so replacing only those blocks creates a distinct
      -- fighting arena without disturbing walls, doors, NPC staging, or
      -- collision elsewhere in the building.
      -----------------------------------------------------------------------

      local dojoTilesetId = hall.tileset or baseDojo.tileset or "DOJO"
      local dojoTileset = mod.content.tilesets:get(dojoTilesetId)

      if dojoTileset and dojoTileset.blocks then
        local arenaTileset = tournamentDeepCopy(dojoTileset)
        arenaTileset.id = "INDIGO_TOURNAMENT_ARENA"

        -- Existing neutral Gym/Dojo tiles:
        -- $10 = lighter field
        -- $11 = darker border
        local MAT_FILL = 0x10
        local MAT_BORDER = 0x11

        arenaTileset.walkable = arenaTileset.walkable or {}

        local function arenaEnsureWalkable(tileId)
          for _, existing in ipairs(arenaTileset.walkable) do
            if existing == tileId then return end
          end
          arenaTileset.walkable[#arenaTileset.walkable + 1] = tileId
        end

        arenaEnsureWalkable(MAT_FILL)
        arenaEnsureWalkable(MAT_BORDER)

        local function matBlock(top, bottom, left, right)
          local block = {}

          for ty = 0, 3 do
            for tx = 0, 3 do
              local border =
                (top and ty == 0)
                or (bottom and ty == 3)
                or (left and tx == 0)
                or (right and tx == 3)

              block[#block + 1] =
                border and MAT_BORDER or MAT_FILL
            end
          end

          return block
        end

        -- Block IDs are zero-based; Lua arrays are one-based.
        local firstMatBlockId = #arenaTileset.blocks

        local matIds = {
          topLeft = firstMatBlockId,
          topCenter = firstMatBlockId + 1,
          topRight = firstMatBlockId + 2,
          bottomLeft = firstMatBlockId + 3,
          bottomCenter = firstMatBlockId + 4,
          bottomRight = firstMatBlockId + 5,
        }

        arenaTileset.blocks[#arenaTileset.blocks + 1] =
          matBlock(true, false, true, false)
        arenaTileset.blocks[#arenaTileset.blocks + 1] =
          matBlock(true, false, false, false)
        arenaTileset.blocks[#arenaTileset.blocks + 1] =
          matBlock(true, false, false, true)

        arenaTileset.blocks[#arenaTileset.blocks + 1] =
          matBlock(false, true, true, false)
        arenaTileset.blocks[#arenaTileset.blocks + 1] =
          matBlock(false, true, false, false)
        arenaTileset.blocks[#arenaTileset.blocks + 1] =
          matBlock(false, true, false, true)

        mod.content.tilesets:register(
          "INDIGO_TOURNAMENT_ARENA",
          arenaTileset
        )

        ---------------------------------------------------------------------
        -- ADVANCED COLOR
        --
        -- Advanced Color's world palettes are keyed by tileset ID. Because
        -- this arena tileset is a clone of DOJO using the same raw tile
        -- graphics, inherit DOJO's exact per-tile group map and group colors
        -- under the new tileset ID.
        --
        -- This keeps the authored Dojo coloring everywhere in the room.
        -- The mat's reused raw tiles naturally receive their native groups:
        --   $10 -> DOJO group 6
        --   $11 -> DOJO group 0
        ---------------------------------------------------------------------

        local ArenaPaletteFX = require("src.render.PaletteFX")
        local arenaGbcPack = ArenaPaletteFX.gbcPack()

        if arenaGbcPack and arenaGbcPack.world then
          arenaGbcPack.world.tileGroups =
            arenaGbcPack.world.tileGroups or {}
          arenaGbcPack.world.groupColors =
            arenaGbcPack.world.groupColors or {}

          local sourceTileGroups =
            arenaGbcPack.world.tileGroups.DOJO
          local sourceGroupColors =
            arenaGbcPack.world.groupColors.DOJO

          if sourceTileGroups and sourceGroupColors then
            arenaGbcPack.world.tileGroups.INDIGO_TOURNAMENT_ARENA =
              tournamentDeepCopy(sourceTileGroups)

            arenaGbcPack.world.groupColors.INDIGO_TOURNAMENT_ARENA =
              tournamentDeepCopy(sourceGroupColors)

            mod.log:info(
              "Installed INDIGO_TOURNAMENT_ARENA Advanced Color groups"
            )
          else
            mod.log:warn(
              "DOJO Advanced Color groups unavailable; "
                .. "Tournament arena will use fallback colors"
            )
          end
        else
          mod.log:warn(
            "Advanced Color palette pack unavailable; "
              .. "Tournament arena will use fallback colors"
          )
        end

        hall.tileset = "INDIGO_TOURNAMENT_ARENA"

        local mapWidth = hall.width or baseDojo.width

        local function setArenaBlock(bx, by, blockId)
          local index = by * mapWidth + bx + 1
          hall.blocks[index] = blockId
        end

        -- Fighting Dojo's central plain-floor rectangle:
        -- columns 1-3, rows 2-3 (zero-based block coordinates).
        -- This covers the tournament battle staging area.
        if mapWidth and mapWidth >= 5 and hall.blocks then
          setArenaBlock(1, 2, matIds.topLeft)
          setArenaBlock(2, 2, matIds.topCenter)
          setArenaBlock(3, 2, matIds.topRight)

          setArenaBlock(1, 3, matIds.bottomLeft)
          setArenaBlock(2, 3, matIds.bottomCenter)
          setArenaBlock(3, 3, matIds.bottomRight)
        end
      else
        mod.log:warn(
          "could not clone the Fighting Dojo tileset; "
            .. "Tournament Hall will use its normal floor"
        )
      end

      -- Put MAEVIS where the Karate Master stood.
      local maevisPos = { x = 5, y = 3 }

      if baseDojo.objects and baseDojo.objects[1] then
        maevisPos.x = baseDojo.objects[1].x or maevisPos.x
        maevisPos.y = baseDojo.objects[1].y or maevisPos.y
      end

      -- Reuse the lowest non-item NPC position for the receptionist so the
      -- placement is guaranteed to be a valid walkable NPC cell in the
      -- original Dojo layout.
      local receptionPos = { x = maevisPos.x, y = maevisPos.y + 6 }

      for _, obj in ipairs(baseDojo.objects or {}) do
        if not obj.item
           and not obj.pokemon
           and obj.x
           and obj.y
           and obj.y > receptionPos.y
        then
          receptionPos.x = obj.x
          receptionPos.y = obj.y
        end
      end

      tournamentLayout.maevisLobby = {
        x = maevisPos.x,
        y = maevisPos.y,
        facing = "down",
      }
      tournamentLayout.receptionist = {
        x = receptionPos.x,
        y = receptionPos.y,
      }
      tournamentLayout.arenaPlayer = {
        x = math.max(1, maevisPos.x - 2),
        y = maevisPos.y + 3,
        facing = "right",
      }
      tournamentLayout.arenaMaevis = {
        x = maevisPos.x + 1,
        y = maevisPos.y + 3,
        facing = "left",
      }

      hall.objects = {
        {
          index = 1,
          name = "INDIGO_TOURNAMENT_MAEVIS",
          sprite = "SPRITE_COOLTRAINER_F",
          movement = "STAY",
          range = "DOWN",
          x = maevisPos.x,
          y = maevisPos.y,
          text = "TEXT_INDIGO_TOURNAMENT_MAEVIS",
        },
        {
          index = 2,
          name = "INDIGO_TOURNAMENT_RECEPTIONIST",
          sprite = "SPRITE_GYM_GUIDE",
          movement = "STAY",
          range = "UP",
          x = receptionPos.x,
          y = receptionPos.y,
          text = "TEXT_INDIGO_TOURNAMENT_RECEPTIONIST",
        },
      }

      hall.warps = {}

      for _, warp in ipairs(baseDojo.warps or {}) do
        hall.warps[#hall.warps + 1] = {
          x = warp.x,
          y = warp.y,
          destMap = "INDIGO_CITY",
          destWarp = 7,
        }
      end

      mod.content.maps:register(
        "INDIGO_TOURNAMENT",
        hall
      )

      -- The tournament facade uses OVERWORLD building block 125 at block
      -- position (9,6). As with the Pokecenter, Mart, and apartments, the
      -- actual doorway is the block's bottom-right 16x16 cell: (19,13).
      mod.content.maps:patch("INDIGO_CITY", {
        warps = {
          __append = {
            {
              x = 19,
              y = 13,
              destMap = "INDIGO_TOURNAMENT",
              destWarp = 1,
            },
          },
        },
      })
    else
      mod.log:error(
        "tournament could not find FIGHTING_DOJO base map"
      )
    end

    -------------------------------------------------------------------------
    -- NPC TALK / REGISTRATION
    -------------------------------------------------------------------------

    local function tournamentMasterUnlocked(game)
      local flags = game.save.flags or {}
      return flags.EVENT_BEAT_CHAMPION_RIVAL
        and (
          flags.EVENT_REGULAR_TOURNEY_CHAMPION
          or flags.EVENT_REGULAR_TOURNEY_MELTAN_WON
        )
    end

    local function tournamentRegisterMode(game, ow, done, mode)
      local promptId = mode == "master"
        and "_MARS_TOURNEY_MASTER_RECEPTION"
        or "_MARS_TOURNEY_RECEPTION"

      game.stack:push(TextBox.new(
        game,
        game.data.text[promptId],
        nil,
        {
          choice = function(yes)
            if not yes then
              tournamentSayId(game, "_MARS_TOURNEY_DECLINE", done)
              return
            end

            local valid, textId, bannedName =
              tournamentValidateParty(game, mode)

            if not valid then
              if bannedName then
                tournamentSay(
                  game,
                  string.format(game.data.text._MARS_TOURNEY_BANNED, bannedName),
                  done
                )
              else
                tournamentSayId(game, textId, done)
              end
              return
            end

            if mode == "master" then
              game.save.marsKantoTournament = tournamentNewMasterState(game)
              tournamentSayId(
                game,
                "_MARS_TOURNEY_MASTER_REGISTERED",
                function()
                  tournamentStartRound(game, ow, { fromDesk = true, done = done })
                end
              )
            else
              game.save.marsKantoTournament = tournamentNewRegularState(game)
              tournamentSayId(
                game,
                "_MARS_TOURNEY_REGISTERED",
                function()
                  tournamentStartRound(game, ow, { fromDesk = true, done = done })
                end
              )
            end
          end,
        }
      ))
    end

    local function tournamentReceptionTalk(game, ow, npc, done)
      tournamentFacePlayer(ow, npc)

      local flags = game.save.flags or {}

      if flags.EVENT_MASTER_TOURNEY_MASTER_BALL_PENDING
         and not flags.EVENT_MASTER_TOURNEY_MASTER_BALL_WON
      then
        tournamentSayId(
          game,
          "_MARS_TOURNEY_MASTER_BALL_PENDING",
          function()
            tournamentGiveMasterBall(game, done)
          end
        )
        return
      end

      if flags.EVENT_REGULAR_TOURNEY_MELTAN_PENDING
         and not flags.EVENT_REGULAR_TOURNEY_MELTAN_WON
      then
        tournamentSayId(
          game,
          "_MARS_TOURNEY_MELTAN_PENDING",
          function()
            tournamentGiveMeltan(game, done)
          end
        )
        return
      end

      local state = game.save.marsKantoTournament

      if state and state.active then
        local activeId = state.mode == "master"
          and "_MARS_TOURNEY_MASTER_ACTIVE"
          or "_MARS_TOURNEY_ACTIVE"

        game.stack:push(TextBox.new(
          game,
          game.data.text[activeId],
          nil,
          {
            choice = function(yes)
              if not yes then
                tournamentSayId(game, "_MARS_TOURNEY_DECLINE", done)
                return
              end

              tournamentStartRound(game, ow, { fromDesk = true, done = done })
            end,
          }
        ))
        return
      end

      if not tournamentMasterUnlocked(game) then
        tournamentRegisterMode(game, ow, done, "regular")
        return
      end

      tournamentSayId(game, "_MARS_TOURNEY_MODE_SELECT", function()
        local menu
        menu = ListMenu.new(
          game,
          "TOURNAMENT",
          {
            { label = "REGULAR", value = "regular" },
            { label = "MASTER'S", value = "master" },
            { label = "CANCEL", value = "cancel" },
          },
          {
            onChoose = function(item)
              if not item or not item.value then return end
              local value = item.value
              menu:close()

              if value == "cancel" then
                tournamentSayId(game, "_MARS_TOURNEY_DECLINE", done)
                return
              end

              tournamentRegisterMode(game, ow, done, value)
            end,
            onCancel = function()
              menu:close()
              tournamentSayId(game, "_MARS_TOURNEY_DECLINE", done)
            end,
          }
        )
        game.stack:push(menu)
      end)
    end

    local function tournamentMaevisTalk(game, ow, npc, done)
      tournamentFacePlayer(ow, npc)

      tournamentSayId(
        game,
        tournamentMasterUnlocked(game)
          and "_MARS_TOURNEY_MAEVIS_IDLE_MASTER"
          or "_MARS_TOURNEY_MAEVIS_IDLE",
        done
      )
    end

    mod.commands:register("mars_tourney_begin_battle", function(ctx)
      tournamentLaunchBattle(ctx.game, ctx.overworld)
    end)

    -- Unlike the engine's push_screen script command, this intentionally does
    -- NOT yield the runner. The bracket remains live underneath the following
    -- TextBox, which is exactly the presentation we want.
    mod.commands:register("mars_tourney_show_bracket", function(ctx)
      local Screens = require("src.ui.Screens")
      ctx.game.marsTournamentBracketState =
        Screens.push(ctx.game, "MarsTournamentBracket")
    end)

    mod.commands:register("mars_tourney_close_bracket", function(ctx)
      local stack = ctx.game.stack
      local bracket = ctx.game.marsTournamentBracketState

      -- After the NEXT BATTLE TextBox closes, the bracket should once again
      -- be the top state. Pop only when that exact state is on top.
      if bracket
         and stack.states
         and stack.states[#stack.states] == bracket
      then
        stack:pop()
      end

      ctx.game.marsTournamentBracketState = nil
    end)

    if mod.content.map_scripts then
      mod.content.map_scripts:register("INDIGO_TOURNAMENT", {
        priority = 140,

        onEnter = function(game, ow)
          ow:queueScript({
            {
              "place_npc",
              1,
              tournamentLayout.maevisLobby.x,
              tournamentLayout.maevisLobby.y,
              tournamentLayout.maevisLobby.facing,
            },
          })
        end,

        talk = {
          TEXT_INDIGO_TOURNAMENT_RECEPTIONIST =
            tournamentReceptionTalk,

          TEXT_INDIGO_TOURNAMENT_MAEVIS =
            tournamentMaevisTalk,
        },
      })

      -- Scripted fallback for the tournament facade. The authored doorway is
      -- the single cell (19,13).
      mod.content.map_scripts:register("INDIGO_CITY", {
        priority = 140,

        onStep = function(game, ow, x, y)
          if x == 19 and y == 13 then
            ow:takeWarp({
              destMap = "INDIGO_TOURNAMENT",
              destWarp = 1,
            })
            return true
          end

          return false
        end,
      })
    end

    mod.log:info(
      "installed Regular Kanto Fighting Tournament + arena Advanced Color: "
        .. "20 generic trainers, 8 named contenders, MAEVIS, "
        .. "Lv50 temporary party, non-blocking box-only bracket UI, MELTAN first prize, ¥50000 repeats"
    )
  end)()

