  ;(function()
    -------------------------------------------------------------------------
    -- INDIGO CITY GYM / BENJI — INTENDED SPINNERS RESTORED
    --
    -- BENJI runs an unofficial mixed-type Gym. His first battle is available
    -- only after all eight Kanto Gym Leaders have been defeated. After the
    -- Champion is beaten, he switches to his full postgame team and becomes
    -- repeatably rematchable like the official Gym Leaders.
    -------------------------------------------------------------------------

    local function appendIndigoGymParty(trainerClass, party)
      local trainer = mod.content.trainers:get(trainerClass)
      local partyIndex = #(trainer and trainer.parties or {}) + 1

      mod.content.trainers:patch(trainerClass, {
        parties = {
          __append = {
            copyTrainerParty(party),
          },
        },
      })

      return partyIndex
    end

    -------------------------------------------------------------------------
    -- GYM TRAINERS
    -------------------------------------------------------------------------

    local indigoBlackbeltParty = appendIndigoGymParty("OPP_BLACKBELT", {
      { level = 49, species = "PRIMEAPE" },
