    )

    -------------------------------------------------------------------------
    -- GYM MAP
    -------------------------------------------------------------------------

    mod.content.maps:register("INDIGO_GYM", {
      id = "INDIGO_GYM",
      label = "IndigoGym",
      index = 1021,
      tileset = "GYM",
      palette = "VIRIDIAN",
      environment = "inside",
      width = 10,
      height = 9,
      borderBlock = 3,
      blocks = {
          1,   1,   1,  33,  33,  33,  33,  95,  68,   1,
         14,   8,  13,  68,   2,   2,  68,  98,  69,  11,
         12,  11,   5,  69, 114, 115,  69,   5,  68,   5,
          8,  10,   5,  75,   5,   5,  79,   5,  69,  15,
          5,  15,  10,  82,  27,  27, 111,  67,  10,   5,
         96,   5,  11,  81,   2,   2,  76,  13,  68,   5,
         76,  70,  70,  70,  70,  70, 111,  70,  69,  14,
         85, 104,   5,  50,   5,  49,   5,   5, 104,   5,
         97,   5,   5,   5,   4,   5,   5,   5,   5,  13,
      },
      connections = {},
      warps = {
        -- Both bottom doorway tiles are active exits, just like the two-tile
        -- doorway in the Indigo Pokemon Center.
        { x = 8, y = 17, destMap = "INDIGO_CITY", destWarp = 6 },
        { x = 9, y = 17, destMap = "INDIGO_CITY", destWarp = 6 },
      },
      signs = {},
      objects = {
        {
          index = 1, name = "INDIGO_GYM_TRAINER1",
          sprite = "SPRITE_HIKER", movement = "STAY", range = "RIGHT",
          x = 18, y = 11,
          trainerClass = "OPP_BLACKBELT",
          trainerParty = indigoBlackbeltParty,
        },
        {
          index = 2, name = "INDIGO_GYM_TRAINER2",
          sprite = "SPRITE_SUPER_NERD", movement = "STAY", range = "UP",
          x = 4, y = 2,
          trainerClass = "OPP_POKEMANIAC",
          trainerParty = indigoPokemaniacParty,
        },
        {
          index = 3, name = "INDIGO_GYM_TRAINER3",
          sprite = "SPRITE_GAMBLER", movement = "STAY", range = "DOWN",
          x = 6, y = 11,
          trainerClass = "OPP_COOLTRAINER_M",
          trainerParty = indigoCooltrainerParty,
        },
        {
          index = 4, name = "INDIGO_GYM_BENJI",
          sprite = "SPRITE_COOLTRAINER_M", movement = "STAY", range = "DOWN",
          x = 10, y = 6, text = "TEXT_INDIGO_GYM_BENJI",
        },
        {
          index = 5, name = "INDIGO_GYM_GUIDE",
          sprite = "SPRITE_GYM_GUIDE", movement = "STAY", range = "UP",
          x = 11, y = 15, text = "TEXT_INDIGO_GYM_GUIDE",
        },
      },
    })

    local indigoGymSong = mod.content.map_songs:get("VIRIDIAN_GYM")
    if indigoGymSong then
      mod.content.map_songs:register("INDIGO_GYM", indigoGymSong)
    end

    -- Make Benji use the Gym Leader battle/victory presentation without
    -- awarding any badge/TM; the custom onFinish below never calls the
    -- normal victory-reward handler.
    local indigoGymVictories = require("data.scripts.victories")
    indigoGymVictories["OPP_BENJI#1"] = { badge = "EARTHBADGE" }
    indigoGymVictories["OPP_BENJI#2"] = { badge = "EARTHBADGE" }

    -------------------------------------------------------------------------
    -- SCRIPTS
    -------------------------------------------------------------------------

    if mod.content.map_scripts then
      local BattleState = require("src.battle.BattleState")
      local TextBox = require("src.render.TextBox")

      local Badges = require("src.inventory.Badges")

      -- Check the actual badge inventory, not Gym-defeat event flags.
      -- This matches Gen1Recomp's own badge-count logic and also works
      -- correctly with imported/edited saves that genuinely contain all
      -- eight badges without every historical EVENT_BEAT_* flag.
      local function hasAllEightBadges(game)
        return Badges.count(game.data, game.save) >= 8
      end

      local function showIndigoGymText(game, textId, done)
        game.stack:push(TextBox.new(
          game,
          game.data.text[textId],
          done
        ))
      end

      local function startBenjiBattle(
        game, ow, npc, done, partyIndex, wonTextId, setInitialWin
      )
        -- Match the proven BURIEDALIVE custom-trainer launch path already
        -- used by Expanded Kanto: construct the trainer battle directly and
        -- push it. Benji does not need the sight-trainer preparation wrapper.
        local battle = BattleState.newTrainer(
          game,
          "OPP_BENJI",
          partyIndex
        )

        battle.endBattleText = TextBox.substitute(
          game,
          game.data.text[wonTextId]
        )

        battle.onFinish = function(result)
          if result == "win" and setInitialWin then
            game.save.flags.EVENT_BEAT_BENJI = true
          end

          ow:afterBattle(result, battle)
          if done then done() end
        end

        ow:pushBattle(battle)
      end

      local function askBenjiBattle(
        game, ow, npc, done,
        askTextId, declineTextId, partyIndex, wonTextId, setInitialWin
      )
        game.stack:push(TextBox.new(
          game,
          game.data.text[askTextId],
          nil,
          {
            choice = function(yes)
              if not yes then
                showIndigoGymText(game, declineTextId, done)
                return
              end

              startBenjiBattle(
                game,
                ow,
                npc,
                done,
                partyIndex,
                wonTextId,
                setInitialWin
              )
            end,
          }
        ))
      end

      mod.content.map_scripts:register("INDIGO_GYM", {
        priority = 200,

        -- Explicitly honor both authored exit tiles. Normally the GYM
        -- tileset's warp metadata handles these, but this keeps the exits
        -- functional even when an exported/stale tileset cache does not.
        onStep = function(game, ow, x, y)
          -- The Gym's real exit is the center aisle marked by the blue rug
          -- and the two statues, not the far-right edge of the room.
          if y == 17 and (x == 8 or x == 9) then
            ow:takeWarp({
              destMap = "INDIGO_CITY",
              destWarp = 6,
            })
            return true
          end

          -- Returning false is important: OverworldController runs its
          -- normal spinner-arrow check immediately after map onStep.
          return false
        end,

        onEnter = function(game, ow)
          -------------------------------------------------------------------
          -- INDIGO GYM SPINNER ARROWS
          --
          -- These are the five actual arrow cells visible in the authored
          -- map. Their movement ends on the checker/stop tiles already drawn
          -- into the room.
          -------------------------------------------------------------------
          game.data.field = game.data.field or {}
          game.data.field.spinners = game.data.field.spinners or {}
          game.data.field.spinners.INDIGO_GYM = {
            -- Intended left-side DOWN spinner shown in the circled screenshot.
            { x = 0,  y = 10, moves = { { dir = "down", count = 7 } } },

            -- Intended paired UP spinner shown in the other circled screenshot.
            { x = 14, y = 9, moves = { { dir = "up", count = 7 } } },
            { x = 15, y = 9, moves = { { dir = "up", count = 7 } } },

            -- IMPORTANT: the stale invisible triggers at (2,12) and (3,12)
            -- remain deleted. The removed spinner before Benji also remains
            -- deleted and has no trigger.
          }

          local headers = game.data.trainer_headers
          headers.IndigoGym = headers.IndigoGym or {}

          headers.IndigoGym[1] = {
            range = 4,
            battle = "_MARS_INDIGO_GYM_TRAINER1_BATTLE",
            won = "_MARS_INDIGO_GYM_TRAINER1_WON",
            after = "_MARS_INDIGO_GYM_TRAINER1_AFTER",
          }
          headers.IndigoGym[2] = {
            range = 4,
            battle = "_MARS_INDIGO_GYM_TRAINER2_BATTLE",
            won = "_MARS_INDIGO_GYM_TRAINER2_WON",
            after = "_MARS_INDIGO_GYM_TRAINER2_AFTER",
          }
          headers.IndigoGym[3] = {
            range = 4,
            battle = "_MARS_INDIGO_GYM_TRAINER3_BATTLE",
            won = "_MARS_INDIGO_GYM_TRAINER3_WON",
            after = "_MARS_INDIGO_GYM_TRAINER3_AFTER",
          }
        end,

        talk = {
          TEXT_INDIGO_GYM_GUIDE = function(game, ow, npc, done)
            local flags = game.save.flags or {}

            if flags.EVENT_BEAT_CHAMPION_RIVAL then
              showIndigoGymText(game, "_MARS_INDIGO_GYM_GUIDE_CHAMPION", done)
            elseif hasAllEightBadges(game) then
              showIndigoGymText(game, "_MARS_INDIGO_GYM_GUIDE_READY", done)
            else
              showIndigoGymText(game, "_MARS_INDIGO_GYM_GUIDE_LOCKED", done)
            end
          end,

          TEXT_INDIGO_GYM_BENJI = function(game, ow, npc, done)
            local flags = game.save.flags or {}

            if flags.EVENT_BEAT_CHAMPION_RIVAL then
              askBenjiBattle(
                game, ow, npc, done,
                "_MARS_INDIGO_GYM_BENJI_REMATCH_ASK",
                "_MARS_INDIGO_GYM_BENJI_REMATCH_DECLINE",
                2,
                "_MARS_INDIGO_GYM_BENJI_REMATCH_WON",
                false
              )
              return
            end

            if not hasAllEightBadges(game) then
              showIndigoGymText(game, "_MARS_INDIGO_GYM_BENJI_LOCKED", done)
              return
            end

            if flags.EVENT_BEAT_BENJI then
              showIndigoGymText(game, "_MARS_INDIGO_GYM_BENJI_AFTER", done)
              return
            end

            askBenjiBattle(
              game, ow, npc, done,
              "_MARS_INDIGO_GYM_BENJI_INITIAL_ASK",
              "_MARS_INDIGO_GYM_BENJI_DECLINE",
              1,
              "_MARS_INDIGO_GYM_BENJI_INITIAL_WON",
              true
            )
          end,
        },
      })
    end

    mod.log:info(
      "Indigo Gym installed: corrected single exterior door at (21,7), scripted Gym exits, real inventory badge check, corrected trainer facings, custom Benji portrait, "
        .. "8-badge first battle, and repeatable Champion rematch"
    )
  end)()

  ;(function()
  end)()

  ---------------------------------------------------------------------------
  -- ROUTE 5 DAY CARE HAPPINY SIDE QUEST
  ---------------------------------------------------------------------------
  ;(function()
  ---------------------------------------------------------------------------
  -- STORY
  --
  -- The Day-Care Man waits outside his Route 5 house because two trainers
  -- inside are fighting over an Egg their Pokemon apparently produced.
  --
  -- The player:
  --   1. hears NORA's side
  --   2. hears LIAM's side
  --   3. returns outside and chooses who has the stronger claim
  --   4. follows the Day-Care Man inside
  --   5. battles the angry trainer who lost the ruling
  --   6. watches the Egg hatch into Happiny
  --   7. discovers neither trainer could have been its parent
  --   8. may adopt the Lv.1 Happiny
  ---------------------------------------------------------------------------

  local FLAGS = {
    started = "EVENT_ROUTE5_HAPPINY_STARTED",
    heardNora = "EVENT_ROUTE5_HAPPINY_HEARD_NORA",
    heardLiam = "EVENT_ROUTE5_HAPPINY_HEARD_LIAM",
    choseNora = "EVENT_ROUTE5_HAPPINY_CHOSE_NORA",
    choseLiam = "EVENT_ROUTE5_HAPPINY_CHOSE_LIAM",
    choiceMade = "EVENT_ROUTE5_HAPPINY_CHOICE_MADE",
    battleWon = "EVENT_ROUTE5_HAPPINY_BATTLE_WON",
    hatched = "EVENT_ROUTE5_HAPPINY_HATCHED",
    received = "EVENT_ROUTE5_HAPPINY_RECEIVED",
  }

  local TEXT_OUTSIDE_MAN = "TEXT_ROUTE5_HAPPINY_DAYCARE_MAN"
  local TEXT_NORA = "TEXT_DAYCARE_HAPPINY_NORA"
  local TEXT_LIAM = "TEXT_DAYCARE_HAPPINY_LIAM"
  local TEXT_INSIDE_MAN = "TEXT_DAYCARE_HAPPINY_MAN"
  local TEXT_HAPPINY_MON = "TEXT_DAYCARE_HAPPINY_MON"
  local TEXT_NORA_EPILOGUE = "TEXT_VERMILION_HAPPINY_NORA"
  local TEXT_LIAM_EPILOGUE = "TEXT_CERULEAN_HAPPINY_LIAM"

  local route5Def = mod.content.maps:get("ROUTE_5")
  local daycareDef = mod.content.maps:get("DAYCARE")
  local vermilionDef = mod.content.maps:get("VERMILION_CITY")
  local ceruleanDef = mod.content.maps:get("CERULEAN_CITY")

  if not route5Def or not daycareDef
     or not vermilionDef or not ceruleanDef
  then
    mod.log:error(
      "Happiny quest requires ROUTE_5, DAYCARE, VERMILION_CITY, and CERULEAN_CITY maps"
    )
    return
  end

  local nativeMan = nil
  for _, obj in ipairs(daycareDef.objects or {}) do
    if obj.name == "DAYCARE_GENTLEMAN"
       or obj.text == "TEXT_DAYCARE_GENTLEMAN"
    then
      nativeMan = obj
      break
    end
  end

  if not nativeMan then
    mod.log:error(
      "Happiny quest could not locate the native Day-Care Man"
    )
    return
  end

  ---------------------------------------------------------------------------
  -- AUTHORED POSITIONS DERIVED FROM THE VANILLA MAPS
  ---------------------------------------------------------------------------

  local routeDoorX, routeDoorY = 10, 21
  for _, warp in ipairs(route5Def.warps or {}) do
    if warp.destMap == "DAYCARE" then
      routeDoorX, routeDoorY = warp.x, warp.y
      break
    end
  end

  -- This matches the familiar Gen 2-style "Day-Care Man waiting beside the
  -- door" staging while deriving the actual door coordinate from the map.
  local outsideManX = routeDoorX + 2
  local outsideManY = routeDoorY + 1

  local insideExitX, insideExitY = 3, 7
  for _, warp in ipairs(daycareDef.warps or {}) do
    if warp.destMap == "ROUTE_5" then
      insideExitX, insideExitY = warp.x, warp.y
      break
    end
  end

  local trainerY = math.max(2, insideExitY - 3)
  local noraX = math.max(1, insideExitX - 1)
  local liamX = math.min(daycareDef.width * 2 - 2, insideExitX + 2)

  -- the player should take the upper-right stool at the table, matching
  -- the user's marked seat in the Day Care screenshot. This is one tile above
  -- LIAM's seat position on the vanilla Day Care map.
  local playerSeatX = liamX
  local playerSeatY = trainerY - 1

  -- after the Egg hatches, Happiny stands on the north side of the
  -- table until the player actually adopts it.
  local happinyX = insideExitX + 1
  local happinyY = trainerY - 2

  local outsideIndex = #(route5Def.objects or {}) + 1
  local insideBaseIndex = #(daycareDef.objects or {}) + 1
  local noraIndex = insideBaseIndex
  local liamIndex = insideBaseIndex + 1
  local questManIndex = insideBaseIndex + 2
  local happinyIndex = insideBaseIndex + 3

  local MapDef = require("src.world.Map")

  local function happinyCitySpot(def, preferredX, preferredY)
    local tileset =
      def and mod.content.tilesets:get(def.tileset)
      or nil

    local occupied = {}
    for _, obj in ipairs((def and def.objects) or {}) do
      occupied[tostring(obj.x) .. ":" .. tostring(obj.y)] = true
    end

    for radius = 0, 12 do
      for dy = -radius, radius do
        for dx = -radius, radius do
          if radius == 0
             or math.max(math.abs(dx), math.abs(dy)) == radius
          then
            local x = preferredX + dx
            local y = preferredY + dy
            local key = tostring(x) .. ":" .. tostring(y)

            if not occupied[key]
               and def
               and tileset
               and x >= 0
               and y >= 0
               and x < def.width * 2
               and y < def.height * 2
               and MapDef.defIsWalkableCell(def, tileset, x, y)
               and not MapDef.defIsWaterCell(def, tileset, x, y)
            then
              return x, y
            end
          end
        end
      end
    end

    return preferredX, preferredY
  end

  local noraCityX, noraCityY = happinyCitySpot(
    vermilionDef,
    math.floor(vermilionDef.width),
