  ---------------------------------------------------------------------------
  -- HELPERS
  ---------------------------------------------------------------------------

  local function happinySay(game, textIdOrLiteral, done, opts)
    local TextBox = require("src.render.TextBox")
    local value =
      game.data.text[textIdOrLiteral]
      or textIdOrLiteral

    game.stack:push(TextBox.new(
      game,
      value,
      done,
      opts
    ))
  end

  local happinyCutsceneCallbacks =
    setmetatable({}, { __mode = "k" })

  mod.commands:register("mars_happiny_cutscene_done", function(ctx)
    local callback = happinyCutsceneCallbacks[ctx.game]
    happinyCutsceneCallbacks[ctx.game] = nil

    if callback then callback() end
  end)

  local function queueHappinyCutscene(game, ow, rows, callback)
    happinyCutsceneCallbacks[game] = callback
    rows[#rows + 1] = { "mars_happiny_cutscene_done" }
    ow:queueScript(rows)
  end

  local function faceHappinyNpc(ow, npc)
    if npc and npc.facePlayer and ow and ow.player then
      npc:facePlayer(ow.player)
    end
  end

  local function appendPlayerWalkToHappinySeat(rows, ow)
    local player = ow and ow.player
    if not player then return end

    local targetX = playerSeatX
    local targetY = playerSeatY

    -- Route the player around the table and into the upper-right stool.
    -- Going straight toward the seat can snag on the table/chairs, so walk
    -- into the right-side aisle first, then up, then step left onto the seat.
    local aisleX = targetX + 1

    local dx1 = aisleX - player.cellX
    if dx1 < 0 then
      rows[#rows + 1] = { "move_player", "left", math.abs(dx1) }
    elseif dx1 > 0 then
      rows[#rows + 1] = { "move_player", "right", dx1 }
    end

    local dy = targetY - player.cellY
    if dy < 0 then
      rows[#rows + 1] = { "move_player", "up", math.abs(dy) }
    elseif dy > 0 then
      rows[#rows + 1] = { "move_player", "down", dy }
    end

    rows[#rows + 1] = { "move_player", "left", 1 }
    rows[#rows + 1] = { "face_player_dir", "left" }
  end

  local function buildGiftHappiny(game)
    local Pokemon = require("src.pokemon.Pokemon")
    local Party = require("src.pokemon.Party")
    local Boxes = require("src.pokemon.Boxes")
    local BattleState = require("src.battle.BattleState")

    local mon = Pokemon.new(game.data, "HAPPINY", 1)
    BattleState.stampOT(game.save, mon)

    local addedToParty = Party.add(game.save.party, mon)
    local boxNum = nil

    if not addedToParty then
      boxNum = Boxes.deposit(game.save, mon)
      if not boxNum then
        return false
      end
    end

    local dex = game.save.pokedex
    if dex then
      dex.seen = dex.seen or {}
      dex.owned = dex.owned or {}
      dex.seen.HAPPINY = true
      dex.owned.HAPPINY = true
    end

    return true, boxNum
  end

  local function swapToNativeDaycareMan(ow)
    if not ow then return end

    ow:queueScript({
      {
        "hide_object",
        "DAYCARE",
        "DAYCARE_HAPPINY_MAN",
      },
      {
        "show_object",
        "DAYCARE",
        "DAYCARE_GENTLEMAN",
      },
    })
  end

  local function offerHappiny(game, ow, done)
    local flags = game.save.flags or {}

    if flags[FLAGS.received] then
      swapToNativeDaycareMan(ow)
      if done then done() end
      return
    end

    happinySay(
      game,
      "_MARS_HAPPINY_OFFER",
      nil,
      {
        choice = function(yes)
          if not yes then
            happinySay(
              game,
              "_MARS_HAPPINY_DECLINE",
              done
            )
            return
          end

          local ok, boxNum = buildGiftHappiny(game)
          if not ok then
            happinySay(
              game,
              "_MARS_HAPPINY_FULL",
              done
            )
            return
          end

          flags[FLAGS.received] = true

          local receivedText =
            game.data.text._MARS_HAPPINY_RECEIVED

          if boxNum then
            receivedText =
              "You received a\nLv.1 HAPPINY!\f"
              .. "HAPPINY was sent to\nPOKEMON BOX "
              .. tostring(boxNum)
              .. ".\f"
              .. "DAY-CARE MAN: Take\ngood care of her!"
          end

          queueHappinyCutscene(
            game,
            ow,
            {
              {
                "hide_object",
                "DAYCARE",
                "DAYCARE_HAPPINY_MON",
              },
            },
            function()
              local Sound = require("src.core.Sound")
              Sound.play(game.data, "Get_Item1")

              happinySay(
                game,
                receivedText,
                function()
                  swapToNativeDaycareMan(ow)
                  if done then done() end
                end
              )
            end
          )
        end,
      }
    )
  end

  ---------------------------------------------------------------------------
  -- OUTSIDE DAY-CARE MAN
  ---------------------------------------------------------------------------

  local function outsideManTalk(game, ow, npc, done)
    local flags = game.save.flags or {}
    faceHappinyNpc(ow, npc)

    if flags[FLAGS.received] then
      happinySay(
        game,
        "_MARS_HAPPINY_COMPLETE",
        done
      )
      return
    end

    if not flags[FLAGS.started] then
      flags[FLAGS.started] = true

      happinySay(
        game,
        "_MARS_HAPPINY_OUTSIDE_INTRO",
        done
      )
      return
    end

    if not (
      flags[FLAGS.heardNora]
      and flags[FLAGS.heardLiam]
    ) then
      happinySay(
        game,
        "_MARS_HAPPINY_OUTSIDE_REMINDER",
        done
      )
      return
    end

    if flags[FLAGS.choiceMade] then
      happinySay(
        game,
        "DAY-CARE MAN: I've made\nmy decision.\f"
          .. "Come inside with me.",
        done
      )
      return
    end

    happinySay(
      game,
      "_MARS_HAPPINY_READY_TO_JUDGE",
      function()
        local ListMenu = require("src.ui.ListMenu")
        local entries = {
          {
            label = "NORA",
            value = "NORA",
          },
          {
            label = "LIAM",
            value = "LIAM",
          },
        }

        local list
        list = ListMenu.new(
          game,
          "WHO IS RIGHT?",
          entries,
          {
            onChoose = function(item)
              if not item or not item.value then
                return
              end

              flags[FLAGS.choiceMade] = true
              flags[FLAGS.choseNora] =
                item.value == "NORA"
              flags[FLAGS.choseLiam] =
                item.value == "LIAM"

              list:close()

              local textId =
                flags[FLAGS.choseNora]
                and "_MARS_HAPPINY_CHOSE_NORA"
                or "_MARS_HAPPINY_CHOSE_LIAM"

              happinySay(
                game,
                textId,
                function()
                  queueHappinyCutscene(
                    game,
                    ow,
                    {
                      {
                        "move_npc_to",
                        outsideIndex,
                        routeDoorX,
                        routeDoorY,
                      },
                      {
                        "hide_object",
                        "ROUTE_5",
                        "ROUTE5_HAPPINY_DAYCARE_MAN",
                      },
                    },
                    done
                  )
                end
              )
            end,

            onCancel = function()
              list:close()
              if done then done() end
            end,
          }
        )

        game.stack:push(list)
      end
    )
  end

  ---------------------------------------------------------------------------
  -- THE TWO CLAIMANTS
  ---------------------------------------------------------------------------

  local function noraTalk(game, ow, npc, done)
    local flags = game.save.flags or {}
    faceHappinyNpc(ow, npc)

    if not flags[FLAGS.started] then
      happinySay(
        game,
        "_MARS_HAPPINY_TRAINERS_BUSY",
        done
      )
      return
    end

    if flags[FLAGS.heardNora] then
      happinySay(
        game,
        "_MARS_HAPPINY_NORA_REPEAT",
        done
      )
      return
    end

    flags[FLAGS.heardNora] = true

    happinySay(
      game,
      "_MARS_HAPPINY_NORA_SIDE",
      done
    )
  end

  local function liamTalk(game, ow, npc, done)
    local flags = game.save.flags or {}
    faceHappinyNpc(ow, npc)

    if not flags[FLAGS.started] then
      happinySay(
        game,
        "_MARS_HAPPINY_TRAINERS_BUSY",
        done
      )
      return
    end

    if flags[FLAGS.heardLiam] then
      happinySay(
        game,
        "_MARS_HAPPINY_LIAM_REPEAT",
        done
      )
      return
