  ---------------------------------------------------------------------------
  -- INSIDE DAY-CARE MAN AFTER THE HATCH
  ---------------------------------------------------------------------------

  local function insideManTalk(game, ow, npc, done)
    local flags = game.save.flags or {}
    faceHappinyNpc(ow, npc)

    if flags[FLAGS.received] then
      swapToNativeDaycareMan(ow)
      if done then done() end
      return
    end

    if flags[FLAGS.hatched] then
      offerHappiny(game, ow, done)
      return
    end

    happinySay(
      game,
      "DAY-CARE MAN: Let's get\nthis argument settled\nfirst.",
      done
    )
  end

  ---------------------------------------------------------------------------
  -- VERDICT / BATTLE / HATCH CUTSCENE
  ---------------------------------------------------------------------------

  local function startDisputeBattle(game, ow)
    local flags = game.save.flags or {}
    local BattleState = require("src.battle.BattleState")

    local choseNora = flags[FLAGS.choseNora]
    local verdictText =
      choseNora
      and "_MARS_HAPPINY_VERDICT_NORA"
      or "_MARS_HAPPINY_VERDICT_LIAM"

    local rageText =
      choseNora
      and "_MARS_HAPPINY_LIAM_RAGE"
      or "_MARS_HAPPINY_NORA_RAGE"

    local opponent =
      choseNora
      and "OPP_DAYCARE_LIAM"
      or "OPP_DAYCARE_NORA"

    local loserIndex =
      choseNora
      and liamIndex
      or noraIndex

    local loserName =
      choseNora
      and "DAYCARE_HAPPINY_LIAM"
      or "DAYCARE_HAPPINY_NORA"

    local loserStormText =
      choseNora
      and "_MARS_HAPPINY_LIAM_STORMS_OUT"
      or "_MARS_HAPPINY_NORA_STORMS_OUT"

    local remainingIndex =
      choseNora
      and noraIndex
      or liamIndex

    local remainingName =
      choseNora
      and "DAYCARE_HAPPINY_NORA"
      or "DAYCARE_HAPPINY_LIAM"

    local remainingShock =
      choseNora
      and "_MARS_HAPPINY_NORA_SHOCK"
      or "_MARS_HAPPINY_LIAM_SHOCK"

    happinySay(
      game,
      verdictText,
      function()
        happinySay(
          game,
          rageText,
          function()
            local battle = BattleState.newTrainer(
              game,
              opponent,
              1
            )

            -- Trainer battles already prefix the opponent's name in the
            -- battle text box. Do not include LIAM:/NORA: here or it prints
            -- twice (e.g. "NORA: NORA: This isn't fair!").
            battle.endBattleText =
              choseNora
              and "This isn't over!"
              or "This isn't fair!"

            battle.onFinish = function(result)
              if result ~= "win" then
                ow:afterBattle(result, battle)
                return
              end

              flags[FLAGS.battleWon] = true
              flags[FLAGS.hatched] = true

              queueHappinyCutscene(
                game,
                ow,
                {
                  {
                    "show_text",
                    loserStormText,
                  },
                  {
                    "move_npc_to",
                    loserIndex,
                    insideExitX,
                    insideExitY,
                  },
                  {
                    "hide_object",
                    "DAYCARE",
                    loserName,
                  },
                  {
                    "show_text",
                    "_MARS_HAPPINY_EGG_SHAKES",
                  },
                  {
                    "wait",
                    30,
                  },
                  {
                    "play_cry",
                    "HAPPINY",
                  },
                  {
                    "show_object",
                    "DAYCARE",
                    "DAYCARE_HAPPINY_MON",
                  },
                  {
                    "show_text",
                    "_MARS_HAPPINY_HATCHED",
                  },
                  {
                    "show_text",
                    remainingShock,
                  },
                  {
                    "move_npc_to",
                    remainingIndex,
                    insideExitX,
                    insideExitY,
                  },
                  {
                    "hide_object",
                    "DAYCARE",
                    remainingName,
                  },
                  {
                    "show_text",
                    "_MARS_HAPPINY_MAN_AFTER",
                  },
                },
                function()
                  offerHappiny(
                    game,
                    ow,
                    function()
                      ow:afterBattle("win", battle)
                    end
                  )
                end
              )
            end

            ow:pushBattle(battle)
          end
        )
      end
    )
  end

  ---------------------------------------------------------------------------
  -- MAP STATE
  ---------------------------------------------------------------------------

  if mod.content.map_scripts then
    mod.content.map_scripts:register("ROUTE_5", {
      priority = 180,

      onEnter = function(game, ow)
        local flags = game.save.flags or {}

        if flags[FLAGS.choiceMade]
           or flags[FLAGS.received]
        then
          ow:queueScript({
            {
              "hide_object",
              "ROUTE_5",
              "ROUTE5_HAPPINY_DAYCARE_MAN",
            },
          })
        else
          ow:queueScript({
            {
              "show_object",
              "ROUTE_5",
              "ROUTE5_HAPPINY_DAYCARE_MAN",
            },
          })
        end
      end,

      talk = {
        [TEXT_OUTSIDE_MAN] = outsideManTalk,
      },
    })

    mod.content.map_scripts:register("DAYCARE", {
      priority = 180,

      onEnter = function(game, ow)
        local flags = game.save.flags or {}
        local rows = {}

        -- The native Day-Care Man is unavailable while he is mediating the
        -- dispute. After Happiny is adopted, normal vanilla Day Care service
        -- returns without overriding TEXT_DAYCARE_GENTLEMAN.
        if flags[FLAGS.received] then
          rows[#rows + 1] = {
            "show_object",
            "DAYCARE",
            "DAYCARE_GENTLEMAN",
          }
          rows[#rows + 1] = {
            "hide_object",
            "DAYCARE",
            "DAYCARE_HAPPINY_MAN",
          }
        else
          rows[#rows + 1] = {
            "hide_object",
            "DAYCARE",
            "DAYCARE_GENTLEMAN",
          }

          if flags[FLAGS.choiceMade] then
            rows[#rows + 1] = {
              "show_object",
              "DAYCARE",
              "DAYCARE_HAPPINY_MAN",
            }
          else
            rows[#rows + 1] = {
              "hide_object",
              "DAYCARE",
              "DAYCARE_HAPPINY_MAN",
            }
          end
        end

        if flags[FLAGS.hatched]
           or flags[FLAGS.received]
        then
          rows[#rows + 1] = {
            "hide_object",
            "DAYCARE",
            "DAYCARE_HAPPINY_NORA",
          }
          rows[#rows + 1] = {
            "hide_object",
            "DAYCARE",
            "DAYCARE_HAPPINY_LIAM",
          }
        else
          rows[#rows + 1] = {
            "show_object",
            "DAYCARE",
            "DAYCARE_HAPPINY_NORA",
          }
          rows[#rows + 1] = {
            "show_object",
            "DAYCARE",
            "DAYCARE_HAPPINY_LIAM",
          }
        end

        if flags[FLAGS.hatched]
           and not flags[FLAGS.received]
        then
          rows[#rows + 1] = {
            "show_object",
            "DAYCARE",
            "DAYCARE_HAPPINY_MON",
          }
        else
          rows[#rows + 1] = {
            "hide_object",
            "DAYCARE",
            "DAYCARE_HAPPINY_MON",
          }
        end

        if flags[FLAGS.choiceMade]
           and not flags[FLAGS.battleWon]
        then
          -- following the Day-Care Man inside now stages the player at
          -- the final open chair before anyone begins the ruling dialogue.
          appendPlayerWalkToHappinySeat(rows, ow)

          queueHappinyCutscene(
            game,
            ow,
            rows,
            function()
              startDisputeBattle(game, ow)
            end
          )
        else
          ow:queueScript(rows)
        end
      end,

      talk = {
        [TEXT_NORA] = noraTalk,
        [TEXT_LIAM] = liamTalk,
        [TEXT_INSIDE_MAN] = insideManTalk,

        [TEXT_HAPPINY_MON] = {
          { "play_cry", "HAPPINY" },
          { "show_text", "_MARS_HAPPINY_MON_IDLE" },
        },
      },
    })

    local function noraEpilogueTalk(game, ow, npc, done)
      faceHappinyNpc(ow, npc)
      local flags = game.save.flags or {}

      happinySay(
        game,
        flags[FLAGS.choseNora]
          and "_MARS_HAPPINY_NORA_EPILOGUE_CHOSEN"
          or "_MARS_HAPPINY_NORA_EPILOGUE_REJECTED",
        done
      )
    end

    local function liamEpilogueTalk(game, ow, npc, done)
      faceHappinyNpc(ow, npc)
      local flags = game.save.flags or {}

      happinySay(
        game,
        flags[FLAGS.choseLiam]
          and "_MARS_HAPPINY_LIAM_EPILOGUE_CHOSEN"
          or "_MARS_HAPPINY_LIAM_EPILOGUE_REJECTED",
        done
      )
    end

    mod.content.map_scripts:register("VERMILION_CITY", {
      priority = 181,

      onEnter = function(game, ow)
        local flags = game.save.flags or {}
        ow:queueScript({
          {
            flags[FLAGS.received]
              and "show_object"
              or "hide_object",
            "VERMILION_CITY",
            "VERMILION_HAPPINY_NORA",
          },
        })
      end,

      talk = {
        [TEXT_NORA_EPILOGUE] = noraEpilogueTalk,
      },
    })

    mod.content.map_scripts:register("CERULEAN_CITY", {
      priority = 181,

      onEnter = function(game, ow)
        local flags = game.save.flags or {}
        ow:queueScript({
          {
            flags[FLAGS.received]
              and "show_object"
              or "hide_object",
            "CERULEAN_CITY",
            "CERULEAN_HAPPINY_LIAM",
          },
        })
      end,

      talk = {
        [TEXT_LIAM_EPILOGUE] = liamEpilogueTalk,
      },
    })
  end

  mod.log:info(
    "installed Route 5 Happiny hatch sprite and city epilogues"
  )
  end)()


  ---------------------------------------------------------------------------
  -- ROUTE 2 "A DOSE OF MERCY" CHOICE QUEST
  ---------------------------------------------------------------------------
  ;(function()
  ---------------------------------------------------------------------------
  -- ROUTE 2
  --
  -- A Team Rocket Grunt steals a young trainer's Pidgey and flees into
  -- Viridian Forest.
  --
  -- VIRIDIAN FOREST
  --
  -- The Grunt is found poisoned and immobilized after being stung by a
  -- Weedle. The player can:
  --
  --   * GIVE ANTIDOTE         -> mercy route
  --   * SAY NO ANTIDOTES      -> retaliation route
  --   * TAKE PIDGEY / LEAVE   -> retaliation route
  --
  -- If the player actually has an Antidote, "NO ANTIDOTES" is knowingly a
  -- lie and is remembered separately.
  --
  -- MERCY ROUTE
  --
  -- The Grunt returns Pidgey voluntarily, leaves Team Rocket, and later
  -- appears in Vermilion City helping the man and Machop build the radio
  -- tower.
  --
  -- RETALIATION ROUTE
  --
  -- The Grunt survives, tells other Rockets what happened, and ambushes the
  -- player on their first Mt. Moon visit. The group takes all money and all
  -- carried NON-KEY items. The same Grunt then recognizes the player again
  -- alongside the normal three Rocket Grunts holding Mr. Fuji on Pokemon
  -- Tower 7F. The normal tower battles remain the resolution.
  ---------------------------------------------------------------------------

  local FLAGS = {
    started = "EVENT_ROUTE2_MERCY_QUEST_STARTED",
    recovered = "EVENT_ROUTE2_STOLEN_POKEMON_RECOVERED",
    returned = "EVENT_ROUTE2_STOLEN_POKEMON_RETURNED",
    reward = "EVENT_ROUTE2_MERCY_ETHER_RECEIVED",
    complete = "EVENT_ROUTE2_MERCY_QUEST_COMPLETE",

    mercy = "EVENT_ROUTE2_ROCKET_MERCY",
    retaliation = "EVENT_ROUTE2_ROCKET_RETALIATION",
    lied = "EVENT_ROUTE2_ROCKET_LIED_ABOUT_ANTIDOTE",
    noAntidote = "EVENT_ROUTE2_ROCKET_HAD_NO_ANTIDOTE",
    abandoned = "EVENT_ROUTE2_ROCKET_ABANDONED",

    mtMoonRobbed = "EVENT_ROUTE2_ROCKET_MTMOON_ROBBERY",
    towerTaunt = "EVENT_ROUTE2_ROCKET_TOWER_TAUNT",
  }

  local TEXT_KID = "TEXT_MARS_ROUTE2_ROCKET_KID"
  local TEXT_GRUNT_ROUTE2 = "TEXT_MARS_ROUTE2_THIEF"
  local TEXT_KID_PIDGEY = "TEXT_MARS_ROUTE2_KID_PIDGEY"
  local TEXT_FOREST_GRUNT = "TEXT_MARS_ROUTE2_POISONED_ROCKET"
  local TEXT_VERMILION_EX_ROCKET = "TEXT_MARS_VERMILION_EX_ROCKET"

  local route2Def = mod.content.maps:get("ROUTE_2")
  local forestDef = mod.content.maps:get("VIRIDIAN_FOREST")
  local mtMoonDef = mod.content.maps:get("MT_MOON_1F")
  local vermilionDef = mod.content.maps:get("VERMILION_CITY")

  if not route2Def
     or not forestDef
     or not mtMoonDef
     or not vermilionDef
  then
    mod.log:error(
      "A Dose of Mercy requires ROUTE_2, VIRIDIAN_FOREST, "
        .. "MT_MOON_1F, and VERMILION_CITY"
    )
    return
  end

  ---------------------------------------------------------------------------
  -- SAFE POSITION HELPERS
  ---------------------------------------------------------------------------

  local MapDef = require("src.world.Map")

  local function mercyQuestSpot(def, preferredX, preferredY, extraBlocked)
    local tileset =
      def and mod.content.tilesets:get(def.tileset)
      or nil

    local occupied = {}
    for _, obj in ipairs((def and def.objects) or {}) do
      occupied[tostring(obj.x) .. ":" .. tostring(obj.y)] = true
    end
    for _, pos in ipairs(extraBlocked or {}) do
      occupied[tostring(pos[1]) .. ":" .. tostring(pos[2])] = true
    end

    for radius = 0, 14 do
      for dy = -radius, radius do
        for dx = -radius, radius do
          if radius == 0
             or math.max(math.abs(dx), math.abs(dy)) == radius
          then
            local x = preferredX + dx
            local y = preferredY + dy
            local key = tostring(x) .. ":" .. tostring(y)

            if not occupied[key]
               and def
               and tileset
               and x >= 0
               and y >= 0
               and x < def.width * 2
               and y < def.height * 2
               and MapDef.defIsWalkableCell(def, tileset, x, y)
               and not MapDef.defIsWaterCell(def, tileset, x, y)
            then
              return x, y
            end
          end
        end
      end
    end

    return preferredX, preferredY
  end

  ---------------------------------------------------------------------------
  -- ROUTE 2 STAGING
  ---------------------------------------------------------------------------

  -- Keep the scene in the lower half of Route 2 so it is naturally met when
  -- heading north from Viridian City toward the Forest.
  --
  -- shift the whole encounter another three walking cells farther
  -- DOWN Route 2. The scene now begins with the kid, Rocket, and stolen
  -- Pokemon comfortably inside the camera instead of hugging the top edge.
  local kidX, kidY = mercyQuestSpot(
    route2Def,
    math.floor(route2Def.width),
    math.max(3, route2Def.height * 2 - 3)
  )

  local thiefX, thiefY = mercyQuestSpot(
    route2Def,
    kidX + 1,
    kidY,
    {
      { kidX, kidY },
    }
  )

  local pidgeyX, pidgeyY = mercyQuestSpot(
    route2Def,
    kidX - 1,
    kidY,
    {
      { kidX, kidY },
      { thiefX, thiefY },
    }
  )

  local thiefRunX, thiefRunY = mercyQuestSpot(
    route2Def,
    thiefX,
    math.max(1, thiefY - 5),
    {
      { kidX, kidY },
      { pidgeyX, pidgeyY },
    }
  )

  ---------------------------------------------------------------------------
  -- VIRIDIAN FOREST STAGING
  ---------------------------------------------------------------------------

  -- Lower-left side of the Forest, where the Grunt has collapsed in the
  -- grass after a Weedle sting.
  local forestGruntX, forestGruntY = mercyQuestSpot(
    forestDef,
    3,
    math.max(3, forestDef.height * 2 - 6)
  )

  ---------------------------------------------------------------------------
  -- VERMILION EPILOGUE STAGING
  ---------------------------------------------------------------------------

  -- Find the existing construction Machop first. The imported object names
  -- differ a little between ROMs, so prefer a MACHOP-named/text object, then
  -- fall back to the first monster sprite in Vermilion.
  local constructionMon = nil

  for _, obj in ipairs(vermilionDef.objects or {}) do
    local name = tostring(obj.name or "")
    local textId = tostring(obj.text or "")

    if name:find("MACHOP", 1, true)
       or textId:find("MACHOP", 1, true)
    then
      constructionMon = obj
      break
    end
  end

  if not constructionMon then
    for _, obj in ipairs(vermilionDef.objects or {}) do
      if obj.sprite == "SPRITE_MONSTER" then
        constructionMon = obj
        break
      end
    end
  end

  local constructionX =
    constructionMon and constructionMon.x
    or math.floor(vermilionDef.width)

  local constructionY =
    constructionMon and constructionMon.y
    or math.floor(vermilionDef.height)

  local exRocketX, exRocketY = mercyQuestSpot(
    vermilionDef,
    constructionX + 1,
    constructionY,
    {
      { constructionX, constructionY },
    }
  )

  ---------------------------------------------------------------------------
  -- OBJECT INDICES
  ---------------------------------------------------------------------------

  local route2BaseIndex = #(route2Def.objects or {}) + 1
  local kidIndex = route2BaseIndex
  local route2ThiefIndex = route2BaseIndex + 1
  local kidPidgeyIndex = route2BaseIndex + 2

  local forestGruntIndex = #(forestDef.objects or {}) + 1

  local mtMoonBaseIndex = #(mtMoonDef.objects or {}) + 1
  local mtMoonGruntIndices = {
    mtMoonBaseIndex,
    mtMoonBaseIndex + 1,
    mtMoonBaseIndex + 2,
    mtMoonBaseIndex + 3,
  }

  local vermilionExRocketIndex =
    #(vermilionDef.objects or {}) + 1

  ---------------------------------------------------------------------------
  -- MAP OBJECTS
  ---------------------------------------------------------------------------

  mod.content.maps:patch("ROUTE_2", {
    objects = {
      __append = {
        {
          index = kidIndex,
          name = "MARS_ROUTE2_ROCKET_KID",
          sprite = "SPRITE_YOUNGSTER",
          movement = "STAY",
          range = "RIGHT",
          x = kidX,
          y = kidY,
          text = TEXT_KID,
        },
        {
          index = route2ThiefIndex,
          name = "MARS_ROUTE2_ROCKET_THIEF",
          sprite = "SPRITE_ROCKET",
          movement = "STAY",
          range = "LEFT",
          x = thiefX,
          y = thiefY,
          text = TEXT_GRUNT_ROUTE2,
        },
        {
          index = kidPidgeyIndex,
          name = "MARS_ROUTE2_KID_PIDGEY",
          sprite = "SPRITE_BIRD",
          movement = "STAY",
          range = "ANY_DIR",
          x = pidgeyX,
          y = pidgeyY,
          text = TEXT_KID_PIDGEY,
          hidden = true,
        },
      },
    },
  })

  mod.content.maps:patch("VIRIDIAN_FOREST", {
    objects = {
      __append = {
        {
