  ---------------------------------------------------------------------------
  -- TEXT HELPERS
  ---------------------------------------------------------------------------

  local function mercySay(game, textIdOrLiteral, done, opts)
    local TextBox = require("src.render.TextBox")
    local value =
      game.data.text[textIdOrLiteral]
      or textIdOrLiteral

    game.stack:push(TextBox.new(
      game,
      value,
      done,
      opts
    ))
  end

  local mercyCutsceneCallbacks =
    setmetatable({}, { __mode = "k" })

  mod.commands:register("mars_route2_mercy_cutscene_done", function(ctx)
    local callback = mercyCutsceneCallbacks[ctx.game]
    mercyCutsceneCallbacks[ctx.game] = nil
    if callback then callback() end
  end)

  local function queueMercyCutscene(game, ow, rows, callback)
    mercyCutsceneCallbacks[game] = callback
    rows[#rows + 1] = {
      "mars_route2_mercy_cutscene_done"
    }
    ow:queueScript(rows)
  end

  local function faceMercyNpc(ow, npc)
    if npc and npc.facePlayer and ow and ow.player then
      npc:facePlayer(ow.player)
    end
  end

  ---------------------------------------------------------------------------
  -- ROUTE 2 THEFT SCENE
  ---------------------------------------------------------------------------

  local function startRoute2Theft(game, ow)
    local flags = game.save.flags or {}
    if flags[FLAGS.started] then return end

    flags[FLAGS.started] = true

    queueMercyCutscene(
      game,
      ow,
      {
        {
          "show_text",
          "_MARS_ROUTE2_THEFT_GRUNT",
        },
        {
          "show_text",
          "_MARS_ROUTE2_THEFT_KID",
        },
        {
          "show_text",
          "_MARS_ROUTE2_THEFT_ESCAPE",
        },
        {
          "move_npc_to",
          route2ThiefIndex,
          thiefRunX,
          thiefRunY,
        },
        {
          "hide_object",
          "ROUTE_2",
          "MARS_ROUTE2_ROCKET_THIEF",
        },

        -- once the thief is gone, the kid visibly turns DOWN toward
        -- the player before asking for help.
        {
          "face_object",
          kidIndex,
          "down",
        },
        {
          "wait",
          8,
        },
        {
          "show_text",
          "_MARS_ROUTE2_KID_PLEA",
        },
      },
      function() end
    )
  end

  ---------------------------------------------------------------------------
  -- FOREST DECISION
  ---------------------------------------------------------------------------

  local function finishForestChoice(
    game,
    ow,
    done,
    textId,
    hideGruntNow
  )
    local flags = game.save.flags or {}
    flags[FLAGS.recovered] = true

    local function finishRecovery()
      local rows = {
        {
          "show_text",
          "_MARS_ROUTE2_RECOVERED",
        },
      }

      -- Mercy is the only branch where the Grunt actually leaves.
      --
      -- retaliation branches explicitly re-show him after recovery so
      -- he remains visibly stranded for the rest of this Forest visit.
      --
      -- on the mercy route, do not let him simply blink out. Once the
      -- Forest dialogue/recovery message is finished, fade fully to black,
      -- remove him while the screen is covered, then fade back in.
      if hideGruntNow then
        rows[#rows + 1] = {
          "fade",
          "out",
          20,
        }
        rows[#rows + 1] = {
          "wait",
          30,
        }
        rows[#rows + 1] = {
          "hide_object",
          "VIRIDIAN_FOREST",
          "MARS_ROUTE2_POISONED_ROCKET",
        }
        rows[#rows + 1] = {
          "fade",
          "in",
          20,
        }
      else
        -- retaliation branches leave the already-visible Grunt exactly
        -- where he collapsed. Do not recreate the NPC during this interaction.
      end

      queueMercyCutscene(
        game,
        ow,
        rows,
        done
      )
    end

    if textId then
      mercySay(
        game,
        textId,
        finishRecovery
      )
    else
      finishRecovery()
    end
  end

  local function forestMercy(game, ow, done)
    local flags = game.save.flags or {}
    local Bag = require("src.inventory.Bag")

    if (game.save.inventory.ANTIDOTE or 0) <= 0 then
      -- Defensive fallback if the Bag changed while the choice menu was up.
      flags[FLAGS.retaliation] = true
      flags[FLAGS.noAntidote] = true

      finishForestChoice(
        game,
        ow,
        done,
        "_MARS_ROUTE2_NO_ANTIDOTE_REACTION",
        false
      )
      return
    end

    Bag.remove(game.save, "ANTIDOTE", 1)

    flags[FLAGS.mercy] = true

    mercySay(
      game,
      "_MARS_ROUTE2_MERCY_GIVE",
      function()
        finishForestChoice(
          game,
          ow,
          done,
          "_MARS_ROUTE2_MERCY_REACTION",
          true
        )
      end
    )
  end

  local function forestNoAntidote(
    game,
    ow,
    done,
    playerActuallyHasOne
  )
    local flags = game.save.flags or {}

    flags[FLAGS.retaliation] = true

    if playerActuallyHasOne then
      flags[FLAGS.lied] = true
      finishForestChoice(
        game,
        ow,
        done,
        "_MARS_ROUTE2_LIE_REACTION",
        false
      )
    else
      flags[FLAGS.noAntidote] = true
      finishForestChoice(
        game,
        ow,
        done,
        "_MARS_ROUTE2_NO_ANTIDOTE_REACTION",
        false
      )
    end
  end

  local function forestAbandon(game, ow, done)
    local flags = game.save.flags or {}

    flags[FLAGS.retaliation] = true
    flags[FLAGS.abandoned] = true
    flags[FLAGS.recovered] = true

    -- a dedicated linear branch guarantees one reaction, one recovery
    -- message, and leaves the poisoned Grunt physically stranded in place.
    queueMercyCutscene(
      game,
      ow,
      {
        {
          "show_text",
          "_MARS_ROUTE2_ABANDON_REACTION",
        },
        {
          "show_text",
          "_MARS_ROUTE2_RECOVERED",
        },
      },
      done
    )
  end

  local function forestGruntTalk(game, ow, npc, done)
    local flags = game.save.flags or {}
    faceMercyNpc(ow, npc)

    if not flags[FLAGS.started] then
      if done then done() end
      return
    end

    if flags[FLAGS.recovered] then
      if flags[FLAGS.retaliation] then
        local textId =
          flags[FLAGS.lied]
          and "_MARS_ROUTE2_FOREST_AFTER_LIED"
          or (
            flags[FLAGS.abandoned]
            and "_MARS_ROUTE2_FOREST_AFTER_ABANDON"
            or "_MARS_ROUTE2_FOREST_AFTER_NO_ANTIDOTE"
          )

        mercySay(
          game,
          textId,
          done
        )
      elseif done then
        done()
      end
      return
    end

    local hasAntidote =
      (game.save.inventory.ANTIDOTE or 0) > 0

    mercySay(
      game,
      "_MARS_ROUTE2_FOREST_GRUNT",
      function()
        mercySay(
          game,
          hasAntidote
            and "_MARS_ROUTE2_FOREST_HAVE_ANTIDOTE"
            or "_MARS_ROUTE2_FOREST_NO_ANTIDOTE",
          function()
            local ListMenu = require("src.ui.ListMenu")
            local entries = {}

            if hasAntidote then
              entries[#entries + 1] = {
                label = "GIVE ANTIDOTE",
                value = "GIVE",
              }
            end

            entries[#entries + 1] = {
              label = hasAntidote
                and "NO ANTIDOTES"
                or "I CAN'T HELP",
              value = "NO_ANTIDOTE",
            }

            entries[#entries + 1] = {
              label = "TAKE PIDGEY",
              value = "ABANDON",
            }

            local list
            list = ListMenu.new(
              game,
              "WHAT DO YOU DO?",
              entries,
              {
                onChoose = function(item)
                  if not item or not item.value then return end
                  list:close()

                  if item.value == "GIVE" then
                    forestMercy(game, ow, done)
                  elseif item.value == "NO_ANTIDOTE" then
                    forestNoAntidote(
                      game,
                      ow,
                      done,
                      hasAntidote
                    )
                  else
                    forestAbandon(game, ow, done)
                  end
                end,

                onCancel = function()
                  list:close()
                  if done then done() end
                end,
              }
            )

            game.stack:push(list)
          end
        )
      end
    )
  end

  ---------------------------------------------------------------------------
  -- RETURN PIDGEY / ETHER REWARD
  ---------------------------------------------------------------------------

  local function giveKidEther(game, done)
    local flags = game.save.flags or {}
    local Bag = require("src.inventory.Bag")

    if flags[FLAGS.reward] then
      flags[FLAGS.complete] = true
      if done then done() end
      return
    end

    if not Bag.add(
      game.save,
      "ETHER",
      1,
      game.data
    ) then
      mercySay(
        game,
        "_MARS_ROUTE2_KID_BAG_FULL",
        done
      )
      return
    end

    flags[FLAGS.reward] = true
    flags[FLAGS.complete] = true

    local Sound = require("src.core.Sound")
    Sound.play(game.data, "Get_Item1")

    mercySay(
      game,
      "_MARS_ROUTE2_KID_ETHER",
      done
    )
  end

  local function kidTalk(game, ow, npc, done)
    local flags = game.save.flags or {}
    faceMercyNpc(ow, npc)

    if not flags[FLAGS.started] then
      startRoute2Theft(game, ow)
      if done then done() end
      return
    end

    if not flags[FLAGS.recovered] then
      mercySay(
        game,
        "_MARS_ROUTE2_KID_WAITING",
        done
      )
      return
    end

    if not flags[FLAGS.returned] then
      flags[FLAGS.returned] = true

      queueMercyCutscene(
        game,
        ow,
        {
          {
            "show_object",
            "ROUTE_2",
            "MARS_ROUTE2_KID_PIDGEY",
          },
          {
            "show_text",
            flags[FLAGS.mercy]
              and "_MARS_ROUTE2_KID_RETURN_MERCY"
              or "_MARS_ROUTE2_KID_RETURN_RETALIATION",
          },
        },
        function()
          giveKidEther(game, done)
        end
      )
      return
    end

    if not flags[FLAGS.reward] then
      giveKidEther(game, done)
      return
    end

    mercySay(
      game,
      "_MARS_ROUTE2_KID_AFTER",
      done
    )
  end

  ---------------------------------------------------------------------------
  -- MT. MOON ROBBERY
  ---------------------------------------------------------------------------

  local function faceToward(px, py, x, y)
    local dx = px - x
    local dy = py - y

    if math.abs(dx) > math.abs(dy) then
      return dx > 0 and "right" or "left"
    end

    return dy > 0 and "down" or "up"
  end

  mod.commands:register(
    "mars_route2_stage_mtmoon_ambush",
    function(ctx)
      local ow = ctx.overworld
      local player = ow and ow.player
      if not ow or not player then return end

      local px, py = player.cellX, player.cellY

      local candidates = {
        { px - 1, py },
        { px + 1, py },
        { px, py - 1 },
        { px, py + 1 },
        { px - 1, py - 1 },
        { px + 1, py - 1 },
        { px - 1, py + 1 },
        { px + 1, py + 1 },
        { px - 2, py },
        { px + 2, py },
      }

      local chosen = {}
      for _, pos in ipairs(candidates) do
        if #chosen >= #mtMoonGruntIndices then break end

        local x, y = pos[1], pos[2]
        if ow.map
           and ow.map:inBounds(x, y)
           and ow.map:isWalkableCell(x, y)
           and not (x == px and y == py)
        then
          chosen[#chosen + 1] = pos
        end
      end

      while #chosen < #mtMoonGruntIndices do
        local n = #chosen + 1
        chosen[n] = {
          px + ((n % 2 == 0) and 1 or -1),
          py + math.floor((n - 1) / 2),
        }
      end

      local Commands = require("src.script.Commands")

      for i, index in ipairs(mtMoonGruntIndices) do
        local pos = chosen[i]
        Commands.place_npc(
          ctx,
          index,
          pos[1],
          pos[2],
          faceToward(px, py, pos[1], pos[2])
        )
      end
    end
  )

  local function isProtectedInventoryItem(game, itemId)
    local def =
      game.data.items
      and game.data.items[itemId]
      or nil

    if def and def.keyItem then
      return true
    end

    -- Badges are stored through the same inventory table in Gen1Recomp.
    -- Preserve them even on a ROM/import whose item metadata does not mark
    -- them as key items.
    local Badges = require("src.inventory.Badges")
    for _, badge in ipairs(Badges.list(game.data) or {}) do
      if Badges.itemFor(badge) == itemId then
        return true
      end
    end

    return false
  end

  mod.commands:register(
    "mars_route2_rocket_rob_player",
    function(ctx)
      local game = ctx.game
      local save = ctx.save or (game and game.save)
      if not game or not save then return end

      save.money = 0
      save.inventory = save.inventory or {}

      local toRemove = {}
      for itemId, qty in pairs(save.inventory) do
        if qty
           and not isProtectedInventoryItem(game, itemId)
        then
          toRemove[#toRemove + 1] = itemId
        end
      end

      for _, itemId in ipairs(toRemove) do
        save.inventory[itemId] = nil
      end

      save.flags = save.flags or {}
      save.flags[FLAGS.mtMoonRobbed] = true
    end
  )

  local function mtMoonBranchText(flags)
    if flags[FLAGS.lied] then
      return "_MARS_ROUTE2_MTMOON_LIED"
    elseif flags[FLAGS.abandoned] then
      return "_MARS_ROUTE2_MTMOON_ABANDONED"
    end

    return "_MARS_ROUTE2_MTMOON_NO_ANTIDOTE"
  end

  local function runMtMoonRobbery(game, ow)
    local flags = game.save.flags or {}

    if not flags[FLAGS.retaliation]
       or flags[FLAGS.mtMoonRobbed]
    then
      return
    end

    local rows = {
      { "fade", "out", 15 },
    }

    for i = 1, #mtMoonGruntIndices do
      rows[#rows + 1] = {
        "show_object",
        "MT_MOON_1F",
        "MARS_ROUTE2_MTMOON_ROCKET_" .. tostring(i),
      }
    end

    rows[#rows + 1] = {
      "mars_route2_stage_mtmoon_ambush",
    }

    rows[#rows + 1] = { "fade", "in", 15 }

    rows[#rows + 1] = {
      "show_text",
      "_MARS_ROUTE2_MTMOON_SURROUNDED",
    }

    rows[#rows + 1] = {
      "show_text",
      mtMoonBranchText(flags),
    }

    rows[#rows + 1] = {
      "show_text",
      "_MARS_ROUTE2_MTMOON_PAYBACK",
    }

    rows[#rows + 1] = {
      "mars_route2_rocket_rob_player",
    }

    rows[#rows + 1] = {
      "show_text",
      "_MARS_ROUTE2_MTMOON_ROBBED",
    }

    rows[#rows + 1] = {
      "show_text",
      "_MARS_ROUTE2_MTMOON_EXIT",
    }

    rows[#rows + 1] = { "fade", "out", 15 }

    for i = 1, #mtMoonGruntIndices do
      rows[#rows + 1] = {
        "hide_object",
        "MT_MOON_1F",
        "MARS_ROUTE2_MTMOON_ROCKET_" .. tostring(i),
      }
    end

    rows[#rows + 1] = { "fade", "in", 15 }

    ow:queueScript(rows)
  end

  ---------------------------------------------------------------------------
  -- POKEMON TOWER CALLBACK
  ---------------------------------------------------------------------------

  local function towerBranchText(flags)
    if flags[FLAGS.lied] then
      return "_MARS_ROUTE2_TOWER_TAUNT_LIED"
    elseif flags[FLAGS.abandoned] then
      return "_MARS_ROUTE2_TOWER_TAUNT_ABANDONED"
    end

    return "_MARS_ROUTE2_TOWER_TAUNT_NO_ANTIDOTE"
  end

  ---------------------------------------------------------------------------
  -- VERMILION FORMER-ROCKET EPILOGUE
  ---------------------------------------------------------------------------

  local function exRocketTalk(game, ow, npc, done)
    faceMercyNpc(ow, npc)

    mercySay(
      game,
      "_MARS_ROUTE2_EX_ROCKET",
      done
    )
  end

  ---------------------------------------------------------------------------
  -- MAP SCRIPTS
  ---------------------------------------------------------------------------

  if mod.content.map_scripts then
    mod.content.map_scripts:register("ROUTE_2", {
      priority = 190,

      onEnter = function(game, ow)
        local flags = game.save.flags or {}
        local rows = {}

        if flags[FLAGS.returned] then
          rows[#rows + 1] = {
            "show_object",
            "ROUTE_2",
            "MARS_ROUTE2_KID_PIDGEY",
          }
        else
          rows[#rows + 1] = {
            "hide_object",
            "ROUTE_2",
            "MARS_ROUTE2_KID_PIDGEY",
          }
        end

        if flags[FLAGS.started] then
          rows[#rows + 1] = {
            "hide_object",
            "ROUTE_2",
            "MARS_ROUTE2_ROCKET_THIEF",
          }
        else
          rows[#rows + 1] = {
            "show_object",
            "ROUTE_2",
            "MARS_ROUTE2_ROCKET_THIEF",
          }
        end

        ow:queueScript(rows)
      end,

      onStep = function(game, ow, x, y)
        local flags = game.save.flags or {}

        if flags[FLAGS.started] then
          return false
        end

        if math.abs(x - kidX) <= 4
           and math.abs(y - kidY) <= 4
        then
          startRoute2Theft(game, ow)
          return true
        end

        return false
      end,

      talk = {
        [TEXT_KID] = kidTalk,

        [TEXT_GRUNT_ROUTE2] = function(game, ow, npc, done)
          if not (game.save.flags or {})[FLAGS.started] then
            startRoute2Theft(game, ow)
            if done then done() end
          elseif done then
            done()
          end
        end,

        [TEXT_KID_PIDGEY] = {
          { "play_cry", "PIDGEY" },
          { "show_text", "_MARS_ROUTE2_PIDGEY_AFTER" },
        },
      },
    })

    mod.content.map_scripts:register("VIRIDIAN_FOREST", {
      priority = 190,

      onEnter = function(game, ow)
        local flags = game.save.flags or {}

        local keepPoisonedGrunt =
          flags[FLAGS.started]
          and (
            not flags[FLAGS.recovered]
            or (
              flags[FLAGS.retaliation]
              and not flags[FLAGS.mtMoonRobbed]
            )
          )

        if keepPoisonedGrunt then
          ow:queueScript({
            {
              "show_object",
              "VIRIDIAN_FOREST",
              "MARS_ROUTE2_POISONED_ROCKET",
            },
          })
        else
          ow:queueScript({
            {
              "hide_object",
              "VIRIDIAN_FOREST",
              "MARS_ROUTE2_POISONED_ROCKET",
            },
          })
        end
      end,

      talk = {
        [TEXT_FOREST_GRUNT] = forestGruntTalk,
      },
    })

    mod.content.map_scripts:register("MT_MOON_1F", {
      priority = 190,

      onEnter = function(game, ow)
        local flags = game.save.flags or {}

        if flags[FLAGS.retaliation]
           and not flags[FLAGS.mtMoonRobbed]
        then
          runMtMoonRobbery(game, ow)
        else
          local rows = {}
          for i = 1, #mtMoonGruntIndices do
            rows[#rows + 1] = {
              "hide_object",
              "MT_MOON_1F",
              "MARS_ROUTE2_MTMOON_ROCKET_" .. tostring(i),
            }
          end
          ow:queueScript(rows)
        end
      end,

      talk = {
        TEXT_MARS_ROUTE2_MTMOON_ROCKET_1 = {
          {
            "show_text",
            "_MARS_ROUTE2_MTMOON_PAYBACK",
          },
        },
        TEXT_MARS_ROUTE2_MTMOON_ROCKET_2 = {
          {
            "show_text",
            "_MARS_ROUTE2_MTMOON_PAYBACK",
          },
        },
        TEXT_MARS_ROUTE2_MTMOON_ROCKET_3 = {
          {
            "show_text",
            "_MARS_ROUTE2_MTMOON_PAYBACK",
          },
        },
        TEXT_MARS_ROUTE2_MTMOON_ROCKET_4 = {
          {
            "show_text",
            "_MARS_ROUTE2_MTMOON_PAYBACK",
          },
        },
      },
    })

    mod.content.map_scripts:register("POKEMON_TOWER_7F", {
      priority = 190,

      onEnter = function(game, ow)
        local flags = game.save.flags or {}

        if not flags[FLAGS.retaliation]
           or not flags[FLAGS.mtMoonRobbed]
           or flags[FLAGS.towerTaunt]
           or flags.EVENT_RESCUED_MR_FUJI
        then
          return
        end

        flags[FLAGS.towerTaunt] = true

        ow:queueScript({
          {
            "show_text",
            towerBranchText(flags),
          },
          {
            "show_text",
            "_MARS_ROUTE2_TOWER_TAUNT_GROUP",
          },
        })
      end,
    })

    mod.content.map_scripts:register("VERMILION_CITY", {
      priority = 190,

      onEnter = function(game, ow)
        local flags = game.save.flags or {}

        if flags[FLAGS.mercy]
           and flags[FLAGS.complete]
        then
          ow:queueScript({
            {
              "show_object",
              "VERMILION_CITY",
              "MARS_ROUTE2_EX_ROCKET",
            },
          })
        else
          ow:queueScript({
            {
              "hide_object",
              "VERMILION_CITY",
              "MARS_ROUTE2_EX_ROCKET",
            },
          })
        end
      end,

      talk = {
        [TEXT_VERMILION_EX_ROCKET] = exRocketTalk,
      },
    })
  end

  mod.log:info(
    "installed A Dose of Mercy opening exposition and abandonment polish"
  )
  end)()


  ---------------------------------------------------------------------------
  -- SAFARI ZONE ACTIVIST SIDE QUEST
  ---------------------------------------------------------------------------
  ;(function()
  ---------------------------------------------------------------------------
  -- "SAFARI BREAKOUT"
  --
  -- A Safari Zone Ranger suspects someone has repeatedly been hopping the
  -- perimeter fence and removing Pokemon without authorization.
  --
