    reported = "EVENT_SAFARI_ACTIVIST_REPORTED",
    resolved = "EVENT_SAFARI_ACTIVIST_RESOLVED",
    tmReceived = "EVENT_SAFARI_ACTIVIST_TM_RECEIVED",
    unlimitedSteps = "EVENT_SAFARI_UNLIMITED_STEPS",
  }

  local TEXT_RANGER = "TEXT_MARS_SAFARI_RANGER"
  local TEXT_ACTIVIST_EAST = "TEXT_MARS_SAFARI_ACTIVIST_EAST"
  local TEXT_ACTIVIST_CITY = "TEXT_MARS_SAFARI_ACTIVIST_CITY"
  local TEXT_ARREST_ACTIVIST = "TEXT_MARS_SAFARI_ARREST_ACTIVIST"
  local TEXT_ARREST_OFFICER = "TEXT_MARS_SAFARI_ARREST_OFFICER"

  local gateDef = mod.content.maps:get("SAFARI_ZONE_GATE")
  local eastDef = mod.content.maps:get("SAFARI_ZONE_EAST")
  local fuchsiaDef = mod.content.maps:get("FUCHSIA_CITY")

  if not gateDef or not eastDef or not fuchsiaDef then
    mod.log:error(
      "Safari activist quest requires SAFARI_ZONE_GATE, "
        .. "SAFARI_ZONE_EAST, and FUCHSIA_CITY"
    )
    return
  end

  ---------------------------------------------------------------------------
  -- SAFE PLACEMENT
  ---------------------------------------------------------------------------

  local MapDef = require("src.world.Map")

  local function questSpot(def, preferredX, preferredY, extraBlocked)
    local tileset =
      def and mod.content.tilesets:get(def.tileset)
      or nil

    local occupied = {}
    for _, obj in ipairs((def and def.objects) or {}) do
      occupied[tostring(obj.x) .. ":" .. tostring(obj.y)] = true
    end
    for _, pos in ipairs(extraBlocked or {}) do
      occupied[tostring(pos[1]) .. ":" .. tostring(pos[2])] = true
    end

    for radius = 0, 14 do
      for dy = -radius, radius do
        for dx = -radius, radius do
          if radius == 0
             or math.max(math.abs(dx), math.abs(dy)) == radius
          then
            local x = preferredX + dx
            local y = preferredY + dy
            local key = tostring(x) .. ":" .. tostring(y)

            if not occupied[key]
               and def
               and tileset
               and x >= 0
               and y >= 0
               and x < def.width * 2
               and y < def.height * 2
               and MapDef.defIsWalkableCell(def, tileset, x, y)
               and not MapDef.defIsWaterCell(def, tileset, x, y)
            then
              return x, y
            end
          end
        end
      end
    end

    return preferredX, preferredY
  end

  -- Ranger: inside the entrance building, away from the two vanilla workers.
  -- shifted one tile down so the fee gate/counter does not block interaction.
  local rangerX, rangerY = questSpot(
    gateDef,
    1,
    3,
    {
      { 3, 0 }, { 4, 0 },
      { 3, 2 }, { 4, 2 },
      { 3, 5 }, { 4, 5 },
    }
  )

  -- Activist: deliberately near the southern perimeter of the east zone.
  local activistEastX, activistEastY = questSpot(
    eastDef,
    math.floor(eastDef.width),
    math.max(2, eastDef.height * 2 - 4)
  )

  -- Post-choice activist: immediately east of the Safari Zone entrance
  -- building in Fuchsia City.
  local activistCityX, activistCityY = questSpot(
    fuchsiaDef,
    22,
    5
  )

  local gateBaseIndex = #(gateDef.objects or {}) + 1
  local rangerIndex = gateBaseIndex
  local arrestActivistIndex = gateBaseIndex + 1
  local arrestOfficerIndex = gateBaseIndex + 2

  local eastActivistIndex = #(eastDef.objects or {}) + 1
  local cityActivistIndex = #(fuchsiaDef.objects or {}) + 1

  ---------------------------------------------------------------------------
  -- OBJECTS
  ---------------------------------------------------------------------------

  mod.content.maps:patch("SAFARI_ZONE_GATE", {
    objects = {
      __append = {
        {
          index = rangerIndex,
          name = "MARS_SAFARI_RANGER",
          sprite = "SPRITE_SAFARI_ZONE_WORKER",
