          sprite = "SPRITE_COOLTRAINER_F",
          movement = "STAY",
          range = "DOWN",
          x = 3,
          y = 2,
          text = TEXT_ARREST_ACTIVIST,
          hidden = true,
        },
        {
          index = arrestOfficerIndex,
          name = "MARS_SAFARI_ARREST_OFFICER",
          sprite = "SPRITE_GUARD",
          movement = "STAY",
          range = "DOWN",
          x = 4,
          y = 2,
          text = TEXT_ARREST_OFFICER,
          hidden = true,
        },
      },
    },
  })

  mod.content.maps:patch("SAFARI_ZONE_EAST", {
    objects = {
      __append = {
        {
          index = eastActivistIndex,
          name = "MARS_SAFARI_ACTIVIST_EAST",
          sprite = "SPRITE_COOLTRAINER_F",
          movement = "STAY",
          range = "UP",
          x = activistEastX,
          y = activistEastY,
          text = TEXT_ACTIVIST_EAST,
          hidden = true,
        },
      },
    },
  })

  mod.content.maps:patch("FUCHSIA_CITY", {
    objects = {
      __append = {
        {
          index = cityActivistIndex,
          name = "MARS_SAFARI_ACTIVIST_CITY",
          sprite = "SPRITE_COOLTRAINER_F",
          movement = "STAY",
          range = "ANY_DIR",
          x = activistCityX,
