  ---------------------------------------------------------------------------
  -- COMMON HELPERS
  ---------------------------------------------------------------------------

  local function safariSay(game, textIdOrLiteral, done, opts)
    local TextBox = require("src.render.TextBox")
    local value =
      game.data.text[textIdOrLiteral]
      or textIdOrLiteral

    game.stack:push(TextBox.new(
      game,
      value,
      done,
      opts
    ))
  end

  local safariCutsceneCallbacks =
    setmetatable({}, { __mode = "k" })

  mod.commands:register("mars_safari_cutscene_done", function(ctx)
    local callback = safariCutsceneCallbacks[ctx.game]
    safariCutsceneCallbacks[ctx.game] = nil
    if callback then callback() end
  end)

  local function queueSafariCutscene(game, ow, rows, callback)
    safariCutsceneCallbacks[game] = callback
    rows[#rows + 1] = { "mars_safari_cutscene_done" }
    ow:queueScript(rows)
  end

  local function faceSafariNpc(ow, npc)
    if npc and npc.facePlayer and ow and ow.player then
      npc:facePlayer(ow.player)
    end
  end

  ---------------------------------------------------------------------------
  -- PERMANENT SAFARI STEP-LIMIT REWARD
  ---------------------------------------------------------------------------

  do
    local OverworldState =
      require("src.world.OverworldController")

    if not OverworldState._marsUnlimitedSafariSteps then
      OverworldState._marsUnlimitedSafariSteps = true
      local baseSafariStep = OverworldState.safariStep

      OverworldState.safariStep = function(self)
        local Game = require("src.core.Game")
        local flags =
          Game.save and Game.save.flags or {}

        if flags[FLAGS.unlimitedSteps]
           and Game.save.safari
           and self:inSafariStepZone()
        then
          return false
        end

        return baseSafariStep(self)
      end
    end
  end

  ---------------------------------------------------------------------------
  -- QUEST GIVER
  ---------------------------------------------------------------------------

  local function startSafariInvestigation(game, done)
    local flags = game.save.flags or {}
    flags[FLAGS.started] = true

    safariSay(
      game,
      "_MARS_SAFARI_RANGER_INTRO",
      function()
        if not flags[FLAGS.feePaid] then
          flags[FLAGS.feePaid] = true
          game.save.money =
            math.min(999999, (game.save.money or 0) + 500)

          local Sound = require("src.core.Sound")
          Sound.play(game.data, "Get_Item1")

          safariSay(
            game,
            "_MARS_SAFARI_RANGER_FEE",
            done
          )
        elseif done then
          done()
        end
      end
    )
  end

  local function reportActivist(game, ow, done)
    local flags = game.save.flags or {}

    flags[FLAGS.reported] = true
    flags[FLAGS.resolved] = true

    safariSay(
      game,
      "_MARS_SAFARI_RANGER_TRUTH",
      function()
        queueSafariCutscene(
          game,
          ow,
          {
            { "fade", "out", 20 },

            {
              "show_object",
              "SAFARI_ZONE_GATE",
              "MARS_SAFARI_ARREST_ACTIVIST",
            },
            {
              "show_object",
              "SAFARI_ZONE_GATE",
              "MARS_SAFARI_ARREST_OFFICER",
            },

            { "fade", "in", 20 },

            {
              "show_text",
              "_MARS_SAFARI_ARREST_RANGER",
            },
            {
              "show_text",
              "_MARS_SAFARI_ARREST_ACTIVIST_1",
            },
            {
              "face_player_dir",
              "up",
            },
            {
              "show_text",
              "_MARS_SAFARI_ARREST_ACTIVIST_2",
            },
            {
              "show_text",
              "_MARS_SAFARI_ARREST_OFFICER",
            },

            -- Have the officer lead the way and the activist follow
            -- behind him toward the south exit.
            {
              "move_npc_to",
              arrestOfficerIndex,
              4,
              5,
            },
            {
              "move_npc_to",
              arrestActivistIndex,
              4,
              4,
            },

            { "fade", "out", 15 },

            {
              "hide_object",
              "SAFARI_ZONE_GATE",
              "MARS_SAFARI_ARREST_ACTIVIST",
            },
            {
              "hide_object",
              "SAFARI_ZONE_GATE",
              "MARS_SAFARI_ARREST_OFFICER",
            },

            { "fade", "in", 15 },

            {
              "show_text",
              "_MARS_SAFARI_RANGER_REWARD",
            },
          },
          function()
            flags[FLAGS.unlimitedSteps] = true
            if done then done() end
          end
        )
      end
    )
  end

  local function protectActivist(game, done)
    local flags = game.save.flags or {}

    flags[FLAGS.protected] = true
    flags[FLAGS.resolved] = true

    safariSay(
      game,
      "_MARS_SAFARI_RANGER_LIED",
      done
    )
  end

  local function rangerDecision(game, ow, done)
    local flags = game.save.flags or {}

    safariSay(
      game,
      "_MARS_SAFARI_RANGER_REPORT",
      function()
        local ListMenu = require("src.ui.ListMenu")
        local list

        list = ListMenu.new(
          game,
          "WHAT DO YOU SAY?",
          {
            {
              label = "TELL THE TRUTH",
              value = "TRUTH",
            },
            {
              label = "NOTHING TO REPORT",
              value = "LIE",
            },
          },
          {
            onChoose = function(item)
              if not item or not item.value then return end
              list:close()

              if item.value == "TRUTH" then
                reportActivist(game, ow, done)
              else
                protectActivist(game, done)
              end
            end,

            onCancel = function()
              list:close()
              if done then done() end
            end,
          }
        )

        game.stack:push(list)
      end
    )
  end

  local function rangerTalk(game, ow, npc, done)
    local flags = game.save.flags or {}
    faceSafariNpc(ow, npc)

    if flags[FLAGS.reported] then
      safariSay(
        game,
        "_MARS_SAFARI_RANGER_AFTER_TRUTH",
        done
      )
      return
    end

    if flags[FLAGS.protected] then
      safariSay(
        game,
        "_MARS_SAFARI_RANGER_AFTER_LIE",
        done
      )
      return
    end

    if not flags[FLAGS.started] then
      startSafariInvestigation(game, done)
      return
    end

    if not flags[FLAGS.found] then
      safariSay(
        game,
        "_MARS_SAFARI_RANGER_SEARCH",
        done
      )
      return
    end

    rangerDecision(game, ow, done)
  end

  ---------------------------------------------------------------------------
  -- ACTIVIST IN SAFARI ZONE EAST
  ---------------------------------------------------------------------------

  local function activistEastTalk(game, ow, npc, done)
    local flags = game.save.flags or {}
    faceSafariNpc(ow, npc)

    if not flags[FLAGS.started]
       or flags[FLAGS.resolved]
    then
      if done then done() end
      return
    end

    if flags[FLAGS.found] then
      safariSay(
        game,
        "_MARS_SAFARI_ACTIVIST_REPEAT",
        done
      )
      return
    end

    flags[FLAGS.found] = true

    safariSay(
      game,
      "_MARS_SAFARI_ACTIVIST_DISCOVERY",
      done
    )
  end

  ---------------------------------------------------------------------------
  -- ACTIVIST REWARD IN FUCHSIA CITY
  ---------------------------------------------------------------------------

  local function activistCityTalk(game, ow, npc, done)
    local flags = game.save.flags or {}
    faceSafariNpc(ow, npc)

    if not flags[FLAGS.protected] then
      if done then done() end
      return
    end

    if flags[FLAGS.tmReceived] then
      safariSay(
        game,
        "_MARS_SAFARI_ACTIVIST_CITY_AFTER",
        done
      )
      return
    end

    safariSay(
      game,
      "_MARS_SAFARI_ACTIVIST_CITY_REWARD",
      function()
        local Bag = require("src.inventory.Bag")

        if not Bag.add(
          game.save,
          "TM54",
          1,
          game.data
        ) then
          safariSay(
            game,
            "_MARS_SAFARI_ACTIVIST_TM_FULL",
            done
          )
          return
        end

        flags[FLAGS.tmReceived] = true

        local Sound = require("src.core.Sound")
        Sound.play(game.data, "Get_Item1")

        safariSay(
          game,
          "_MARS_SAFARI_ACTIVIST_GOT_TM",
          done
        )
      end
    )
  end

