          },
        },
      },
    })

    mod.content.map_scripts:register("SAFARI_ZONE_EAST", {
      priority = 185,

      onEnter = function(game, ow)
        local flags = game.save.flags or {}

        if flags[FLAGS.started]
           and not flags[FLAGS.resolved]
        then
          ow:queueScript({
            {
