              "SAFARI_ZONE_EAST",
              "MARS_SAFARI_ACTIVIST_EAST",
            },
          })
        end
      end,

      talk = {
        [TEXT_ACTIVIST_EAST] = activistEastTalk,
      },
    })

    mod.content.map_scripts:register("FUCHSIA_CITY", {
      priority = 185,

      onEnter = function(game, ow)
        local flags = game.save.flags or {}

        if flags[FLAGS.protected] then
          ow:queueScript({
