              "FUCHSIA_CITY",
              "MARS_SAFARI_ACTIVIST_CITY",
            },
          })
        end
      end,

      talk = {
        [TEXT_ACTIVIST_CITY] = activistCityTalk,
      },
    })
  end

  mod.log:info(
