  ---------------------------------------------------------------------------
  -- MOOMOO MILK
  --
  -- Later-generation behavior: restores 100 HP. The farm seller stocks only
  -- this specialty item for ¥500.
  ---------------------------------------------------------------------------

  mod.content.item_effects:register("MARS_MOOMOO_MILK_HEAL", {
    field = true,
    battle = true,
    needsTarget = true,

    use = function(ctx)
      local target = ctx and ctx.target
      local data = ctx and ctx.data

      if not target
         or not target.stats
         or target.hp == nil
         or target.hp <= 0
         or target.hp >= (target.stats.hp or 0)
      then
        return "failed", { "It won't have\nany effect." }
      end

      local before = target.hp
      target.hp = math.min(target.stats.hp, target.hp + 100)

      local Sound = require("src.core.Sound")
      pcall(Sound.play, data, "Heal_HP")

      local name = target.nickname
      if not name and data and data.pokemon and data.pokemon[target.species] then
        name = data.pokemon[target.species].name
      end
      name = name or "POKEMON"

      return "consumed",
        { tostring(name) .. "'s HP\nwas restored!" },
        { healedFrom = before }
    end,
  })

  mod.content.items:register("MOOMOO_MILK", {
