    connections = {
      east = { map = "PALLET_FARMS", offset = 4.5 },
    },
  })

  ---------------------------------------------------------------------------
  -- PALLET FARMS MAP GEOMETRY
  ---------------------------------------------------------------------------

  local route1Def = mod.content.maps:get("ROUTE_1")
  local overworldTileset = mod.content.tilesets:get("OVERWORLD")
  local farmBorder = route1Def and route1Def.borderBlock or 11

  local farmProbe = {
    id = "PALLET_FARMS",
    tileset = "OVERWORLD",
    width = 16,
    height = 16,
    borderBlock = farmBorder,
    blocks = palletFarmsBlocks,
  }

  local usedFarmCells = {}

  local function farmCellKey(x, y)
    return tostring(x) .. ":" .. tostring(y)
  end

  local function reserveFarmCell(x, y)
    usedFarmCells[farmCellKey(x, y)] = true
    return x, y
  end

  local function farmIsLand(x, y)
    return overworldTileset
      and MapDef.defIsWalkableCell(farmProbe, overworldTileset, x, y)
      and not MapDef.defIsWaterCell(farmProbe, overworldTileset, x, y)
  end

  local function farmNearestLand(preferredX, preferredY, radius)
    radius = radius or 10

    for r = 0, radius do
      for dy = -r, r do
        for dx = -r, r do
          if r == 0 or math.max(math.abs(dx), math.abs(dy)) == r then
            local x = preferredX + dx
            local y = preferredY + dy
            local key = farmCellKey(x, y)

            if x >= 0 and y >= 0
               and x < farmProbe.width * 2
               and y < farmProbe.height * 2
               and not usedFarmCells[key]
               and farmIsLand(x, y)
            then
              return reserveFarmCell(x, y)
            end
          end
        end
      end
    end

    return reserveFarmCell(preferredX, preferredY)
  end

  local function farmTileIn(list, tile)
    for _, value in ipairs(list or {}) do
      if value == tile then return true end
    end
    return false
  end

  local function farmNearestDoor(preferredX, preferredY)
    if overworldTileset then
      for r = 0, 10 do
        for dy = -r, r do
          for dx = -r, r do
            if r == 0 or math.max(math.abs(dx), math.abs(dy)) == r then
              local x = preferredX + dx
              local y = preferredY + dy

              if x >= 0 and y >= 0
                 and x < farmProbe.width * 2
                 and y < farmProbe.height * 2
              then
                local tile = MapDef.defCellTile(
                  farmProbe,
                  overworldTileset,
                  x,
                  y
                )

                if farmTileIn(overworldTileset.doorTiles, tile) then
                  return x, y
                end
              end
            end
          end
        end
      end
    end

    -- Center-bottom of the small farmhouse in the supplied TMJ.
    return 13, 11
  end

  local houseDoorX, houseDoorY = farmNearestDoor(13, 11)
  reserveFarmCell(houseDoorX, houseDoorY)

  -- Entrance worker. The user's west opening is centered around y=13.
  local gateX, gateY = farmNearestLand(4, 13, 8)
  local gateOpenX, gateOpenY = farmNearestLand(7, 11, 8)

  -- Three additional ordinary outdoor NPCs.
  local farmhandX, farmhandY = farmNearestLand(10, 18, 10)
  local pondGirlX, pondGirlY = farmNearestLand(21, 9, 10)
  local visitorX, visitorY = farmNearestLand(23, 23, 10)

  -- Reserved future side-quest giver. No quest marker is shown until an
  -- actual quest is attached to this NPC.
  local questGiverX, questGiverY = farmNearestLand(16, 25, 10)

  -- Overworld Miltank herd.
  local miltank1X, miltank1Y = farmNearestLand(11, 20, 10)
  local miltank2X, miltank2Y = farmNearestLand(18, 21, 10)
  local miltank3X, miltank3Y = farmNearestLand(24, 18, 10)

  ---------------------------------------------------------------------------
  -- Find the authored sign near the entrance by matching Route 1's native
  -- sign collision tile. If the map art changes later, this remains much more
  -- robust than hardcoding a random cell.
  ---------------------------------------------------------------------------

  local signX, signY = 5, 15

  if route1Def and overworldTileset then
    local route1SignTile = MapDef.defCellTile(
      route1Def,
      overworldTileset,
      9,
      27
    )

    local bestDist = nil

    if route1SignTile ~= nil then
      for y = 0, farmProbe.height * 2 - 1 do
        for x = 0, farmProbe.width * 2 - 1 do
          local tile = MapDef.defCellTile(
            farmProbe,
            overworldTileset,
            x,
            y
          )

          if tile == route1SignTile then
            local dist = math.abs(x - 5) + math.abs(y - 14)
            if not bestDist or dist < bestDist then
              signX, signY = x, y
              bestDist = dist
            end
          end
        end
      end
    end
  end

