        mart = { "MOOMOO_MILK" },
      },
    })
  end

  ---------------------------------------------------------------------------
  -- CASCADE BADGE GATE
  ---------------------------------------------------------------------------

  local function palletFarmsHasCascadeBadge(game)
    local Badges = require("src.inventory.Badges")
    local badges = Badges.list(game.data)
    local cascade = badges and badges[2]
    if not cascade then return false end

    local itemId = Badges.itemFor(cascade)
    return game.save.inventory
      and game.save.inventory[itemId]
      and true
      or false
  end

  local function palletFarmsSay(game, text, done)
    local TextBox = require("src.render.TextBox")
    game.stack:push(TextBox.new(game, text, done))
  end

  local function palletFarmsGateTalk(game, ow, npc, done)
    if npc and npc.facePlayer and ow and ow.player then
      npc:facePlayer(ow.player)
    end

    if palletFarmsHasCascadeBadge(game) then
      palletFarmsSay(
        game,
        "PALLET FARMS is open\nto visitors again!\f"
          .. "Feel free to look\naround.",
        done
      )
    else
      palletFarmsSay(
        game,
        "Sorry, but PALLET\nFARMS is not currently\ntaking visitors.\f"
          .. "Come back another\ntime.",
        done
      )
    end
  end

  local function palletFarmsPlaceGatekeeper(game, ow)
    if not ow then return end

    local Commands = require("src.script.Commands")
    local open = palletFarmsHasCascadeBadge(game)

    Commands.place_npc(
      {
        game = game,
        save = game.save,
        overworld = ow,
      },
      1,
      open and gateOpenX or gateX,
      open and gateOpenY or gateY,
      open and "down" or "right"
    )
  end

  if mod.content.map_scripts then
    mod.content.map_scripts:register("PALLET_FARMS", {
      priority = 138,

      onEnter = function(game, ow)
        palletFarmsPlaceGatekeeper(game, ow)
      end,

      -- The NPC itself is the visible blocker. This narrow entrance guard is
      -- an extra fail-safe so a player cannot slip around him before Misty.
      onStep = function(game, ow, x, y)
        if palletFarmsHasCascadeBadge(game) then
          return false
        end

        if x == gateX + 1
           and math.abs(y - gateY) <= 3
        then
          ow:queueScript({
            { "show_text", "_MARS_PALLET_FARMS_CLOSED" },
            { "move_player", "left", 1 },
          })
          return true
        end

        return false
      end,

      talk = {
        TEXT_PALLET_FARMS_GATEKEEPER = palletFarmsGateTalk,
      },
    })

    mod.content.map_scripts:register("PALLET_FARMS_HOUSE", {
      priority = 138,
      talk = {
        TEXT_PALLET_FARMS_MILK_SELLER = {
          { "face_player" },
          { "show_text", "_MARS_PALLET_FARMS_MILK_SELLER" },
          { "open_mart", "TEXT_PALLET_FARMS_MILK_SELLER" },
        },
      },
    })
  end

  ---------------------------------------------------------------------------
  -- MUSIC
  ---------------------------------------------------------------------------

  local farmSong = mod.content.map_songs:get("ROUTE_1")
  if farmSong then
    mod.content.map_songs:register("PALLET_FARMS", farmSong)
  end

  local houseSong = mod.content.map_songs:get("REDS_HOUSE_1F")
  if houseSong then
    mod.content.map_songs:register("PALLET_FARMS_HOUSE", houseSong)
  end

  mod.log:info(
    "Pallet Farms installed: one-cell seam alignment, Cascade Badge gate, "
      .. "Miltank habitat, pond encounters, farmhouse, and MOOMOO MILK seller"
  )
  end)()


  ;(function()
  ---------------------------------------------------------------------------
  -- PALLET FARMS — ORNERY TAUROS SIDE QUEST
  --
  -- Stage 1: Pallet Farms barn
  -- Stage 2: Route 1
  -- Stage 3: Pallet Town, in front of Oak's Lab
  --
  -- Tauros uses trainer-style battles so the quest Tauros cannot be caught
  -- during the chase. The same animal grows more difficult as it becomes
  -- increasingly worked up.
  ---------------------------------------------------------------------------

  local MapDef = require("src.world.Map")

  local FLAGS = {
    started = "EVENT_PALLET_TAUROS_QUEST_STARTED",
    farmBeat = "EVENT_PALLET_TAUROS_FARM_BEAT",
    route1Beat = "EVENT_PALLET_TAUROS_ROUTE1_BEAT",
    subdued = "EVENT_PALLET_TAUROS_SUBDUED",
    rewardReady = "EVENT_PALLET_TAUROS_REWARD_READY",
    complete = "EVENT_PALLET_TAUROS_QUEST_COMPLETE",
  }

  local TEXT_FARM_TAUROS =
    "TEXT_PALLET_FARMS_ORNERY_TAUROS"
  local TEXT_ROUTE1_TAUROS =
    "TEXT_ROUTE1_ORNERY_TAUROS"
  local TEXT_ROUTE1_HANDLER =
    "TEXT_ROUTE1_TAUROS_HANDLER"
  local TEXT_PALLET_TAUROS =
    "TEXT_PALLET_TOWN_ORNERY_TAUROS"
  local TEXT_PALLET_HANDLER =
    "TEXT_PALLET_TOWN_TAUROS_HANDLER"

  ---------------------------------------------------------------------------
  -- POSITION HELPERS
  ---------------------------------------------------------------------------

  local function questTilesetFor(def)
    return def and mod.content.tilesets:get(def.tileset) or nil
  end

  local function questIsLand(def, tileset, x, y)
    return def
      and tileset
      and x >= 0
      and y >= 0
      and x < def.width * 2
      and y < def.height * 2
      and MapDef.defIsWalkableCell(def, tileset, x, y)
      and not MapDef.defIsWaterCell(def, tileset, x, y)
  end

  local function questNearestLand(
    def,
    tileset,
    preferredX,
    preferredY,
    used,
    radius
  )
    used = used or {}
    radius = radius or 10

    for r = 0, radius do
      for dy = -r, r do
        for dx = -r, r do
          if r == 0
             or math.max(math.abs(dx), math.abs(dy)) == r
          then
            local x = preferredX + dx
            local y = preferredY + dy
            local key = tostring(x) .. ":" .. tostring(y)

            if not used[key]
               and questIsLand(def, tileset, x, y)
            then
              used[key] = true
              return x, y
            end
          end
        end
      end
    end

    return preferredX, preferredY
  end

  local farmDef = mod.content.maps:get("PALLET_FARMS")
  local route1Def = mod.content.maps:get("ROUTE_1")
  local palletDef = mod.content.maps:get("PALLET_TOWN")

  local farmTileset = questTilesetFor(farmDef)
  local route1Tileset = questTilesetFor(route1Def)
  local palletTileset = questTilesetFor(palletDef)

  ---------------------------------------------------------------------------
  -- FARM: the large barn is the 3-block-wide authored structure centered at
  -- Tiled block columns 5-7 / rows 4-5. The smaller 2x2 structure farther
  -- east is the one beside the pond and is NOT the barn.
  --
  -- Each Tiled block is two player movement cells, so the barn frontage is
  -- centered around movement x=12-13 with its south edge at y=11. Put Tauros
  -- on the first walkable cell directly in front of that center frontage.
  ---------------------------------------------------------------------------

  local farmUsed = {}
  local farmTaurosX, farmTaurosY = questNearestLand(
    farmDef,
    farmTileset,
    12,
    12,
    farmUsed,
    4
  )

  ---------------------------------------------------------------------------
  -- ROUTE 1: stage Tauros near the farm-side/eastern edge, lined up to the
  -- Pallet Farms gate using the current +4.5 connection (9 walking cells).
  ---------------------------------------------------------------------------

  local farmGateY = 13
  for _, obj in ipairs(farmDef and farmDef.objects or {}) do
    if obj.name == "PALLET_FARMS_GATEKEEPER" then
      farmGateY = obj.y
      break
    end
  end

  local route1Used = {}
  local route1TaurosX, route1TaurosY = questNearestLand(
    route1Def,
    route1Tileset,
    (route1Def and route1Def.width * 2 - 3) or 17,
    farmGateY + 9,
    route1Used,
    10
  )

  ---------------------------------------------------------------------------
  -- PALLET TOWN: derive Oak's Lab's actual authored doorway from its warp.
  -- Tauros stands two cells in front of the Lab rather than using a guessed
  -- Pallet Town coordinate.
  ---------------------------------------------------------------------------

  local oakDoorX, oakDoorY = 10, 8

  for _, warp in ipairs(palletDef and palletDef.warps or {}) do
    if warp.destMap == "OAKS_LAB" then
      oakDoorX, oakDoorY = warp.x, warp.y
      break
    end
  end

  local palletUsed = {}
  local palletTaurosX, palletTaurosY = questNearestLand(
    palletDef,
    palletTileset,
    oakDoorX,
    oakDoorY + 2,
    palletUsed,
    10
  )

  ---------------------------------------------------------------------------
  -- QUEST OBJECTS
  ---------------------------------------------------------------------------

  mod.content.maps:patch("PALLET_FARMS", {
    objects = {
      __append = {
        {
          index = 9,
          name = "PALLET_FARMS_ORNERY_TAUROS",
          sprite = "SPRITE_MONSTER",
          movement = "STAY",
          range = "DOWN",
          x = farmTaurosX,
          y = farmTaurosY,
          text = TEXT_FARM_TAUROS,
        },
      },
    },
  })

  mod.content.maps:patch("ROUTE_1", {
    objects = {
      __append = {
        {
          index = 90,
          name = "ROUTE1_ORNERY_TAUROS",
          sprite = "SPRITE_MONSTER",
          movement = "STAY",
          range = "DOWN",
          x = route1TaurosX,
          y = route1TaurosY,
          text = TEXT_ROUTE1_TAUROS,
        },
        {
          index = 91,
          name = "ROUTE1_TAUROS_HANDLER",
          sprite = "SPRITE_MIDDLE_AGED_WOMAN",
          movement = "STAY",
          range = "DOWN",
          x = math.max(1, route1TaurosX - 2),
          y = route1TaurosY,
          text = TEXT_ROUTE1_HANDLER,
        },
      },
    },
  })

  mod.content.maps:patch("PALLET_TOWN", {
    objects = {
      __append = {
        {
          index = 90,
          name = "PALLET_TOWN_ORNERY_TAUROS",
          sprite = "SPRITE_MONSTER",
          movement = "STAY",
          range = "DOWN",
          x = palletTaurosX,
          y = palletTaurosY,
          text = TEXT_PALLET_TAUROS,
        },
        {
          index = 91,
          name = "PALLET_TOWN_TAUROS_HANDLER",
          sprite = "SPRITE_MIDDLE_AGED_WOMAN",
          movement = "STAY",
          range = "DOWN",
          x = math.max(1, palletTaurosX - 2),
          y = palletTaurosY,
          text = TEXT_PALLET_HANDLER,
        },
      },
    },
  })

  ---------------------------------------------------------------------------
  -- THREE ESCALATING TAUROS BATTLES
  ---------------------------------------------------------------------------

  local taurosDef = mod.content.pokemon:get("TAUROS")

  mod.content.trainers:register("OPP_PALLET_TAUROS", {
    id = "OPP_PALLET_TAUROS",
    name = "TAUROS",
    basePic = "OPP_TAMER",
    pic = taurosDef and taurosDef.spriteFront,
    baseMoney = 0,
    aiClass = (mod.content.trainers:get("OPP_TAMER") or {}).aiClass,
    aiMods = (mod.content.trainers:get("OPP_TAMER") or {}).aiMods,
    parties = {
      {
        { level = 20, species = "TAUROS" },
      },
      {
        { level = 22, species = "TAUROS" },
      },
      {
        { level = 24, species = "TAUROS" },
      },
    },
  })

  ---------------------------------------------------------------------------
  -- DIALOGUE
  ---------------------------------------------------------------------------

  mod.content.text:register(
    "_MARS_PALLET_TAUROS_QUEST_START",
    "We've got a problem.\f"
      .. "There's an ornery\nTAUROS that keeps\nattacking our MILTANK.\f"
      .. "Every time it starts\ntrouble, our dairy\nproduction gets ruined.\f"
      .. "Could you calm it\ndown for us?\f"
      .. "You'll find TAUROS\nin front of the barn."
  )

  mod.content.text:register(
    "_MARS_PALLET_TAUROS_FARM_REMINDER",
    "That ornery TAUROS\nshould be in front\nof the barn.\f"
      .. "Please calm it down\nbefore it scares the\nMILTANK again."
  )

  mod.content.text:register(
    "_MARS_PALLET_TAUROS_FARM_ATTACK",
    "TAUROS paws angrily\nat the ground...\f"
      .. "It charges!"
  )

  mod.content.text:register(
    "_MARS_PALLET_TAUROS_FARM_FLEE",
    "TAUROS lets out an\nangry bellow!\f"
      .. "It bolts away toward\nROUTE 1!"
  )

  mod.content.text:register(
    "_MARS_PALLET_TAUROS_ROUTE1_REMINDER",
    "TAUROS fled toward\nROUTE 1!\f"
      .. "Please don't let it\nget any farther."
  )

  mod.content.text:register(
    "_MARS_PALLET_TAUROS_ROUTE1_ATTACK",
    "TAUROS sees you and\nsnorts angrily!\f"
      .. "It charges again!"
  )

  mod.content.text:register(
    "_MARS_PALLET_TAUROS_ROUTE1_FLEE",
    "TAUROS staggers...\f"
      .. "Then it bolts south\ntoward PALLET TOWN!"
  )

  mod.content.text:register(
    "_MARS_PALLET_TAUROS_HANDLER_WARNING",
    "There you are!\f"
      .. "TAUROS is heading\nstraight for\nPALLET TOWN!\f"
      .. "Please subdue it\nbefore it causes any\ndamage to the town!"
  )

  mod.content.text:register(
    "_MARS_PALLET_TAUROS_HANDLER_HURRY",
    "Hurry!\f"
      .. "TAUROS is heading\nfor PALLET TOWN!"
  )

  mod.content.text:register(
    "_MARS_PALLET_TAUROS_TOWN_ATTACK",
    "TAUROS is raging in\nfront of OAK'S LAB!\f"
      .. "It lowers its head\nand charges one last\ntime!"
  )

  mod.content.text:register(
    "_MARS_PALLET_TAUROS_EXHAUSTED",
    "TAUROS tries to stand\nits ground...\f"
      .. "But it's completely\nexhausted."
  )

  mod.content.text:register(
    "_MARS_PALLET_TAUROS_RECALL",
    "Easy, TAUROS...\nThat's enough.\f"
      .. "The farmer returns\nTAUROS to its\nPOKE BALL."
  )

  mod.content.text:register(
    "_MARS_PALLET_TAUROS_APOLOGY",
    "I'm sorry about all\nof this.\f"
      .. "This is the first\ntime things have gotten\nthis out of hand with\nTAUROS.\f"
      .. "Meet me back at\nPALLET FARMS.\f"
      .. "I owe you a reward."
  )

  mod.content.text:register(
    "_MARS_PALLET_TAUROS_TOWN_HANDLER_AFTER",
    "I'll meet you back\nat PALLET FARMS.\f"
      .. "I still owe you for\nall your help."
  )

  mod.content.text:register(
    "_MARS_PALLET_TAUROS_REWARD",
    "You really saved us\na lot of trouble.\f"
      .. "The MILTANK are calm\nand dairy production\nis back to normal.\f"
      .. "Here. You earned this!\f"
      .. "You received a\nNUGGET and 3 bottles\nof MOOMOO MILK!"
  )

  mod.content.text:register(
    "_MARS_PALLET_TAUROS_REWARD_FULL",
    "I still have your\nreward ready.\f"
      .. "Make some room in\nyour BAG and come\nback to me."
  )

  mod.content.text:register(
    "_MARS_PALLET_TAUROS_COMPLETE",
    "TAUROS has settled\ndown again.\f"
      .. "The MILTANK are a\nlot happier now.\f"
      .. "Thanks again!"
  )

  ---------------------------------------------------------------------------
  -- COMMON HELPERS
  ---------------------------------------------------------------------------

  local function taurosSay(game, textId, done)
    local TextBox = require("src.render.TextBox")
    local text = game.data.text[textId] or textId
    game.stack:push(TextBox.new(game, text, done))
  end

  local taurosCutsceneCallbacks =
    setmetatable({}, { __mode = "k" })

  mod.commands:register("mars_tauros_cutscene_done", function(ctx)
    local callback = taurosCutsceneCallbacks[ctx.game]
    taurosCutsceneCallbacks[ctx.game] = nil

    if callback then
      callback()
    end
  end)

  local function queueTaurosCutscene(game, ow, rows, callback)
    taurosCutsceneCallbacks[game] = callback

    rows[#rows + 1] = {
      "mars_tauros_cutscene_done"
    }

    ow:queueScript(rows)
  end

  local function faceQuestNpc(ow, npc)
    if npc and npc.facePlayer and ow and ow.player then
      npc:facePlayer(ow.player)
    end
  end

  local function giveTaurosReward(game, done)
    local flags = game.save.flags or {}
    local Bag = require("src.inventory.Bag")

    if not Bag.add(
      game.save,
      "NUGGET",
      1,
      game.data
    ) then
      taurosSay(
        game,
        "_MARS_PALLET_TAUROS_REWARD_FULL",
        done
      )
      return
    end

    if not Bag.add(
      game.save,
      "MOOMOO_MILK",
      3,
      game.data
    ) then
      -- Roll back the Nugget so a failed reward attempt is atomic.
      Bag.remove(game.save, "NUGGET", 1)

      taurosSay(
        game,
        "_MARS_PALLET_TAUROS_REWARD_FULL",
        done
      )
      return
    end

    flags[FLAGS.complete] = true

    local Sound = require("src.core.Sound")
    Sound.play(game.data, "Get_Item1")

    taurosSay(
      game,
      "_MARS_PALLET_TAUROS_REWARD",
      done
    )
  end

  ---------------------------------------------------------------------------
  -- FARM QUEST GIVER
  ---------------------------------------------------------------------------

  local function palletTaurosQuestTalk(game, ow, npc, done)
    local flags = game.save.flags or {}
    faceQuestNpc(ow, npc)

    if flags[FLAGS.complete] then
      taurosSay(
        game,
        "_MARS_PALLET_TAUROS_COMPLETE",
        done
      )
      return
    end

    if flags[FLAGS.rewardReady] then
      giveTaurosReward(game, done)
      return
    end

    if not flags[FLAGS.started] then
      flags[FLAGS.started] = true

      taurosSay(
        game,
        "_MARS_PALLET_TAUROS_QUEST_START",
        function()
          -- PALLET_FARMS onEnter hides the quest Tauros before the quest
          -- exists. Starting the quest happens without reloading the map, so
          -- explicitly reveal the already-registered overworld Tauros now.
          ow:queueScript({
            {
              "show_object",
              "PALLET_FARMS",
              "PALLET_FARMS_ORNERY_TAUROS",
            },
          })

          if done then done() end
        end
      )
      return
    end

    if not flags[FLAGS.farmBeat] then
      taurosSay(
        game,
        "_MARS_PALLET_TAUROS_FARM_REMINDER",
        done
      )
      return
    end

    if not flags[FLAGS.route1Beat] then
      taurosSay(
        game,
        "_MARS_PALLET_TAUROS_ROUTE1_REMINDER",
        done
      )
      return
    end

    -- The farmer has followed the chase away from Pallet Farms during this
    -- stage, so this is only a defensive fallback.
    taurosSay(
      game,
      "_MARS_PALLET_TAUROS_HANDLER_HURRY",
      done
    )
  end

  ---------------------------------------------------------------------------
  -- BATTLE LAUNCHER
  ---------------------------------------------------------------------------

  local function startTaurosBattle(
    game,
    ow,
    done,
    partyIndex,
    attackText,
    onWin
  )
    local BattleState = require("src.battle.BattleState")

    taurosSay(
      game,
      attackText,
      function()
        local battle = BattleState.newTrainer(
          game,
          "OPP_PALLET_TAUROS",
          partyIndex
        )

        battle.endBattleText =
          "TAUROS was subdued!"

        battle.onFinish = function(result)
          if result ~= "win" then
            if done then done() end
            ow:afterBattle(result, battle)
            return
          end

          onWin(
            battle,
            function()
              if done then done() end
              ow:afterBattle("win", battle)
            end
          )
        end

        ow:pushBattle(battle)
      end
    )
  end

  ---------------------------------------------------------------------------
  -- STAGE 1 — PALLET FARMS BARN
  ---------------------------------------------------------------------------

  local function farmTaurosTalk(game, ow, npc, done)
    local flags = game.save.flags or {}

    if not flags[FLAGS.started]
       or flags[FLAGS.farmBeat]
    then
      if done then done() end
      return
    end

    startTaurosBattle(
      game,
      ow,
      done,
      1,
      "_MARS_PALLET_TAUROS_FARM_ATTACK",
      function(battle, finishBattle)
        flags[FLAGS.farmBeat] = true

        queueTaurosCutscene(
          game,
          ow,
          {
            { "fade", "out", 20 },
            { "wait", 30 },
            {
              "hide_object",
              "PALLET_FARMS",
              "PALLET_FARMS_ORNERY_TAUROS",
            },
            { "fade", "in", 20 },
            {
              "show_text",
              "_MARS_PALLET_TAUROS_FARM_FLEE",
            },
          },
          finishBattle
        )
      end
    )
  end

  ---------------------------------------------------------------------------
  -- STAGE 2 — ROUTE 1
  ---------------------------------------------------------------------------

  local function route1TaurosTalk(game, ow, npc, done)
    local flags = game.save.flags or {}

    if not flags[FLAGS.farmBeat]
       or flags[FLAGS.route1Beat]
    then
      if done then done() end
      return
    end

    startTaurosBattle(
      game,
      ow,
      done,
      2,
      "_MARS_PALLET_TAUROS_ROUTE1_ATTACK",
      function(battle, finishBattle)
        flags[FLAGS.route1Beat] = true

        local player = ow and ow.player
        local handlerX =
          player and (player.cellX + 1) or route1TaurosX
        local handlerY =
          player and player.cellY or route1TaurosY

        -- the farmer should not pop directly into the final position.
        -- Start several cells farther to the RIGHT, then visibly walk LEFT
        -- until they are exactly one tile to the player's right.
        local handlerStartX = handlerX + 3

        if ow and ow.map then
          while handlerStartX > handlerX
             and not (
               ow.map:inBounds(handlerStartX, handlerY)
               and ow.map:isWalkableCell(handlerStartX, handlerY)
             )
          do
            handlerStartX = handlerStartX - 1
          end
        end

        local rows = {
          { "fade", "out", 20 },
          { "wait", 30 },
          {
            "hide_object",
            "ROUTE_1",
            "ROUTE1_ORNERY_TAUROS",
          },

          -- show_object creates the runtime NPC from its authored object
          -- coordinates. Therefore it MUST happen before place_npc.
          {
            "show_object",
            "ROUTE_1",
            "ROUTE1_TAUROS_HANDLER",
          },
          {
            "place_npc",
            91,
            handlerStartX,
            handlerY,
            "left",
          },
          { "fade", "in", 20 },
          {
            "show_text",
            "_MARS_PALLET_TAUROS_ROUTE1_FLEE",
          },
        }

        if handlerStartX ~= handlerX then
          rows[#rows + 1] = {
            "move_npc_to",
            91,
            handlerX,
            handlerY,
          }
        end

        rows[#rows + 1] = {
          "face_object",
          91,
          "left",
        }

        rows[#rows + 1] = {
          "show_text",
          "_MARS_PALLET_TAUROS_HANDLER_WARNING",
        }

        queueTaurosCutscene(
          game,
          ow,
          rows,
          finishBattle
        )
      end
    )
  end

  local function route1HandlerTalk(game, ow, npc, done)
    faceQuestNpc(ow, npc)
    taurosSay(
      game,
      "_MARS_PALLET_TAUROS_HANDLER_HURRY",
      done
    )
  end

  ---------------------------------------------------------------------------
  -- STAGE 3 — PALLET TOWN / OAK'S LAB
  ---------------------------------------------------------------------------

  local function palletTownTaurosTalk(game, ow, npc, done)
    local flags = game.save.flags or {}

    if not flags[FLAGS.route1Beat]
       or flags[FLAGS.subdued]
    then
      if done then done() end
      return
    end

    startTaurosBattle(
      game,
      ow,
      done,
      3,
      "_MARS_PALLET_TAUROS_TOWN_ATTACK",
      function(battle, finishBattle)
        flags[FLAGS.subdued] = true
        flags[FLAGS.rewardReady] = true

        local player = ow and ow.player
        local playerX =
          player and player.cellX or palletTaurosX
        local playerY =
          player and player.cellY or (palletTaurosY + 1)

        -- Tauros occupies the cell immediately to the player's RIGHT
        -- in this scene. Put the farmer one tile to the player's LEFT instead
        -- so the final staging is:
        --
        --   FARMER  PLAYER  TAUROS
        --
        -- The farmer still enters vertically from the north.
        local targetX = playerX - 1
        local targetY = playerY
        local startX = targetX
        local startY = math.max(1, targetY - 5)

        -- If the ideal north-side start falls on terrain the NPC cannot use,
        -- move downward until we find the first valid cell on that column.
        if ow and ow.map then
          while startY < targetY
             and not (
               ow.map:inBounds(startX, startY)
               and ow.map:isWalkableCell(startX, startY)
             )
          do
            startY = startY + 1
          end
        end

        local rows = {
          {
            "show_text",
            "_MARS_PALLET_TAUROS_EXHAUSTED",
          },

          -- Spawn the hidden object first. show_object constructs a fresh
          -- runtime NPC at its authored coordinates, so placement must follow.
          {
            "show_object",
            "PALLET_TOWN",
            "PALLET_TOWN_TAUROS_HANDLER",
          },
          {
            "place_npc",
            91,
            startX,
            startY,
            "down",
          },
        }

        if startY ~= targetY then
          rows[#rows + 1] = {
            "move_npc_to",
            91,
            targetX,
            targetY,
          }
        end

        rows[#rows + 1] = {
          "face_object",
          91,
          "right",
        }

        rows[#rows + 1] = {
          "show_text",
          "_MARS_PALLET_TAUROS_RECALL",
        }

        rows[#rows + 1] = {
          "hide_object",
          "PALLET_TOWN",
          "PALLET_TOWN_ORNERY_TAUROS",
        }

        rows[#rows + 1] = {
          "show_text",
          "_MARS_PALLET_TAUROS_APOLOGY",
        }

        -- The farmer is heading back to Pallet Farms. Hide that departure
        -- cleanly rather than leaving them standing beside Oak's Lab.
        rows[#rows + 1] = { "fade", "out", 20 }
        rows[#rows + 1] = { "wait", 30 }
        rows[#rows + 1] = {
          "hide_object",
          "PALLET_TOWN",
          "PALLET_TOWN_TAUROS_HANDLER",
        }
        rows[#rows + 1] = { "fade", "in", 20 }

        queueTaurosCutscene(
          game,
          ow,
          rows,
          finishBattle
        )
      end
    )
  end

  local function palletTownHandlerTalk(game, ow, npc, done)
    faceQuestNpc(ow, npc)
    taurosSay(
      game,
      "_MARS_PALLET_TAUROS_TOWN_HANDLER_AFTER",
      done
    )
  end

