  -- Runtime safety net. game.ready fires after every registry has been merged
  -- into game.data but before the overworld is pushed, so this writes the
  -- authored Route 25 directly into the exact table MapLoader reads.
  mod.events:on("game.ready", function(event)
    local game = event and event.game
    local def = game and game.data and game.data.maps
      and game.data.maps["ROUTE_25"]
    if not def then
      mod.log:error("ROUTE_25 missing from game.data at game.ready")
      return
    end

    def.blocks = copyTable(route25AuthoredBlocks)
    def.connections = def.connections or {}
    def.connections.north = { map = "ROUTE_26", offset = 21 }

    mod.log:info(
      "game.ready forced ROUTE_25 terrain: blocks[26..28]=%s,%s,%s",
      tostring(def.blocks[26]), tostring(def.blocks[27]), tostring(def.blocks[28])
    )
  end)

  -- Second safety net for an already-built/current Route 25 instance.
  -- map.entered fires after MapLoader has produced the runtime Map; rewrite
  -- that live def too and drop the renderer's cached tile window.
  mod.events:on("map.entered", function(event)
    if not event or event.mapId ~= "ROUTE_25" or not event.map then return end

    local map = event.map
    map.def.blocks = copyTable(route25AuthoredBlocks)
    map.def.connections = map.def.connections or {}
    map.def.connections.north = { map = "ROUTE_26", offset = 21 }

    if map.renderer and map.renderer.rebuild then
      map.renderer:rebuild()
    end

    mod.log:info(
      "map.entered forced live ROUTE_25 terrain: blocks[26..28]=%s,%s,%s",
      tostring(map.def.blocks[26]), tostring(map.def.blocks[27]),
      tostring(map.def.blocks[28])
