  ;(function()
  ---------------------------------------------------------------------------
  -- "FALSE FLAG"
  --
  -- Reworks the vanilla undercover International Police / Global Police NPC
  -- aboard the S.S. Anne into a deduction side quest. The bow already has
  -- exactly five NPCs, so those five become the suspects rather than adding a
  -- second crowd on top of the vanilla one.
  --
  -- Suspect #4 is the Rocket operative. His claim that he paid a 5000-dollar
  -- admission fee is impossible because passengers board with tickets.
  --
  -- CORRECT:
  --   accuse #4 -> disguise comes off -> Rocket battle -> officer arrests him
  --   -> TM55 TAUNT
  --
  -- WRONG:
  --   accuse #1/#2/#3/#5 -> innocent is arrested -> the real Rocket slips away
  --   -> accused NPC later appears in Saffron and explains that the S.S. Anne
  --      was sabotaged after departure and forced back to port; the officer was
  --      fired over the bad arrest. Either outcome still resolves the quest.
  ---------------------------------------------------------------------------

  local FLAGS = {
    started = "EVENT_SS_ANNE_INVESTIGATION_STARTED",
    verdictMade = "EVENT_SS_ANNE_INVESTIGATION_VERDICT_MADE",
    correct = "EVENT_SS_ANNE_CORRECT_SUSPECT",
    failed = "EVENT_SS_ANNE_INVESTIGATION_FAILED",
    revealed = "EVENT_SS_ANNE_ROCKET_REVEALED",
    caught = "EVENT_SS_ANNE_ROCKET_CAUGHT",
    tmReceived = "EVENT_SS_ANNE_TM55_RECEIVED",
    complete = "EVENT_SS_ANNE_INVESTIGATION_COMPLETE",
    resolved = "EVENT_SS_ANNE_INVESTIGATION_RESOLVED",
    heard1 = "EVENT_SS_ANNE_HEARD_SUSPECT_1",
    heard2 = "EVENT_SS_ANNE_HEARD_SUSPECT_2",
    heard3 = "EVENT_SS_ANNE_HEARD_SUSPECT_3",
    heard4 = "EVENT_SS_ANNE_HEARD_SUSPECT_4",
    heard5 = "EVENT_SS_ANNE_HEARD_SUSPECT_5",
    wrong1 = "EVENT_SS_ANNE_WRONG_SUSPECT_1",
    wrong2 = "EVENT_SS_ANNE_WRONG_SUSPECT_2",
    wrong3 = "EVENT_SS_ANNE_WRONG_SUSPECT_3",
    wrong4 = "EVENT_SS_ANNE_WRONG_SUSPECT_4",
    wrong5 = "EVENT_SS_ANNE_WRONG_SUSPECT_5",
  }

  local TEXT_OFFICER = "TEXT_SSANNE1FROOMS_GENTLEMAN3"
  local SUSPECT_TEXTS = {
    "TEXT_SSANNEBOW_SUPER_NERD",
    "TEXT_SSANNEBOW_SAILOR1",
    "TEXT_SSANNEBOW_COOLTRAINER_M",
    "TEXT_SSANNEBOW_SAILOR2",
    "TEXT_SSANNEBOW_SAILOR3",
  }
  local TEXT_ROCKET = "TEXT_MARS_SS_ANNE_ROCKET"
  local TEXT_ARREST_OFFICER = "TEXT_MARS_SS_ANNE_ARREST_OFFICER"
  local TEXT_SAFFRON_EPILOGUE = "TEXT_MARS_SS_ANNE_FAILED_ACCUSED"

  local roomsDef = mod.content.maps:get("SS_ANNE_1F_ROOMS")
  local bowDef = mod.content.maps:get("SS_ANNE_BOW")
  local saffronHouseDef = mod.content.maps:get("SAFFRON_PIDGEY_HOUSE")

  if not roomsDef or not bowDef or not saffronHouseDef then
    mod.log:error(
