  -- LOCATE AND NAME THE VANILLA OFFICER + FIVE BOW NPCs
  ---------------------------------------------------------------------------

  local officerDef = nil
  for _, obj in ipairs(roomsDef.objects or {}) do
    if obj.text == TEXT_OFFICER then
      officerDef = obj
      obj.name = "MARS_SS_ANNE_OFFICER"
      break
    end
  end

  if not officerDef then
    mod.log:error(
      "could not locate the vanilla International Police NPC"
