      return
    end
  end

  -- Only suspects #2 and #5 are members of the S.S. Anne crew. The vanilla
  -- fourth bow NPC uses a sailor sprite, but for this investigation he is an
  -- ordinary passenger whose disguise is hiding the Rocket uniform beneath it.
  suspects[4].sprite = "SPRITE_GENTLEMAN"

  ---------------------------------------------------------------------------
  -- SAFE PLACEMENT FOR THE REVEALED ROCKET, ARREST OFFICER, AND EPILOGUE NPC
  ---------------------------------------------------------------------------

  local MapDef = require("src.world.Map")

  local function questSpot(def, preferredX, preferredY, extraBlocked)
    local tileset = def and mod.content.tilesets:get(def.tileset) or nil
    local occupied = {}

    for _, obj in ipairs((def and def.objects) or {}) do
      occupied[tostring(obj.x) .. ":" .. tostring(obj.y)] = true
    end

    for _, pos in ipairs(extraBlocked or {}) do
      occupied[tostring(pos[1]) .. ":" .. tostring(pos[2])] = true
    end

    for radius = 0, 10 do
      for dy = -radius, radius do
        for dx = -radius, radius do
          if radius == 0
             or math.max(math.abs(dx), math.abs(dy)) == radius
          then
            local x = preferredX + dx
            local y = preferredY + dy
            local key = tostring(x) .. ":" .. tostring(y)

            if not occupied[key]
               and x >= 0
               and y >= 0
               and x < def.width * 2
               and y < def.height * 2
               and tileset
               and MapDef.defIsWalkableCell(def, tileset, x, y)
               and not MapDef.defIsWaterCell(def, tileset, x, y)
            then
              return x, y
            end
          end
        end
      end
    end

    return preferredX, preferredY
  end

  local suspect4 = suspects[4]

  -- The officer's normal investigation post belongs by the ship's wall, not
  -- shoulder-to-shoulder with the hidden Rocket. Find the nearest wall-adjacent
  -- walkable cell that is still at least three tiles from every suspect. This
  -- keeps the scene portable across Red/Blue map imports without pinning him to
  -- one fragile hardcoded coordinate.
  local function bowWallStandbySpot()
    local tileset = mod.content.tilesets:get(bowDef.tileset)
    local occupied = {}
    local centerX, centerY = 0, 0

    for _, obj in ipairs(bowDef.objects or {}) do
      occupied[tostring(obj.x) .. ":" .. tostring(obj.y)] = true
    end

    for i = 1, 5 do
      centerX = centerX + suspects[i].x
      centerY = centerY + suspects[i].y
    end
    centerX = centerX / 5
    centerY = centerY / 5

    local function terrainIsOpen(x, y)
      if not tileset
         or x < 0 or y < 0
         or x >= bowDef.width * 2
         or y >= bowDef.height * 2
      then
        return false
      end

      return MapDef.defIsWalkableCell(bowDef, tileset, x, y)
        and not MapDef.defIsWaterCell(bowDef, tileset, x, y)
    end

    local function isOpen(x, y)
      return terrainIsOpen(x, y)
        and not occupied[tostring(x) .. ":" .. tostring(y)]
    end

    local function isWall(x, y)
      -- Other NPCs are not walls. Only the actual map terrain/boundary counts.
      return not terrainIsOpen(x, y)
    end

    local bestX, bestY, bestScore = nil, nil, nil
    local fallbackX, fallbackY, fallbackSeparation = nil, nil, -1

    for y = 0, bowDef.height * 2 - 1 do
      for x = 0, bowDef.width * 2 - 1 do
        if isOpen(x, y) then
          local wallAdjacent = isWall(x - 1, y)
            or isWall(x + 1, y)
            or isWall(x, y - 1)
            or isWall(x, y + 1)

          if wallAdjacent then
            local nearestSuspect = math.huge
            for i = 1, 5 do
              nearestSuspect = math.min(
                nearestSuspect,
                math.abs(x - suspects[i].x) + math.abs(y - suspects[i].y)
              )
            end

            if nearestSuspect > fallbackSeparation then
              fallbackX, fallbackY = x, y
              fallbackSeparation = nearestSuspect
            end

            if nearestSuspect >= 3 then
              local score = math.abs(x - centerX) + math.abs(y - centerY)
              if not bestScore or score < bestScore then
                bestX, bestY, bestScore = x, y, score
              end
            end
          end
        end
      end
    end

    return bestX or fallbackX or suspect4.x + 3,
      bestY or fallbackY or suspect4.y
  end

  local officerStandbyX, officerStandbyY = bowWallStandbySpot()

  -- Pick a free cardinal cell beside each suspect. These are the destinations
  -- the officer walks to only after the player has actually made an accusation.
  local suspectApproach = {}

  local function approachSpotFor(index)
    local target = suspects[index]
    local tileset = mod.content.tilesets:get(bowDef.tileset)
    local occupied = {}

    for _, obj in ipairs(bowDef.objects or {}) do
      if obj ~= target then
        occupied[tostring(obj.x) .. ":" .. tostring(obj.y)] = true
      end
    end

    local candidates = {
      { x = target.x - 1, y = target.y, facing = "right" },
      { x = target.x + 1, y = target.y, facing = "left" },
      { x = target.x, y = target.y - 1, facing = "down" },
      { x = target.x, y = target.y + 1, facing = "up" },
    }

    local best, bestDist = nil, nil
    for _, candidate in ipairs(candidates) do
      local key = tostring(candidate.x) .. ":" .. tostring(candidate.y)
      if tileset
         and not occupied[key]
         and candidate.x >= 0 and candidate.y >= 0
         and candidate.x < bowDef.width * 2
         and candidate.y < bowDef.height * 2
         and MapDef.defIsWalkableCell(
           bowDef,
           tileset,
           candidate.x,
           candidate.y
         )
         and not MapDef.defIsWaterCell(
           bowDef,
           tileset,
           candidate.x,
           candidate.y
         )
      then
        local dist = math.abs(candidate.x - officerStandbyX)
          + math.abs(candidate.y - officerStandbyY)
        if not bestDist or dist < bestDist then
          best, bestDist = candidate, dist
        end
      end
    end

    if best then return best end

    local x, y = questSpot(
      bowDef,
      target.x + 1,
      target.y,
      { { target.x, target.y } }
    )
    local facing = "left"
    if x < target.x then
      facing = "right"
    elseif y < target.y then
      facing = "down"
    elseif y > target.y then
      facing = "up"
    end

    return { x = x, y = y, facing = facing }
  end

  for i = 1, 5 do
    suspectApproach[i] = approachSpotFor(i)
  end

  local epilogueX, epilogueY = questSpot(
    saffronHouseDef,
    math.floor(saffronHouseDef.width),
    math.max(2, saffronHouseDef.height * 2 - 3)
  )

  local rocketIndex = #(bowDef.objects or {}) + 1
  local arrestOfficerIndex = rocketIndex + 1
  local saffronBaseIndex = #(saffronHouseDef.objects or {}) + 1

