  ---------------------------------------------------------------------------
  -- HELPERS
  ---------------------------------------------------------------------------

  local function ssAnneSay(game, textIdOrLiteral, done)
    local TextBox = require("src.render.TextBox")
    local text = game.data.text[textIdOrLiteral] or textIdOrLiteral
    game.stack:push(TextBox.new(game, text, done))
  end

  local ssAnneCutsceneCallbacks = setmetatable({}, { __mode = "k" })

  mod.commands:register("mars_ssanne_cutscene_done", function(ctx)
    local callback = ssAnneCutsceneCallbacks[ctx.game]
    ssAnneCutsceneCallbacks[ctx.game] = nil
    if callback then callback() end
  end)

  local function queueSsAnneCutscene(game, ow, rows, callback)
    ssAnneCutsceneCallbacks[game] = callback
    rows[#rows + 1] = { "mars_ssanne_cutscene_done" }
    ow:queueScript(rows)
  end

  local function faceSsAnneNpc(ow, npc)
    if npc and npc.facePlayer and ow and ow.player then
      npc:facePlayer(ow.player)
    end
  end

  local function officerApproachRows(index)
    local spot = suspectApproach[index]
    if not spot then return {} end

    return {
      {
        "move_npc_to",
        arrestOfficerIndex,
        spot.x,
        spot.y,
      },
      {
        "face_object",
        arrestOfficerIndex,
        spot.facing,
      },
    }
  end

  local function allSuspectsHeard(flags)
    return flags[FLAGS.heard1]
      and flags[FLAGS.heard2]
      and flags[FLAGS.heard3]
      and flags[FLAGS.heard4]
      and flags[FLAGS.heard5]
  end

  local function wrongFlagFor(index)
    return FLAGS["wrong" .. tostring(index)]
  end

  local function accusedWrongIndex(flags)
    for i = 1, 5 do
      if flags[wrongFlagFor(i)] then return i end
    end
    return nil
  end

  local function giveTM55(game, done)
    local flags = game.save.flags or {}

    if flags[FLAGS.tmReceived] then
      flags[FLAGS.complete] = true
      if done then done(true) end
      return
    end

    local Bag = require("src.inventory.Bag")
    if not Bag.add(game.save, "TM55", 1, game.data) then
      ssAnneSay(
        game,
        "_MARS_SS_ANNE_TM55_FULL",
        function()
          if done then done(false) end
        end
      )
      return
    end

    flags[FLAGS.tmReceived] = true
    flags[FLAGS.complete] = true

    local Sound = require("src.core.Sound")
    Sound.play(game.data, "Get_Item1")

    ssAnneSay(
      game,
      "_MARS_SS_ANNE_GOT_TM55",
      function()
        if done then done(true) end
      end
    )
  end

  ---------------------------------------------------------------------------
  -- OFFICER / VERDICT
  ---------------------------------------------------------------------------

  local function chooseSuspect(game, ow, done)
    local flags = game.save.flags or {}
    local ListMenu = require("src.ui.ListMenu")
    local list

    list = ListMenu.new(
      game,
      "WHO IS THE IMPOSTOR?",
      {
        { label = "MAN WITH FAMILY", value = 1 },
        { label = "VETERAN SAILOR", value = 2 },
        { label = "HOENN WOMAN", value = 3 },
        { label = "ANGRY PASSENGER", value = 4 },
        { label = "SECOND SAILOR", value = 5 },
      },
      {
        onChoose = function(item)
          if not item or not item.value then return end
          list:close()

          local chosen = item.value
          flags[FLAGS.verdictMade] = true

          if chosen == 4 then
            flags[FLAGS.correct] = true

            -- The officer waits at his wall post until the accusation is made,
            -- then visibly crosses the bow to stand beside the named suspect.
            queueSsAnneCutscene(
              game,
              ow,
              officerApproachRows(chosen),
              function()
                ssAnneSay(
                  game,
                  "_MARS_SS_ANNE_OFFICER_CORRECT",
                  done
                )
              end
            )
            return
          end

          flags[FLAGS.failed] = true
          flags[FLAGS.resolved] = true
          flags[wrongFlagFor(chosen)] = true

          queueSsAnneCutscene(
            game,
            ow,
            officerApproachRows(chosen),
            function()
              ssAnneSay(
                game,
                "_MARS_SS_ANNE_OFFICER_WRONG",
                function()
                  queueSsAnneCutscene(
                    game,
                    ow,
                    {
                      { "fade", "out", 15 },
                      {
                        "hide_object",
                        "SS_ANNE_BOW",
                        "MARS_SS_ANNE_SUSPECT_" .. tostring(chosen),
                      },
                      {
                        "hide_object",
                        "SS_ANNE_BOW",
                        "MARS_SS_ANNE_ARREST_OFFICER",
                      },
                      { "wait", 15 },
                      { "fade", "in", 15 },
                    },
                    done
                  )
                end
              )
            end
          )
        end,

        onCancel = function()
          list:close()
          if done then done() end
        end,
      }
    )

    game.stack:push(list)
  end

  local function officerTalk(game, ow, npc, done)
    local flags = game.save.flags or {}
    faceSsAnneNpc(ow, npc)

    if flags[FLAGS.complete] then
      ssAnneSay(game, "_MARS_SS_ANNE_OFFICER_COMPLETE", done)
      return
    end

    if flags[FLAGS.failed] then
      ssAnneSay(game, "_MARS_SS_ANNE_OFFICER_FAILED_AFTER", done)
      return
    end

    if flags[FLAGS.caught] and not flags[FLAGS.tmReceived] then
      giveTM55(game, function()
        if done then done() end
      end)
      return
    end

    if flags[FLAGS.correct] then
      ssAnneSay(game, "_MARS_SS_ANNE_OFFICER_WAIT_BOW", done)
      return
    end

    if not flags[FLAGS.started] then
      flags[FLAGS.started] = true
      ssAnneSay(
        game,
        "_MARS_SS_ANNE_OFFICER_INTRO",
        function()
          queueSsAnneCutscene(
            game,
            ow,
            {
              { "fade", "out", 15 },
              {
                "hide_object",
                "SS_ANNE_1F_ROOMS",
                "MARS_SS_ANNE_OFFICER",
              },
              { "wait", 15 },
              { "fade", "in", 15 },
            },
            done
          )
        end
      )
      return
    end

    if not allSuspectsHeard(flags) then
      ssAnneSay(game, "_MARS_SS_ANNE_OFFICER_REMINDER", done)
      return
    end

    ssAnneSay(
      game,
      "_MARS_SS_ANNE_OFFICER_READY",
      function()
        chooseSuspect(game, ow, done)
      end
    )
  end

