    "_MARS_SS_ANNE_REACT_WRONG_5",
  }

  local function detentionReactionId(index, flags)
    if flags[FLAGS.caught] then
      return correctReactionIds[index]
    end

    if flags[FLAGS.failed] then
      local wrong = accusedWrongIndex(flags)
      if index == wrong then return nil end

      -- The two sailors explicitly know and vouch for one another, so falsely
      -- detaining either of them gets a stronger response from the other.
      if index == 2 and wrong == 5 then
        return "_MARS_SS_ANNE_REACT_WRONG_SAILOR5"
      end

      if index == 5 and wrong == 2 then
        return "_MARS_SS_ANNE_REACT_WRONG_SAILOR2"
      end

      return wrongReactionIds[index]
    end

    return nil
  end

  local function nativeOrFallback(game, textId, fallback, done)
    ssAnneSay(game, game.data.text[textId] or fallback, done)
  end

  local function suspectStoryTalk(index)
    return function(game, ow, npc, done)
      local flags = game.save.flags or {}
      faceSsAnneNpc(ow, npc)

      if not flags[FLAGS.started] then
        nativeOrFallback(
          game,
          SUSPECT_TEXTS[index],
          "Enjoying the voyage?",
          done
        )
        return
      end

      local reactionId = detentionReactionId(index, flags)
      if reactionId then
        ssAnneSay(game, reactionId, done)
        return
      end

      flags[heardFlags[index]] = true
      ssAnneSay(game, suspectStoryIds[index], done)
    end
  end

  ---------------------------------------------------------------------------
  -- CORRECT ACCUSATION: REVEAL + BATTLE + ARREST
  ---------------------------------------------------------------------------

  local function finishRocketArrest(game, ow, battle, done)
    local flags = game.save.flags or {}
    flags[FLAGS.caught] = true
    flags[FLAGS.resolved] = true

    ssAnneSay(
      game,
      "_MARS_SS_ANNE_ROCKET_AFTER_WIN",
      function()
        giveTM55(game, function(gotReward)
          queueSsAnneCutscene(
            game,
            ow,
            {
              { "fade", "out", 15 },
              { "hide_object", "SS_ANNE_BOW", "MARS_SS_ANNE_ROCKET_REVEALED" },
              { "hide_object", "SS_ANNE_BOW", "MARS_SS_ANNE_ARREST_OFFICER" },
              { "fade", "in", 15 },
            },
            function()
              if gotReward then
                ssAnneSay(
                  game,
                  "_MARS_SS_ANNE_ROCKET_ARRESTED",
                  function()
                    if done then done() end
                    ow:afterBattle("win", battle)
                  end
                )
              else
                if done then done() end
                ow:afterBattle("win", battle)
              end
            end
          )
        end)
      end
    )
  end

  local function startRocketBattle(game, ow, done)
    local flags = game.save.flags or {}
    local BattleState = require("src.battle.BattleState")
    local battle = BattleState.newTrainer(
      game,
      "OPP_SS_ANNE_ROCKET_IMPOSTOR",
      1
    )

    battle.endBattleText = "You blew our whole operation!"

    battle.onFinish = function(result)
      if result ~= "win" then
        if done then done() end
        ow:afterBattle(result, battle)
        return
      end

      finishRocketArrest(game, ow, battle, done)
    end

    ow:pushBattle(battle)
  end

  local function revealRocket(game, ow, done)
    local flags = game.save.flags or {}

    if flags[FLAGS.caught] then
      if done then done() end
      return
    end

    flags[FLAGS.revealed] = true

    queueSsAnneCutscene(
      game,
      ow,
      {
        { "hide_object", "SS_ANNE_BOW", "MARS_SS_ANNE_SUSPECT_4" },
        { "show_object", "SS_ANNE_BOW", "MARS_SS_ANNE_ROCKET_REVEALED" },
      },
      function()
        ssAnneSay(
          game,
          "_MARS_SS_ANNE_ROCKET_REVEAL",
          function()
            startRocketBattle(game, ow, done)
          end
        )
      end
    )
  end

  local function suspect4Talk(game, ow, npc, done)
    local flags = game.save.flags or {}
    faceSsAnneNpc(ow, npc)

    if flags[FLAGS.correct]
       and not flags[FLAGS.caught]
    then
      revealRocket(game, ow, done)
      return
    end

    suspectStoryTalk(4)(game, ow, npc, done)
  end

  local function revealedRocketTalk(game, ow, npc, done)
    local flags = game.save.flags or {}
    faceSsAnneNpc(ow, npc)

    if flags[FLAGS.revealed]
       and not flags[FLAGS.caught]
    then
      startRocketBattle(game, ow, done)
      return
    end

    if done then done() end
  end

  ---------------------------------------------------------------------------
  -- SAFFRON FAILURE EPILOGUE
  ---------------------------------------------------------------------------

  local function saffronFailureTalk(game, ow, npc, done)
    local flags = game.save.flags or {}
    faceSsAnneNpc(ow, npc)

    local firstFlag = "EVENT_SS_ANNE_FAILURE_EPILOGUE_SEEN"
    if flags[firstFlag] then
      ssAnneSay(
        game,
        "_MARS_SS_ANNE_SAFFRON_FAILURE_REPEAT",
        done
      )
      return
    end

    flags[firstFlag] = true
    ssAnneSay(
      game,
      "_MARS_SS_ANNE_SAFFRON_FAILURE",
      done
    )
  end

  ---------------------------------------------------------------------------
  -- MAP SCRIPTS / STATE
  ---------------------------------------------------------------------------

  if mod.content.map_scripts then
    mod.content.map_scripts:register("SS_ANNE_1F_ROOMS", {
      priority = 205,

      onEnter = function(game, ow)
        local flags = game.save.flags or {}

        if flags[FLAGS.started] then
          ow:queueScript({
            {
              "hide_object",
              "SS_ANNE_1F_ROOMS",
              "MARS_SS_ANNE_OFFICER",
            },
          })
        else
          ow:queueScript({
            {
              "show_object",
              "SS_ANNE_1F_ROOMS",
              "MARS_SS_ANNE_OFFICER",
            },
          })
        end
      end,

      talk = {
        [TEXT_OFFICER] = officerTalk,
      },
    })

    mod.content.map_scripts:register("SS_ANNE_BOW", {
      priority = 205,

      onEnter = function(game, ow)
        local flags = game.save.flags or {}
        local rows = {
          { "hide_object", "SS_ANNE_BOW", "MARS_SS_ANNE_ROCKET_REVEALED" },
          { "hide_object", "SS_ANNE_BOW", "MARS_SS_ANNE_ARREST_OFFICER" },
        }

        -- Restore all five suspects first so hot reloads and revisits are
        -- deterministic, then apply whichever permanent branch is active.
        for i = 1, 5 do
          rows[#rows + 1] = {
            "show_object",
            "SS_ANNE_BOW",
            "MARS_SS_ANNE_SUSPECT_" .. tostring(i),
          }
        end

        if flags[FLAGS.failed] then
          local wrong = accusedWrongIndex(flags)
          if wrong then
            rows[#rows + 1] = {
              "hide_object",
              "SS_ANNE_BOW",
              "MARS_SS_ANNE_SUSPECT_" .. tostring(wrong),
            }
          end
        else
          -- Once the officer gives the quest, his cabin copy is gone and this
          -- bow copy becomes the active investigation NPC. He remains here while
          -- the player questions suspects and submits the accusation.
          if flags[FLAGS.started]
             and not flags[FLAGS.complete]
             and (
               not flags[FLAGS.caught]
               or not flags[FLAGS.tmReceived]
             )
          then
            rows[#rows + 1] = {
              "show_object",
              "SS_ANNE_BOW",
              "MARS_SS_ANNE_ARREST_OFFICER",
            }

            local officerSpot = nil
            if flags[FLAGS.correct] and not flags[FLAGS.caught] then
              officerSpot = suspectApproach[4]
            else
              officerSpot = {
                x = officerStandbyX,
                y = officerStandbyY,
                facing = "down",
              }
            end

            rows[#rows + 1] = {
              "place_npc",
              arrestOfficerIndex,
              officerSpot.x,
              officerSpot.y,
              officerSpot.facing,
            }
          end

          if flags[FLAGS.correct]
             and not flags[FLAGS.caught]
          then
            if flags[FLAGS.revealed] then
              rows[#rows + 1] = {
                "hide_object",
                "SS_ANNE_BOW",
                "MARS_SS_ANNE_SUSPECT_4",
              }
              rows[#rows + 1] = {
                "show_object",
                "SS_ANNE_BOW",
                "MARS_SS_ANNE_ROCKET_REVEALED",
              }
            end
          elseif flags[FLAGS.caught] then
            rows[#rows + 1] = {
              "hide_object",
              "SS_ANNE_BOW",
              "MARS_SS_ANNE_SUSPECT_4",
            }
          end
        end

        ow:queueScript(rows)
      end,

      talk = {
        [SUSPECT_TEXTS[1]] = suspectStoryTalk(1),
        [SUSPECT_TEXTS[2]] = suspectStoryTalk(2),
        [SUSPECT_TEXTS[3]] = suspectStoryTalk(3),
        [SUSPECT_TEXTS[4]] = suspect4Talk,
        [SUSPECT_TEXTS[5]] = suspectStoryTalk(5),
        [TEXT_ROCKET] = revealedRocketTalk,
        [TEXT_ARREST_OFFICER] = officerTalk,
      },
    })

    mod.content.map_scripts:register("SAFFRON_PIDGEY_HOUSE", {
      priority = 205,

      onEnter = function(game, ow)
        local flags = game.save.flags or {}
        local rows = {}

        for i = 1, 5 do
          rows[#rows + 1] = {
            "hide_object",
            "SAFFRON_PIDGEY_HOUSE",
            "MARS_SS_ANNE_EPILOGUE_" .. tostring(i),
          }
        end

        if flags[FLAGS.failed] then
          local wrong = accusedWrongIndex(flags)
          if wrong then
            rows[#rows + 1] = {
              "show_object",
              "SAFFRON_PIDGEY_HOUSE",
              "MARS_SS_ANNE_EPILOGUE_" .. tostring(wrong),
            }
          end
        end

        ow:queueScript(rows)
      end,

      talk = {
        [TEXT_SAFFRON_EPILOGUE] = saffronFailureTalk,
      },
    })
  end

  mod.log:info(
    "installed S.S. Anne International Police deduction quest + TM55 TAUNT"
  )
  end)()


  ---------------------------------------------------------------------------
  -- SILPH CO. POST-ROCKET SIDE QUEST
  ---------------------------------------------------------------------------
  ;(function()
  ---------------------------------------------------------------------------
  -- "DAMAGE CONTROL"
  --
  -- Unlock: immediately after EVENT_BEAT_SILPH_CO_GIOVANNI.
  --
  -- Silph has been liberated, but the building does not instantly return to
  -- normal. A security officer on 1F asks the player to help with three pieces
  -- of immediate cleanup work that can be handled in any order:
  --   * 4F  - locate a researcher who barricaded himself in an office
  --   * 7F  - recover a dropped Silph data cartridge
  --   * 10F - stop a Rocket straggler trying to destroy R&D evidence
  --
  -- Return to the 1F officer after all three tasks for TM56 MAGNET BOMB.
  ---------------------------------------------------------------------------

  local FLAGS = {
    started = "EVENT_SILPH_DAMAGE_CONTROL_STARTED",
    researcher = "EVENT_SILPH_DAMAGE_CONTROL_RESEARCHER_FOUND",
    data = "EVENT_SILPH_DAMAGE_CONTROL_DATA_RECOVERED",
    rocket = "EVENT_SILPH_DAMAGE_CONTROL_ROCKET_DEFEATED",
    tmReceived = "EVENT_SILPH_DAMAGE_CONTROL_TM56_RECEIVED",
    complete = "EVENT_SILPH_DAMAGE_CONTROL_COMPLETE",
  }

  local TEXT_OFFICER = "TEXT_MARS_SILPH_DAMAGE_CONTROL_OFFICER"
  local TEXT_RESEARCHER = "TEXT_MARS_SILPH_DAMAGE_CONTROL_RESEARCHER"
  local TEXT_DATA = "TEXT_MARS_SILPH_DAMAGE_CONTROL_DATA"
  local TEXT_ROCKET = "TEXT_MARS_SILPH_DAMAGE_CONTROL_ROCKET"

  local floor1 = mod.content.maps:get("SILPH_CO_1F")
  local floor4 = mod.content.maps:get("SILPH_CO_4F")
  local floor7 = mod.content.maps:get("SILPH_CO_7F")
  local floor10 = mod.content.maps:get("SILPH_CO_10F")

  if not floor1 or not floor4 or not floor7 or not floor10 then
    mod.log:error(
      "Damage Control requires SILPH_CO_1F, SILPH_CO_4F, "
        .. "SILPH_CO_7F, and SILPH_CO_10F"
    )
    return
  end

  ---------------------------------------------------------------------------
  -- SAFE PLACEMENT
  ---------------------------------------------------------------------------

  local MapDef = require("src.world.Map")

  local function questSpot(def, preferredX, preferredY, extraBlocked)
    local tileset = def and mod.content.tilesets:get(def.tileset) or nil
    local occupied = {}

    for _, obj in ipairs((def and def.objects) or {}) do
      occupied[tostring(obj.x) .. ":" .. tostring(obj.y)] = true
    end

    -- Do not place quest actors directly on stairs, elevators, or warp pads.
    for _, warp in ipairs((def and def.warps) or {}) do
      occupied[tostring(warp.x) .. ":" .. tostring(warp.y)] = true
    end

    for _, pos in ipairs(extraBlocked or {}) do
      occupied[tostring(pos[1]) .. ":" .. tostring(pos[2])] = true
    end

    for radius = 0, 14 do
      for dy = -radius, radius do
        for dx = -radius, radius do
          if radius == 0
             or math.max(math.abs(dx), math.abs(dy)) == radius
          then
            local x = preferredX + dx
            local y = preferredY + dy
            local key = tostring(x) .. ":" .. tostring(y)

            if not occupied[key]
               and x >= 0
               and y >= 0
               and x < def.width * 2
               and y < def.height * 2
               and tileset
               and MapDef.defIsWalkableCell(def, tileset, x, y)
               and not MapDef.defIsWaterCell(def, tileset, x, y)
            then
              return x, y
            end
          end
        end
      end
    end

    return preferredX, preferredY
  end

  -- 1F: near the center/lobby rather than blocking the entrance or elevator.
  local officerX, officerY = questSpot(
    floor1,
    math.max(2, math.floor(floor1.width)),
    math.max(2, math.floor(floor1.height))
  )

  -- 4F: bias toward the upper-right portion of the floor to read as an office.
  local researcherX, researcherY = questSpot(
    floor4,
    math.max(2, floor4.width * 2 - 5),
    3
  )

  -- 7F: bias toward an interior corridor where a fleeing Rocket could have
  -- dropped the cartridge during the evacuation.
  local dataX, dataY = questSpot(
    floor7,
    math.max(2, math.floor(floor7.width)),
    math.max(2, math.floor(floor7.height))
  )

  -- 10F: upper side of the floor, framed as one of Silph's R&D work areas.
  local rocketX, rocketY = questSpot(
    floor10,
    4,
    3
  )

  local officerIndex = #(floor1.objects or {}) + 1
  local researcherIndex = #(floor4.objects or {}) + 1
  local dataIndex = #(floor7.objects or {}) + 1
  local rocketIndex = #(floor10.objects or {}) + 1

  ---------------------------------------------------------------------------
  -- OBJECTS
  ---------------------------------------------------------------------------

  mod.content.maps:patch("SILPH_CO_1F", {
    objects = {
      __append = {
        {
          index = officerIndex,
          name = "MARS_SILPH_DAMAGE_CONTROL_OFFICER",
          sprite = "SPRITE_SILPH_WORKER_M",
          movement = "STAY",
          range = "ANY_DIR",
          x = officerX,
          y = officerY,
          text = TEXT_OFFICER,
          hidden = true,
        },
      },
    },
  })

  mod.content.maps:patch("SILPH_CO_4F", {
    objects = {
      __append = {
        {
          index = researcherIndex,
          name = "MARS_SILPH_DAMAGE_CONTROL_RESEARCHER",
          sprite = "SPRITE_SCIENTIST",
          movement = "STAY",
          range = "ANY_DIR",
          x = researcherX,
          y = researcherY,
          text = TEXT_RESEARCHER,
          hidden = true,
        },
      },
    },
  })

  mod.content.maps:patch("SILPH_CO_7F", {
    objects = {
      __append = {
        {
          index = dataIndex,
          name = "MARS_SILPH_DAMAGE_CONTROL_DATA",
          sprite = "SPRITE_POKE_BALL",
          movement = "STAY",
          range = "NONE",
          x = dataX,
          y = dataY,
          text = TEXT_DATA,
          hidden = true,
        },
      },
    },
  })

  mod.content.maps:patch("SILPH_CO_10F", {
    objects = {
      __append = {
        {
          index = rocketIndex,
          name = "MARS_SILPH_DAMAGE_CONTROL_ROCKET",
          sprite = "SPRITE_ROCKET",
          movement = "STAY",
          range = "ANY_DIR",
          x = rocketX,
          y = rocketY,
          text = TEXT_ROCKET,
          hidden = true,
        },
      },
    },
  })

  ---------------------------------------------------------------------------
  -- ROCKET STRAGGLER
  ---------------------------------------------------------------------------

  mod.content.trainers:register("OPP_SILPH_DAMAGE_CONTROL_ROCKET", {
    id = "OPP_SILPH_DAMAGE_CONTROL_ROCKET",
    name = "ROCKET",
    basePic = "OPP_ROCKET",
    baseMoney = 30,
    aiClass = (mod.content.trainers:get("OPP_ROCKET") or {}).aiClass,
    aiMods = (mod.content.trainers:get("OPP_ROCKET") or {}).aiMods,
    parties = {
      {
        { level = 32, species = "RATICATE" },
        { level = 33, species = "MUK" },
        { level = 34, species = "GOLBAT" },
      },
    },
  })

  ---------------------------------------------------------------------------
  -- DIALOGUE
  ---------------------------------------------------------------------------

  mod.content.text:register(
    "_MARS_SILPH_DAMAGE_CONTROL_INTRO",
    "SECURITY: You're the TRAINER\nwho drove GIOVANNI out, right?\f"
      .. "Then SILPH owes you more\nthan I can put into words.\f"
      .. "But the building is still\na wreck from the takeover.\f"
      .. "Most of TEAM ROCKET fled,\nbut we're still accounting\nfor people and equipment.\f"
      .. "I could use someone who\ncan move through the floors\nfaster than our staff can.\f"
      .. "A researcher on 4F locked\nhimself inside an office and\nhasn't answered anyone.\f"
      .. "A witness on 7F saw a\nROCKET drop a SILPH data\ncartridge while fleeing.\f"
      .. "And security footage shows\none ROCKET never leaving the\n10F R&D section.\f"
      .. "Check all three. Then come\nback and report to me."
  )

  mod.content.text:register(
    "_MARS_SILPH_DAMAGE_CONTROL_RESEARCHER",
    "RESEARCHER: W-who's there?!\f"
      .. "You're not TEAM ROCKET...\nThey're really gone?\f"
      .. "I shoved a cabinet against\nthe door when the fighting\nstarted.\f"
      .. "I heard footsteps outside\nfor so long I stopped trusting\nany voice I heard.\f"
      .. "Thank goodness. I'll stay\nhere until SECURITY clears\nthe floor properly.\f"
      .. "Please tell them I'm safe."
  )

  mod.content.text:register(
    "_MARS_SILPH_DAMAGE_CONTROL_RESEARCHER_AFTER",
    "RESEARCHER: I'm all right now.\f"
      .. "Tell SECURITY they can mark\nme down as accounted for."
  )

  mod.content.text:register(
    "_MARS_SILPH_DAMAGE_CONTROL_DATA",
    "There's a cracked SILPH\ndata cartridge on the floor.\f"
      .. "It must have been dropped\nduring TEAM ROCKET's retreat.\f"
      .. "You recovered the SILPH\ndata cartridge!"
  )

  mod.content.text:register(
    "_MARS_SILPH_DAMAGE_CONTROL_ROCKET_INTRO",
    "ROCKET: What are YOU doing\nback up here?!\f"
      .. "GIOVANNI called the retreat,\nbut somebody had to make sure\nSILPH learned nothing from us.\f"
      .. "These R&D records are going\nto disappear before I do!\f"
      .. "If you want what's left,\nyou'll have to go through me!"
  )

  mod.content.text:register(
    "_MARS_SILPH_DAMAGE_CONTROL_ROCKET_WIN",
    "ROCKET: Tch...\f"
      .. "Fine! Keep your precious\nrecords. I'm done here!"
  )

  mod.content.text:register(
    "_MARS_SILPH_DAMAGE_CONTROL_PROGRESS",
    "SECURITY: We're still sorting\nthrough the damage.\f"
      .. "Finish checking the three\nproblems I told you about,\nthen report back."
  )

  mod.content.text:register(
    "_MARS_SILPH_DAMAGE_CONTROL_ALL_DONE",
    "SECURITY: That's all three.\f"
      .. "The researcher's safe, the\ndata cartridge is back, and\nthat last ROCKET is gone.\f"
      .. "You just saved us days of\ncleanup work--and possibly\nsome important research.\f"
      .. "SILPH was developing this\nas an experimental TM.\f"
      .. "I think you've earned it."
  )

  mod.content.text:register(
    "_MARS_SILPH_DAMAGE_CONTROL_GOT_TM56",
    "You received TM56!\f"
      .. "TM56 teaches\nMAGNET BOMB!"
  )

  mod.content.text:register(
    "_MARS_SILPH_DAMAGE_CONTROL_BAG_FULL",
    "SECURITY: Your BAG is full.\f"
      .. "Make some room and come\nback. That TM is yours."
  )

  mod.content.text:register(
    "_MARS_SILPH_DAMAGE_CONTROL_COMPLETE",
    "SECURITY: SILPH is getting\nback on its feet.\f"
      .. "After what TEAM ROCKET did,\nthat'll take time.\f"
      .. "But thanks to you, we're\nfinally moving forward."
  )

  ---------------------------------------------------------------------------
  -- HELPERS
  ---------------------------------------------------------------------------

  local function silphSay(game, textIdOrLiteral, done)
    local TextBox = require("src.render.TextBox")
    local text = game.data.text[textIdOrLiteral] or textIdOrLiteral
    game.stack:push(TextBox.new(game, text, done))
  end

  local function faceSilphNpc(ow, npc)
    if npc and npc.facePlayer and ow and ow.player then
      npc:facePlayer(ow.player)
    end
  end

  local function allObjectivesComplete(flags)
    return flags[FLAGS.researcher]
      and flags[FLAGS.data]
      and flags[FLAGS.rocket]
  end

  local function giveTM56(game, done)
    local flags = game.save.flags or {}

    if flags[FLAGS.tmReceived] then
      flags[FLAGS.complete] = true
      if done then done(true) end
      return
    end

    local Bag = require("src.inventory.Bag")
    if not Bag.add(game.save, "TM56", 1, game.data) then
      silphSay(
        game,
        "_MARS_SILPH_DAMAGE_CONTROL_BAG_FULL",
        function()
          if done then done(false) end
        end
      )
      return
    end

    flags[FLAGS.tmReceived] = true
    flags[FLAGS.complete] = true

    local Sound = require("src.core.Sound")
    Sound.play(game.data, "Get_Item1")

    silphSay(
      game,
      "_MARS_SILPH_DAMAGE_CONTROL_GOT_TM56",
      function()
        if done then done(true) end
      end
    )
  end

  ---------------------------------------------------------------------------
  -- QUEST GIVER / OBJECTIVES
  ---------------------------------------------------------------------------

  local function officerTalk(game, ow, npc, done)
    local flags = game.save.flags or {}
    faceSilphNpc(ow, npc)

    if not flags.EVENT_BEAT_SILPH_CO_GIOVANNI then
      if done then done() end
      return
    end

    if flags[FLAGS.complete] then
      silphSay(game, "_MARS_SILPH_DAMAGE_CONTROL_COMPLETE", done)
      return
    end

    if not flags[FLAGS.started] then
      flags[FLAGS.started] = true
      silphSay(game, "_MARS_SILPH_DAMAGE_CONTROL_INTRO", done)
      return
    end

    if not allObjectivesComplete(flags) then
      silphSay(game, "_MARS_SILPH_DAMAGE_CONTROL_PROGRESS", done)
      return
    end

    if not flags[FLAGS.tmReceived] then
      silphSay(
        game,
        "_MARS_SILPH_DAMAGE_CONTROL_ALL_DONE",
        function()
          giveTM56(game, function()
            if done then done() end
          end)
        end
      )
      return
    end

    flags[FLAGS.complete] = true
    silphSay(game, "_MARS_SILPH_DAMAGE_CONTROL_COMPLETE", done)
  end

  local function researcherTalk(game, ow, npc, done)
    local flags = game.save.flags or {}
    faceSilphNpc(ow, npc)

    if not flags[FLAGS.started] then
      if done then done() end
      return
    end

    if flags[FLAGS.researcher] then
      silphSay(game, "_MARS_SILPH_DAMAGE_CONTROL_RESEARCHER_AFTER", done)
      return
    end

    flags[FLAGS.researcher] = true
    silphSay(game, "_MARS_SILPH_DAMAGE_CONTROL_RESEARCHER", done)
  end

  local function dataTalk(game, ow, npc, done)
    local flags = game.save.flags or {}

    if not flags[FLAGS.started] or flags[FLAGS.data] then
      if done then done() end
      return
    end

    flags[FLAGS.data] = true
    ow:queueScript({
      {
        "hide_object",
        "SILPH_CO_7F",
        "MARS_SILPH_DAMAGE_CONTROL_DATA",
      },
    })

    silphSay(game, "_MARS_SILPH_DAMAGE_CONTROL_DATA", done)
  end

  local function startStragglerBattle(game, ow, done)
    local flags = game.save.flags or {}
    local BattleState = require("src.battle.BattleState")
    local battle = BattleState.newTrainer(
      game,
      "OPP_SILPH_DAMAGE_CONTROL_ROCKET",
      1
    )

    battle.endBattleText = "This cleanup job isn't worth it!"

    battle.onFinish = function(result)
      if result ~= "win" then
        if done then done() end
        ow:afterBattle(result, battle)
        return
      end

      flags[FLAGS.rocket] = true

      silphSay(
        game,
        "_MARS_SILPH_DAMAGE_CONTROL_ROCKET_WIN",
        function()
          ow:queueScript({
            {
              "hide_object",
              "SILPH_CO_10F",
              "MARS_SILPH_DAMAGE_CONTROL_ROCKET",
            },
          })
          if done then done() end
          ow:afterBattle("win", battle)
        end
      )
    end

    ow:pushBattle(battle)
  end

  local function rocketTalk(game, ow, npc, done)
    local flags = game.save.flags or {}
    faceSilphNpc(ow, npc)

    if not flags[FLAGS.started] or flags[FLAGS.rocket] then
      if done then done() end
      return
    end

    silphSay(
      game,
      "_MARS_SILPH_DAMAGE_CONTROL_ROCKET_INTRO",
      function()
        startStragglerBattle(game, ow, done)
      end
    )
  end

  ---------------------------------------------------------------------------
  -- MAP STATE
  ---------------------------------------------------------------------------

  if mod.content.map_scripts then
    mod.content.map_scripts:register("SILPH_CO_1F", {
      priority = 190,

      onEnter = function(game, ow)
        local flags = game.save.flags or {}
        ow:queueScript({
          {
            flags.EVENT_BEAT_SILPH_CO_GIOVANNI and "show_object" or "hide_object",
            "SILPH_CO_1F",
            "MARS_SILPH_DAMAGE_CONTROL_OFFICER",
          },
        })
      end,

      talk = {
        [TEXT_OFFICER] = officerTalk,
      },
    })

    mod.content.map_scripts:register("SILPH_CO_4F", {
      priority = 190,

      onEnter = function(game, ow)
        local flags = game.save.flags or {}
        ow:queueScript({
          {
            flags[FLAGS.started] and "show_object" or "hide_object",
            "SILPH_CO_4F",
            "MARS_SILPH_DAMAGE_CONTROL_RESEARCHER",
          },
        })
      end,

      talk = {
        [TEXT_RESEARCHER] = researcherTalk,
      },
    })

    mod.content.map_scripts:register("SILPH_CO_7F", {
      priority = 190,

      onEnter = function(game, ow)
        local flags = game.save.flags or {}
        local shouldShow = flags[FLAGS.started] and not flags[FLAGS.data]
        ow:queueScript({
          {
            shouldShow and "show_object" or "hide_object",
            "SILPH_CO_7F",
            "MARS_SILPH_DAMAGE_CONTROL_DATA",
          },
        })
      end,

      talk = {
        [TEXT_DATA] = dataTalk,
      },
    })

    mod.content.map_scripts:register("SILPH_CO_10F", {
      priority = 190,

      onEnter = function(game, ow)
        local flags = game.save.flags or {}
        local shouldShow = flags[FLAGS.started] and not flags[FLAGS.rocket]
        ow:queueScript({
          {
            shouldShow and "show_object" or "hide_object",
            "SILPH_CO_10F",
            "MARS_SILPH_DAMAGE_CONTROL_ROCKET",
          },
        })
      end,

      talk = {
        [TEXT_ROCKET] = rocketTalk,
      },
    })
  end

  mod.log:info(
    "installed Silph Co. Damage Control aftermath quest + TM56 MAGNET BOMB"
  )
  end)()


  ---------------------------------------------------------------------------
  -- CYCLING ROAD "DOWNHILL DASH" REPEATABLE RACE
  ---------------------------------------------------------------------------
  ;(function()
  local RACE_MAP = "ROUTE_17"
  local FINISH_MAP = "ROUTE_18"

  local FLAGS = {
    upgrade = "EVENT_CYCLING_ROAD_RACE_BIKE_UPGRADE",

    hasResult = "EVENT_CYCLING_ROAD_RACE_HAS_RESULT",
    rank1 = "EVENT_CYCLING_ROAD_RACE_LAST_RANK_1",
    rank2 = "EVENT_CYCLING_ROAD_RACE_LAST_RANK_2",
    rank3 = "EVENT_CYCLING_ROAD_RACE_LAST_RANK_3",
    rank4 = "EVENT_CYCLING_ROAD_RACE_LAST_RANK_4",

    rexBeatPlayer = "EVENT_CYCLING_ROAD_REX_BEAT_PLAYER",
    juneBeatPlayer = "EVENT_CYCLING_ROAD_JUNE_BEAT_PLAYER",
    marcoBeatPlayer = "EVENT_CYCLING_ROAD_MARCO_BEAT_PLAYER",
  }

  ---------------------------------------------------------------------------
  -- COURSE
  ---------------------------------------------------------------------------
  local PLAYER_START_Y = 1
  local LINEUP_Y = 0

  local route16Def = mod.content.maps:get("ROUTE_16")
  local route17Def = mod.content.maps:get(RACE_MAP)
  local route18Def = mod.content.maps:get(FINISH_MAP)
  local MapDef = require("src.world.Map")

  if not route16Def or not route17Def or not route18Def then
    mod.log:error(
      "Downhill Dash requires ROUTE_16, ROUTE_17, and ROUTE_18"
    )
    return
  end

  -- Stop the racers on the LAST actual tile row of Route 17, immediately
  -- after the final ledge and right at the Route 18 transition.
  local RACE_BOTTOM_Y = (route17Def.height * 2) - 1

  local route17Tileset = mod.content.tilesets:get(route17Def.tileset)
  local route18Tileset = mod.content.tilesets:get(route18Def.tileset)

  local function passable(def, tileset, x, y)
    return x >= 0
      and y >= 0
      and x < def.width * 2
      and y < def.height * 2
      and MapDef.defIsWalkableCell(def, tileset, x, y)
      and not MapDef.defIsWaterCell(def, tileset, x, y)
  end

  local function nearestOpenX(def, tileset, y, preferred, used)
    local width = def.width * 2

    for d = 0, width do
      local left = preferred - d
      local right = preferred + d

      if left >= 0
         and passable(def, tileset, left, y)
         and not used[left]
      then
        used[left] = true
        return left
      end

      if right < width
         and right ~= left
         and passable(def, tileset, right, y)
         and not used[right]
      then
        used[right] = true
        return right
      end
    end

    return preferred
  end

  ---------------------------------------------------------------------------
  -- STARTING LINE
  --
  -- established that x=10 is the correct open-road player lane. Keep it.
  -- Put the three racers literally beside the player:
  --
  --       REX  JUNE  MARCO  PLAYER
  --        7     8     9      10
  ---------------------------------------------------------------------------
  local usedStart = {}

  local PLAYER_START_X = nearestOpenX(
    route17Def,
    route17Tileset,
    PLAYER_START_Y,
    10,
    usedStart
  )

  local racerUsed = {}
  local RACER_START_X = {
    nearestOpenX(
      route17Def,
      route17Tileset,
      LINEUP_Y,
      PLAYER_START_X - 3,
      racerUsed
    ),
    nearestOpenX(
      route17Def,
      route17Tileset,
      LINEUP_Y,
      PLAYER_START_X - 2,
      racerUsed
    ),
    nearestOpenX(
      route17Def,
      route17Tileset,
      LINEUP_Y,
      PLAYER_START_X - 1,
      racerUsed
    ),
  }

  ---------------------------------------------------------------------------
  -- RACER PATHS
  ---------------------------------------------------------------------------
  local function bfsPath(startX, startY)
    local width = route17Def.width * 2
    local height = route17Def.height * 2

    local function key(x, y)
      return y * width + x
    end

    local qx = { startX }
    local qy = { startY }
    local head = 1

    local seen = {
      [key(startX, startY)] = true,
    }

    local prev = {}

    -- Bias south first so the race line follows Cycling Road downhill.
    local dirs = {
      { 0, 1, "down" },
      { -1, 0, "left" },
      { 1, 0, "right" },
      { 0, -1, "up" },
    }

    local foundX, foundY = nil, nil

    while head <= #qx do
      local x = qx[head]
      local y = qy[head]
      head = head + 1

      if y >= RACE_BOTTOM_Y then
        foundX, foundY = x, y
        break
      end

      for _, d in ipairs(dirs) do
        local nx = x + d[1]
        local ny = y + d[2]

        if nx >= 0
           and ny >= 0
           and nx < width
           and ny < height
           and passable(route17Def, route17Tileset, nx, ny)
        then
          local k = key(nx, ny)

          if not seen[k] then
            seen[k] = true
            prev[k] = {
              x = x,
              y = y,
              dir = d[3],
            }

            qx[#qx + 1] = nx
            qy[#qy + 1] = ny
          end
        end
      end
    end

    if not foundX then
      mod.log:error(
        "Downhill Dash could not build racer path from (%d,%d)",
        startX,
        startY
      )

      return {
        cells = {
          { x = startX, y = startY },
        },
        dirs = {},
      }
    end

    local reverseCells = {
      {
        x = foundX,
        y = foundY,
      },
    }

    local reverseDirs = {}

    local cx, cy = foundX, foundY

    while cx ~= startX or cy ~= startY do
      local p = prev[key(cx, cy)]
      if not p then break end

      reverseDirs[#reverseDirs + 1] = p.dir
      reverseCells[#reverseCells + 1] = {
        x = p.x,
        y = p.y,
      }

      cx = p.x
      cy = p.y
    end

    local cells = {}
    for i = #reverseCells, 1, -1 do
      cells[#cells + 1] = reverseCells[i]
    end

    local dirsOut = {}
    for i = #reverseDirs, 1, -1 do
      dirsOut[#dirsOut + 1] = reverseDirs[i]
    end

    return {
      cells = cells,
      dirs = dirsOut,
    }
  end

  local RACERS = {
    {
      name = "REX",
      stageName = "MARS_CYCLING_STAGE_REX",
      postName = "MARS_CYCLING_POST_REX",
      postText = "TEXT_MARS_CYCLING_POST_REX",
      beatFlag = FLAGS.rexBeatPlayer,
      startX = RACER_START_X[1],
      baseStepFrames = 9,
      advancedStepFrames = 8,
      stepFrames = 9,
      mistakeChance = 0.030,
    },
    {
      name = "JUNE",
      stageName = "MARS_CYCLING_STAGE_JUNE",
      postName = "MARS_CYCLING_POST_JUNE",
      postText = "TEXT_MARS_CYCLING_POST_JUNE",
      beatFlag = FLAGS.juneBeatPlayer,
      startX = RACER_START_X[2],
      baseStepFrames = 10,
      advancedStepFrames = 9,
      stepFrames = 10,
      mistakeChance = 0.030,
    },
    {
      name = "MARCO",
      stageName = "MARS_CYCLING_STAGE_MARCO",
      postName = "MARS_CYCLING_POST_MARCO",
      postText = "TEXT_MARS_CYCLING_POST_MARCO",
      beatFlag = FLAGS.marcoBeatPlayer,
      startX = RACER_START_X[3],
      baseStepFrames = 10,
      advancedStepFrames = 9,
      stepFrames = 10,
      mistakeChance = 0.025,
    },
  }

  for _, racer in ipairs(RACERS) do
    racer.path = bfsPath(racer.startX, LINEUP_Y)

    -- the BFS reaches the south stair/ledge. Continue two more visible
    -- downhill steps into the Route 17 -> Route 18 connection area.
    local lastCell = racer.path.cells[#racer.path.cells]
    if lastCell then
      for extra = 1, 2 do
        racer.path.dirs[#racer.path.dirs + 1] = "down"
        racer.path.cells[#racer.path.cells + 1] = {
          x = lastCell.x,
          y = lastCell.y + extra,
        }
      end
    end

    racer.pathIndex = 1
    racer.finished = false
    racer.runToken = 0
  end

  ---------------------------------------------------------------------------
  -- NORMAL MAP OBJECTS FOR THE STARTING LINE
  --
  -- These are not runtime spawns. They are ordinary Route 17 Biker objects,
  -- so all three are already present beside the sign when the player arrives.
  ---------------------------------------------------------------------------
  local stageBaseIndex = #(route17Def.objects or {}) + 1

  -- keep the real object_event index for each visible lineup Biker.
  -- race.ow:npcByIndex(index) returns the actual NPC instance that NPC:update
  -- advances every frame. mod.world:npc() only returns the public handle and
  -- does not expose the movement fields used below.
  for i, racer in ipairs(RACERS) do
    racer.stageIndex = stageBaseIndex + (i - 1)
  end

  mod.content.maps:patch(RACE_MAP, {
    objects = {
      __append = {
        {
          index = RACERS[1].stageIndex,
          name = RACERS[1].stageName,
          sprite = "SPRITE_BIKER",
          movement = "STAY",
          range = "DOWN",
          x = RACERS[1].startX,
          y = LINEUP_Y,
          text = "TEXT_MARS_CYCLING_STAGE_RACER",
        },
        {
          index = RACERS[2].stageIndex,
          name = RACERS[2].stageName,
          sprite = "SPRITE_BIKER",
          movement = "STAY",
          range = "DOWN",
          x = RACERS[2].startX,
          y = LINEUP_Y,
          text = "TEXT_MARS_CYCLING_STAGE_RACER",
        },
        {
          index = RACERS[3].stageIndex,
          name = RACERS[3].stageName,
          sprite = "SPRITE_BIKER",
          movement = "STAY",
          range = "DOWN",
          x = RACERS[3].startX,
          y = LINEUP_Y,
          text = "TEXT_MARS_CYCLING_STAGE_RACER",
        },
      },
    },
  })

  ---------------------------------------------------------------------------
  -- ADVANCED COURSE
  --
  -- Once the first-place Bicycle upgrade has been earned, later races use a
  -- harder layout. Six non-trainer Bikers form a staggered slalom down Route17.
  -- They are solid obstacles, but have no trainer sight/battle behavior.
  ---------------------------------------------------------------------------
  local ADVANCED_OBSTACLE_ROWS = {
    { y = 24, preferredX = 8 },
    { y = 43, preferredX = 11 },
    { y = 63, preferredX = 7 },
    { y = 84, preferredX = 10 },
    { y = 104, preferredX = 8 },
    { y = 124, preferredX = 11 },
  }

  local advancedObstacles = {}
  local advancedObstacleBaseIndex = stageBaseIndex + #RACERS

  for i, spec in ipairs(ADVANCED_OBSTACLE_ROWS) do
    local used = {}
    local x = nearestOpenX(
      route17Def,
      route17Tileset,
      spec.y,
      spec.preferredX,
      used
    )

    advancedObstacles[#advancedObstacles + 1] = {
      index = advancedObstacleBaseIndex + (i - 1),
      name = "MARS_CYCLING_ADV_OBSTACLE_" .. tostring(i),
      x = x,
      y = spec.y,
    }
  end

  local advancedObjectRows = {}
  for _, obstacle in ipairs(advancedObstacles) do
    advancedObjectRows[#advancedObjectRows + 1] = {
      index = obstacle.index,
      name = obstacle.name,
      sprite = "SPRITE_BIKER",
      movement = "STAY",
      range = "DOWN",
      x = obstacle.x,
      y = obstacle.y,
      text = "TEXT_MARS_CYCLING_ADV_OBSTACLE",
      hidden = true,
    }
  end

  mod.content.maps:patch(RACE_MAP, {
    objects = {
      __append = advancedObjectRows,
    },
  })

  local function advancedObstacleRows(show)
    local rows = {}

    for _, obstacle in ipairs(advancedObstacles) do
      rows[#rows + 1] = {
        show and "show_object" or "hide_object",
        RACE_MAP,
        obstacle.name,
      }
    end

    return rows
  end

  local function setAdvancedObstaclesVisibleWhileInactive(visible)
    local pos = mod.world:current()

    if pos and pos.mapId == RACE_MAP then
      mod.log:warn(
        "refused active Route17 advanced-obstacle toggle"
      )
      return
    end

    for _, obstacle in ipairs(advancedObstacles) do
      mod.world:toggleObject(
        RACE_MAP,
        obstacle.name,
        visible
      )
    end

    mod.log:info(
      "Downhill Dash: advanced obstacles %s (%d objects)",
      visible and "ENABLED" or "DISABLED",
      #advancedObstacles
    )
  end

  ---------------------------------------------------------------------------
  -- VANILLA TRAINERS
  ---------------------------------------------------------------------------
  local vanillaTrainerNames = {}

  for i = 1, math.min(10, #(route17Def.objects or {})) do
    local obj = route17Def.objects[i]

    if obj then
      obj.name =
        obj.name
        or ("MARS_ROUTE17_RACE_HIDE_TRAINER_" .. tostring(i))

      vanillaTrainerNames[#vanillaTrainerNames + 1] = obj.name
    end
  end

  local function trainerRows(show)
    local rows = {}

    for _, name in ipairs(vanillaTrainerNames) do
      rows[#rows + 1] = {
        show and "show_object" or "hide_object",
        RACE_MAP,
        name,
      }
    end

    return rows
  end

  local function setVanillaTrainersVisibleWhileInactive(visible)
    -- WorldAPI:toggleObject reloads the map when the TARGET map is active.
    -- Only call this from Route 16/18, where Route 17 is inactive. That lets
    -- the normal object spawn filter hide/restore all trainers without any
    -- Route 17 reload recursion.
    local pos = mod.world:current()

    if pos and pos.mapId == RACE_MAP then
      mod.log:warn(
        "refused active-map trainer toggle to prevent Route17 reload loop"
      )
      return
    end

    for _, name in ipairs(vanillaTrainerNames) do
      mod.world:toggleObject(
        RACE_MAP,
        name,
        visible
      )
    end

    mod.log:info(
      "Downhill Dash: Route17 trainers %s (%d objects)",
      visible and "RESTORED" or "DISABLED",
      #vanillaTrainerNames
    )
  end

  local function stageRows(show)
    local rows = {}

    for _, racer in ipairs(RACERS) do
      rows[#rows + 1] = {
        show and "show_object" or "hide_object",
        RACE_MAP,
        racer.stageName,
      }
    end

    return rows
  end

  local function ensureStageRacersLive(game, ow, resetToStart)
    if not game
       or not ow
       or not ow.map
       or ow.map.id ~= RACE_MAP
    then
      return 0
    end

    ow.npcs = ow.npcs or {}
    ow.entities = ow.entities or {}
    ow.npcPool = ow.npcPool or {}

    local NPC = require("src.world.NPC")
    local recreated = 0

    local function findLiveByName(name)
      for _, npc in ipairs(ow.npcs) do
        if npc
           and npc.def
           and npc.def.name == name
        then
          return npc
        end
      end

      return nil
    end

    local function findDefByName(name)
      for _, obj in ipairs(ow.map.def.objects or {}) do
        if obj.name == name then
          return obj
        end
      end

      return nil
    end

    for _, racer in ipairs(RACERS) do
      local npc = findLiveByName(racer.stageName)

      if not npc then
        local obj = findDefByName(racer.stageName)

        if obj then
          npc = NPC.new(
            game.data,
            RACE_MAP,
            obj
          )

          table.insert(ow.npcs, npc)
          table.insert(ow.entities, npc)
          ow.npcPool[npc.id] = npc
          recreated = recreated + 1
        end
      end

      if npc then
        npc.frozen = false
        npc.wanders = false
        npc.stepFrames = racer.stepFrames
        npc.moving = false
        npc.targetX = nil
        npc.targetY = nil
        npc.progress = 0

        if resetToStart then
          npc.cellX = racer.startX
          npc.cellY = LINEUP_Y
          npc.px = racer.startX * 16
          npc.py = LINEUP_Y * 16
          npc.facing = "down"
        end
      end
    end

    mod.log:info(
      "Downhill Dash: ensured live start racers; recreated=%d reset=%s",
      recreated,
      tostring(resetToStart)
    )

    return recreated
  end

  ---------------------------------------------------------------------------
  -- OFFICIALS
  ---------------------------------------------------------------------------
  mod.content.maps:patch("ROUTE_16", {
    objects = {
      __append = {
        {
          index = #(route16Def.objects or {}) + 1,
          name = "MARS_CYCLING_RACE_OFFICIAL",
          sprite = "SPRITE_BIKER",
          movement = "STAY",
          range = "DOWN",
          x = 15,
          y = 11,
          text = "TEXT_MARS_CYCLING_RACE_OFFICIAL",
        },
      },
    },
  })

  local POST_RACE_Y = 2
  local finishSpreadUsed = {}

  local postCenterX = nearestOpenX(
    route18Def,
    route18Tileset,
    POST_RACE_Y,
    16,
    finishSpreadUsed
  )

  local POST_RACE_X = {
    nearestOpenX(
      route18Def,
      route18Tileset,
      POST_RACE_Y,
      postCenterX - 3,
      finishSpreadUsed
    ),
    nearestOpenX(
      route18Def,
      route18Tileset,
      POST_RACE_Y,
      postCenterX,
      finishSpreadUsed
    ),
    nearestOpenX(
      route18Def,
      route18Tileset,
      POST_RACE_Y,
      postCenterX + 3,
      finishSpreadUsed
    ),
  }

  local finishOfficialIndex = #(route18Def.objects or {}) + 1
  local postRacerBaseIndex = finishOfficialIndex + 1

  local finishY = 4
  local finishX = nearestOpenX(
    route18Def,
    route18Tileset,
    finishY,
    postCenterX,
    {}
  )

  for i, racer in ipairs(RACERS) do
    racer.postIndex = postRacerBaseIndex + (i - 1)
    racer.postX = POST_RACE_X[i]
    racer.postY = POST_RACE_Y
  end

  mod.content.maps:patch(FINISH_MAP, {
    objects = {
      __append = {
        {
          index = finishOfficialIndex,
          name = "MARS_CYCLING_FINISH_OFFICIAL",
          sprite = "SPRITE_BIKER",
          movement = "STAY",
          range = "UP",
          x = finishX,
          y = finishY,
          text = "TEXT_MARS_CYCLING_FINISH_OFFICIAL",
        },
        {
          index = RACERS[1].postIndex,
          name = RACERS[1].postName,
          sprite = "SPRITE_BIKER",
          movement = "STAY",
          range = "UP",
          x = RACERS[1].postX,
          y = RACERS[1].postY,
          text = RACERS[1].postText,
          hidden = true,
        },
        {
          index = RACERS[2].postIndex,
          name = RACERS[2].postName,
          sprite = "SPRITE_BIKER",
          movement = "STAY",
          range = "UP",
          x = RACERS[2].postX,
          y = RACERS[2].postY,
          text = RACERS[2].postText,
          hidden = true,
        },
        {
          index = RACERS[3].postIndex,
          name = RACERS[3].postName,
          sprite = "SPRITE_BIKER",
          movement = "STAY",
          range = "UP",
          x = RACERS[3].postX,
          y = RACERS[3].postY,
          text = RACERS[3].postText,
          hidden = true,
        },
      },
    },
  })

  ---------------------------------------------------------------------------
  -- DIALOGUE
  ---------------------------------------------------------------------------
