  ---------------------------------------------------------------------------
  -- RACE STATE
  ---------------------------------------------------------------------------
  local race = {
    prepared = false,
    active = false,
    startQueued = false,
    advanced = false,
    game = nil,
    ow = nil,
  }

  local function clearLastRaceResult(game)
    game.save.flags = game.save.flags or {}
    local flags = game.save.flags

    flags[FLAGS.hasResult] = false
    flags[FLAGS.rank1] = false
    flags[FLAGS.rank2] = false
    flags[FLAGS.rank3] = false
    flags[FLAGS.rank4] = false

    flags[FLAGS.rexBeatPlayer] = false
    flags[FLAGS.juneBeatPlayer] = false
    flags[FLAGS.marcoBeatPlayer] = false
  end

  local function saveLastRaceResult(game, rank)
    game.save.flags = game.save.flags or {}
    local flags = game.save.flags

    flags[FLAGS.hasResult] = true
    flags[FLAGS.rank1] = rank == 1
    flags[FLAGS.rank2] = rank == 2
    flags[FLAGS.rank3] = rank == 3
    flags[FLAGS.rank4] = rank == 4

    for _, racer in ipairs(RACERS) do
      -- A racer whose extended finish path was already complete crossed the
      -- line before the player.
      flags[racer.beatFlag] = racer.finished and true or false
    end
  end

  local function postRaceRows(show)
    local rows = {}

    for _, racer in ipairs(RACERS) do
      rows[#rows + 1] = {
        show and "show_object" or "hide_object",
        FINISH_MAP,
        racer.postName,
      }

      if show then
        rows[#rows + 1] = {
          "place_npc",
          racer.postIndex,
          racer.postX,
          racer.postY,
          "up",
        }
      end
    end

    return rows
  end

  local function setStageRacersVisibleWhileInactive(visible)
    local pos = mod.world:current()

    if pos and pos.mapId == RACE_MAP then
      mod.log:warn(
        "refused active Route17 racer visibility toggle"
      )
      return
    end

    for _, racer in ipairs(RACERS) do
      mod.world:toggleObject(
        RACE_MAP,
        racer.stageName,
        visible
      )
    end
  end

  local function removeStageRacersFromLiveOverworld(ow)
    if not ow then
      return 0
    end

    local wanted = {}
    for _, racer in ipairs(RACERS) do
      wanted[racer.stageName] = true
    end

    local removed = 0

    -- Remove from the NPC list first.
    if ow.npcs then
      for i = #ow.npcs, 1, -1 do
        local npc = ow.npcs[i]
        local name = npc
          and npc.def
          and npc.def.name

        if name and wanted[name] then
          if ow.npcPool and npc.id then
            ow.npcPool[npc.id] = nil
          end

          table.remove(ow.npcs, i)
          removed = removed + 1
        end
      end
    end

    -- Also remove the same actors from the collision/render entity list.
    if ow.entities then
      for i = #ow.entities, 1, -1 do
        local entity = ow.entities[i]
        local name = entity
          and entity.def
          and entity.def.name

        if name and wanted[name] then
          table.remove(ow.entities, i)
        end
      end
    end

    return removed
  end

  local function setPostRacersVisibleWhileInactive(visible)
    local pos = mod.world:current()

    if pos and pos.mapId == FINISH_MAP then
      mod.log:warn(
        "refused active Route18 post-racer visibility toggle"
      )
      return
    end

    for _, racer in ipairs(RACERS) do
      mod.world:toggleObject(
        FINISH_MAP,
        racer.postName,
        visible
      )
    end
  end

  ---------------------------------------------------------------------------
  -- FIXED-TICK RACER MOVEMENT
  --
  -- The user's engine build does not expose a non-blocking move method on the
  -- public NPC handle. The handle DOES contain the live NPC instance under
  -- handle.npc, and NPC:update() advances these exact fields every overworld
  -- tick:
  --
  --   facing, targetX, targetY, progress, moving, stepFrames
  --
  -- Starting a racer step here therefore uses the NPC's normal animation path
  -- without touching ow.scriptMoves, so the player stays fully controllable.
  ---------------------------------------------------------------------------

  local DELTA = {
    up = { 0, -1 },
    down = { 0, 1 },
    left = { -1, 0 },
    right = { 1, 0 },
  }

  local function currentRacerNpc(racer)
    local handle = mod.world:npc(
      RACE_MAP,
      racer.stageName
    )

    if not handle or not handle.npc then
      return nil
    end

    local npc = handle.npc
    npc.stepFrames = racer.stepFrames
    npc.frozen = false
    npc.wanders = false

    return npc
  end

  local function resetRacerProgress()
    for _, racer in ipairs(RACERS) do
      racer.pathIndex = 1
      racer.finished = false
      racer.startedMoving = false
      racer.missingNpcLogged = false
      racer.mistakeTicks = 0
      racer.mistakeCooldown = 0
    end
  end

  local function beginRawNpcStep(racer, npc, dir)
    local d = DELTA[dir]
    if not d then
      return false, "bad direction"
    end

    npc.facing = dir
    npc.targetX = npc.cellX + d[1]
    npc.targetY = npc.cellY + d[2]
    npc.progress = 0
    npc.stepFrames = racer.stepFrames
    npc.marching = false
    npc.hopStep = nil
    npc.moving = true

    return true
  end

  local function advanceOneRacer(racer)
    if not race.active or racer.finished then
      return
    end

    local npc = currentRacerNpc(racer)

    if not npc then
      if not racer.missingNpcLogged then
        racer.missingNpcLogged = true
        mod.log:warn(
          "Downhill Dash: live NPC missing for %s",
          racer.name
        )
      end
      return
    end

    if npc.moving then
      return
    end

    -- Racers are allowed to mess up. A mistake is a brief wobble/hesitation:
    -- they turn the wrong way for a moment, lose time, then recover and resume
    -- the authored downhill path. This cannot derail them into walls.
    if (racer.mistakeTicks or 0) > 0 then
      racer.mistakeTicks = racer.mistakeTicks - 1
      return
    end

    if (racer.mistakeCooldown or 0) > 0 then
      racer.mistakeCooldown = racer.mistakeCooldown - 1
    elseif racer.pathIndex > 6
       and racer.pathIndex < #racer.path.dirs - 4
       and math.random() < (racer.mistakeChance or 0)
    then
      local mistakeMin = 6
      local mistakeMax = 18

      if racer.name == "REX" then
        mistakeMin = 10
        mistakeMax = 22
      elseif racer.name == "JUNE" then
        mistakeMin = 8
        mistakeMax = 20
      end

      racer.mistakeTicks = math.random(mistakeMin, mistakeMax)
      racer.mistakeCooldown = math.random(8, 16)
      npc.facing = (math.random(0, 1) == 0) and "left" or "right"

      mod.log:info(
        "Downhill Dash: %s made a mistake and lost a little time",
        racer.name
      )
      return
    end

    local dir = racer.path.dirs[racer.pathIndex]

    if not dir then
      racer.finished = true

      mod.log:info(
        "Downhill Dash: %s crossed the extended finish two steps below the ledge",
        racer.name
      )
      return
    end

    local ok, err = beginRawNpcStep(racer, npc, dir)

    if not ok then
      mod.log:error(
        "Downhill Dash: %s could not start step %d: %s",
        racer.name,
        racer.pathIndex,
        tostring(err)
      )
      racer.finished = true
      return
    end

    racer.pathIndex = racer.pathIndex + 1

    if not racer.startedMoving then
      racer.startedMoving = true

      mod.log:info(
        "Downhill Dash: %s MOVING from (%d,%d), first dir=%s",
        racer.name,
        npc.cellX,
        npc.cellY,
        tostring(dir)
      )
    end
  end

  local function advanceAllRacers()
    for _, racer in ipairs(RACERS) do
      advanceOneRacer(racer)
    end
  end

  local function restoreRacersAtProgress()
    local rows = {}

    for _, racer in ipairs(RACERS) do
      local cells = racer.path.cells
      local landedIndex = math.max(
        1,
        math.min(#cells, racer.pathIndex)
      )
      local cell = cells[landedIndex]

      rows[#rows + 1] = {
        "show_object",
        RACE_MAP,
        racer.stageName,
      }

      rows[#rows + 1] = {
        "place_npc",
        racer.stageIndex,
        cell.x,
        cell.y,
        "down",
      }
    end

    return rows
  end

  local function rankAtFinish()
    local ahead = 0

    for _, racer in ipairs(RACERS) do
      if racer.finished then
        ahead = ahead + 1
      end
    end

    return math.min(4, ahead + 1)
  end

  local function finishRace(game, ow)
    if not race.active then return end

    local rank = rankAtFinish()

    -- Snapshot who crossed the extended finish before the player BEFORE
    -- changing any race state.
    saveLastRaceResult(game, rank)

    race.active = false
    race.prepared = false
    race.startQueued = false
    race.game = game
    race.ow = ow

    -- Race is over: put every normal Cycling Road trainer back and remove
    -- any upgraded-course obstacle layout before Route17 is visited again.
    setVanillaTrainersVisibleWhileInactive(true)
    setAdvancedObstaclesVisibleWhileInactive(false)

    -- Start with ONLY the result/reward dialogue. The visible race actors
    -- remain on-screen until that dialogue has finished.
    local rows = {}

    if rank == 1 then
      local flags = game.save.flags or {}

      if not flags[FLAGS.upgrade] then
        flags[FLAGS.upgrade] = true

        rows[#rows + 1] = {
          "show_text",
          "_MARS_CYCLING_FIRST_WIN",
        }
      else
        game.save.money = math.min(
          999999,
          (game.save.money or 0) + 3000
        )

        rows[#rows + 1] = {
          "show_text",
          "_MARS_CYCLING_REPEAT_WIN",
        }
      end
    elseif rank == 2 then
      rows[#rows + 1] = {
        "show_text",
        "_MARS_CYCLING_SECOND",
      }
    elseif rank == 3 then
      rows[#rows + 1] = {
        "show_text",
        "_MARS_CYCLING_THIRD",
      }
    else
      rows[#rows + 1] = {
        "show_text",
        "_MARS_CYCLING_FOURTH",
      }
    end

    -- Once the result dialogue is finished, hide the transition under black.
    rows[#rows + 1] = {
      "fade",
      "out",
      16,
    }

    -- Delete/hide the three racers that physically came down the hill.
    rows[#rows + 1] = {
      "mars_cycling_finish_swap",
    }

    -- Replace them with the three spread-out dialogue actors while black.
    for _, row in ipairs(postRaceRows(true)) do
      rows[#rows + 1] = row
    end

    rows[#rows + 1] = {
      "wait",
      2,
    }

    rows[#rows + 1] = {
      "fade",
      "in",
      16,
    }

    ow:queueScript(rows)

    mod.log:info(
      "Downhill Dash finished on Route18; rank=%d; black-screen racer swap queued",
      rank
    )
  end

  local function postRaceTalkFor(racer, firstText, gloatText, lastText, jealousText)
    return {
      { "check_flag", FLAGS.rank1 },
      { "jump_if_true", "first" },

      { "check_flag", racer.beatFlag },
      { "jump_if_false", "jealous" },

      { "check_flag", FLAGS.rank4 },
      { "jump_if_true", "last" },

      { "show_text", gloatText },
      { "jump", "end" },

      { "label", "last" },
      { "show_text", lastText },
      { "jump", "end" },

      { "label", "jealous" },
      { "show_text", jealousText },
      { "jump", "end" },

      { "label", "first" },
      { "show_text", firstText },

      { "label", "end" },
    }
  end

  local rexPostTalk = postRaceTalkFor(
    RACERS[1],
    "_MARS_CYCLING_REX_FIRST",
    "_MARS_CYCLING_REX_GLOAT",
    "_MARS_CYCLING_REX_GLOAT_LAST",
    "_MARS_CYCLING_REX_JEALOUS"
  )

  local junePostTalk = postRaceTalkFor(
    RACERS[2],
    "_MARS_CYCLING_JUNE_FIRST",
    "_MARS_CYCLING_JUNE_GLOAT",
    "_MARS_CYCLING_JUNE_GLOAT_LAST",
    "_MARS_CYCLING_JUNE_JEALOUS"
  )

  local marcoPostTalk = postRaceTalkFor(
    RACERS[3],
    "_MARS_CYCLING_MARCO_FIRST",
    "_MARS_CYCLING_MARCO_GLOAT",
    "_MARS_CYCLING_MARCO_GLOAT_LAST",
    "_MARS_CYCLING_MARCO_JEALOUS"
  )

  ---------------------------------------------------------------------------
  -- COMMANDS
  ---------------------------------------------------------------------------

  mod.commands:register(
    "mars_cycling_finish_swap",
    function(ctx)
      -- The three racers can still exist inside Route18's live overworld as
      -- connected Route17 actors. Remove those exact live instances while the
      -- screen is black, then persist Route17's copies as hidden.
      local removed = removeStageRacersFromLiveOverworld(
        ctx.overworld
      )

      setStageRacersVisibleWhileInactive(false)

      mod.log:info(
        "Downhill Dash: removed %d live racing actors during black-screen swap",
        removed
      )
    end
  )

  mod.commands:register(
    "mars_cycling_race_prepare",
    function(ctx)
      race.prepared = true
      race.active = false
      race.startQueued = false
      race.game = ctx.game
      race.ow = nil

      local flags = ctx.game.save.flags or {}
      race.advanced = flags[FLAGS.upgrade] == true

      for _, racer in ipairs(RACERS) do
        racer.stepFrames = race.advanced
          and racer.advancedStepFrames
          or racer.baseStepFrames
      end

      resetRacerProgress()
      clearLastRaceResult(ctx.game)

      -- A new YES starts a completely fresh actor lifecycle. Route16 is active,
      -- so both Route17 and Route18 can be toggled safely without reload loops.
      setPostRacersVisibleWhileInactive(false)
      setStageRacersVisibleWhileInactive(true)
      setAdvancedObstaclesVisibleWhileInactive(race.advanced)

      -- Disable every vanilla Route 17 trainer as soon as the player registers.
      -- Because this is a persistent object toggle, they never spawn when the
      -- player crosses onto Cycling Road and therefore cannot trigger sight.
      setVanillaTrainersVisibleWhileInactive(false)

      -- Keep the three visible lineup NPCs on the map. They are the racers.

      mod.log:info(
        "Downhill Dash registered; advanced=%s; racer frames=%d/%d/%d; "
          .. "Route17 trainers disabled",
        tostring(race.advanced),
        RACERS[1].stepFrames,
        RACERS[2].stepFrames,
        RACERS[3].stepFrames
      )
    end
  )

  mod.commands:register(
    "mars_cycling_race_go",
    function(ctx)
      race.active = true
      race.prepared = true
      race.startQueued = false
      race.game = ctx.game
      race.ow = ctx.overworld

      -- Trainers were already disabled while Route 17 was inactive.
      -- Do NOT call WorldAPI:toggleObject on the active Route 17 map.

      -- Do not start movement from inside the countdown ScriptRunner.
      -- The fixed-tick hook begins all three on the first free gameplay tick.
      for _, racer in ipairs(RACERS) do
        racer.startedMoving = false
        racer.missingNpcLogged = false
      end

      local r1 = currentRacerNpc(RACERS[1])
      local r2 = currentRacerNpc(RACERS[2])
      local r3 = currentRacerNpc(RACERS[3])

      mod.log:info(
        "Downhill Dash GO: live racers=%s/%s/%s; "
          .. "raw NPC movement armed; free player control; trainers disabled",
        tostring(r1 ~= nil),
        tostring(r2 ~= nil),
        tostring(r3 ~= nil)
      )
    end
  )

  ---------------------------------------------------------------------------
  -- PERMANENT BICYCLE UPGRADE
  ---------------------------------------------------------------------------
  mod.hooks:wrap(
    "movement.speed",
    function(next, frames, ctx)
      frames = next(frames, ctx)

      local save = ctx and ctx.save
      local flags = save and save.flags or {}

      if ctx
         and ctx.onBike
         and flags[FLAGS.upgrade]
      then
        return math.max(
          1,
          math.floor(frames * 0.75 + 0.5)
        )
      end

      return frames
    end
  )

  ---------------------------------------------------------------------------
  -- RACE MOVEMENT DRIVER
  ---------------------------------------------------------------------------
  mod.hooks:wrap(
    "input.step",
    function(next, game, dt)
      local result = next(game, dt)

      if race.active
         and race.game == game
      then
        local pos = mod.world:current()

        if pos
           and pos.mapId == RACE_MAP
           and race.ow
           and not (
             race.ow.runner
             and race.ow.runner.isRunning
             and race.ow.runner:isRunning()
           )
        then
          advanceAllRacers()
        end
      end

      return result
    end,
    100
  )

  ---------------------------------------------------------------------------
  -- MAP SCRIPTS
  ---------------------------------------------------------------------------
  -- Post-race actors only exist for the current stay on Route18. As soon as
  -- the player leaves, permanently hide them and discard the previous result.
  mod.events:on("map.entered", function(event)
    if not event
       or event.fromMapId ~= FINISH_MAP
       or event.mapId == FINISH_MAP
    then
      return
    end

    setPostRacersVisibleWhileInactive(false)

    local game = event.game or race.game
    if game then
      clearLastRaceResult(game)
    end

    mod.log:info(
      "Downhill Dash: post-race actors cleared after leaving Route18"
    )
  end)

  if mod.content.map_scripts then
    mod.content.map_scripts:register("ROUTE_16", {
      priority = 230,

      onEnter = function(game, ow)
        if race.active then
          -- Keep the race alive if the player goes north of the start.
          -- A partially animated step is snapped back to its last completed
          -- path cell when Route 17 is restored.
          race.game = game
          race.ow = nil
        end
      end,

      talk = {
        TEXT_MARS_CYCLING_RACE_OFFICIAL = {
          {
            "show_text",
            "_MARS_CYCLING_RACE_INTRO",
          },
          {
            "ask",
            "_MARS_CYCLING_RACE_ASK",
          },
          {
            "jump_if_false",
            "done",
          },
          {
            "mars_cycling_race_prepare",
          },
          {
            "show_text",
            "_MARS_CYCLING_RACE_REGISTERED",
          },
          {
            "label",
            "done",
          },
        },
      },
    })

    mod.content.map_scripts:register(RACE_MAP, {
      priority = 230,

      onEnter = function(game, ow)
        race.game = game
        race.ow = ow

        if race.active then
          -- Returning after briefly riding north: rebuild any racer instance
          -- that may have been removed by the prior finish lifecycle, then
          -- restore its last completed race position.
          ensureStageRacersLive(game, ow, false)

          local rows = trainerRows(false)

          for _, row in ipairs(advancedObstacleRows(race.advanced)) do
            rows[#rows + 1] = row
          end

          for _, row in ipairs(restoreRacersAtProgress()) do
            rows[#rows + 1] = row
          end

          ow:queueScript(rows)

          mod.log:info(
            "Downhill Dash lineup racers restored on Route17 re-entry"
          )
        else
          local rows = {}

          if race.prepared then
            -- The previous finish physically removes these live NPCs. Rebuild
            -- any missing instances and force all three back onto the starting
            -- grid before showing them and starting the countdown.
            ensureStageRacersLive(game, ow, true)

            -- Registered race: disable battle trainers and apply the correct
            -- first-run/advanced-course obstacle layout.
            for _, row in ipairs(trainerRows(false)) do
              rows[#rows + 1] = row
            end

            for _, row in ipairs(advancedObstacleRows(race.advanced)) do
              rows[#rows + 1] = row
            end
          else
            -- No race: restore the normal road and keep race-only obstacles gone.
            for _, row in ipairs(trainerRows(true)) do
              rows[#rows + 1] = row
            end

            for _, row in ipairs(advancedObstacleRows(false)) do
              rows[#rows + 1] = row
            end
          end

          for _, row in ipairs(stageRows(true)) do
            rows[#rows + 1] = row
          end

          if race.prepared then
            for _, racer in ipairs(RACERS) do
              rows[#rows + 1] = {
                "place_npc",
                racer.stageIndex,
                racer.startX,
                LINEUP_Y,
                "down",
              }
            end
          end

          ow:queueScript(rows)

          if race.prepared and not race.startQueued then
            race.startQueued = true

            -- Entering Route17 places the player in the open fourth lane right
            -- beside the three Bikers. Only NOW do we start the countdown.
            ow:queueScript({
              { "wait", 8 },
              { "show_text", "_MARS_CYCLING_COUNTDOWN" },
              { "mars_cycling_race_go" },
            })

            mod.log:info(
              "Downhill Dash player joined lineup; countdown queued"
            )
          end
        end
      end,

      talk = {
        TEXT_MARS_CYCLING_STAGE_RACER = {
          {
            "show_text",
            "_MARS_CYCLING_STAGE_RACER_TEXT",
          },
        },

        TEXT_MARS_CYCLING_ADV_OBSTACLE = {
          {
            "show_text",
            "_MARS_CYCLING_ADV_OBSTACLE_TEXT",
          },
        },
      },
    })

    mod.content.map_scripts:register(FINISH_MAP, {
      priority = 230,

      onEnter = function(game, ow)
        if race.active then
          finishRace(game, ow)
        else
          -- Outside the immediate finish sequence, these actors stay gone.
          ow:queueScript(
            postRaceRows(false)
          )
        end
      end,

      talk = {
        TEXT_MARS_CYCLING_POST_REX = rexPostTalk,
        TEXT_MARS_CYCLING_POST_JUNE = junePostTalk,
        TEXT_MARS_CYCLING_POST_MARCO = marcoPostTalk,

        TEXT_MARS_CYCLING_FINISH_OFFICIAL = {
          {
            "ask",
            "_MARS_CYCLING_FINISH_RETURN",
          },
          {
            "jump_if_false",
            "done",
          },
          {
            "fade",
            "out",
            16,
          },
          {
            "warp",
            "ROUTE_16",
            15,
            13,
            "up",
          },
          {
            "fade",
            "in",
            16,
          },
          {
            "label",
            "done",
          },
        },
      },
    })
  end

  mod.log:info(
    "installed Downhill Dash: permanent 3-racer lineup at Route17 sign; "
      .. "entering fourth lane starts countdown; same visible racers use live NPC movement state on fixed ticks; "
      .. "first race unchanged; repeat races explicitly rebuild/reset the three start racers; upgraded repeats keep six-Biker slalom + faster opponents; finish swap retained"
  )
  end)()


  ---------------------------------------------------------------------------
  -- ROCK TUNNEL "A LONG WAY DOWN" SIDE QUEST
  ---------------------------------------------------------------------------
  ;(function()
  ---------------------------------------------------------------------------
  -- FLOW
  --
  -- 1. Find an injured Hiker off the main path on ROCK_TUNNEL_B1F.
  -- 2. Recover his backpack elsewhere on B1F; a Machoke is rummaging through it.
  -- 3. Return the pack so he can splint his broken leg.
  -- 4. Find his hiking partner near the Route 10 Pokemon Center.
  -- 5. Return to the injured Hiker after the partner heads into the tunnel.
  -- 6. Reward: $5,000 and 3 MAX REPELS.
  ---------------------------------------------------------------------------

  local FLAGS = {
    started = "EVENT_ROCK_TUNNEL_RESCUE_STARTED",
    packRecovered = "EVENT_ROCK_TUNNEL_RESCUE_PACK_RECOVERED",
    splinted = "EVENT_ROCK_TUNNEL_RESCUE_SPLINTED",
    partnerNotified = "EVENT_ROCK_TUNNEL_RESCUE_PARTNER_NOTIFIED",
    complete = "EVENT_ROCK_TUNNEL_RESCUE_COMPLETE",
  }

  local TEXT_HIKER = "TEXT_MARS_ROCK_TUNNEL_INJURED_HIKER"
  local TEXT_PACK = "TEXT_MARS_ROCK_TUNNEL_BACKPACK"
  local TEXT_MACHOKE = "TEXT_MARS_ROCK_TUNNEL_MACHOKE"
  local TEXT_ROUTE10_PARTNER = "TEXT_MARS_ROUTE10_HIKER_PARTNER"
  local TEXT_RESCUE_PARTNER = "TEXT_MARS_ROCK_TUNNEL_RESCUE_PARTNER"

  local caveDef = mod.content.maps:get("ROCK_TUNNEL_B1F")
  local route10Def = mod.content.maps:get("ROUTE_10")
  local MapDef = require("src.world.Map")

  if not caveDef or not route10Def then
    mod.log:error(
      "A Long Way Down requires ROCK_TUNNEL_B1F and ROUTE_10"
    )
    return
  end

  ---------------------------------------------------------------------------
  -- SAFE, REACHABLE OBJECT PLACEMENT
  ---------------------------------------------------------------------------

  local function cellKey(x, y)
    return tostring(x) .. ":" .. tostring(y)
  end

  local function isWalkable(def, tileset, x, y)
    return def
      and tileset
      and x >= 0
      and y >= 0
      and x < def.width * 2
      and y < def.height * 2
      and MapDef.defIsWalkableCell(def, tileset, x, y)
      and not MapDef.defIsWaterCell(def, tileset, x, y)
  end

  local function occupiedCells(def)
    local used = {}

    for _, obj in ipairs(def.objects or {}) do
      if obj.x ~= nil and obj.y ~= nil then
        used[cellKey(obj.x, obj.y)] = true
      end
    end

    for _, warp in ipairs(def.warps or {}) do
      if warp.x ~= nil and warp.y ~= nil then
        used[cellKey(warp.x, warp.y)] = true
      end
    end

    return used
  end

  local function reachableCells(def)
    local tileset = mod.content.tilesets:get(def.tileset)
    local reachable = {}
    local queue = {}
    local head = 1

    local function seed(x, y)
      local key = cellKey(x, y)
      if not reachable[key] and isWalkable(def, tileset, x, y) then
        reachable[key] = true
        queue[#queue + 1] = { x, y }
      end
    end

    -- Seed from every map warp and the walkable cells touching it. This keeps
    -- quest objects in a component the player can actually enter.
    for _, warp in ipairs(def.warps or {}) do
      local x, y = warp.x, warp.y
      if x ~= nil and y ~= nil then
        seed(x, y)
        seed(x - 1, y)
        seed(x + 1, y)
        seed(x, y - 1)
        seed(x, y + 1)
      end
    end

    -- Defensive fallback for maps whose imported warp cell itself is unusual.
    if #queue == 0 then
      for y = 0, def.height * 2 - 1 do
        for x = 0, def.width * 2 - 1 do
          if isWalkable(def, tileset, x, y) then
            seed(x, y)
            break
          end
        end
        if #queue > 0 then break end
      end
    end

    local dirs = {
      { 1, 0 }, { -1, 0 }, { 0, 1 }, { 0, -1 },
    }

    while head <= #queue do
      local node = queue[head]
      head = head + 1

      for _, d in ipairs(dirs) do
        local nx, ny = node[1] + d[1], node[2] + d[2]
        local key = cellKey(nx, ny)

        if not reachable[key]
           and isWalkable(def, tileset, nx, ny)
        then
          reachable[key] = true
          queue[#queue + 1] = { nx, ny }
        end
      end
    end

    return reachable
  end

  local function chooseSpot(def, preferredX, preferredY, used, reachable, minFrom)
    local tileset = mod.content.tilesets:get(def.tileset)
    local bestX, bestY, bestScore = nil, nil, math.huge

    for y = 1, def.height * 2 - 2 do
      for x = 1, def.width * 2 - 2 do
        local key = cellKey(x, y)

        if not used[key]
           and (not reachable or reachable[key])
           and isWalkable(def, tileset, x, y)
        then
          local farEnough = true

          if minFrom then
            local distance =
              math.abs(x - minFrom.x) + math.abs(y - minFrom.y)
            farEnough = distance >= (minFrom.distance or 0)
          end

          if farEnough then
            local score =
              math.abs(x - preferredX) + math.abs(y - preferredY)

            if score < bestScore then
              bestScore = score
              bestX, bestY = x, y
            end
          end
        end
      end
    end

    if bestX then
      used[cellKey(bestX, bestY)] = true
      return bestX, bestY
    end

    return preferredX, preferredY
  end

  local caveUsed = occupiedCells(caveDef)
  local caveReachable = reachableCells(caveDef)
  -- Keep clear of the existing hidden Jaw Fossil.
  caveUsed[cellKey(11, 14)] = true

  local caveW = caveDef.width * 2
  local caveH = caveDef.height * 2

  local hikerX, hikerY = chooseSpot(
    caveDef,
    math.max(2, math.floor(caveW * 0.24)),
    math.max(2, math.floor(caveH * 0.72)),
    caveUsed,
    caveReachable
  )

  local packX, packY = chooseSpot(
    caveDef,
    math.max(2, math.floor(caveW * 0.76)),
    math.max(2, math.floor(caveH * 0.28)),
    caveUsed,
    caveReachable,
    { x = hikerX, y = hikerY, distance = 10 }
  )

  local machokeX, machokeY = chooseSpot(
    caveDef,
    math.min(caveW - 2, packX + 1),
    packY,
    caveUsed,
    caveReachable
  )

  local rescuePartnerX, rescuePartnerY = chooseSpot(
    caveDef,
    math.min(caveW - 2, hikerX + 1),
    hikerY,
    caveUsed,
    caveReachable
  )

  local routeUsed = occupiedCells(route10Def)
  local routeReachable = reachableCells(route10Def)
  local centerDoorX = math.floor(route10Def.width)
  local centerDoorY = math.floor(route10Def.height)

  for _, warp in ipairs(route10Def.warps or {}) do
    local dest = tostring(warp.destMap or "")
    if string.find(dest, "POKECENTER", 1, true)
       or string.find(dest, "POKEMON_CENTER", 1, true)
    then
      centerDoorX, centerDoorY = warp.x, warp.y
      break
    end
  end

  local routePartnerX, routePartnerY = chooseSpot(
    route10Def,
    math.min(route10Def.width * 2 - 2, centerDoorX + 2),
    math.min(route10Def.height * 2 - 2, centerDoorY + 1),
    routeUsed,
    routeReachable
  )

  ---------------------------------------------------------------------------
  -- QUEST OBJECTS
  ---------------------------------------------------------------------------

  local caveBaseIndex = #(caveDef.objects or {}) + 1
  local hikerIndex = caveBaseIndex
  local packIndex = caveBaseIndex + 1
  local machokeIndex = caveBaseIndex + 2
  local rescuePartnerIndex = caveBaseIndex + 3
  local routePartnerIndex = #(route10Def.objects or {}) + 1

  mod.content.sprites:register("SPRITE_MARS_ROCK_TUNNEL_BACKPACK", {
    image = mod.assets:path("assets/rock_tunnel_backpack.png"),
    frames = 1,
    walker = false,
  })

  mod.content.maps:patch("ROCK_TUNNEL_B1F", {
    objects = {
      __append = {
        {
          index = hikerIndex,
          name = "MARS_ROCK_TUNNEL_INJURED_HIKER",
          sprite = "SPRITE_HIKER",
          movement = "STAY",
          range = "ANY_DIR",
          x = hikerX,
          y = hikerY,
          text = TEXT_HIKER,
        },
        {
          index = packIndex,
          name = "MARS_ROCK_TUNNEL_BACKPACK",
          sprite = "SPRITE_MARS_ROCK_TUNNEL_BACKPACK",
          movement = "STAY",
          range = "ANY_DIR",
          x = packX,
          y = packY,
          text = TEXT_PACK,
        },
        {
          index = machokeIndex,
          name = "MARS_ROCK_TUNNEL_PACK_MACHOKE",
          sprite = "SPRITE_MONSTER",
          movement = "STAY",
          range = "ANY_DIR",
          x = machokeX,
          y = machokeY,
          text = TEXT_MACHOKE,
        },
        {
          index = rescuePartnerIndex,
          name = "MARS_ROCK_TUNNEL_RESCUE_PARTNER",
          sprite = "SPRITE_HIKER",
          movement = "STAY",
          range = "ANY_DIR",
          x = rescuePartnerX,
          y = rescuePartnerY,
          text = TEXT_RESCUE_PARTNER,
        },
      },
    },
  })

  mod.content.maps:patch("ROUTE_10", {
    objects = {
      __append = {
        {
          index = routePartnerIndex,
          name = "MARS_ROUTE10_HIKER_PARTNER",
          sprite = "SPRITE_HIKER",
          movement = "STAY",
          range = "ANY_DIR",
          x = routePartnerX,
          y = routePartnerY,
          text = TEXT_ROUTE10_PARTNER,
        },
      },
    },
  })

  ---------------------------------------------------------------------------
  -- MACHOKE BATTLE
  ---------------------------------------------------------------------------

  local machokeDef = mod.content.pokemon:get("MACHOKE")

  mod.content.trainers:register("OPP_ROCK_TUNNEL_RESCUE_MACHOKE", {
    id = "OPP_ROCK_TUNNEL_RESCUE_MACHOKE",
    name = "MACHOKE",
    basePic = "OPP_HIKER",
    pic = machokeDef and machokeDef.spriteFront,
    baseMoney = 0,
    parties = {
      {
        { level = 23, species = "MACHOKE" },
      },
    },
  })

  ---------------------------------------------------------------------------
  -- DIALOGUE
  ---------------------------------------------------------------------------

  mod.content.text:register(
    "_MARS_ROCK_RESCUE_START",
    "HIKER: Ngh... easy!\f"
      .. "I slipped climbing down a\nledge and landed hard.\f"
      .. "Pretty sure my leg's broken.\f"
      .. "My PACK went sliding farther\ninto the tunnel when I fell.\f"
      .. "It's got bandages and tent\nstakes I can use for a splint.\f"
      .. "Could you find it for me?"
  )

  mod.content.text:register(
    "_MARS_ROCK_RESCUE_WAIT_PACK",
    "HIKER: My PACK should be\nsomewhere deeper in B1F.\f"
      .. "I won't be going anywhere."
  )

  mod.content.text:register(
    "_MARS_ROCK_RESCUE_MACHOKE",
    "A MACHOKE is rummaging through\nthe battered backpack!\f"
      .. "It notices you and plants\nitself between you and the PACK!"
  )

  mod.content.text:register(
    "_MARS_ROCK_RESCUE_PACK_FOUND",
    "MACHOKE backs away and\ndisappears into the tunnel.\f"
      .. "You recovered the HIKER'S\nPACK!"
  )

  mod.content.text:register(
    "_MARS_ROCK_RESCUE_SPLINT",
    "HIKER: You actually found it!\f"
      .. "Good. Cloth... tent stakes...\nthis'll do.\f"
      .. "There. Not exactly hospital\nwork, but it'll keep the leg\nstraight.\f"
      .. "My hiking partner is waiting\nnear the ROUTE 10 POKEMON\nCENTER.\f"
      .. "Tell him what happened.\nHe'll know how to get me out."
  )

  mod.content.text:register(
    "_MARS_ROCK_RESCUE_WAIT_PARTNER",
    "HIKER: My partner should still\nbe near the ROUTE 10 POKEMON\nCENTER.\f"
      .. "Tell him I finally found a\nrock tougher than me."
  )

  mod.content.text:register(
    "_MARS_ROCK_RESCUE_PARTNER_ROUTE10",
    "HIKER: What?! He broke his leg?\f"
      .. "Of course he did. I told him\nthat ledge looked bad.\f"
      .. "Thanks for finding me.\nI'll head in and get him."
  )

  mod.content.text:register(
    "_MARS_ROCK_RESCUE_FINAL",
    "HIKER: There you are!\f"
      .. "PARTNER: I found him right\nwhere you said.\f"
      .. "HIKER: Told you I was fine.\f"
      .. "PARTNER: You're sitting on a\ncave floor with a splinted leg.\f"
      .. "HIKER: ...Mostly fine.\f"
      .. "PARTNER: Seriously, thanks.\nWe can handle it from here.\f"
      .. "Take this for all the trouble."
  )

  mod.content.text:register(
    "_MARS_ROCK_RESCUE_BAG_FULL",
    "Your BAG is too full for the\n3 MAX REPELS.\f"
      .. "Make some room and talk to us\nagain."
  )

  mod.content.text:register(
    "_MARS_ROCK_RESCUE_REWARD",
    "You received $5000 and\n3 MAX REPELS!"
  )

  ---------------------------------------------------------------------------
  -- INTERACTIONS
  ---------------------------------------------------------------------------

  local function rockSay(game, textId, done)
    local TextBox = require("src.render.TextBox")
    game.stack:push(
      TextBox.new(game, game.data.text[textId] or textId, done)
    )
  end

  local function faceRockNpc(ow, npc)
    if npc and npc.facePlayer and ow and ow.player then
      npc:facePlayer(ow.player)
    end
  end

  local transitionCallbacks = setmetatable({}, { __mode = "k" })

  mod.commands:register("mars_rock_rescue_transition_done", function(ctx)
    local callback = transitionCallbacks[ctx.game]
    transitionCallbacks[ctx.game] = nil
    if callback then callback() end
  end)

  local function queueTransition(game, ow, rows, callback)
    transitionCallbacks[game] = callback
    rows[#rows + 1] = { "mars_rock_rescue_transition_done" }
    ow:queueScript(rows)
  end

  local function hikerTalk(game, ow, npc, done)
    local flags = game.save.flags or {}
    faceRockNpc(ow, npc)

    if flags[FLAGS.complete] then
      if done then done() end
      return
    end

    if not flags[FLAGS.started] then
      flags[FLAGS.started] = true
      rockSay(game, "_MARS_ROCK_RESCUE_START", done)
      return
    end

    if not flags[FLAGS.packRecovered] then
      rockSay(game, "_MARS_ROCK_RESCUE_WAIT_PACK", done)
      return
    end

    if not flags[FLAGS.splinted] then
      flags[FLAGS.splinted] = true
      rockSay(game, "_MARS_ROCK_RESCUE_SPLINT", done)
      return
    end

    if not flags[FLAGS.partnerNotified] then
      rockSay(game, "_MARS_ROCK_RESCUE_WAIT_PARTNER", done)
      return
    end

    local Bag = require("src.inventory.Bag")

    rockSay(game, "_MARS_ROCK_RESCUE_FINAL", function()
      if not Bag.add(game.save, "MAX_REPEL", 3, game.data) then
        rockSay(game, "_MARS_ROCK_RESCUE_BAG_FULL", done)
        return
      end

      game.save.money = math.min(
        999999,
        (game.save.money or 0) + 5000
      )

      flags[FLAGS.complete] = true

      local Sound = require("src.core.Sound")
      Sound.play(game.data, "Get_Item1")

      rockSay(game, "_MARS_ROCK_RESCUE_REWARD", function()
        queueTransition(
          game,
          ow,
          {
            { "fade", "out", 20 },
            { "wait", 30 },
            {
              "hide_object",
              "ROCK_TUNNEL_B1F",
              "MARS_ROCK_TUNNEL_INJURED_HIKER",
            },
            {
              "hide_object",
              "ROCK_TUNNEL_B1F",
              "MARS_ROCK_TUNNEL_RESCUE_PARTNER",
            },
            { "wait", 20 },
            { "fade", "in", 20 },
          },
          done
        )
      end)
    end)
  end

  local function finishPackRecovery(game, ow, done, battle)
    local flags = game.save.flags or {}
    flags[FLAGS.packRecovered] = true

    queueTransition(
      game,
      ow,
      {
        { "fade", "out", 16 },
        { "wait", 20 },
        {
          "hide_object",
          "ROCK_TUNNEL_B1F",
          "MARS_ROCK_TUNNEL_PACK_MACHOKE",
        },
        {
          "hide_object",
          "ROCK_TUNNEL_B1F",
          "MARS_ROCK_TUNNEL_BACKPACK",
        },
        { "fade", "in", 16 },
      },
      function()
        rockSay(game, "_MARS_ROCK_RESCUE_PACK_FOUND", function()
          if done then done() end
          if battle then ow:afterBattle("win", battle) end
        end)
      end
    )
  end

  local function startMachokeBattle(game, ow, done)
    local flags = game.save.flags or {}

    if flags[FLAGS.packRecovered] then
      if done then done() end
      return
    end

    rockSay(game, "_MARS_ROCK_RESCUE_MACHOKE", function()
      local BattleState = require("src.battle.BattleState")
      local battle = BattleState.newTrainer(
        game,
        "OPP_ROCK_TUNNEL_RESCUE_MACHOKE",
        1
      )

      battle.endBattleText = "MACHOKE: Gwoh!"

      battle.onFinish = function(result)
        if result ~= "win" then
          if done then done() end
          ow:afterBattle(result, battle)
          return
        end

        finishPackRecovery(game, ow, done, battle)
      end

      ow:pushBattle(battle)
    end)
  end

  local function packTalk(game, ow, npc, done)
    local flags = game.save.flags or {}

    if not flags[FLAGS.started] or flags[FLAGS.packRecovered] then
      if done then done() end
      return
    end

    startMachokeBattle(game, ow, done)
  end

  local function routePartnerTalk(game, ow, npc, done)
    local flags = game.save.flags or {}
    faceRockNpc(ow, npc)

    if not flags[FLAGS.splinted]
       or flags[FLAGS.partnerNotified]
       or flags[FLAGS.complete]
    then
      if done then done() end
      return
    end

    rockSay(game, "_MARS_ROCK_RESCUE_PARTNER_ROUTE10", function()
      flags[FLAGS.partnerNotified] = true

      queueTransition(
        game,
        ow,
        {
          { "fade", "out", 20 },
          { "wait", 30 },
          {
            "hide_object",
            "ROUTE_10",
            "MARS_ROUTE10_HIKER_PARTNER",
          },
          { "wait", 20 },
          { "fade", "in", 20 },
        },
        done
      )
    end)
  end

  local function rescuePartnerTalk(game, ow, npc, done)
    local flags = game.save.flags or {}
    faceRockNpc(ow, npc)

    if not flags[FLAGS.partnerNotified] or flags[FLAGS.complete] then
      if done then done() end
      return
    end

    -- Either Hiker can finish the rescue once both are together.
    hikerTalk(game, ow, npc, done)
  end

  ---------------------------------------------------------------------------
  -- MAP STATE
  ---------------------------------------------------------------------------

  if mod.content.map_scripts then
    mod.content.map_scripts:register("ROCK_TUNNEL_B1F", {
      priority = 220,

      onEnter = function(game, ow)
        local flags = game.save.flags or {}

        local showHiker = not flags[FLAGS.complete]
        local showPack =
          flags[FLAGS.started]
          and not flags[FLAGS.packRecovered]
          and not flags[FLAGS.complete]
        local showMachoke = showPack
        local showRescuePartner =
          flags[FLAGS.partnerNotified]
          and not flags[FLAGS.complete]

        ow:queueScript({
          {
            showHiker and "show_object" or "hide_object",
            "ROCK_TUNNEL_B1F",
            "MARS_ROCK_TUNNEL_INJURED_HIKER",
          },
          {
            showPack and "show_object" or "hide_object",
            "ROCK_TUNNEL_B1F",
            "MARS_ROCK_TUNNEL_BACKPACK",
          },
          {
            showMachoke and "show_object" or "hide_object",
            "ROCK_TUNNEL_B1F",
            "MARS_ROCK_TUNNEL_PACK_MACHOKE",
          },
          {
            showRescuePartner and "show_object" or "hide_object",
            "ROCK_TUNNEL_B1F",
            "MARS_ROCK_TUNNEL_RESCUE_PARTNER",
          },
        })
      end,

      talk = {
        [TEXT_HIKER] = hikerTalk,
        [TEXT_PACK] = packTalk,
        [TEXT_MACHOKE] = packTalk,
        [TEXT_RESCUE_PARTNER] = rescuePartnerTalk,
      },
    })

    mod.content.map_scripts:register("ROUTE_10", {
      priority = 220,

      onEnter = function(game, ow)
        local flags = game.save.flags or {}
        local showPartner =
          flags[FLAGS.splinted]
          and not flags[FLAGS.partnerNotified]
          and not flags[FLAGS.complete]

        ow:queueScript({
          {
            showPartner and "show_object" or "hide_object",
            "ROUTE_10",
            "MARS_ROUTE10_HIKER_PARTNER",
          },
        })
      end,

      talk = {
        [TEXT_ROUTE10_PARTNER] = routePartnerTalk,
      },
    })
  end

  mod.log:info(
    "installed Rock Tunnel side quest 'A Long Way Down' "
      .. "+ MACHOKE backpack rescue + $5000/3 MAX REPEL reward"
  )
  end)()


  ---------------------------------------------------------------------------
  -- CINNABAR "AFTERSHOCK" + POSTGAME LEGENDARY BIRDS
  ---------------------------------------------------------------------------
  ;(function()
  ---------------------------------------------------------------------------
  -- AFTERSHOCK
  --
  -- Blaine starts this quest automatically after following the player out of
  -- the Gym once his normal Volcano Badge/TM38 sequence is complete.
  -- The Pokemon Lab confirms that Mt. Cinnabar's repeating tremors are coming
  -- from an old three-station volcanic monitoring network. The player inspects
  -- the 1F seismic sensor, B1F pressure monitor, and B2F main control station,
  -- discovering that wild Aron/Lairon caused only part of the damage. A former
  -- Team Rocket scientist has removed components from the network. After beating
  -- him and recovering the stolen parts, the player must revisit and repair all
  -- three stations before returning to Blaine for TM57 BULLDOZE.
  --
  -- LEGENDARY BIRDS
  --
  -- Articuno, Zapdos, and Moltres are all hidden until
  -- EVENT_BEAT_CHAMPION_RIVAL. Their chambers remain fully explorable during
  -- the main story and contain environmental foreshadowing. After the League,
  -- each bird appears in its established nest independent of Aftershock.
  ---------------------------------------------------------------------------

  local FLAGS = {
    started = "EVENT_CINNABAR_AFTERSHOCK_STARTED",
    introDone = "EVENT_CINNABAR_AFTERSHOCK_INTRO_DONE",
    briefed = "EVENT_CINNABAR_AFTERSHOCK_BRIEFED",
    sensor = "EVENT_CINNABAR_AFTERSHOCK_SENSOR_REPAIRED",
    pressure = "EVENT_CINNABAR_AFTERSHOCK_PRESSURE_REPAIRED",
    scientist = "EVENT_CINNABAR_AFTERSHOCK_SCIENTIST_DEFEATED",
    control = "EVENT_CINNABAR_AFTERSHOCK_CONTROL_REPAIRED",
    repairFlow = "EVENT_CINNABAR_AFTERSHOCK_V190_REPAIR_FLOW",
    tmReceived = "EVENT_CINNABAR_AFTERSHOCK_TM57_RECEIVED",
    complete = "EVENT_CINNABAR_AFTERSHOCK_COMPLETE",
  }

  local TEXT_RESEARCHER = "TEXT_MARS_CINNABAR_AFTERSHOCK_RESEARCHER"
  local TEXT_SENSOR = "TEXT_MARS_AFTERSHOCK_SENSOR"
  local TEXT_PRESSURE = "TEXT_MARS_AFTERSHOCK_PRESSURE"
  local TEXT_CONTROL = "TEXT_MARS_AFTERSHOCK_CONTROL"
  local TEXT_SCIENTIST = "TEXT_MARS_AFTERSHOCK_SCIENTIST"

  local labDef = mod.content.maps:get("CINNABAR_LAB")
  local mt1Def = mod.content.maps:get("MT_CINNABAR_1F")
  local mtB1Def = mod.content.maps:get("MT_CINNABAR_B1F")
  local mtB2Def = mod.content.maps:get("MT_CINNABAR_B2F")

  if not labDef or not mt1Def or not mtB1Def or not mtB2Def then
    mod.log:error(
      "Aftershock requires CINNABAR_LAB and all three Mt. Cinnabar floors"
    )
    return
  end

  ---------------------------------------------------------------------------
  -- SAFE QUEST OBJECT PLACEMENT
  ---------------------------------------------------------------------------

  local MapDef = require("src.world.Map")

  local function questSpot(def, preferredX, preferredY, extraBlocked)
    local tileset = def and mod.content.tilesets:get(def.tileset) or nil
    local occupied = {}

    for _, obj in ipairs((def and def.objects) or {}) do
      occupied[tostring(obj.x) .. ":" .. tostring(obj.y)] = true
    end
    for _, warp in ipairs((def and def.warps) or {}) do
      occupied[tostring(warp.x) .. ":" .. tostring(warp.y)] = true
    end
    for _, pos in ipairs(extraBlocked or {}) do
      occupied[tostring(pos[1]) .. ":" .. tostring(pos[2])] = true
    end

    for radius = 0, 12 do
      for dy = -radius, radius do
        for dx = -radius, radius do
          if radius == 0 or math.max(math.abs(dx), math.abs(dy)) == radius then
            local x = preferredX + dx
            local y = preferredY + dy
            local key = tostring(x) .. ":" .. tostring(y)
            if not occupied[key]
               and x >= 0 and y >= 0
               and x < def.width * 2 and y < def.height * 2
               and tileset
               and MapDef.defIsWalkableCell(def, tileset, x, y)
               and not MapDef.defIsWaterCell(def, tileset, x, y)
            then
              return x, y
            end
          end
        end
      end
    end

    return preferredX, preferredY
  end

  local researcherX, researcherY = questSpot(
    labDef,
    math.max(2, math.floor(labDef.width)),
    math.max(2, math.floor(labDef.height))
  )
  -- Keep the 1F seismic sensor on the SAME CONNECTED WALKABLE REGION as the
  -- actual Mt. Cinnabar entrance. A plain walkability check is not enough for
  -- cave maps: decorative wall geometry can contain isolated floor cells that
  -- are technically walkable but can never be reached by the player.
  local function reachableQuestSpot(def, startX, startY, preferredX, preferredY, extraBlocked)
    local tileset = def and mod.content.tilesets:get(def.tileset) or nil
    if not def or not tileset then
      return preferredX, preferredY
    end

    local width = def.width * 2
    local height = def.height * 2
    local occupied = {}

    for _, obj in ipairs(def.objects or {}) do
      occupied[tostring(obj.x) .. ":" .. tostring(obj.y)] = true
    end
    for _, warp in ipairs(def.warps or {}) do
      occupied[tostring(warp.x) .. ":" .. tostring(warp.y)] = true
    end
    for _, pos in ipairs(extraBlocked or {}) do
      occupied[tostring(pos[1]) .. ":" .. tostring(pos[2])] = true
    end

    local function key(x, y)
      return tostring(x) .. ":" .. tostring(y)
    end

    local function terrainWalkable(x, y)
      return x >= 0 and y >= 0 and x < width and y < height
        and MapDef.defIsWalkableCell(def, tileset, x, y)
        and not MapDef.defIsWaterCell(def, tileset, x, y)
    end

    -- The exterior entrance warps are (24,23) and (25,23). If a particular
    -- imported blockset marks the warp cell itself as non-walkable, seed the
    -- flood fill from the closest neighboring walkable cell instead.
    local seedX, seedY = startX, startY
    if not terrainWalkable(seedX, seedY) then
      local found = false
      for radius = 1, 4 do
        for dy = -radius, radius do
          for dx = -radius, radius do
            if math.max(math.abs(dx), math.abs(dy)) == radius then
              local x, y = startX + dx, startY + dy
              if terrainWalkable(x, y) then
                seedX, seedY = x, y
                found = true
                break
              end
            end
          end
          if found then break end
        end
        if found then break end
      end
    end

    if not terrainWalkable(seedX, seedY) then
      return questSpot(def, preferredX, preferredY, extraBlocked)
    end

    local queue = { { seedX, seedY } }
    local head = 1
    local reachable = { [key(seedX, seedY)] = true }
    local dirs = { {1,0}, {-1,0}, {0,1}, {0,-1} }

    while head <= #queue do
      local cell = queue[head]
      head = head + 1

      for _, dir in ipairs(dirs) do
        local nx = cell[1] + dir[1]
        local ny = cell[2] + dir[2]
        local k = key(nx, ny)
        if not reachable[k] and terrainWalkable(nx, ny) then
          reachable[k] = true
          queue[#queue + 1] = { nx, ny }
        end
      end
    end

    local bestX, bestY, bestDist = nil, nil, nil
    for _, cell in ipairs(queue) do
      local x, y = cell[1], cell[2]
      local k = key(x, y)

      if not occupied[k] then
        -- The station is an NPC-style object, so the player must have at least
        -- one reachable cardinal neighbor from which to face/interact with it.
        local hasInteractionTile = false
        for _, dir in ipairs(dirs) do
          if reachable[key(x + dir[1], y + dir[2])] then
            hasInteractionTile = true
            break
          end
        end

        if hasInteractionTile then
          local dist = math.abs(x - preferredX) + math.abs(y - preferredY)
          if not bestDist or dist < bestDist then
            bestX, bestY, bestDist = x, y, dist
          end
        end
      end
    end

    if bestX then
      return bestX, bestY
    end

    return questSpot(def, preferredX, preferredY, extraBlocked)
  end

  -- place the 1F sensor toward the TOP of the floor, but never in the
  -- route the player needs to reach the B1F stairs. We first enumerate the
  -- entrance-connected region, then prefer upper-floor candidates whose
  -- removal still leaves a route from the entrance to the stair block.
  local function safeUpperSensorSpot(def)
    local tileset = def and mod.content.tilesets:get(def.tileset) or nil
    if not def or not tileset then
      return reachableQuestSpot(def, 24, 23, 22, 7)
    end

    local width = def.width * 2
    local height = def.height * 2
    local dirs = { {1,0}, {-1,0}, {0,1}, {0,-1} }
    local occupied = {}

    local function key(x, y)
      return tostring(x) .. ":" .. tostring(y)
    end

    for _, obj in ipairs(def.objects or {}) do
      occupied[key(obj.x, obj.y)] = true
    end
    for _, warp in ipairs(def.warps or {}) do
      occupied[key(warp.x, warp.y)] = true
    end

    local function walkable(x, y)
      return x >= 0 and y >= 0 and x < width and y < height
        and MapDef.defIsWalkableCell(def, tileset, x, y)
        and not MapDef.defIsWaterCell(def, tileset, x, y)
    end

    -- Find a walkable seed just inside the exterior entrance.
    local seedX, seedY = 24, 23
    if not walkable(seedX, seedY) then
      local found = false
      for radius = 1, 5 do
        for dy = -radius, radius do
          for dx = -radius, radius do
            if math.max(math.abs(dx), math.abs(dy)) == radius then
              local x, y = 24 + dx, 23 + dy
              if walkable(x, y) then
                seedX, seedY = x, y
                found = true
                break
              end
            end
          end
          if found then break end
        end
        if found then break end
      end
    end

    if not walkable(seedX, seedY) then
      return reachableQuestSpot(def, 24, 23, 22, 7)
    end

    local function flood(blockX, blockY)
      local q = { { seedX, seedY } }
      local head = 1
      local seen = { [key(seedX, seedY)] = true }

      while head <= #q do
        local cell = q[head]
        head = head + 1
        for _, d in ipairs(dirs) do
          local nx, ny = cell[1] + d[1], cell[2] + d[2]
          local k = key(nx, ny)
          if not seen[k]
             and not (nx == blockX and ny == blockY)
             and walkable(nx, ny)
          then
            seen[k] = true
            q[#q + 1] = { nx, ny }
          end
        end
      end

      return seen, q
    end

    local baseSeen, reachable = flood(-999, -999)

    -- The stair itself may use a non-walkable warp graphic, so consider the
    -- stair reachable when any cardinal neighbor of its 2x2 authored block is
    -- still connected to the entrance.
    local stairCells = {
      {24,2}, {25,2}, {24,3}, {25,3},
    }

    local function stairStillReachable(blockX, blockY)
      local seen = flood(blockX, blockY)
      for _, stair in ipairs(stairCells) do
        for _, d in ipairs(dirs) do
          if seen[key(stair[1] + d[1], stair[2] + d[2])] then
            return true
          end
        end
      end
      return false
    end

    local bestX, bestY, bestScore = nil, nil, nil
    local upperLimit = math.floor(height * 0.48)

    for _, cell in ipairs(reachable) do
      local x, y = cell[1], cell[2]
      local k = key(x, y)

      if y <= upperLimit and not occupied[k] then
        local neighborCount = 0
        for _, d in ipairs(dirs) do
          if baseSeen[key(x + d[1], y + d[2])] then
            neighborCount = neighborCount + 1
          end
        end

        -- Avoid one-tile corridors. Prefer alcoves/open pockets, and verify
        -- that physically occupying this tile cannot cut off the B1F stairs.
        if neighborCount ~= 2 and neighborCount >= 1
           and stairStillReachable(x, y)
        then
          -- Prefer the upper-right half, but distance is secondary to being
          -- high on the floor and safely out of the traversal route.
          local score = y * 100 + math.abs(x - 20)
          if not bestScore or score < bestScore then
            bestX, bestY, bestScore = x, y, score
          end
        end
      end
    end

    if bestX then
      return bestX, bestY
    end

    -- Conservative fallback: still use entrance reachability and bias high.
    return reachableQuestSpot(def, 24, 23, 22, 7)
  end

  local sensorX, sensorY = safeUpperSensorSpot(mt1Def)
  local pressureX, pressureY = questSpot(mtB1Def, 21, 17)
  local controlX, controlY = questSpot(mtB2Def, 16, 13)
  local scientistX, scientistY = questSpot(
    mtB2Def,
    controlX + 2,
    controlY,
    { { controlX, controlY } }
  )

  local researcherIndex = #(labDef.objects or {}) + 1
  local sensorIndex = #(mt1Def.objects or {}) + 1
  local pressureIndex = #(mtB1Def.objects or {}) + 1
  local controlIndex = #(mtB2Def.objects or {}) + 1
  local scientistIndex = controlIndex + 1

  -- dedicated single-frame monitoring-station sprite.
  mod.content.sprites:register("SPRITE_MARS_AFTERSHOCK_MACHINE", {
    image = mod.assets:path("assets/aftershock_machine.png"),
    frames = 1,
    walker = false,
  })

  mod.content.maps:patch("CINNABAR_LAB", {
    objects = {
      __append = {
        {
          index = researcherIndex,
          name = "MARS_CINNABAR_AFTERSHOCK_RESEARCHER",
          sprite = "SPRITE_SCIENTIST",
          movement = "STAY",
          range = "ANY_DIR",
          x = researcherX,
          y = researcherY,
          text = TEXT_RESEARCHER,
          hidden = true,
        },
      },
    },
  })

  mod.content.maps:patch("MT_CINNABAR_1F", {
    objects = {
      __append = {
        {
          index = sensorIndex,
          name = "MARS_AFTERSHOCK_SENSOR",
          sprite = "SPRITE_MARS_AFTERSHOCK_MACHINE",
          movement = "STAY",
          range = "NONE",
          x = sensorX,
          y = sensorY,
          text = TEXT_SENSOR,
          hidden = true,
        },
      },
    },
  })

  mod.content.maps:patch("MT_CINNABAR_B1F", {
    objects = {
      __append = {
        {
          index = pressureIndex,
          name = "MARS_AFTERSHOCK_PRESSURE",
          sprite = "SPRITE_MARS_AFTERSHOCK_MACHINE",
          movement = "STAY",
          range = "NONE",
          x = pressureX,
          y = pressureY,
          text = TEXT_PRESSURE,
          hidden = true,
        },
      },
    },
  })

  mod.content.maps:patch("MT_CINNABAR_B2F", {
    objects = {
      __append = {
        {
          index = controlIndex,
          name = "MARS_AFTERSHOCK_CONTROL",
          sprite = "SPRITE_MARS_AFTERSHOCK_MACHINE",
          movement = "STAY",
          range = "NONE",
          x = controlX,
          y = controlY,
          text = TEXT_CONTROL,
          hidden = true,
        },
        {
          index = scientistIndex,
          name = "MARS_AFTERSHOCK_SCIENTIST",
          sprite = "SPRITE_SCIENTIST",
          movement = "STAY",
          range = "ANY_DIR",
          x = scientistX,
          y = scientistY,
          text = TEXT_SCIENTIST,
          hidden = true,
        },
      },
    },
  })

  ---------------------------------------------------------------------------
  -- AFTERSHOCK TRAINER
  ---------------------------------------------------------------------------

  mod.content.trainers:register("OPP_CINNABAR_AFTERSHOCK_SCIENTIST", {
    id = "OPP_CINNABAR_AFTERSHOCK_SCIENTIST",
    name = "ROCKET SCIENTIST",
    basePic = "OPP_SCIENTIST",
    baseMoney = 35,
    aiClass = (mod.content.trainers:get("OPP_SCIENTIST") or {}).aiClass,
    aiMods = (mod.content.trainers:get("OPP_SCIENTIST") or {}).aiMods,
    parties = {
      {
        { level = 40, species = "MAGNETON" },
        { level = 41, species = "WEEZING" },
        { level = 42, species = "ELECTRODE" },
      },
    },
  })

  ---------------------------------------------------------------------------
  -- AFTERSHOCK DIALOGUE
  ---------------------------------------------------------------------------

  mod.content.text:register(
    "_MARS_AFTERSHOCK_BLAINE_START",
    "BLAINE: Wait!\f"
      .. "I almost forgot! There's an\nimportant task I need taken\ncare of.\f"
