  ---------------------------------------------------------------------------
  -- AFTERSHOCK INTERACTIONS
  ---------------------------------------------------------------------------

  local function say(game, textId, done)
    local TextBox = require("src.render.TextBox")
    game.stack:push(TextBox.new(game, game.data.text[textId] or textId, done))
  end

  local function faceNpc(ow, npc)
    if npc and npc.facePlayer and ow and ow.player then
      npc:facePlayer(ow.player)
    end
  end

  local function allAftershockStationsRepaired(flags)
    return flags[FLAGS.sensor]
      and flags[FLAGS.pressure]
      and flags[FLAGS.control]
  end

  -- Old test saves may contain repairs performed before the scientist battle.
  -- Reset them once for unfinished quests so the new repair phase is enforced.
  local function normalizeAftershockRepairFlow(flags)
    if not flags
       or not flags[FLAGS.briefed]
       or flags[FLAGS.complete]
       or flags[FLAGS.repairFlow]
    then
      return
    end

    flags[FLAGS.sensor] = false
    flags[FLAGS.pressure] = false
    flags[FLAGS.control] = false
    flags[FLAGS.repairFlow] = true
  end

  local function researcherTalk(game, ow, npc, done)
    local flags = game.save.flags or {}
    faceNpc(ow, npc)

    if not flags[FLAGS.started] then
      if done then done() end
      return
    end

    normalizeAftershockRepairFlow(flags)

    if flags[FLAGS.briefed] then
      say(game, "_MARS_AFTERSHOCK_RESEARCHER_AFTER", done)
      return
    end

    flags[FLAGS.sensor] = false
    flags[FLAGS.pressure] = false
    flags[FLAGS.control] = false
    flags[FLAGS.repairFlow] = true
    flags[FLAGS.briefed] = true
    say(game, "_MARS_AFTERSHOCK_RESEARCHER", done)
  end

  local function finishAftershockRepair(game, flags, repairText, done)
    say(game, repairText, function()
      if flags[FLAGS.scientist] and allAftershockStationsRepaired(flags) then
        say(game, "_MARS_AFTERSHOCK_RETURN_TO_BLAINE", done)
      elseif done then
        done()
      end
    end)
  end

  local function repairStation(flagKey, damagedText, repairText, doneText)
    return function(game, ow, npc, done)
      local flags = game.save.flags or {}
      normalizeAftershockRepairFlow(flags)

      if not flags[FLAGS.briefed] then
        if done then done() end
        return
      end

      if flags[flagKey] then
        say(game, doneText, done)
        return
      end

      -- Before the scientist is defeated, this is inspection only.
      if not flags[FLAGS.scientist] then
        say(game, damagedText, done)
        return
      end

      flags[flagKey] = true
      finishAftershockRepair(game, flags, repairText, done)
    end
  end

  local sensorTalk = repairStation(
    FLAGS.sensor,
    "_MARS_AFTERSHOCK_SENSOR_DAMAGED",
    "_MARS_AFTERSHOCK_SENSOR_REPAIR",
    "_MARS_AFTERSHOCK_SENSOR_DONE"
  )

  local pressureTalk = repairStation(
    FLAGS.pressure,
    "_MARS_AFTERSHOCK_PRESSURE_DAMAGED",
    "_MARS_AFTERSHOCK_PRESSURE_REPAIR",
    "_MARS_AFTERSHOCK_PRESSURE_DONE"
  )

  local function controlTalk(game, ow, npc, done)
    local flags = game.save.flags or {}
    normalizeAftershockRepairFlow(flags)

    if not flags[FLAGS.briefed] then
      if done then done() end
      return
    end

    if flags[FLAGS.control] then
      say(game, "_MARS_AFTERSHOCK_CONTROL_DONE", done)
      return
    end

    if not flags[FLAGS.scientist] then
      say(game, "_MARS_AFTERSHOCK_CONTROL_BLOCKED", done)
      return
    end

    flags[FLAGS.control] = true
    finishAftershockRepair(
      game,
      flags,
      "_MARS_AFTERSHOCK_CONTROL_REPAIR",
      done
    )
  end

  local aftershockScientistExitCallbacks = setmetatable({}, { __mode = "k" })

  mod.commands:register("mars_aftershock_scientist_exit_done", function(ctx)
    local callback = aftershockScientistExitCallbacks[ctx.game]
    aftershockScientistExitCallbacks[ctx.game] = nil
    if callback then callback() end
  end)

  local function queueAftershockScientistExit(game, ow, callback)
    aftershockScientistExitCallbacks[game] = callback
    ow:queueScript({
      { "fade", "out", 20 },
      { "wait", 15 },
      { "hide_object", "MT_CINNABAR_B2F", "MARS_AFTERSHOCK_SCIENTIST" },
      { "wait", 15 },
      { "fade", "in", 20 },
      { "mars_aftershock_scientist_exit_done" },
    })
  end

  local function scientistBattle(game, ow, done)
    local flags = game.save.flags or {}
    normalizeAftershockRepairFlow(flags)

    local BattleState = require("src.battle.BattleState")
    local battle = BattleState.newTrainer(
      game,
      "OPP_CINNABAR_AFTERSHOCK_SCIENTIST",
      1
    )

    battle.endBattleText = "My equipment!"

    battle.onFinish = function(result)
      if result ~= "win" then
        if done then done() end
        ow:afterBattle(result, battle)
        return
      end

      flags[FLAGS.scientist] = true
      say(game, "_MARS_AFTERSHOCK_SCIENTIST_WIN", function()
        queueAftershockScientistExit(game, ow, function()
          say(game, "_MARS_AFTERSHOCK_REPAIRS_UNLOCKED", function()
            if done then done() end
            ow:afterBattle("win", battle)
          end)
        end)
      end)
    end

    ow:pushBattle(battle)
  end

  local function scientistTalk(game, ow, npc, done)
    local flags = game.save.flags or {}
    normalizeAftershockRepairFlow(flags)
    faceNpc(ow, npc)

    if not flags[FLAGS.briefed] or flags[FLAGS.scientist] then
      if done then done() end
      return
    end

    say(game, "_MARS_AFTERSHOCK_SCIENTIST_INTRO", function()
      scientistBattle(game, ow, done)
    end)
  end

  ---------------------------------------------------------------------------
  -- AFTERSHOCK MAP STATE
