  if mod.content.map_scripts then
    -------------------------------------------------------------------------
    -- AUTOMATIC POST-GYM RECRUITMENT
    --
    -- The exterior Gym warp is at (34,3). The engine places the player one
    -- cell below it at (34,4) after leaving the Gym. For this scene, do not
    -- dynamically search for positions: the choreography is deliberately
    -- authored around the doorway so Blaine visibly comes out of the same
    -- door the player just used.
    --
    --   1. Player automatically walks DOWN from (34,4) to (34,5).
    --   2. Blaine appears in the doorway at (34,3).
    --   3. Blaine walks DOWN once to (34,4), directly in front of the player.
    --   4. He gives the Aftershock introduction.
    --   5. Blaine walks UP into the doorway and is hidden again.
    --
    -- Requiring the exact post-warp player cell prevents the scene from
    -- triggering merely because an old save enters Cinnabar near the Gym.
    -------------------------------------------------------------------------
    -- do not use EVENT_CINNABAR_AFTERSHOCK_STARTED as the one-time
    -- cutscene latch. Earlier test builds could set that flag before a broken
    -- exterior scene finished, which caused every corrected build to skip the
    -- scene forever on the same save. INTRO_DONE tracks the choreography
    -- separately, while STARTED remains the actual quest-state flag.
    --
    -- map.entered is also a stronger trigger than checking the player's cell in
    -- onEnter: it exposes fromMapId/via, so this can only fire when the player
    -- actually walks out of CINNABAR_GYM.
    mod.events:on("map.entered", function(event)
      if not event
         or event.mapId ~= "CINNABAR_ISLAND"
         or event.fromMapId ~= "CINNABAR_GYM"
      then
        return
      end

      local world = mod.world
      if not world then return end

      -- The exterior Blaine is only a staging actor. Force him hidden first
      -- in case a previous interrupted test build left his object toggle on.
      world:toggleObject(
        "CINNABAR_ISLAND",
        "MARS_AFTERSHOCK_BLAINE_EXTERIOR",
        false
      )

      local shouldStart = world:getFlag("EVENT_BEAT_BLAINE")
        and world:getFlag("EVENT_GOT_TM38")
        and not world:getFlag(FLAGS.introDone)
        and not world:getFlag(FLAGS.briefed)

      if not shouldStart then return end

      local pos = world:current()
      if not pos or pos.mapId ~= "CINNABAR_ISLAND" then return end

      local rows = {}

      -- Normal Gym exit placement is (34,4). The y==3 fallback makes the
      -- scene tolerant of engine/import variants that report the door cell
      -- itself at map.entered time. Either way the player ends at (34,5)
      -- before Blaine appears.
      if pos.x == 34 and pos.y == 4 then
        rows[#rows + 1] = { "move_player", "down", 1 }
      elseif pos.x == 34 and pos.y == 3 then
        rows[#rows + 1] = { "move_player", "down", 2 }
      else
        mod.log:warn(
          "Aftershock Gym-exit scene got unexpected Cinnabar arrival (%s,%s); "
            .. "expected (34,4)",
          tostring(pos.x),
          tostring(pos.y)
        )
        return
      end

      rows[#rows + 1] = { "face_player_dir", "up" }
      rows[#rows + 1] = {
        "show_object",
        "CINNABAR_ISLAND",
        "MARS_AFTERSHOCK_BLAINE_EXTERIOR",
      }
      rows[#rows + 1] = { "place_npc", 90, 34, 3, "down" }
      rows[#rows + 1] = { "move_npc_to", 90, 34, 4 }
      rows[#rows + 1] = { "face_object", 90, "down" }
      rows[#rows + 1] = { "show_text", "_MARS_AFTERSHOCK_BLAINE_START" }
      rows[#rows + 1] = { "set_flag", FLAGS.started }
      rows[#rows + 1] = { "set_flag", FLAGS.introDone }
      rows[#rows + 1] = { "face_object", 90, "up" }
      rows[#rows + 1] = { "move_npc_to", 90, 34, 3 }
      rows[#rows + 1] = {
        "hide_object",
        "CINNABAR_ISLAND",
        "MARS_AFTERSHOCK_BLAINE_EXTERIOR",
      }

      world:queueScript(rows)
    end)

    mod.content.map_scripts:register("CINNABAR_LAB", {
      priority = 230,
      onEnter = function(game, ow)
        local flags = game.save.flags or {}
        local show = flags[FLAGS.started] and not flags[FLAGS.briefed]
        ow:queueScript({
          {
            show and "show_object" or "hide_object",
            "CINNABAR_LAB",
            "MARS_CINNABAR_AFTERSHOCK_RESEARCHER",
          },
        })
      end,
      talk = {
        [TEXT_RESEARCHER] = researcherTalk,
      },
    })

    mod.content.map_scripts:register("MT_CINNABAR_1F", {
      priority = 230,


      onEnter = function(game, ow)
        local flags = game.save.flags or {}
        normalizeAftershockRepairFlow(flags)
        local show = flags[FLAGS.briefed]
        ow:queueScript({
          {
            show and "show_object" or "hide_object",
            "MT_CINNABAR_1F",
            "MARS_AFTERSHOCK_SENSOR",
          },
        })
      end,
      talk = {
        [TEXT_SENSOR] = sensorTalk,
      },
    })

    mod.content.map_scripts:register("MT_CINNABAR_B1F", {
      priority = 230,


      onEnter = function(game, ow)
        local flags = game.save.flags or {}
        normalizeAftershockRepairFlow(flags)
        local show = flags[FLAGS.briefed]
        ow:queueScript({
          {
            show and "show_object" or "hide_object",
            "MT_CINNABAR_B1F",
            "MARS_AFTERSHOCK_PRESSURE",
          },
        })
      end,
      talk = {
        [TEXT_PRESSURE] = pressureTalk,
      },
    })

    mod.content.map_scripts:register("MT_CINNABAR_B2F", {
      priority = 230,


      onEnter = function(game, ow)
        local flags = game.save.flags or {}
        normalizeAftershockRepairFlow(flags)
