        local showScientist = flags[FLAGS.briefed] and not flags[FLAGS.scientist]
        ow:queueScript({
          {
            showControl and "show_object" or "hide_object",
            "MT_CINNABAR_B2F",
            "MARS_AFTERSHOCK_CONTROL",
          },
          {
            showScientist and "show_object" or "hide_object",
            "MT_CINNABAR_B2F",
            "MARS_AFTERSHOCK_SCIENTIST",
          },
        })
      end,
      talk = {
        [TEXT_CONTROL] = controlTalk,
        [TEXT_SCIENTIST] = scientistTalk,
      },
    })
  end

