  local function hideStaticUntilChampion(mapId, species, fallbackName)
    local def = mod.content.maps:get(mapId)
    if not def or type(def.objects) ~= "table" then
      mod.log:warn("could not inspect " .. tostring(mapId) .. " for " .. species)
      return nil, nil, nil
    end

    local objects = {}
    local foundName, foundX, foundY

    for i, obj in ipairs(def.objects) do
      local copy = {}
      for key, value in pairs(obj) do copy[key] = value end

      if obj.pokemon == species then
        copy.name = obj.name or fallbackName
        copy.hidden = true
        foundName = copy.name
        foundX = obj.x
        foundY = obj.y
      end

      objects[i] = copy
    end

    if not foundName then
      mod.log:warn("could not find static " .. species .. " on " .. mapId)
      return nil, nil, nil
    end

    mod.content.maps:patch(mapId, { objects = objects })
    return foundName, foundX, foundY
  end

