  ---------------------------------------------------------------------------
  -- POSTGAME CELEBI QUEST — "ECHOES OF TIME"
  --
  -- Progression:
  --   Oak's Lab -> Viridian Forest -> Pokemon Tower 4F -> Celadon Woods
  --   -> Pokemon Mansion B1F -> Viridian Deepwood -> Ancient Shard + Celebi
  --   -> Oak's Lab epilogue.
  --
  -- The "time travel" presentation intentionally never swaps maps. Each
  -- temporal portal uses a short opaque white screen before and after a lore
  -- fragment, implying that the player briefly experiences another point in
  -- the location's history while standing in the present-day map.
  ---------------------------------------------------------------------------
  ;(function()

  local MapDef = require("src.world.Map")
  local MapScripts = require("src.script.MapScripts")

  local Q = {
    started  = "EVENT_CELEBI_ECHOES_STARTED",
    forest   = "EVENT_CELEBI_ECHOES_FOREST",
    tower    = "EVENT_CELEBI_ECHOES_TOWER",
    celadon  = "EVENT_CELEBI_ECHOES_CELADON",
    cinnabar = "EVENT_CELEBI_ECHOES_CINNABAR",
    deepwood = "EVENT_CELEBI_ECHOES_DEEPWOOD",
    shard    = "EVENT_CELEBI_ANCIENT_SHARD_TAKEN",
    caught   = "EVENT_CAUGHT_MARS_CELEBI",
    complete = "EVENT_CELEBI_ECHOES_COMPLETE",
  }

  local MAP_OAK      = "OAKS_LAB"
  local MAP_FOREST   = "VIRIDIAN_FOREST"
  local MAP_TOWER    = "POKEMON_TOWER_4F"
  local MAP_CELADON  = "CELADON_WOODS"
  local MAP_CINNABAR = "POKEMON_MANSION_B1F"
  local MAP_DEEPWOOD = "VIRIDIAN_DEEPWOOD"

  local TEXT_OAK = "TEXT_OAKSLAB_OAK1"
  local TEXT_FOREST   = "TEXT_MARS_CELEBI_PORTAL_FOREST"
  local TEXT_TOWER    = "TEXT_MARS_CELEBI_PORTAL_TOWER"
  local TEXT_CELADON  = "TEXT_MARS_CELEBI_PORTAL_CELADON"
  local TEXT_CINNABAR = "TEXT_MARS_CELEBI_PORTAL_CINNABAR"
  local TEXT_DEEPWOOD = "TEXT_MARS_CELEBI_PORTAL_DEEPWOOD"
  local TEXT_SHARD    = "TEXT_MARS_CELEBI_ANCIENT_SHARD"
  local TEXT_CELEBI   = "TEXT_MARS_CELEBI_ENCOUNTER"

  local requiredMaps = {
    MAP_OAK,
    MAP_FOREST,
    MAP_TOWER,
    MAP_CELADON,
    MAP_CINNABAR,
    MAP_DEEPWOOD,
  }

  local defs = {}
  for _, mapId in ipairs(requiredMaps) do
    defs[mapId] = mod.content.maps:get(mapId)
    if not defs[mapId] then
      mod.log:error(
        "Echoes of Time missing required map: %s",
        mapId
      )
      return
    end
  end

  ---------------------------------------------------------------------------
  -- CUSTOM KEY ITEM + EVENT SPRITES
  ---------------------------------------------------------------------------

  if not mod.content.items:get("ANCIENT_SHARD") then
    mod.content.items:register("ANCIENT_SHARD", {
      id = "ANCIENT_SHARD",
      name = "ANCIENT SHARD",
      price = 0,
      pocket = "KEY_ITEM",
      keyItem = true,
      tossable = false,
    })
  end

  mod.content.sprites:register("SPRITE_MARS_TEMPORAL_PORTAL", {
    image = mod.assets:path("assets/temporal_portal.png"),
    frames = 1,
    walker = false,
  })

  mod.content.sprites:register("SPRITE_MARS_ANCIENT_SHARD", {
    image = mod.assets:path("assets/ancient_shard.png"),
    frames = 1,
    walker = false,
  })

  mod.content.sprites:register("SPRITE_MARS_RUNE_MONOLITH", {
    image = mod.assets:path("assets/rune_monolith.png"),
    frames = 1,
    walker = false,
  })

  ---------------------------------------------------------------------------
  -- WHITE TEMPORAL FLASH
  ---------------------------------------------------------------------------

  -- Match the established 20-frame black fades used elsewhere in the mod.
  -- One temporal flash is a 20-frame fade to white followed by a 20-frame
  -- fade back to the overworld, rather than an abrupt opaque blink.
  mod.content.screens:register("MarsTemporalFlash", {
    new = function(game)
      local self = {
        game = game,
        isOpaque = false,
        frames = 0,
        fadeFrames = 20,
      }

      function self:update(dt)
        self.frames = self.frames + 1
        if self.frames >= self.fadeFrames * 2 then
          game.stack:pop()
        end
      end

      function self:draw()
        local total = self.fadeFrames * 2
        local alpha

        if self.frames <= self.fadeFrames then
          alpha = self.frames / self.fadeFrames
        else
          alpha = (total - self.frames) / self.fadeFrames
        end

        if alpha < 0 then alpha = 0 end
        if alpha > 1 then alpha = 1 end

        love.graphics.setColor(1, 1, 1, alpha)
        love.graphics.rectangle("fill", 0, 0, 160, 144)
        love.graphics.setColor(1, 1, 1, 1)
      end

      return self
    end,
  })

  ---------------------------------------------------------------------------
  -- SAFE OBJECT PLACEMENT
  ---------------------------------------------------------------------------

  local function cellKey(x, y)
    return tostring(x) .. ":" .. tostring(y)
  end

  local function tilesetFor(def)
    return def and mod.content.tilesets:get(def.tileset) or nil
  end

  local function occupiedCells(def)
    local used = {}

    for _, obj in ipairs(def and def.objects or {}) do
      used[cellKey(obj.x, obj.y)] = true
    end

    for _, warp in ipairs(def and def.warps or {}) do
      used[cellKey(warp.x, warp.y)] = true
    end

    return used
  end

  local function walkable(def, tileset, x, y)
    if not def or not tileset then return false end

    local w = (def.width or 0) * 2
    local h = (def.height or 0) * 2

    if x < 0 or y < 0 or x >= w or y >= h then
      return false
    end

    return MapDef.defIsWalkableCell(def, tileset, x, y)
  end

  local function nearestOpen(def, preferredX, preferredY, extraUsed, radius)
    local tileset = tilesetFor(def)
    local used = occupiedCells(def)

    for key in pairs(extraUsed or {}) do
      used[key] = true
    end

    for r = 0, (radius or 40) do
      for dy = -r, r do
        for dx = -r, r do
          if r == 0
             or math.max(math.abs(dx), math.abs(dy)) == r
          then
            local x = preferredX + dx
            local y = preferredY + dy
            local key = cellKey(x, y)

            if not used[key]
               and walkable(def, tileset, x, y)
            then
              if extraUsed then
                extraUsed[key] = true
              end
              return x, y
            end
          end
        end
      end
    end

    return preferredX, preferredY
  end

  local function objectByName(def, name)
    for _, obj in ipairs(def and def.objects or {}) do
      if obj.name == name then
        return obj
      end
    end
    return nil
  end

  ---------------------------------------------------------------------------
  -- OBJECT COORDINATES
  ---------------------------------------------------------------------------

  local oakDef = defs[MAP_OAK]
  local forestDef = defs[MAP_FOREST]
  local towerDef = defs[MAP_TOWER]
  local celadonDef = defs[MAP_CELADON]
  local cinnabarDef = defs[MAP_CINNABAR]
  local deepwoodDef = defs[MAP_DEEPWOOD]

  local forestX, forestY = nearestOpen(
    forestDef,
    math.floor((forestDef.width or 17) * 1.35),
    math.floor((forestDef.height or 24) * 1.15),
    {},
    50
  )

  local towerX, towerY = nearestOpen(
    towerDef,
    math.floor(towerDef.width or 10),
    math.floor(towerDef.height or 9),
    {},
    30
  )

  -- Tie Celadon's portal directly to the old Pretty Flower clearing.
  local prettyFlower = objectByName(
    celadonDef,
    "CELADON_WOODS_PRETTY_FLOWER"
  )
  local celadonPreferredX = prettyFlower
    and prettyFlower.x + 2
    or math.floor((celadonDef.width or 18) * 1.2)
  local celadonPreferredY = prettyFlower
    and prettyFlower.y
    or math.floor((celadonDef.height or 18) * 1.2)

  local celadonX, celadonY = nearestOpen(
    celadonDef,
    celadonPreferredX,
    celadonPreferredY,
    {},
    35
  )

  local cinnabarX, cinnabarY = nearestOpen(
    cinnabarDef,
    math.floor(cinnabarDef.width or 10),
    math.floor(cinnabarDef.height or 9),
    {},
    35
