  local deepUsed = {}
  local deepX, deepY = nearestOpen(
    deepwoodDef,
    (deepwoodDef.width or 14) * 2 - 5,
    (deepwoodDef.height or 12) * 2 - 5,
    deepUsed,
    40
  )

  -- authored Deepwood finale staging.
  --
  -- The player stands immediately below the portal while interacting with it.
  -- After the second white flash:
  --   * the Ancient Shard occupies the portal's old tile;
  --   * Celebi appears exactly one row above the Shard.
  --
  -- Do not use nearestOpen() for these two finale actors, because that can
  -- relocate them sideways around the player and ruin the intended reveal.
  local shardX, shardY = deepX, deepY
  local celebiX, celebiY = deepX, deepY - 1

  ---------------------------------------------------------------------------
  -- TEMPORAL MEMORY ACTORS
  --
  -- These NPCs are hidden during normal exploration. The first white flash
  -- reveals them for the lore fragment, and the second flash removes them
  -- again before control returns to the present.
  ---------------------------------------------------------------------------

  local function memoryPositions(def, centerX, centerY, offsets)
    local used = {
      [cellKey(centerX, centerY)] = true,
    }
    local result = {}

    for i, offset in ipairs(offsets) do
      local x, y = nearestOpen(
        def,
        centerX + offset[1],
        centerY + offset[2],
        used,
        14
      )
      result[i] = { x = x, y = y }
    end

    return result
  end

  local forestMemoryPos = memoryPositions(forestDef, forestX, forestY, {
    { -2, -1 },
    {  2, -1 },
  })

  local towerMemoryPos = memoryPositions(towerDef, towerX, towerY, {
    { -2, -1 },
    {  2, -1 },
    { -2,  2 },
    {  2,  2 },
  })

  local celadonMemoryPos = memoryPositions(celadonDef, celadonX, celadonY, {
    { -2,  0 },
    {  0, -2 },
    {  2,  0 },
  })

  local cinnabarMemoryPos = memoryPositions(cinnabarDef, cinnabarX, cinnabarY, {
    { -2, -1 },
    {  2, -1 },
  })

  local deepwoodMemoryPos = memoryPositions(deepwoodDef, deepX, deepY, {
    { -2, -1 },
    {  2, -1 },
    {  0, -3 },
  })

