  ---------------------------------------------------------------------------
  -- PORTAL SCRIPT HELPERS
  ---------------------------------------------------------------------------

  local function flashRow()
    return { "push_screen", "MarsTemporalFlash" }
  end

  local function portalScript(
    mapId,
    doneFlag,
    touchText,
    fragmentText,
    memoryNames,
    extraRows
  )
    local rows = {
      { "show_text", touchText },
      flashRow(),
    }

    -- The memory's people exist only between the two temporal flashes.
    for _, name in ipairs(memoryNames or {}) do
      rows[#rows + 1] = { "show_object", mapId, name }
    end

    rows[#rows + 1] = { "show_text", fragmentText }
    rows[#rows + 1] = flashRow()

    for _, name in ipairs(memoryNames or {}) do
      rows[#rows + 1] = { "hide_object", mapId, name }
    end

    rows[#rows + 1] = { "set_flag", doneFlag }

    for _, row in ipairs(extraRows or {}) do
      rows[#rows + 1] = row
    end

    return rows
  end

  local forestScript = portalScript(
    MAP_FOREST,
    Q.forest,
    "_MARS_CELEBI_FOREST_TOUCH",
    "_MARS_CELEBI_FOREST_FRAGMENT",
    forestMemoryNames,
    {
