  -- Deepwood is the conclusion of the temporal-fragment chain, so it
  -- needs more than the generic "reveal two objects and stop" portal flow.
  -- After the second white flash, reveal the shard and Celebi immediately,
  -- award the shard, then launch the Celebi encounter.  If the bag is full,
  -- give_item halts before the shard flag is set and both objects remain on
  -- the map so the player can recover normally.  If Celebi is not caught,
  -- its overworld object remains for a retry.
  local deepwoodScript = {
    { "show_text", "_MARS_CELEBI_DEEPWOOD_TOUCH" },
    flashRow(),
  }

  for _, name in ipairs(deepwoodMemoryNames or {}) do
    deepwoodScript[#deepwoodScript + 1] =
      { "show_object", MAP_DEEPWOOD, name }
  end

  deepwoodScript[#deepwoodScript + 1] =
    { "show_text", "_MARS_CELEBI_DEEPWOOD_FRAGMENT" }
  deepwoodScript[#deepwoodScript + 1] = flashRow()

  for _, name in ipairs(deepwoodMemoryNames or {}) do
    deepwoodScript[#deepwoodScript + 1] =
      { "hide_object", MAP_DEEPWOOD, name }
  end

  deepwoodScript[#deepwoodScript + 1] = { "set_flag", Q.deepwood }
  deepwoodScript[#deepwoodScript + 1] =
    { "hide_object", MAP_DEEPWOOD, "MARS_CELEBI_PORTAL_DEEPWOOD" }

  -- Make the ending actors visible as soon as the player returns from the
  -- second white flash, before the narration describes them.
  deepwoodScript[#deepwoodScript + 1] =
    { "show_object", MAP_DEEPWOOD, "MARS_CELEBI_ANCIENT_SHARD" }
  deepwoodScript[#deepwoodScript + 1] =
    { "show_object", MAP_DEEPWOOD, "MARS_CELEBI_ENCOUNTER" }
  deepwoodScript[#deepwoodScript + 1] =
    { "show_text", "_MARS_CELEBI_DEEPWOOD_AFTER" }

  -- Pick up the shard as part of the scene instead of requiring a separate
  -- interaction with the newly spawned marker.
  deepwoodScript[#deepwoodScript + 1] = {
    "give_item",
    "ANCIENT_SHARD",
    1,
    "_MARS_CELEBI_SHARD_FOUND",
  }
  deepwoodScript[#deepwoodScript + 1] = { "set_flag", Q.shard }
  deepwoodScript[#deepwoodScript + 1] =
    { "hide_object", MAP_DEEPWOOD, "MARS_CELEBI_ANCIENT_SHARD" }

  -- Celebi immediately steps forward for the encounter.  Catching it clears
  -- the overworld object; running from it or knocking it out leaves the object
  -- in place so the player can interact with it again later.
  deepwoodScript[#deepwoodScript + 1] =
    { "show_text", "_MARS_CELEBI_ENCOUNTER_TEXT" }
  deepwoodScript[#deepwoodScript + 1] = { "play_cry", "CELEBI" }
  deepwoodScript[#deepwoodScript + 1] =
    { "start_battle", "wild", "CELEBI", 60 }
  deepwoodScript[#deepwoodScript + 1] =
    { "check_battle_result", "caught" }
  deepwoodScript[#deepwoodScript + 1] =
    { "jump_if_false", "deepwood_end" }

  deepwoodScript[#deepwoodScript + 1] = { "set_flag", Q.caught }
  deepwoodScript[#deepwoodScript + 1] =
    { "hide_object", MAP_DEEPWOOD, "MARS_CELEBI_ENCOUNTER" }
  deepwoodScript[#deepwoodScript + 1] =
    { "show_text", "_MARS_CELEBI_ENCOUNTER_CAUGHT" }

  deepwoodScript[#deepwoodScript + 1] = { "label", "deepwood_end" }

