  local function memoryHideRows(mapId, names)
    local rows = {}
    for _, name in ipairs(names or {}) do
      rows[#rows + 1] = { "hide_object", mapId, name }
    end
    return rows
  end

  local function stageObjectRows(flags)
    return {
      {
        flags[Q.started] and not flags[Q.forest]
          and "show_object" or "hide_object",
        MAP_FOREST,
        "MARS_CELEBI_PORTAL_FOREST",
      },
      {
        flags[Q.forest] and not flags[Q.tower]
          and "show_object" or "hide_object",
        MAP_TOWER,
        "MARS_CELEBI_PORTAL_TOWER",
      },
      {
        flags[Q.tower] and not flags[Q.celadon]
          and "show_object" or "hide_object",
        MAP_CELADON,
        "MARS_CELEBI_PORTAL_CELADON",
