      {
        flags[Q.celadon] and not flags[Q.cinnabar]
          and "show_object" or "hide_object",
        MAP_CINNABAR,
        "MARS_CELEBI_PORTAL_CINNABAR",
      },
      {
        flags[Q.cinnabar] and not flags[Q.deepwood]
          and "show_object" or "hide_object",
        MAP_DEEPWOOD,
        "MARS_CELEBI_PORTAL_DEEPWOOD",
      },
      {
        flags[Q.deepwood] and not flags[Q.shard]
          and "show_object" or "hide_object",
        MAP_DEEPWOOD,
        "MARS_CELEBI_ANCIENT_SHARD",
      },
      {
        flags[Q.deepwood] and not flags[Q.caught]
          and "show_object" or "hide_object",
        MAP_DEEPWOOD,
        "MARS_CELEBI_ENCOUNTER",
      },
    }
  end

