  mod.content.commands:register("mars_celebi:base_oak_chat", {
    foreground = true,

    fn = function(ctx)
      local base = MapScripts.baseTalk(
        MAP_OAK,
        "TEXT_OAKSLAB_OAK1"
      )

      if not base then
        return
      end

      -- Gen1Recomp's Oak base talk is a script-row TABLE, not a
      -- callable Lua handler. Queue table handlers so they start as soon as
      -- this overriding script finishes. Keep function support for engine
      -- versions/maps whose base handler is still callable.
      if type(base) == "table" then
        ctx.overworld:queueScript(base, { npc = ctx.npc })
        return
      end

      if type(base) == "function" then
        local runner = ctx.runner
        base(
          ctx.game,
          ctx.overworld,
          ctx.npc,
          function()
            runner:resume()
          end
        )
        runner:yield()
      end
    end,
  })

