    -------------------------------------------------------------------------
    -- ESCAPE ROPE SUPPORT FOR ALL DAWN TOWER FLOORS
    -------------------------------------------------------------------------
    local DAWN_TOWER_ESCAPE_MAPS = {
      DAWN_TOWER_1F = true,
      DAWN_TOWER_2F = true,
      DAWN_TOWER_3F = true,
      DAWN_TOWER_4F = true,
      DAWN_TOWER_ROOF = true,
    }

    mod.hooks:wrap(
      "item.use",
      function(next, game, battle, id, target, list, moveIndex, picker)
        local ow = game and game.overworld
        local map = ow and ow.map
        local def = map and map.def

        if id ~= "ESCAPE_ROPE"
           or battle
           or not map
           or not def
           or not DAWN_TOWER_ESCAPE_MAPS[map.id]
        then
          return next(
            game,
            battle,
            id,
            target,
            list,
            moveIndex,
            picker
          )
        end

        -- BagMenu's vanilla Escape Rope branch only permits a fixed list of
        -- dungeon tileset IDs. Temporarily identifying our custom tower as
        -- INTERIOR lets that exact vanilla branch handle bag closing, item
        -- consumption, teleport animation, and destination behavior.
        local realTileset = def.tileset
        def.tileset = "INTERIOR"

        local results = {
          pcall(
            next,
            game,
            battle,
            id,
            target,
            list,
            moveIndex,
            picker
          )
        }

        def.tileset = realTileset

        if not results[1] then
          error(results[2], 0)
        end

        return unpack(results, 2)
      end
    )

