    local function registerDawnTowerEncounters(mapId)
      local source = dawnTowerEncounterTables[mapId]
      local slots = {}

      for i, slot in ipairs(source or {}) do
        slots[i] = {
          level = slot.level,
          species = slot.species,
        }
      end

      mod.content.encounters:register(mapId, {
        id = mapId,
        grass = {
          rate = 10,
          slots = slots,
        },
      })
    end

    registerDawnTowerEncounters("DAWN_TOWER_1F")
    registerDawnTowerEncounters("DAWN_TOWER_2F")
    registerDawnTowerEncounters("DAWN_TOWER_3F")
    registerDawnTowerEncounters("DAWN_TOWER_4F")

    -------------------------------------------------------------------------
    -- Dawn Tower music.
    -- 1F-4F use the Indigo Plateau theme.
    -- The roof keeps a valid map-song assignment, but a music.volume hook
    -- mutes only the roof's overworld map theme. Battle music remains audible.
    -------------------------------------------------------------------------
    local towerSong = mod.content.map_songs:get("INDIGO_PLATEAU")

    if towerSong then
      mod.content.map_songs:register("DAWN_TOWER_1F", towerSong)
      mod.content.map_songs:register("DAWN_TOWER_2F", towerSong)
      mod.content.map_songs:register("DAWN_TOWER_3F", towerSong)
      mod.content.map_songs:register("DAWN_TOWER_4F", towerSong)
      mod.content.map_songs:register("DAWN_TOWER_ROOF", towerSong)
    end

    mod.hooks:wrap("music.volume", function(next, vol, ctx)
      vol = next(vol, ctx)

      if ctx
        and ctx.mapId == "DAWN_TOWER_ROOF"
        and ctx.song
        and ctx.mapSong
        and ctx.song == ctx.mapSong
      then
        return 0
      end

      return vol
    end)

    -------------------------------------------------------------------------
    -- Celadon postgame setup: Erika waits by the Pokemon Center until spoken
    -- to, then Himiko/Hanako become visible near Erika inside the Gym.
    -------------------------------------------------------------------------
    local function occupiedCells(def)
      local used = {}
      for _, obj in ipairs(def and def.objects or {}) do
        if obj.x ~= nil and obj.y ~= nil then
          used[tostring(obj.x) .. ":" .. tostring(obj.y)] = true
        end
      end
      return used
    end

    local function nearestWalkable(mapId, preferredX, preferredY, used, maxRadius)
      local def = mod.content.maps:get(mapId)
      local tileset = def and mod.content.tilesets:get(def.tileset)
      used = used or {}
      maxRadius = maxRadius or 8

      local function valid(x, y)
        if not def then return false end
        if x < 1 or y < 1 or x >= def.width * 2 - 1 or y >= def.height * 2 - 1 then
          return false
        end
        if used[tostring(x) .. ":" .. tostring(y)] then return false end
        if not tileset then return true end
        return MapDef.defIsWalkableCell(def, tileset, x, y)
      end

      for radius = 0, maxRadius do
        for dy = -radius, radius do
          for dx = -radius, radius do
            if radius == 0 or math.max(math.abs(dx), math.abs(dy)) == radius then
              local x = preferredX + dx
              local y = preferredY + dy
              if valid(x, y) then
                used[tostring(x) .. ":" .. tostring(y)] = true
                return x, y
              end
            end
          end
        end
      end

      return preferredX, preferredY
    end

    local cityDef = mod.content.maps:get("CELADON_CITY")
    local cityUsed = occupiedCells(cityDef)
    local erikaOutX, erikaOutY =
      nearestWalkable("CELADON_CITY", 40, 11, cityUsed, 8)

    -- Preserve Erika's established departure path, which already
    -- looked right, then extend it another five movement cells downward before
    -- she disappears.
    local erikaWalkUsed = occupiedCells(cityDef)
    local erikaWalkX, erikaWalkY =
      nearestWalkable(
        "CELADON_CITY",
        erikaOutX - 3,
        erikaOutY + 2,
        erikaWalkUsed,
        5
      )

    local erikaExitX = erikaWalkX
    local erikaExitY = erikaWalkY + 5

    local gymDef = mod.content.maps:get("CELADON_GYM")
    local erikaGymObj = nil
    local erikaGymIndex = nil

    for objectListIndex, obj in ipairs(gymDef and gymDef.objects or {}) do
      if obj.trainerClass == "OPP_ERIKA"
         or obj.text == "TEXT_CELADONGYM_ERIKA"
      then
        erikaGymObj = obj
        erikaGymIndex = obj.index or objectListIndex
        break
      end
    end

    local erikaGymX = erikaGymObj and erikaGymObj.x or 5
    local erikaGymY = erikaGymObj and erikaGymObj.y or 3
    local erikaGymFacing =
      string.lower(
        tostring((erikaGymObj and erikaGymObj.range) or "DOWN")
      )

    -- exact positions requested for the sisters.
    --
    -- Celadon Gym is 10x18 movement cells. These are the two open grass
    -- cells circled in the test screenshot, above the lower tree row:
    --   Himiko: (3,6), facing RIGHT
    --   Hanako: (6,6), facing LEFT
    --
    -- Do NOT run these through nearestWalkable; that was what caused the
    -- previous versions to drift to the lower part of the Gym.
    local himikoGymX, himikoGymY = 3, 6
