    -------------------------------------------------------------------------
    -- Guardian Below object placement.
    -------------------------------------------------------------------------
    local function openAreaCell(mapId, preferredX, preferredY, used, radius)
      local def = mod.content.maps:get(mapId)
      local tileset = def and mod.content.tilesets:get(def.tileset)
      used = used or {}
      radius = radius or 12

      local function walk(x, y)
        if not def or not tileset then return false end
        if x < 1 or y < 1
           or x >= def.width * 2 - 1
           or y >= def.height * 2 - 1
        then
          return false
        end
        return MapDef.defIsWalkableCell(def, tileset, x, y)
      end

      local dirs = {
        { 1, 0 }, { -1, 0 }, { 0, 1 }, { 0, -1 },
      }

      local function openEnough(x, y)
        if used[tostring(x) .. ":" .. tostring(y)] or not walk(x, y) then
          return false
        end

        local neighbors = 0
        for _, d in ipairs(dirs) do
          if walk(x + d[1], y + d[2]) then
            neighbors = neighbors + 1
          end
        end

        return neighbors >= 3
      end

      for r = 0, radius do
        for dy = -r, r do
          for dx = -r, r do
            if r == 0 or math.max(math.abs(dx), math.abs(dy)) == r then
              local x = preferredX + dx
              local y = preferredY + dy
              if openEnough(x, y) then
                used[tostring(x) .. ":" .. tostring(y)] = true
                return x, y
              end
            end
          end
        end
      end

      return nearestWalkable(mapId, preferredX, preferredY, used, radius)
    end

