    -------------------------------------------------------------------------
    -- Shared helpers.
    -------------------------------------------------------------------------
    local function ensureDawnQuestItems(game)
      if not (game and game.save) then return end

      local flags = game.save.flags or {}
      local inventory = game.save.inventory or {}
      local Bag = require("src.inventory.Bag")

      -- Backfill the Rainbow Wing for saves that started the quest before
      -- the earlier event-only implementation.
      if flags[FLAGS.wing]
         and (inventory.RAINBOW_WING or 0) <= 0
      then
        Bag.add(game.save, "RAINBOW_WING", 1, game.data)
      end

      -- An old save that already recovered the striker obviously reached the
      -- answer, so mark the research-clue stage complete as well.
      if flags[FLAGS.strikerFound] then
        flags[FLAGS.strikerClue] = true
      end

      -- Backfill the Sacred Striker only while it has been recovered but not
      -- yet installed in the Bell of Dawn.
      if flags[FLAGS.strikerFound]
         and not flags[FLAGS.dawn]
         and (inventory.SACRED_STRIKER or 0) <= 0
      then
        Bag.add(game.save, "SACRED_STRIKER", 1, game.data)
      end

      -- Old saves may still physically carry the Striker after the bell was
      -- already repaired. Installation consumes the Key Item.
      if flags[FLAGS.dawn]
         and (inventory.SACRED_STRIKER or 0) > 0
      then
        Bag.remove(game.save, "SACRED_STRIKER", 1)
      end

      -- Migrate old Ho-Oh saves accurately when possible. If Ho-Oh is owned,
      -- it was caught. If the old generic BEAT flag exists but Ho-Oh is not
      -- owned, clear it so a prior KO does not permanently lock the encounter.
      local dex = game.save.pokedex
      local ownsHoOh =
        dex and dex.owned and dex.owned.HO_OH

      if ownsHoOh then
        flags[FLAGS.hoohRevealed] = true
        flags[FLAGS.caught] = true
        flags.EVENT_BEAT_HO_OH = true
      elseif flags.EVENT_BEAT_HO_OH and not flags[FLAGS.caught] then
        flags.EVENT_BEAT_HO_OH = nil
      end
    end

    local function allLugiaInscriptions(flags)
      return flags[LUGIA_FLAGS.inscription1]
        and flags[LUGIA_FLAGS.inscription2]
        and flags[LUGIA_FLAGS.inscription3]
    end

    local function ensureLugiaQuestState(game)
      if not (game and game.save) then return end

      local flags = game.save.flags or {}
      local inventory = game.save.inventory or {}
      local Bag = require("src.inventory.Bag")

      if flags[LUGIA_FLAGS.wing]
         and (inventory.SILVER_WING or 0) <= 0
      then
        Bag.add(game.save, "SILVER_WING", 1, game.data)
      end

      local dex = game.save.pokedex
      local ownsLugia =
        dex and dex.owned and dex.owned.LUGIA

      if ownsLugia then
        -- Players who caught the old placeholder Lugia encounter should not
        -- lose that capture. Advance them to the report-back stage.
        flags[LUGIA_FLAGS.started] = true
        flags[LUGIA_FLAGS.wing] = true
        flags[LUGIA_FLAGS.eyewitness] = true
        flags[LUGIA_FLAGS.memorial] = true
        flags[LUGIA_FLAGS.inscription1] = true
        flags[LUGIA_FLAGS.inscription2] = true
        flags[LUGIA_FLAGS.inscription3] = true
        flags[LUGIA_FLAGS.briefed] = true
        flags[LUGIA_FLAGS.revealed] = true
        flags[LUGIA_FLAGS.caught] = true
        flags.EVENT_BEAT_LUGIA = true
      elseif flags.EVENT_BEAT_LUGIA
         and not flags[LUGIA_FLAGS.caught]
      then
        -- The old static battle marked a simple victory as "beat". A KO is
        -- no longer allowed to permanently remove a legendary encounter.
        flags.EVENT_BEAT_LUGIA = nil
      end
    end

