          if done then done() end
          return
        end

        local flags = game.save.flags or {}
        local firstWin = firstWinPossible or not flags[FLAGS.defeated]
        flags[FLAGS.defeated] = true

        if firstWin then
          say(game, "_MARS_ROCKET_REMNANT_FIRST_WIN", function()
            givePrize(game, done)
          end)
          return
        end

        say(game, "_MARS_ROCKET_REMNANT_REPEAT_WIN", function()
          givePrize(game, done)
        end)
      end

      ow:pushBattle(battle)
    end

    local function remnantTalk(game, ow, npc, done)
