         or x >= (highlands.width or 10) * 2 - 1
         or y >= (highlands.height or 54) * 2 - 1
      then
        return false
      end

      if occupied[tostring(x) .. ":" .. tostring(y)] then
        return false
      end

      -- Keep Oak out of another object's immediate personal space.
      for _, obj in ipairs(highlands.objects or {}) do
        if math.abs((obj.x or -99) - x) <= 1
           and math.abs((obj.y or -99) - y) <= 1
        then
          return false
        end
      end

      if not highlandsTileset then return true end
      return MapDef.defIsWalkableCell(highlands, highlandsTileset, x, y)
    end

    -- Preferred eastern overlook, roughly between the early and middle
    -- trainer sections of the Highlands. Search outward only if that exact
    -- cell is blocked by the authored terrain.
    local OAK_X, OAK_Y = 16, 41
    if not oakCellAvailable(OAK_X, OAK_Y) then
      local found = false
      for radius = 1, 10 do
        for dy = -radius, radius do
          for dx = -radius, radius do
            if math.max(math.abs(dx), math.abs(dy)) == radius then
              local x, y = 16 + dx, 41 + dy
              if oakCellAvailable(x, y) then
                OAK_X, OAK_Y = x, y
                found = true
                break
              end
            end
          end
          if found then break end
        end
        if found then break end
      end
    end

    local oakIndex = #(highlands.objects or {}) + 1

    mod.content.maps:patch("INDIGO_HIGHLANDS", {
      objects = {
        __append = {
          {
            index = oakIndex,
            name = "MARS_INDIGO_PROF_OAK",
            sprite = oakSprite,
            movement = "STAY",
            range = "ANY_DIR",
            x = OAK_X,
            y = OAK_Y,
            text = TEXT_OAK,
            hidden = true,
          },
        },
      },
    })

    -------------------------------------------------------------------------
    -- INTERACTION / FIXED ¥10,000 REWARD
    -------------------------------------------------------------------------

    local function fillPlayer(game, s)
      local name = game.save and game.save.player and game.save.player.name or "PLAYER"
      return (s or ""):gsub("{PLAYER}", name)
    end

    local function say(game, textIdOrLiteral, done, opts)
      local raw = game.data.text[textIdOrLiteral] or textIdOrLiteral
      game.stack:push(TextBox.new(game, fillPlayer(game, raw), done, opts))
    end

    local function moneyText(amount)
      amount = math.max(0, math.floor(amount or 0))
      if amount >= 1000 then
        return tostring(math.floor(amount / 1000))
          .. ","
          .. string.format("%03d", amount % 1000)
      end
      return tostring(amount)
    end

    local function givePrize(game, done)
      local before = math.max(0, game.save.money or 0)
      local after = math.min(999999, before + PRIZE)
      local gained = after - before
      game.save.money = after

      if gained <= 0 then
        say(game, "Your wallet is\nalready full!", done)
        return
      end

      local message = "You received\n¥" .. moneyText(gained) .. "!"
      if gained < PRIZE then
        message = message .. "\fYour wallet is\nnow full!"
      end
      say(game, message, done)
    end

    local function startOakBattle(game, ow, done, firstWinPossible)
      local battle = BattleState.newTrainer(game, "OPP_OAK_SUPERBOSS", 1)
      battle.endBattleText = "Excellent!\nSimply excellent!"

      local baseRomText = battle.romText
      battle.romText = function(self, label, fallback, ...)
        if label == "_MoneyForWinningText" then
          return "PROF.OAK was\ndefeated!"
        end
        return baseRomText(self, label, fallback, ...)
      end

      battle.onFinish = function(result)
        ow:afterBattle(result, battle)

        if result ~= "win" then
          if done then done() end
          return
        end

        local flags = game.save.flags or {}
        local firstWin = firstWinPossible or not flags[FLAGS.defeated]
        flags[FLAGS.defeated] = true

        if firstWin then
          say(game, "_MARS_OAK_SUPERBOSS_FIRST_WIN", function()
            givePrize(game, done)
          end)
          return
        end

        say(game, "_MARS_OAK_SUPERBOSS_REPEAT_WIN", function()
          givePrize(game, done)
        end)
      end

      ow:pushBattle(battle)
    end

    local function oakTalk(game, ow, npc, done)
      if npc and npc.facePlayer and ow and ow.player then
        npc:facePlayer(ow.player)
      end

      local flags = game.save.flags or {}

      -- Defensive fallback: Oak should be hidden until Echoes of Time is done.
      if not flags[FLAGS.champion] or not flags[FLAGS.echoesComplete] then
        if done then done() end
        return
      end

      if not flags[FLAGS.met] then
        flags[FLAGS.met] = true
        say(game, "_MARS_OAK_SUPERBOSS_INTRO", function()
          startOakBattle(game, ow, done, true)
        end)
        return
      end

      say(
        game,
        "_MARS_OAK_SUPERBOSS_REBATTLE_ASK",
        nil,
        {
          choice = function(yes)
            if not yes then
              say(game, "_MARS_OAK_SUPERBOSS_REBATTLE_NO", done)
              return
            end

            say(game, "_MARS_OAK_SUPERBOSS_REBATTLE_YES", function()
              startOakBattle(game, ow, done, false)
            end)
          end,
        }
      )
    end

    mod.content.map_scripts:register("INDIGO_HIGHLANDS", {
      priority = 380,

      onEnter = function(game, ow)
        local flags = game.save.flags or {}
        local show = flags[FLAGS.champion] and flags[FLAGS.echoesComplete]

        ow:queueScript({
          {
            show and "show_object" or "hide_object",
            "INDIGO_HIGHLANDS",
            "MARS_INDIGO_PROF_OAK",
          },
        })
      end,

      talk = {
        [TEXT_OAK] = oakTalk,
      },
    })

    mod.log:info(
      "PROF.OAK superboss installed: Indigo Highlands ! marker + separate Lv85-90 encounter + 3 Full Restores + ¥10,000; OAKS_LAB untouched"
    )
  end)()

  ---------------------------------------------------------------------------
  -- PEWTER CITY MUSEUM — "MOONFALL SPECIMEN"
  --
  -- Unlock: after Brock + TM34.
  -- Flow: Museum theft investigation -> Brock in Mt. Moon 1F -> Brock and a
  -- Clefairy gathering on B2F -> Lv.17 Clefable battle -> return Moonfall
  -- Shard to the Museum -> Moon Stone + ¥3,000.
  --
  -- Brock's Gym epilogue is one-time only and then yields permanently to the
  -- existing default/postgame rematch handler.
  ---------------------------------------------------------------------------
  ;(function()
    if not mod.content.map_scripts then return end

    local MapDef = require("src.world.Map")
