      started = "EVENT_MOONFALL_STARTED",
      briefed = "EVENT_MOONFALL_MUSEUM_BRIEFED",
      trail = "EVENT_MOONFALL_TRAIL_FOUND",
      finalWon = "EVENT_MOONFALL_CLEFABLE_DEFEATED",
      shard = "EVENT_MOONFALL_SHARD_OBTAINED",
      complete = "EVENT_MOONFALL_COMPLETE",
    }

    local TEXT_RESEARCHER = "TEXT_MARS_MOONFALL_RESEARCHER"
    local TEXT_MUSEUM_BROCK = "TEXT_MARS_MOONFALL_MUSEUM_BROCK"
