    local TEXT_BROCK_FINAL = "TEXT_MARS_MOONFALL_BROCK_FINAL"
    local TEXT_CLEFAIRY = "TEXT_MARS_MOONFALL_CLEFAIRY"

    -------------------------------------------------------------------------
    -- Quest key item. No new art is required; it is a temporary Key Item that
