    end

    -------------------------------------------------------------------------
    -- Resolve the imported Pewter Museum map without assuming one ROM naming
    -- convention. Gen1 imports commonly expose it as MUSEUM_1F.
    -------------------------------------------------------------------------

    local museumMapId = nil
    local museumDef = nil
    for _, candidate in ipairs({
      "MUSEUM_1F",
      "PEWTER_MUSEUM_1F",
      "PEWTER_MUSEUM",
    }) do
      local def = mod.content.maps:get(candidate)
      if def then
        museumMapId = candidate
        museumDef = def
        break
      end
    end

    local moon1 = mod.content.maps:get("MT_MOON_1F")
