    -------------------------------------------------------------------------
    -- Placement helpers. These search real imported collision instead of
    -- assuming fixed coordinates, so the quest survives the existing map edits.
    -------------------------------------------------------------------------

    local function occupiedCells(def)
      local used = {}
      local function mark(x, y)
        if x ~= nil and y ~= nil then
          used[tostring(x) .. ":" .. tostring(y)] = true
        end
      end

      for _, obj in ipairs(def and def.objects or {}) do mark(obj.x, obj.y) end
      for _, sign in ipairs(def and def.signs or {}) do mark(sign.x, sign.y) end
      for _, warp in ipairs(def and def.warps or {}) do mark(warp.x, warp.y) end
      return used
    end

    local function landCell(def, x, y, used)
      if not def then return false end
      if x < 1 or y < 1 or x >= def.width * 2 - 1 or y >= def.height * 2 - 1 then
        return false
      end
      if used and used[tostring(x) .. ":" .. tostring(y)] then return false end

      local tileset = mod.content.tilesets:get(def.tileset)
      if not tileset then return true end

      return MapDef.defIsWalkableCell(def, tileset, x, y)
        and not MapDef.defIsWaterCell(def, tileset, x, y)
    end

    local function nearestLand(def, preferredX, preferredY, used, radius)
      radius = radius or 12
      for r = 0, radius do
        for dy = -r, r do
          for dx = -r, r do
            if r == 0 or math.max(math.abs(dx), math.abs(dy)) == r then
              local x, y = preferredX + dx, preferredY + dy
              if landCell(def, x, y, used) then
                used[tostring(x) .. ":" .. tostring(y)] = true
                return x, y
              end
            end
          end
        end
      end
      return preferredX, preferredY
    end

    local museumUsed = occupiedCells(museumDef)
    local researcherX, researcherY = nearestLand(
      museumDef,
      math.max(2, math.floor(museumDef.width)),
      math.max(2, math.floor(museumDef.height)),
      museumUsed,
      10
    )
    -- Brock should be part of the briefing scene, not tucked behind
    -- the Museum counter. Keep him immediately beside the researcher.
    local museumBrockX, museumBrockY = researcherX - 1, researcherY

    local moon1Used = occupiedCells(moon1)
    local brock1X, brock1Y = nearestLand(
      moon1,
      math.max(3, math.floor(moon1.width)),
      math.max(3, math.floor(moon1.height * 1.20)),
      moon1Used,
      16
    )

    -------------------------------------------------------------------------
    -- Find a small open B2F cluster for Brock + the Clefairy gathering.
    -------------------------------------------------------------------------

    local b2Used = occupiedCells(moonB2)

    local function clusterOpen(cx, cy)
      local cells = {
        { cx - 2, cy + 1 }, -- Brock
        { cx - 1, cy     }, -- Clefairy
        { cx,     cy     }, -- Clefable
        { cx + 1, cy     }, -- Clefairy
        { cx,     cy - 1 }, -- Clefairy
      }

      for _, pos in ipairs(cells) do
        if not landCell(moonB2, pos[1], pos[2], b2Used) then
          return false
        end
      end
      return true
    end

    local finalCX = math.max(4, math.floor(moonB2.width * 1.25))
    local finalCY = math.max(4, math.floor(moonB2.height * 1.25))
    local foundCluster = false

    for r = 0, 20 do
      if foundCluster then break end
      for dy = -r, r do
        if foundCluster then break end
        for dx = -r, r do
          if r == 0 or math.max(math.abs(dx), math.abs(dy)) == r then
            local cx, cy = finalCX + dx, finalCY + dy
            if clusterOpen(cx, cy) then
              finalCX, finalCY = cx, cy
              foundCluster = true
              break
            end
          end
        end
      end
    end

    local finalBrockX, finalBrockY = finalCX - 2, finalCY + 1

    -- the Pokemon START in the four dance-circle positions, shifted up by one tile.
    local DANCE_AX, DANCE_AY = finalCX,     finalCY + 1
    local DANCE_BX, DANCE_BY = finalCX + 2, finalCY + 1
    local DANCE_CX, DANCE_CY = finalCX + 2, finalCY + 3
    local DANCE_DX, DANCE_DY = finalCX,     finalCY + 3

    local clefairy1X, clefairy1Y = DANCE_AX, DANCE_AY
    local clefairy3X, clefairy3Y = DANCE_BX, DANCE_BY
    local clefairy2X, clefairy2Y = DANCE_CX, DANCE_CY
    local clefableX, clefableY = DANCE_DX, DANCE_DY

