    local b2BaseIndex = #(moonB2.objects or {}) + 1
    local FINAL_BROCK_INDEX = b2BaseIndex
    local FINAL_CLEFAIRY_1_INDEX = b2BaseIndex + 1
    local FINAL_CLEFABLE_INDEX = b2BaseIndex + 2
    local FINAL_CLEFAIRY_2_INDEX = b2BaseIndex + 3
