    -------------------------------------------------------------------------
    -- Small helpers
    -------------------------------------------------------------------------

    local function fillPlayer(game, s)
      local name = game.save and game.save.player and game.save.player.name or "PLAYER"
      return (s or ""):gsub("{PLAYER}", name)
    end

    local function say(game, textIdOrLiteral, done, opts)
      local raw = game.data.text[textIdOrLiteral] or textIdOrLiteral
      game.stack:push(TextBox.new(game, fillPlayer(game, raw), done, opts))
    end

    local moonfallCallbacks = setmetatable({}, { __mode = "k" })

    mod.commands:register("mars_moonfall_cutscene_done", function(ctx)
      local callback = moonfallCallbacks[ctx.game]
      moonfallCallbacks[ctx.game] = nil
      if callback then callback() end
    end)

    local function queueMoonfallCutscene(game, ow, rows, callback)
      moonfallCallbacks[game] = callback
      rows[#rows + 1] = { "mars_moonfall_cutscene_done" }
      ow:queueScript(rows)
    end


    local function moonfallDirectionToward(fromX, fromY, toX, toY)
      local dx = (toX or fromX) - (fromX or 0)
      local dy = (toY or fromY) - (fromY or 0)

      if math.abs(dx) >= math.abs(dy) then
        if dx < 0 then return "left" end
        if dx > 0 then return "right" end
      end

      if dy < 0 then return "up" end
      if dy > 0 then return "down" end

      return "down"
    end

    local function moonfallOppositeDirection(dir)
      if dir == "up" then return "down" end
      if dir == "down" then return "up" end
      if dir == "left" then return "right" end
      if dir == "right" then return "left" end
      return "down"
    end

    local function moonfallFaceEachOtherRows(ow)
      local rows = {}
      local player = ow and ow.player or nil
      local brock =
        ow and ow.npcByIndex and ow:npcByIndex(FINAL_BROCK_INDEX)
        or nil

      if not player or not brock then
        return rows
      end

      rows[#rows + 1] = {
        "face_object",
        FINAL_BROCK_INDEX,
        moonfallDirectionToward(
          brock.cellX,
          brock.cellY,
          player.cellX,
          player.cellY
        ),
      }
      rows[#rows + 1] = {
        "face_player_dir",
        moonfallDirectionToward(
          player.cellX,
          player.cellY,
          brock.cellX,
          brock.cellY
        ),
      }
      rows[#rows + 1] = { "wait", 5 }

      return rows
    end

    local function moonfallFaceDanceRows(ow)
      local rows = {}
      local player = ow and ow.player or nil
      local brock =
        ow and ow.npcByIndex and ow:npcByIndex(FINAL_BROCK_INDEX)
        or nil

      -- Aim both Brock and the player at the center of the four dance spots.
      local centerX = (DANCE_AX + DANCE_BX + DANCE_CX + DANCE_DX) / 4
      local centerY = (DANCE_AY + DANCE_BY + DANCE_CY + DANCE_DY) / 4

      if brock then
        rows[#rows + 1] = {
          "face_object",
          FINAL_BROCK_INDEX,
          moonfallDirectionToward(
            brock.cellX,
            brock.cellY,
            centerX,
            centerY
          ),
        }
      end

      if player then
        rows[#rows + 1] = {
          "face_player_dir",
          moonfallDirectionToward(
            player.cellX,
            player.cellY,
            centerX,
            centerY
          ),
        }
      end

      rows[#rows + 1] = { "wait", 5 }
      return rows
    end

    -------------------------------------------------------------------------
    -- SIMULTANEOUS CLEFAIRY DANCE DRIVER
    --
    -- ScriptRunner's normal move_npc_to command is intentionally sequential.
    -- For this scene, drive the four live NPCs directly, using the same proven
    -- raw movement fields used by Downhill Dash. Every dancer that still has a
    -- step remaining begins that step during the same input tick.
    -------------------------------------------------------------------------

    local moonfallDanceState = {
      active = false,
      game = nil,
      ow = nil,
      runner = nil,
      phase = nil,
      round = 0,
      spinIndex = 0,
      spinWait = 0,
      endWait = 0,
      dancers = nil,
    }

    local DANCE_SPIN_ORDER = { "up", "right", "down", "left" }
    local DANCE_DIR_BY_CORNER = {
      [1] = "right", -- A -> B: 2 cells
      [2] = "down",  -- B -> C: 2 cells
      [3] = "left",  -- C -> D: 2 cells
      [4] = "up",    -- D -> A: 2 cells
    }
    local DANCE_STEPS_BY_CORNER = {
      [1] = 2,
      [2] = 2,
      [3] = 2,
      [4] = 2,
    }
    local DANCE_DELTA = {
      up    = {  0, -1 },
      down  = {  0,  1 },
      left  = { -1,  0 },
      right = {  1,  0 },
    }

    local function moonfallDanceNpc(index)
      local ow = moonfallDanceState.ow
      if not ow or not ow.npcByIndex then return nil end
      return ow:npcByIndex(index)
    end

    local function moonfallRawNpcStep(npc, dir)
      local delta = DANCE_DELTA[dir]
      if not npc or not delta then return false end

      npc.facing = dir
      npc.targetX = npc.cellX + delta[1]
      npc.targetY = npc.cellY + delta[2]
      npc.progress = 0
      npc.stepFrames = 20
      npc.marching = false
      npc.hopStep = nil
      npc.moving = true
      return true
    end

    local function moonfallAllDancersIdle()
      for _, dancer in ipairs(moonfallDanceState.dancers or {}) do
        local npc = moonfallDanceNpc(dancer.index)
        if not npc then
          return false, "missing"
        end
        if npc.moving then
          return false, "moving"
        end
      end
      return true, nil
    end

    local function moonfallFinishDance(aborted)
      local state = moonfallDanceState
      if not state.active then return end

      -- After four clockwise rotations everybody is back at the starting spot.
      -- Face inward for the moment Brock resumes speaking.
      local inward = {
        [1] = "right",
        [2] = "down",
        [3] = "left",
        [4] = "up",
      }

      for _, dancer in ipairs(state.dancers or {}) do
        local npc = moonfallDanceNpc(dancer.index)
        if npc then
          npc.moving = false
          npc.facing = inward[dancer.corner] or npc.facing
        end
      end

      local runner = state.runner

      local game = state.game

      state.active = false
      state.game = nil
      state.ow = nil
      state.runner = nil
      state.phase = nil
      state.dancers = nil

      if game and game.data then
        local Music = require("src.core.Music")
        Music.restoreMap(game.data)
      end

      if aborted then
        mod.log:warn("Moonfall dance aborted safely; resuming scene")
      end

      if runner then
        runner:resume()
      end
    end

    local function moonfallAdvanceDance()
      local state = moonfallDanceState
      if not state.active then return end

      local pos = mod.world:current()
      if not pos or pos.mapId ~= "MT_MOON_B2F" then
        moonfallFinishDance(true)
        return
      end

      local idle, why = moonfallAllDancersIdle()
      if why == "missing" then
        moonfallFinishDance(true)
        return
      end

      -----------------------------------------------------------------------
      -- SPIN: all four change facing on the exact same tick.
      -----------------------------------------------------------------------
      if state.phase == "spin" then
        if not idle then return end

        if state.spinWait > 0 then
          state.spinWait = state.spinWait - 1
          return
        end

        state.spinIndex = state.spinIndex + 1
        local facing = DANCE_SPIN_ORDER[state.spinIndex]

        if facing then
          for _, dancer in ipairs(state.dancers) do
            local npc = moonfallDanceNpc(dancer.index)
            if npc then
              npc.facing = facing
            end
          end

          state.spinWait = 10
          return
        end

        -- Spin complete. Arm one side traversal for each dancer.
        for _, dancer in ipairs(state.dancers) do
          dancer.stepsRemaining = DANCE_STEPS_BY_CORNER[dancer.corner]
        end

        state.phase = "move"
        return
      end

      -----------------------------------------------------------------------
      -- MOVE: every dancer that still has distance remaining starts one cell
      -- on the same tick. Because they all travel clockwise, their targets are
      -- always distinct and they cannot overlap each other.
      -----------------------------------------------------------------------
      if state.phase == "move" then
        if not idle then return end

        local startedAny = false

        for _, dancer in ipairs(state.dancers) do
          if (dancer.stepsRemaining or 0) > 0 then
            local npc = moonfallDanceNpc(dancer.index)
            local dir = DANCE_DIR_BY_CORNER[dancer.corner]

            if moonfallRawNpcStep(npc, dir) then
              dancer.stepsRemaining = dancer.stepsRemaining - 1
              startedAny = true
            else
              moonfallFinishDance(true)
              return
            end
          end
        end

        if startedAny then
          return
        end

        -- Everybody reached the next marked spot. Advance each dancer's
        -- logical corner, then either spin again or end after four rotations.
        for _, dancer in ipairs(state.dancers) do
          dancer.corner = (dancer.corner % 4) + 1
        end

        state.round = state.round + 1

        if state.round >= 4 then
          state.phase = "end_wait"
          state.endWait = 10

          local Sound = require("src.core.Sound")
          if Sound and Sound.play then
            -- Keep the finish understated; the normal Clefairy/Clefable scene
            -- dialogue follows immediately afterward.
          end
          return
        end

        state.phase = "spin"
        state.spinIndex = 0
        state.spinWait = 6
        return
      end

      if state.phase == "end_wait" then
        if state.endWait > 0 then
          state.endWait = state.endWait - 1
          return
        end

        moonfallFinishDance(false)
      end
    end

    mod.content.commands:register("mars_moonfall_dance", {
      foreground = true,

      fn = function(ctx)
        local ow = ctx.overworld
        local runner = ctx.runner

        local dancers = {
          { index = FINAL_CLEFAIRY_1_INDEX, corner = 1 },
          { index = FINAL_CLEFAIRY_3_INDEX, corner = 2 },
          { index = FINAL_CLEFAIRY_2_INDEX, corner = 3 },
          { index = FINAL_CLEFABLE_INDEX,   corner = 4 },
        }

        -- Verify every actor exists before yielding the foreground script.
        for _, dancer in ipairs(dancers) do
          if not (ow and ow.npcByIndex and ow:npcByIndex(dancer.index)) then
            mod.log:warn(
              "Moonfall dance could not find NPC index %s",
              tostring(dancer.index)
            )
            return
          end
        end

        local Music = require("src.core.Music")
        Music.play(
          ctx.game.data,
          "Music_JigglypuffSong",
          true,
          {
            reason = "direct",
            mapId = "MT_MOON_B2F",
          }
        )

        moonfallDanceState.active = true
        moonfallDanceState.game = ctx.game
        moonfallDanceState.ow = ow
        moonfallDanceState.runner = runner
        moonfallDanceState.phase = "spin"
        moonfallDanceState.round = 0
        moonfallDanceState.spinIndex = 0
        moonfallDanceState.spinWait = 8
        moonfallDanceState.endWait = 0
        moonfallDanceState.dancers = dancers

        runner:yield()
      end,
    })

    mod.hooks:wrap(
      "input.step",
      function(next, game, dt)
        local result = next(game, dt)

        if moonfallDanceState.active
           and moonfallDanceState.game == game
        then
          moonfallAdvanceDance()
        end

        return result
      end,
      110
    )

    local function moonfallDanceRows()
      -- One foreground command owns the whole animation. It yields the normal
      -- script until the simultaneous movement driver finishes all four rounds.
      return {
        { "mars_moonfall_dance" },
      }
    end

    local function hideFinalGroup(ow)
      ow:queueScript({
        { "fade", "out", 15 },
        { "hide_object", "MT_MOON_B2F", "MARS_MOONFALL_BROCK_FINAL" },
        { "hide_object", "MT_MOON_B2F", "MARS_MOONFALL_CLEFAIRY_1" },
        { "hide_object", "MT_MOON_B2F", "MARS_MOONFALL_CLEFABLE" },
        { "hide_object", "MT_MOON_B2F", "MARS_MOONFALL_CLEFAIRY_2" },
        { "hide_object", "MT_MOON_B2F", "MARS_MOONFALL_CLEFAIRY_3" },
        { "wait", 8 },
        { "fade", "in", 15 },
      })
    end

    local function giveShard(game, ow, done)
      local flags = game.save.flags or {}
      if flags[FLAGS.shard] then
        if done then done() end
        return
      end

      if not Bag.add(game.save, "MOONFALL_SHARD", 1, game.data) then
        say(game, "_MARS_MOONFALL_SHARD_FULL", done)
        return
      end

      flags[FLAGS.shard] = true
      local Sound = require("src.core.Sound")
      Sound.play(game.data, "Get_Item1")

      say(game, "_MARS_MOONFALL_GOT_SHARD", function()
        if done then done() end
        hideFinalGroup(ow)
      end)
    end

    local function finishMuseumQuest(game, ow, done)
      local flags = game.save.flags or {}

      if flags[FLAGS.complete] then
        say(game, "_MARS_MOONFALL_COMPLETE", done)
        return
      end

      if not flags[FLAGS.shard] then
        say(game, "_MARS_MOONFALL_RESEARCHER_REMINDER", done)
        return
      end

      say(game, "_MARS_MOONFALL_RETURN_1", function()
        say(game, "_MARS_MOONFALL_RETURN_BROCK", function()
          say(game, "_MARS_MOONFALL_RETURN_2", function()
            if not Bag.add(game.save, "MOON_STONE", 1, game.data) then
              say(game, "_MARS_MOONFALL_REWARD_FULL", done)
              return
            end

            Bag.remove(game.save, "MOONFALL_SHARD", 1)
            game.save.money = math.min(999999, (game.save.money or 0) + 3000)
            flags[FLAGS.complete] = true

            local Sound = require("src.core.Sound")
            Sound.play(game.data, "Get_Item1")

            say(game, "_MARS_MOONFALL_REWARD", function()
              if done then done() end
              ow:queueScript({
                { "fade", "out", 15 },
                { "hide_object", museumMapId, "MARS_MOONFALL_BROCK_MUSEUM" },
                { "wait", 8 },
                { "fade", "in", 15 },
              })
            end)
          end)
        end)
      end)
    end

    -------------------------------------------------------------------------
    -- Museum interactions
    -------------------------------------------------------------------------

    local function queueMuseumBriefing(game, ow, done)
      local flags = game.save.flags or {}
      flags[FLAGS.started] = true

      if done then done() end
      ow:queueScript({
        { "show_text", "_MARS_MOONFALL_RESEARCHER_START" },
        { "fade", "out", 15 },
        { "show_object", museumMapId, "MARS_MOONFALL_BROCK_MUSEUM" },
        { "wait", 8 },
        { "fade", "in", 15 },
        { "show_text", "_MARS_MOONFALL_BROCK_MUSEUM" },
        { "set_flag", FLAGS.briefed },
        { "fade", "out", 15 },
        { "hide_object", museumMapId, "MARS_MOONFALL_BROCK_MUSEUM" },
        { "wait", 8 },
        { "fade", "in", 15 },
        { "show_text", "_MARS_MOONFALL_RESEARCHER_GO" },
      })
    end

    local function researcherTalk(game, ow, npc, done)
      local flags = game.save.flags or {}

      if not flags.EVENT_BEAT_BROCK or not flags.EVENT_GOT_TM34 then
        if done then done() end
        return
      end

      if flags[FLAGS.complete] then
        say(game, "_MARS_MOONFALL_COMPLETE", done)
        return
      end

      if flags[FLAGS.shard] then
        finishMuseumQuest(game, ow, done)
        return
      end

      if not flags[FLAGS.started] or not flags[FLAGS.briefed] then
        queueMuseumBriefing(game, ow, done)
        return
      end

      say(game, "_MARS_MOONFALL_RESEARCHER_REMINDER", done)
    end

    local function museumBrockTalk(game, ow, npc, done)
      local flags = game.save.flags or {}
      if flags[FLAGS.shard] and not flags[FLAGS.complete] then
        say(game, "_MARS_MOONFALL_RETURN_BROCK", done)
        return
      end
      if flags[FLAGS.started] and not flags[FLAGS.briefed] then
        queueMuseumBriefing(game, ow, done)
        return
      end
      say(game, "_MARS_MOONFALL_BROCK_MUSEUM", done)
    end

    -------------------------------------------------------------------------
    -- Mt. Moon investigation
    -------------------------------------------------------------------------

    local function brock1Talk(game, ow, npc, done)
      local flags = game.save.flags or {}
      if not flags[FLAGS.briefed] then
        if done then done() end
        return
      end

      if flags[FLAGS.trail] then
        say(game, "The trail led deeper\ninto MT. MOON.", done)
        return
      end

      flags[FLAGS.trail] = true
      say(game, "_MARS_MOONFALL_BROCK_1F", function()
        if done then done() end
        ow:queueScript({
          { "fade", "out", 15 },
          { "hide_object", "MT_MOON_1F", "MARS_MOONFALL_BROCK_1F" },
          { "wait", 8 },
          { "fade", "in", 15 },
        })
      end)
    end

    local function approachClefable(game, ow, done)
      local player = ow and ow.player
      local clefable =
        ow and ow.npcByIndex and ow:npcByIndex(FINAL_CLEFABLE_INDEX)
        or nil

      if not player or not clefable then
        if done then done() end
        return
      end

      local px, py = player.cellX, player.cellY
      local cx, cy = clefable.cellX, clefable.cellY

      -- Keep the other dancers and Brock out of the target search.
      local blocked = {}
      local actorIndices = {
        FINAL_BROCK_INDEX,
        FINAL_CLEFAIRY_1_INDEX,
        FINAL_CLEFAIRY_2_INDEX,
        FINAL_CLEFAIRY_3_INDEX,
      }

      for _, index in ipairs(actorIndices) do
        local actor = ow.npcByIndex and ow:npcByIndex(index) or nil
        if actor then
          blocked[tostring(actor.cellX) .. ":" .. tostring(actor.cellY)] = true
        end
      end

      local candidates = {
        { px,     py - 1, "down"  },
        { px + 1, py,     "left"  },
        { px - 1, py,     "right" },
        { px,     py + 1, "up"    },
      }

      table.sort(candidates, function(a, b)
        local da = math.abs(a[1] - cx) + math.abs(a[2] - cy)
        local db = math.abs(b[1] - cx) + math.abs(b[2] - cy)
        return da < db
      end)

      local targetX, targetY, facing = nil, nil, nil

      for _, candidate in ipairs(candidates) do
        local x, y, dir = candidate[1], candidate[2], candidate[3]
        local key = tostring(x) .. ":" .. tostring(y)

        if not blocked[key]
           and landCell(moonB2, x, y, nil)
        then
          targetX, targetY, facing = x, y, dir
          break
        end
      end

      -- Defensive fallback: if every adjacent tile is blocked, do not stall
      -- the quest. Clefable simply challenges the player from its dance spot.
      if not targetX then
        if done then done() end
        return
      end

      local rows = {
        {
          "move_npc_to",
          FINAL_CLEFABLE_INDEX,
          targetX,
          targetY,
        },
        { "face_object", FINAL_CLEFABLE_INDEX, facing },
        { "face_player_dir", moonfallOppositeDirection(facing) },
        { "wait", 8 },
        { "play_cry", "CLEFABLE" },
        { "wait", 6 },
      }

      queueMoonfallCutscene(game, ow, rows, done)
    end

    local function startClefableBattle(game, ow, done)
      local battle = BattleState.newTrainer(game, "OPP_MOONFALL_CLEFABLE", 1)
      battle.endBattleText = "CLEFABLE seems satisfied!"

      local baseRomText = battle.romText
      battle.romText = function(self, label, fallback, ...)
        if label == "_MoneyForWinningText" then
          return "CLEFABLE seems\nsatisfied!"
        end
        return baseRomText(self, label, fallback, ...)
      end

      battle.onFinish = function(result)
        ow:afterBattle(result, battle)

        if result ~= "win" then
          if done then done() end
          return
        end

        local flags = game.save.flags or {}
        flags[FLAGS.finalWon] = true

        local faceRows = moonfallFaceEachOtherRows(ow)
        queueMoonfallCutscene(game, ow, faceRows, function()
          say(game, "_MARS_MOONFALL_AFTER_BATTLE", function()
            giveShard(game, ow, done)
          end)
        end)
      end

      ow:pushBattle(battle)
    end

    local function finalBrockTalk(game, ow, npc, done)
      local flags = game.save.flags or {}

      if flags[FLAGS.shard] then
        say(game, "BROCK returned to\nPEWTER CITY.", done)
        return
      end

      if flags[FLAGS.finalWon] then
        giveShard(game, ow, done)
        return
      end

      if not flags[FLAGS.trail] then
        if done then done() end
        return
      end

      say(game, "_MARS_MOONFALL_BROCK_WATCH", function()
        local watchRows = moonfallFaceDanceRows(ow)

        for _, row in ipairs(moonfallDanceRows()) do
          watchRows[#watchRows + 1] = row
        end

        queueMoonfallCutscene(game, ow, watchRows, function()
          local talkRows = moonfallFaceEachOtherRows(ow)

          queueMoonfallCutscene(game, ow, talkRows, function()
            say(game, "_MARS_MOONFALL_FINAL_SCENE", function()
              approachClefable(game, ow, function()
                startClefableBattle(game, ow, done)
              end)
            end)
          end)
        end)
      end)
    end

    local function clefairyTalk(game, ow, npc, done)
      say(game, "_MARS_MOONFALL_CLEFAIRY_TEXT", done)
    end

