    -------------------------------------------------------------------------
    -- BROCK PROXIMITY / AUTO-INTERACTION CELLS
    --
    -- NORTH of Brock remains a hard boundary: Brock warns the player and
    -- forces them one tile LEFT.
    --
    -- SOUTH of Brock is now the natural approach tile. Stepping there starts
    -- the exact same full interaction as pressing A on Brock, rather than
    -- bouncing the player away.
    -------------------------------------------------------------------------

    local BROCK_BLOCK_NORTH_X = finalBrockX
    local BROCK_BLOCK_NORTH_Y = finalBrockY - 1
    local BROCK_INTERACT_SOUTH_X = finalBrockX
    local BROCK_INTERACT_SOUTH_Y = finalBrockY + 1

    local function moonfallGuardStep(game, ow, x, y)
      local flags = game.save.flags or {}

      if not flags[FLAGS.trail]
         or flags[FLAGS.finalWon]
         or flags[FLAGS.shard]
      then
        return false
      end

      -- Do not interfere while the scripted dance itself owns input.
      if moonfallDanceState and moonfallDanceState.active then
        return false
      end

      -----------------------------------------------------------------------
      -- SOUTH: begin Brock's full interaction immediately.
      -----------------------------------------------------------------------
      if x == BROCK_INTERACT_SOUTH_X
         and y == BROCK_INTERACT_SOUTH_Y
      then
        local brock =
          ow and ow.npcByIndex and ow:npcByIndex(FINAL_BROCK_INDEX)
          or nil

        -- Make this indistinguishable from walking up and talking to Brock:
        -- the player faces north and Brock faces south before his dialogue.
        if ow and ow.player then
          ow.player.facing = "up"
        end
        if brock then
          brock.facing = "down"
        end

        finalBrockTalk(game, ow, brock, function() end)
        return true
      end

      -----------------------------------------------------------------------
      -- NORTH: still forbidden. Warn and push one tile LEFT.
      -----------------------------------------------------------------------
      if x == BROCK_BLOCK_NORTH_X
         and y == BROCK_BLOCK_NORTH_Y
      then
        ow:queueScript({
          { "show_text", "_MARS_MOONFALL_BROCK_BOUNDARY" },
          { "move_player", "left", 1 },
        })
        return true
      end

      return false
    end


    mod.content.map_scripts:register("MT_MOON_B2F", {
      priority = 365,
      onEnter = function(game, ow)
        local flags = game.save.flags or {}
        local show = flags[FLAGS.trail] and not flags[FLAGS.shard]
        local rows = {
          {
            show and "show_object" or "hide_object",
            "MT_MOON_B2F",
            "MARS_MOONFALL_BROCK_FINAL",
          },
        }

        for _, name in ipairs({
          "MARS_MOONFALL_CLEFAIRY_1",
          "MARS_MOONFALL_CLEFABLE",
          "MARS_MOONFALL_CLEFAIRY_2",
          "MARS_MOONFALL_CLEFAIRY_3",
        }) do
          rows[#rows + 1] = {
            show and "show_object" or "hide_object",
            "MT_MOON_B2F",
            name,
          }
        end

        ow:queueScript(rows)
      end,

      onStep = function(game, ow, x, y)
        return moonfallGuardStep(game, ow, x, y)
      end,

      talk = {
        [TEXT_BROCK_FINAL] = finalBrockTalk,
        [TEXT_CLEFAIRY] = clefairyTalk,
      },
    })

    mod.log:info(
      "MOONFALL SPECIMEN installed: Brock now stands directly left of the Museum quest giver"
    )
  end)()

