    local townDef = mod.content.maps:get("ALABASTER_TOWN")
    local routeDef = mod.content.maps:get("ROUTE_26")
    if not townDef or not routeDef then return end

    local function tilesetFor(def)
      return def and mod.content.tilesets:get(def.tileset) or nil
    end

    local function isLand(def, tileset, x, y)
      return def
        and tileset
        and x >= 0
        and y >= 0
        and x < def.width * 2
        and y < def.height * 2
        and MapDef.defIsWalkableCell(def, tileset, x, y)
        and not MapDef.defIsWaterCell(def, tileset, x, y)
    end

    local function seedUsed(def)
      local used = {}

      for _, obj in ipairs(def.objects or {}) do
        used[tostring(obj.x) .. ":" .. tostring(obj.y)] = true
      end

      for _, warp in ipairs(def.warps or {}) do
        used[tostring(warp.x) .. ":" .. tostring(warp.y)] = true
      end

      for _, sign in ipairs(def.signs or {}) do
        used[tostring(sign.x) .. ":" .. tostring(sign.y)] = true
      end

      return used
    end

    local function nearestLand(def, tileset, preferredX, preferredY, used, radius)
      radius = radius or 8
      used = used or {}

      for r = 0, radius do
        for dy = -r, r do
          for dx = -r, r do
            if r == 0 or math.max(math.abs(dx), math.abs(dy)) == r then
              local x = preferredX + dx
              local y = preferredY + dy
              local key = tostring(x) .. ":" .. tostring(y)

              if not used[key] and isLand(def, tileset, x, y) then
                used[key] = true
                return x, y
              end
            end
          end
        end
      end

      return preferredX, preferredY
    end

