      townDef, townTileset, 20, 15, townUsed, 5
    )

    -- Post-quest festival positions.  These keep the family spread around the
    -- displays instead of leaving everyone clustered at the entrance forever.
    local postUsed = seedUsed(townDef)
    postUsed[tostring(organizerX) .. ":" .. tostring(organizerY)] = true
    postUsed[tostring(sculpture1X) .. ":" .. tostring(sculpture1Y)] = true
    postUsed[tostring(sculpture2X) .. ":" .. tostring(sculpture2Y)] = true
    postUsed[tostring(sculpture3X) .. ":" .. tostring(sculpture3Y)] = true

    local postS1X, postS1Y = nearestLand(
      townDef, townTileset, sculpture1X + 1, sculpture1Y + 1, postUsed, 5
    )
    local postS2X, postS2Y = nearestLand(
      townDef, townTileset, sculpture2X + 1, sculpture2Y + 1, postUsed, 5
    )
    local postJynxX, postJynxY = nearestLand(
      townDef, townTileset, 17, 13, postUsed, 5
    )
    local postS3X, postS3Y = nearestLand(
      townDef, townTileset, postJynxX - 1, postJynxY, postUsed, 5
    )

    local routeUsed = seedUsed(routeDef)

    -- Route 26 is long and narrow.  Each Smoochum sits in a different third of
    -- the route, so the player has to keep pushing south before turning around.
    local routeS1X, routeS1Y = nearestLand(
      routeDef, routeTileset, 12, 8, routeUsed, 5
    )
    local routeS2X, routeS2Y = nearestLand(
      routeDef, routeTileset, 8, 20, routeUsed, 6
    )
    local routeS3X, routeS3Y = nearestLand(
      routeDef, routeTileset, 10, 30, routeUsed, 6
    )

    local function nearestEscape(x, y, preferredY)
      local scratch = {}
      return nearestLand(
        routeDef,
        routeTileset,
        x,
        preferredY or (y - 2),
        scratch,
        4
      )
    end

    local routeS1ExitX, routeS1ExitY = nearestEscape(
      routeS1X, routeS1Y, routeS1Y - 3
    )
    local routeS2ExitX, routeS2ExitY = nearestEscape(
      routeS2X, routeS2Y, routeS2Y - 2
    )
    local routeS3ExitX, routeS3ExitY = nearestEscape(
