    -------------------------------------------------------------------------
    -- CUTSCENE / TEXT HELPERS
    -------------------------------------------------------------------------

    local function festivalSay(game, textId, done)
      local TextBox = require("src.render.TextBox")
      local value = game.data.text[textId] or textId
      game.stack:push(TextBox.new(game, value, done))
    end

    local festivalCallbacks = setmetatable({}, { __mode = "k" })

    mod.commands:register("mars_alabaster_festival_cutscene_done", function(ctx)
      local callback = festivalCallbacks[ctx.game]
      festivalCallbacks[ctx.game] = nil
      if callback then callback() end
    end)

    local function queueFestivalCutscene(game, ow, rows, callback)
      festivalCallbacks[game] = callback
      rows[#rows + 1] = { "mars_alabaster_festival_cutscene_done" }
      ow:queueScript(rows)
    end

    local function faceFestivalNpc(ow, npc)
      if npc and npc.facePlayer and ow and ow.player then
        npc:facePlayer(ow.player)
      end
    end

    local function allCluesFound(flags)
      return flags[FLAGS.clue1]
        and flags[FLAGS.clue2]
        and flags[FLAGS.clue3]
    end

    -------------------------------------------------------------------------
    -- TOWN INVESTIGATION
    -------------------------------------------------------------------------

    local function revealCulprits(game, ow, done)
      local flags = game.save.flags or {}
      if flags[FLAGS.investigated] then
        if done then done() end
        return
      end

      flags[FLAGS.investigated] = true

      queueFestivalCutscene(
        game,
        ow,
        {
          { "show_object", "ALABASTER_TOWN", "ALABASTER_FESTIVAL_SMOOCHUM_1" },
          { "show_object", "ALABASTER_TOWN", "ALABASTER_FESTIVAL_SMOOCHUM_2" },
          { "show_object", "ALABASTER_TOWN", "ALABASTER_FESTIVAL_SMOOCHUM_3" },
          { "play_cry", "SMOOCHUM" },
          { "show_text", "_MARS_ALABASTER_CULPRITS_SPOTTED" },
        },
        done
      )
    end

    local function sculptureTalk(flagKey, clueText, repeatText)
      return function(game, ow, npc, done)
        local flags = game.save.flags or {}

        if flags[FLAGS.complete] then
          if done then done() end
          return
        end

        if not flags[FLAGS.started] then
          festivalSay(game, "_MARS_ALABASTER_BROKEN_PRE", done)
          return
        end

        if flags[flagKey] then
          festivalSay(game, repeatText, done)
          return
        end

        flags[flagKey] = true

        festivalSay(game, clueText, function()
          if allCluesFound(flags) then
            revealCulprits(game, ow, done)
          elseif done then
            done()
          end
        end)
      end
    end

    local broken1Talk = sculptureTalk(
      FLAGS.clue1,
      "_MARS_ALABASTER_CLUE_1",
      "_MARS_ALABASTER_CLUE_1_REPEAT"
    )
    local broken2Talk = sculptureTalk(
      FLAGS.clue2,
      "_MARS_ALABASTER_CLUE_2",
      "_MARS_ALABASTER_CLUE_2_REPEAT"
    )
    local broken3Talk = sculptureTalk(
      FLAGS.clue3,
      "_MARS_ALABASTER_CLUE_3",
      "_MARS_ALABASTER_CLUE_3_REPEAT"
    )

    -------------------------------------------------------------------------
    -- INITIAL SMOOCHUM ESCAPE FROM TOWN
    -------------------------------------------------------------------------

    local function startSmoochumChase(game, ow, npc, done)
      local flags = game.save.flags or {}

      if not flags[FLAGS.investigated] or flags[FLAGS.chaseStarted] then
        if done then done() end
        return
      end

      flags[FLAGS.chaseStarted] = true

      local rows = {
        { "play_cry", "SMOOCHUM" },
        { "show_text", "_MARS_ALABASTER_TOWN_SMOOCHUM_FLEE" },
      }

      -- Each one visibly dashes one cell south before disappearing onto Route 26.
      local fleeData = {
        { TOWN_SMOOCHUM_1, townS1X, townS1Y, "ALABASTER_FESTIVAL_SMOOCHUM_1" },
        { TOWN_SMOOCHUM_2, townS2X, townS2Y, "ALABASTER_FESTIVAL_SMOOCHUM_2" },
        { TOWN_SMOOCHUM_3, townS3X, townS3Y, "ALABASTER_FESTIVAL_SMOOCHUM_3" },
      }

      for _, info in ipairs(fleeData) do
        local index, x, y, name = info[1], info[2], info[3], info[4]
        local targetY = y + 1

        if isLand(townDef, townTileset, x, targetY) then
          rows[#rows + 1] = { "move_npc_to", index, x, targetY }
        end

        rows[#rows + 1] = { "wait", 5 }
        rows[#rows + 1] = { "hide_object", "ALABASTER_TOWN", name }
      end

      queueFestivalCutscene(game, ow, rows, done)
    end

    -------------------------------------------------------------------------
    -- ROUTE 26 CHASE
    -------------------------------------------------------------------------

    local function routeSmoochumTalk(
      requiredFlag,
      blockedFlag,
      setFlag,
      thisIndex,
      thisName,
      nextName,
      exitX,
      exitY,
      textId,
      isFinal
    )
      return function(game, ow, npc, done)
        local flags = game.save.flags or {}

        if requiredFlag and not flags[requiredFlag] then
          if done then done() end
          return
        end

        if blockedFlag and flags[blockedFlag] then
          if done then done() end
          return
        end

        flags[setFlag] = true
        if isFinal then
          flags[FLAGS.allHome] = true
        end

        local rows = {
          { "play_cry", "SMOOCHUM" },
          { "show_text", textId },
        }

        if exitX and exitY then
          rows[#rows + 1] = {
            "move_npc_to",
            thisIndex,
            exitX,
            exitY,
          }
        end

        rows[#rows + 1] = { "wait", 5 }
        rows[#rows + 1] = { "hide_object", "ROUTE_26", thisName }

        if nextName then
          rows[#rows + 1] = { "show_object", "ROUTE_26", nextName }
        end

        queueFestivalCutscene(game, ow, rows, done)
      end
    end

    local routeS1Talk = routeSmoochumTalk(
      FLAGS.chaseStarted,
      FLAGS.smoochum1Home,
      FLAGS.smoochum1Home,
      ROUTE_SMOOCHUM_1,
      "ROUTE26_FESTIVAL_SMOOCHUM_1",
      "ROUTE26_FESTIVAL_SMOOCHUM_2",
      routeS1ExitX,
      routeS1ExitY,
      "_MARS_ALABASTER_ROUTE_SMOOCHUM_1",
      false
    )

    local routeS2Talk = routeSmoochumTalk(
      FLAGS.smoochum1Home,
      FLAGS.smoochum2Home,
      FLAGS.smoochum2Home,
      ROUTE_SMOOCHUM_2,
      "ROUTE26_FESTIVAL_SMOOCHUM_2",
      "ROUTE26_FESTIVAL_SMOOCHUM_3",
      routeS2ExitX,
      routeS2ExitY,
      "_MARS_ALABASTER_ROUTE_SMOOCHUM_2",
      false
    )

    local routeS3Talk = routeSmoochumTalk(
      FLAGS.smoochum2Home,
      FLAGS.smoochum3Home,
      FLAGS.smoochum3Home,
      ROUTE_SMOOCHUM_3,
      "ROUTE26_FESTIVAL_SMOOCHUM_3",
      nil,
      routeS3ExitX,
      routeS3ExitY,
      "_MARS_ALABASTER_ROUTE_SMOOCHUM_3",
      true
    )

    -------------------------------------------------------------------------
    -- JYNX FAKE-OUT
    -------------------------------------------------------------------------

    local function resolveJynxScene(game, ow, npc, done)
      local flags = game.save.flags or {}

      if not flags[FLAGS.allHome] then
        if done then done() end
        return
      end

      if flags[FLAGS.jynxResolved] then
        if flags[FLAGS.complete] then
          festivalSay(game, "_MARS_ALABASTER_SMOOCHUM_POST_1", done)
        else
          festivalSay(game, "_MARS_ALABASTER_BASKET_RETURNED", done)
        end
        return
      end

      -- Stage Jynx relative to the player's actual position. Prefer a tile
      -- horizontally beside the player so she can approach, stare them down,
      -- then make a visible turn upward toward the Smoochum.
      local playerX = ow and ow.player and ow.player.cellX or jynxTargetX
      local playerY = ow and ow.player and ow.player.cellY or jynxTargetY

      local approachX, approachY = jynxTargetX, jynxTargetY
      local approachFacing = "left"
      local occupied = {
        [tostring(townS1X) .. ":" .. tostring(townS1Y)] = true,
        [tostring(townS2X) .. ":" .. tostring(townS2Y)] = true,
        [tostring(townS3X) .. ":" .. tostring(townS3Y)] = true,
        [tostring(organizerX) .. ":" .. tostring(organizerY)] = true,
        [tostring(sculpture1X) .. ":" .. tostring(sculpture1Y)] = true,
        [tostring(sculpture2X) .. ":" .. tostring(sculpture2Y)] = true,
        [tostring(sculpture3X) .. ":" .. tostring(sculpture3Y)] = true,
      }
      local candidates = {
        { playerX + 1, playerY, "left" },
        { playerX - 1, playerY, "right" },
        { playerX, playerY + 1, "up" },
        { playerX, playerY - 1, "down" },
      }

      for _, candidate in ipairs(candidates) do
        local cx, cy = candidate[1], candidate[2]
        local key = tostring(cx) .. ":" .. tostring(cy)
        if not occupied[key] and isLand(townDef, townTileset, cx, cy) then
          approachX, approachY, approachFacing = cx, cy, candidate[3]
          break
        end
      end

      local rows = {
        { "play_cry", "SMOOCHUM" },
        { "show_text", "_MARS_ALABASTER_JYNX_START" },
        { "show_object", "ALABASTER_TOWN", "ALABASTER_FESTIVAL_JYNX" },
        { "place_npc", TOWN_JYNX, jynxStartX, jynxStartY, approachFacing },
      }

      if jynxStartX ~= approachX or jynxStartY ~= approachY then
        rows[#rows + 1] = {
          "move_npc_to",
          TOWN_JYNX,
          approachX,
          approachY,
        }
      end

      -- First face the player for the fake-out. Then turn upward and scold
      -- the Smoochum, exactly like a staged little parent/child scene.
      rows[#rows + 1] = { "face_object", TOWN_JYNX, approachFacing }
      rows[#rows + 1] = { "play_cry", "JYNX" }
      rows[#rows + 1] = { "show_text", "_MARS_ALABASTER_JYNX_STARE" }
      rows[#rows + 1] = { "wait", 35 }
      rows[#rows + 1] = { "face_object", TOWN_JYNX, "up" }
      rows[#rows + 1] = { "wait", 10 }
      rows[#rows + 1] = { "play_cry", "JYNX" }
      rows[#rows + 1] = { "show_text", "_MARS_ALABASTER_JYNX_SCOLD" }
      rows[#rows + 1] = { "show_text", "_MARS_ALABASTER_BASKET_RETURNED" }

      queueFestivalCutscene(game, ow, rows, function()
        flags[FLAGS.jynxResolved] = true
        if done then done() end
      end)
    end

    -------------------------------------------------------------------------
    -- REWARD / FESTIVAL TRANSFORMATION
    -------------------------------------------------------------------------

    local function showFestivalStateRows()
      return {
        { "hide_object", "ALABASTER_TOWN", "ALABASTER_FESTIVAL_BROKEN_1" },
        { "hide_object", "ALABASTER_TOWN", "ALABASTER_FESTIVAL_BROKEN_2" },
        { "hide_object", "ALABASTER_TOWN", "ALABASTER_FESTIVAL_BROKEN_3" },
        { "show_object", "ALABASTER_TOWN", "ALABASTER_FESTIVAL_ARTICUNO_SCULPTURE" },
        { "show_object", "ALABASTER_TOWN", "ALABASTER_FESTIVAL_DEWGONG_SCULPTURE" },
        { "show_object", "ALABASTER_TOWN", "ALABASTER_FESTIVAL_SMOOCHUM_SCULPTURE" },
        { "show_object", "ALABASTER_TOWN", "ALABASTER_FESTIVAL_SMOOCHUM_1" },
        { "show_object", "ALABASTER_TOWN", "ALABASTER_FESTIVAL_SMOOCHUM_2" },
        { "show_object", "ALABASTER_TOWN", "ALABASTER_FESTIVAL_SMOOCHUM_3" },
        { "show_object", "ALABASTER_TOWN", "ALABASTER_FESTIVAL_JYNX" },
        { "place_npc", TOWN_SMOOCHUM_1, postS1X, postS1Y, "down" },
        { "place_npc", TOWN_SMOOCHUM_2, postS2X, postS2Y, "down" },
        { "place_npc", TOWN_SMOOCHUM_3, postS3X, postS3Y, "right" },
        { "place_npc", TOWN_JYNX, postJynxX, postJynxY, "left" },
      }
    end

    local function giveFestivalReward(game, ow, done)
      local flags = game.save.flags or {}
      local Bag = require("src.inventory.Bag")

      if not Bag.add(game.save, "ICE_STONE", 1, game.data) then
        festivalSay(game, "_MARS_ALABASTER_FESTIVAL_BAG_FULL", done)
        return
      end

      game.save.money = math.min(
        999999,
        (game.save.money or 0) + 3000
      )

      flags[FLAGS.complete] = true

      local Sound = require("src.core.Sound")
      Sound.play(game.data, "Get_Item1")

      festivalSay(game, "_MARS_ALABASTER_FESTIVAL_REWARD", function()
        local rows = {
          { "fade", "out", 20 },
          { "wait", 25 },
        }

        for _, row in ipairs(showFestivalStateRows()) do
          rows[#rows + 1] = row
        end

        rows[#rows + 1] = { "wait", 20 }
        rows[#rows + 1] = { "fade", "in", 20 }
        rows[#rows + 1] = { "show_text", "_MARS_ALABASTER_FESTIVAL_OPEN" }

        queueFestivalCutscene(game, ow, rows, done)
      end)
    end

    local function organizerTalk(game, ow, npc, done)
      local flags = game.save.flags or {}
      faceFestivalNpc(ow, npc)

      if flags[FLAGS.complete] then
        festivalSay(game, "_MARS_ALABASTER_FESTIVAL_COMPLETE", done)
        return
      end

      if flags[FLAGS.jynxResolved] then
        festivalSay(game, "_MARS_ALABASTER_FESTIVAL_REWARD_INTRO", function()
          festivalSay(game, "_MARS_ALABASTER_FESTIVAL_SCULPT_RALLY", function()
            giveFestivalReward(game, ow, done)
          end)
        end)
        return
      end

      if flags[FLAGS.allHome] then
        festivalSay(game, "_MARS_ALABASTER_FESTIVAL_RETURN_REMINDER", done)
        return
      end

      if flags[FLAGS.chaseStarted] then
        festivalSay(game, "_MARS_ALABASTER_FESTIVAL_CHASE_REMINDER", done)
        return
      end

      if flags[FLAGS.investigated] then
        festivalSay(game, "_MARS_ALABASTER_CULPRITS_SPOTTED", done)
        return
      end

      if flags[FLAGS.started] then
        festivalSay(game, "_MARS_ALABASTER_FESTIVAL_REMINDER", done)
        return
      end

      flags[FLAGS.started] = true
      festivalSay(game, "_MARS_ALABASTER_FESTIVAL_START", done)
    end

    -------------------------------------------------------------------------
    -- EXISTING ALABASTER NPCS BECOME PART OF THE INVESTIGATION
    -------------------------------------------------------------------------

    local function existingTownNpcTalk(
      normalText,
      questText,
      postText
    )
      return function(game, ow, npc, done)
        local flags = game.save.flags or {}
        faceFestivalNpc(ow, npc)

        if flags[FLAGS.complete] then
          festivalSay(game, postText, done)
        elseif flags[FLAGS.started] then
          festivalSay(game, questText, done)
        else
          festivalSay(game, normalText, done)
        end
      end
    end

    local hikerFestivalTalk = existingTownNpcTalk(
      "_MARS_ALABASTER_TOWN_HIKER",
      "_MARS_ALABASTER_HIKER_FESTIVAL",
      "_MARS_ALABASTER_HIKER_FESTIVAL_POST"
    )
    local girlFestivalTalk = existingTownNpcTalk(
      "_MARS_ALABASTER_TOWN_GIRL",
      "_MARS_ALABASTER_GIRL_FESTIVAL",
      "_MARS_ALABASTER_GIRL_FESTIVAL_POST"
    )
    local youngsterFestivalTalk = existingTownNpcTalk(
      "_MARS_ALABASTER_TOWN_YOUNGSTER",
      "_MARS_ALABASTER_YOUNGSTER_FESTIVAL",
      "_MARS_ALABASTER_YOUNGSTER_FESTIVAL_POST"
    )

    local function finishedSculptureTalk(textId)
      return function(game, ow, npc, done)
        festivalSay(game, textId, done)
      end
    end

    local finished1Talk = finishedSculptureTalk(
      "_MARS_ALABASTER_SCULPTURE_ARTICUNO"
    )
    local finished2Talk = finishedSculptureTalk(
      "_MARS_ALABASTER_SCULPTURE_DEWGONG"
    )
    local finished3Talk = finishedSculptureTalk(
      "_MARS_ALABASTER_SCULPTURE_SMOOCHUM"
    )

    local function townSmoochumTalk(postText)
      return function(game, ow, npc, done)
        local flags = game.save.flags or {}

        if flags[FLAGS.complete] then
          festivalSay(game, postText, done)
          return
        end

        if flags[FLAGS.allHome] then
          resolveJynxScene(game, ow, npc, done)
          return
        end

        startSmoochumChase(game, ow, npc, done)
      end
    end

    local townS1Talk = townSmoochumTalk("_MARS_ALABASTER_SMOOCHUM_POST_1")
    local townS2Talk = townSmoochumTalk("_MARS_ALABASTER_SMOOCHUM_POST_2")
    local townS3Talk = townSmoochumTalk("_MARS_ALABASTER_SMOOCHUM_POST_3")

    local function townJynxTalk(game, ow, npc, done)
      local flags = game.save.flags or {}

      if flags[FLAGS.complete] then
        festivalSay(game, "_MARS_ALABASTER_JYNX_POST", done)
      elseif flags[FLAGS.jynxResolved] then
        festivalSay(game, "_MARS_ALABASTER_JYNX_SCOLD", done)
      elseif flags[FLAGS.allHome] then
        resolveJynxScene(game, ow, npc, done)
      elseif done then
        done()
      end
    end

    -------------------------------------------------------------------------
    -- MAP STATE
    -------------------------------------------------------------------------

    mod.content.map_scripts:register("ALABASTER_TOWN", {
      priority = 294,

      onEnter = function(game, ow)
        local flags = game.save.flags or {}
        local rows = {
          { "show_object", "ALABASTER_TOWN", "ALABASTER_FESTIVAL_ORGANIZER" },
        }

        if flags[FLAGS.complete] then
          for _, row in ipairs(showFestivalStateRows()) do
            rows[#rows + 1] = row
          end
        else
          rows[#rows + 1] = { "show_object", "ALABASTER_TOWN", "ALABASTER_FESTIVAL_BROKEN_1" }
          rows[#rows + 1] = { "show_object", "ALABASTER_TOWN", "ALABASTER_FESTIVAL_BROKEN_2" }
          rows[#rows + 1] = { "show_object", "ALABASTER_TOWN", "ALABASTER_FESTIVAL_BROKEN_3" }
          rows[#rows + 1] = { "hide_object", "ALABASTER_TOWN", "ALABASTER_FESTIVAL_ARTICUNO_SCULPTURE" }
          rows[#rows + 1] = { "hide_object", "ALABASTER_TOWN", "ALABASTER_FESTIVAL_DEWGONG_SCULPTURE" }
          rows[#rows + 1] = { "hide_object", "ALABASTER_TOWN", "ALABASTER_FESTIVAL_SMOOCHUM_SCULPTURE" }

          local showInitialCulprits =
            flags[FLAGS.investigated]
            and not flags[FLAGS.chaseStarted]

          local showReturnedFamily =
            flags[FLAGS.allHome]

          if showInitialCulprits or showReturnedFamily then
            rows[#rows + 1] = { "show_object", "ALABASTER_TOWN", "ALABASTER_FESTIVAL_SMOOCHUM_1" }
            rows[#rows + 1] = { "show_object", "ALABASTER_TOWN", "ALABASTER_FESTIVAL_SMOOCHUM_2" }
            rows[#rows + 1] = { "show_object", "ALABASTER_TOWN", "ALABASTER_FESTIVAL_SMOOCHUM_3" }
            rows[#rows + 1] = { "place_npc", TOWN_SMOOCHUM_1, townS1X, townS1Y, "down" }
            rows[#rows + 1] = { "place_npc", TOWN_SMOOCHUM_2, townS2X, townS2Y, "down" }
            rows[#rows + 1] = { "place_npc", TOWN_SMOOCHUM_3, townS3X, townS3Y, "down" }
          else
            rows[#rows + 1] = { "hide_object", "ALABASTER_TOWN", "ALABASTER_FESTIVAL_SMOOCHUM_1" }
            rows[#rows + 1] = { "hide_object", "ALABASTER_TOWN", "ALABASTER_FESTIVAL_SMOOCHUM_2" }
            rows[#rows + 1] = { "hide_object", "ALABASTER_TOWN", "ALABASTER_FESTIVAL_SMOOCHUM_3" }
          end

          if flags[FLAGS.jynxResolved] then
            rows[#rows + 1] = { "show_object", "ALABASTER_TOWN", "ALABASTER_FESTIVAL_JYNX" }
            rows[#rows + 1] = { "place_npc", TOWN_JYNX, jynxTargetX, jynxTargetY, "left" }
          else
            rows[#rows + 1] = { "hide_object", "ALABASTER_TOWN", "ALABASTER_FESTIVAL_JYNX" }
          end
        end

        ow:queueScript(rows)
      end,

      talk = {
        [TEXT_ORGANIZER] = organizerTalk,
        [TEXT_BROKEN_1] = broken1Talk,
        [TEXT_BROKEN_2] = broken2Talk,
        [TEXT_BROKEN_3] = broken3Talk,
        [TEXT_FINISHED_1] = finished1Talk,
        [TEXT_FINISHED_2] = finished2Talk,
        [TEXT_FINISHED_3] = finished3Talk,
        [TEXT_TOWN_SMOOCHUM_1] = townS1Talk,
        [TEXT_TOWN_SMOOCHUM_2] = townS2Talk,
        [TEXT_TOWN_SMOOCHUM_3] = townS3Talk,
        [TEXT_TOWN_JYNX] = townJynxTalk,

        -- Higher priority than the original Alabaster flavor registration.
        TEXT_ALABASTER_TOWN_HIKER = hikerFestivalTalk,
        TEXT_ALABASTER_TOWN_GIRL = girlFestivalTalk,
        TEXT_ALABASTER_TOWN_YOUNGSTER = youngsterFestivalTalk,
      },
    })

    mod.content.map_scripts:register("ROUTE_26", {
      priority = 294,

      onEnter = function(game, ow)
        local flags = game.save.flags or {}
        local rows = {}

        local show1 = flags[FLAGS.chaseStarted]
          and not flags[FLAGS.smoochum1Home]
        local show2 = flags[FLAGS.smoochum1Home]
          and not flags[FLAGS.smoochum2Home]
        local show3 = flags[FLAGS.smoochum2Home]
