      townScarf = "EVENT_FROSLASS_CLUE_TOWN_SCARF",
      townTracks = "EVENT_FROSLASS_CLUE_TOWN_TRACKS",
      caveBell = "EVENT_FROSLASS_CLUE_CAVE_BELL",
      caveTracks = "EVENT_FROSLASS_CLUE_CAVE_TRACKS",

      rush = "EVENT_FROSLASS_QUEST_GIVER_RUSHED_TO_CAVE",
      firstWon = "EVENT_FROSLASS_FIRST_BATTLE_WON",
      retreatPending = "EVENT_FROSLASS_FIRST_BATTLE_RETREAT_PENDING",
