    local function hasSilphScope(save)
      local inventory = save and save.inventory or {}
      local qty = inventory.SILPH_SCOPE

      if qty ~= nil and qty ~= false and qty ~= 0 then
        return true
      end

      -- Defensive compatibility with saves/imports that expose an acquisition
      -- event alongside the key item.
      local flags = save and save.flags or {}
      return flags.EVENT_GOT_SILPH_SCOPE
        or flags.EVENT_SILPH_SCOPE
        or false
    end

    local function clueCount(flags)
      local n = 0
      for _, flag in ipairs(CLUE_FLAGS) do
        if flags[flag] then n = n + 1 end
      end
      return n
    end

    local function allClues(flags)
      return clueCount(flags) == #CLUE_FLAGS
    end

    local function tilesetFor(def)
      return def and mod.content.tilesets:get(def.tileset) or nil
    end

    local function isLand(def, tileset, x, y)
      if not def or not tileset then return false end
      if x < 0 or y < 0 or x >= def.width * 2 or y >= def.height * 2 then
        return false
      end

      return MapDef.defIsWalkableCell(def, tileset, x, y)
        and not MapDef.defIsWaterCell(def, tileset, x, y)
    end

    local function seedUsed(def)
      local used = {}

      for _, obj in ipairs(def.objects or {}) do
        if obj.x ~= nil and obj.y ~= nil then
          used[tostring(obj.x) .. ":" .. tostring(obj.y)] = true
        end
      end
      for _, warp in ipairs(def.warps or {}) do
        if warp.x ~= nil and warp.y ~= nil then
          used[tostring(warp.x) .. ":" .. tostring(warp.y)] = true
        end
      end
      for _, sign in ipairs(def.signs or {}) do
        if sign.x ~= nil and sign.y ~= nil then
          used[tostring(sign.x) .. ":" .. tostring(sign.y)] = true
        end
      end

      return used
    end

    local function nearestLand(def, tileset, preferredX, preferredY, used, radius)
      used = used or {}
      radius = radius or 8

      for r = 0, radius do
        for dy = -r, r do
          for dx = -r, r do
            if r == 0 or math.max(math.abs(dx), math.abs(dy)) == r then
              local x = preferredX + dx
              local y = preferredY + dy
              local key = tostring(x) .. ":" .. tostring(y)

              if not used[key] and isLand(def, tileset, x, y) then
                used[key] = true
                return x, y
              end
            end
          end
        end
      end

      return preferredX, preferredY
    end

    local function directionToward(fromX, fromY, toX, toY)
      local dx = (toX or fromX) - (fromX or 0)
      local dy = (toY or fromY) - (fromY or 0)

      if math.abs(dx) > math.abs(dy) then
        return dx >= 0 and "right" or "left"
      end
      if dy ~= 0 then
        return dy >= 0 and "down" or "up"
      end
      return "down"
    end

    local function marsCellKey(x, y)
      return tostring(x) .. ":" .. tostring(y)
    end

    local function findLandPath(def, tileset, startX, startY, targetX, targetY)
      if startX == targetX and startY == targetY then return {} end

      local directions = {
        { dx = 0, dy = -1, dir = "up" },
        { dx = -1, dy = 0, dir = "left" },
        { dx = 1, dy = 0, dir = "right" },
        { dx = 0, dy = 1, dir = "down" },
      }

      local startKey = marsCellKey(startX, startY)
      local targetKey = marsCellKey(targetX, targetY)
      local queue = { { x = startX, y = startY } }
      local head = 1
      local previous = {
        [startKey] = false,
      }

      while head <= #queue do
        local current = queue[head]
        head = head + 1

        for _, step in ipairs(directions) do
          local nx = current.x + step.dx
          local ny = current.y + step.dy
          local key = marsCellKey(nx, ny)

          if previous[key] == nil
             and isLand(def, tileset, nx, ny)
          then
            previous[key] = {
              x = current.x,
              y = current.y,
              dir = step.dir,
            }

            if key == targetKey then
              local reversed = {}
              local cx, cy = nx, ny
              local ck = key

              while ck ~= startKey do
                local link = previous[ck]
                if not link then break end

                reversed[#reversed + 1] = link.dir
                cx, cy = link.x, link.y
                ck = marsCellKey(cx, cy)
              end

              local path = {}
              for i = #reversed, 1, -1 do
                path[#path + 1] = reversed[i]
              end
              return path
            end

            queue[#queue + 1] = { x = nx, y = ny }
          end
        end
      end

      return nil
    end

    local function appendNpcPath(rows, objectIndex, path)
      if not path then return false end

      for _, dir in ipairs(path) do
        rows[#rows + 1] = {
          "move_npc",
          objectIndex,
          dir,
          1,
        }
      end

      return true
    end

    local function appendNpcSteps(rows, objectIndex, dir, count)
      count = math.max(0, math.floor(count or 0))

      for _ = 1, count do
        rows[#rows + 1] = {
          "move_npc",
          objectIndex,
          dir,
          1,
        }
      end
    end

    -- exact stair cells from the NEW supplied ALABASTER_CAVE TMJ.
