      local x = startX
      local y = startY
      local dx = targetX - startX
      local dy = targetY - startY
      local ax = math.abs(dx)
      local ay = math.abs(dy)
      local sx = dx < 0 and "left" or "right"
      local sy = dy < 0 and "up" or "down"

      -- Bresenham-style Manhattan stepping: alternate the needed horizontal
      -- and vertical moves so the NPC heads directly toward the target instead
      -- of tracing a rectangular/pathfinder route around the platform.
      local total = ax + ay
      local usedX = 0
      local usedY = 0

