          local xProgress = ax > 0 and (usedX / ax) or 1
          local yProgress = ay > 0 and (usedY / ay) or 1

          if xProgress <= yProgress then
            rows[#rows + 1] = {
              "move_npc",
              objectIndex,
              sx,
              1,
            }
            usedX = usedX + 1
            x = x + (dx < 0 and -1 or 1)
          else
            rows[#rows + 1] = {
              "move_npc",
              objectIndex,
              sy,
              1,
            }
            usedY = usedY + 1
            y = y + (dy < 0 and -1 or 1)
          end
        elseif wantX then
          rows[#rows + 1] = {
            "move_npc",
            objectIndex,
            sx,
            1,
          }
          usedX = usedX + 1
          x = x + (dx < 0 and -1 or 1)
        elseif wantY then
