    -------------------------------------------------------------------------
    -- Quest markers.
    -------------------------------------------------------------------------

    do
      local NPC = require("src.world.NPC")
      local registry = NPC._marsQuestMarkerRegistry

      if registry then
        registry.ALABASTER_HOUSE_1 = registry.ALABASTER_HOUSE_1 or {}
        registry.ALABASTER_HOUSE_1[#registry.ALABASTER_HOUSE_1 + 1] = {
          objectName = "ALABASTER_HOUSE1_OLD_MAN",
          active = function(save)
            local flags = save and save.flags or {}
            if flags[FLAGS.complete] then return false end
            if not hasSilphScope(save) then return false end

            return not flags[FLAGS.started]
              or (
                flags[FLAGS.started]
                and allClues(flags)
                and not flags[FLAGS.rush]
              )
              or (
                flags[FLAGS.reunion]
                and not flags[FLAGS.complete]
              )
          end,
        }
      end
    end

    -------------------------------------------------------------------------
    -- Uncatchable Froslass confrontation.
    --
    -- Same proven technique as Moonfall Clefable: a trainer-style battle with
    -- Froslass's own Pokemon front art. This removes BALL/RUN while presenting
    -- FROSLASS itself rather than a human trainer.
    -------------------------------------------------------------------------

    local froslassDef = mod.content.pokemon:get("FROSLASS")

    mod.content.trainers:register("OPP_FROSLASS_GUARDIAN", {
      id = "OPP_FROSLASS_GUARDIAN",
      name = "FROSLASS",
      basePic = "OPP_POKEMANIAC",
      pic = froslassDef and froslassDef.spriteFront,
      trueColor = true,
      baseMoney = 0,
      aiClass = (mod.content.trainers:get("OPP_POKEMANIAC") or {}).aiClass,
      aiMods = (mod.content.trainers:get("OPP_POKEMANIAC") or {}).aiMods,
      parties = {
        {
          { level = 32, species = "FROSLASS" },
        },
      },
    })

    mod.hooks:wrap("trainer.party", function(next, oppClass, partyIndex, partyDef)
      if oppClass ~= "OPP_FROSLASS_GUARDIAN" or (partyIndex or 1) ~= 1 then
        return next(oppClass, partyIndex, partyDef)
      end

      return next(oppClass, partyIndex, {
        {
          level = 32,
          species = "FROSLASS",
          moves = { "ICE_BEAM", "SHADOW_BALL", "CONFUSE_RAY", "DOUBLE_TEAM" },
        },
      })
    end, 92)

