    -------------------------------------------------------------------------
    -- Helpers / callbacks.
    -------------------------------------------------------------------------

    local function say(game, idOrText, done)
      game.stack:push(TextBox.new(
        game,
        game.data.text[idOrText] or idOrText,
        done
      ))
    end

    local sceneCallbacks = setmetatable({}, { __mode = "k" })

    mod.commands:register("mars_froslass_quest_callback", function(ctx)
      local callback = sceneCallbacks[ctx.game]
      sceneCallbacks[ctx.game] = nil
      if callback then callback() end
    end)

    local function queueScene(game, ow, rows, callback)
      sceneCallbacks[game] = callback
      rows[#rows + 1] = { "mars_froslass_quest_callback" }
      ow:queueScript(rows)
    end

    local function faceNpc(ow, npc)
      if npc and npc.facePlayer and ow and ow.player then
        npc:facePlayer(ow.player)
      end
    end

    local function clueVisible(flags, flag)
      return flags[FLAGS.started]
        and not flags[FLAGS.rush]
        and not flags[flag]
        and not flags[FLAGS.complete]
    end

    local clueInfo = {
      [TEXT_ROUTE_SLED] = {
        flag = FLAGS.routeSled,
        map = "ROUTE_26",
        object = "MARS_FROSLASS_ROUTE_SLED",
        text = "_MARS_FROSLASS_ROUTE_SLED_TEXT",
      },
      [TEXT_ROUTE_MITTEN] = {
        flag = FLAGS.routeMitten,
        map = "ROUTE_26",
        object = "MARS_FROSLASS_ROUTE_MITTEN",
        text = "_MARS_FROSLASS_ROUTE_MITTEN_TEXT",
      },
      [TEXT_TOWN_SCARF] = {
        flag = FLAGS.townScarf,
        map = "ALABASTER_TOWN",
        object = "MARS_FROSLASS_TOWN_SCARF",
        text = "_MARS_FROSLASS_TOWN_SCARF_TEXT",
      },
      [TEXT_TOWN_TRACKS] = {
        flag = FLAGS.townTracks,
        map = "ALABASTER_TOWN",
        object = "MARS_FROSLASS_TOWN_TRACKS",
        text = "_MARS_FROSLASS_TOWN_TRACKS_TEXT",
      },
      [TEXT_CAVE_BELL] = {
        flag = FLAGS.caveBell,
        map = "ALABASTER_CAVE",
        object = "MARS_FROSLASS_CAVE_BELL",
        text = "_MARS_FROSLASS_CAVE_BELL_TEXT",
      },
      [TEXT_CAVE_TRACKS] = {
        flag = FLAGS.caveTracks,
        map = "ALABASTER_CAVE",
        object = "MARS_FROSLASS_CAVE_TRACKS",
        text = "_MARS_FROSLASS_CAVE_TRACKS_TEXT",
      },
    }

    local function makeClueTalk(info)
      return function(game, ow, npc, done)
        local flags = game.save.flags or {}

        if not flags[FLAGS.started] or flags[info.flag] then
          if done then done() end
          return
        end

        say(game, info.text, function()
          flags[info.flag] = true

          ow:queueScript({
            { "hide_object", info.map, info.object },
          })

          if allClues(flags) then
            say(game, "_MARS_FROSLASS_ALL_CLUES", done)
          elseif done then
            done()
          end
        end)
      end
    end

    -------------------------------------------------------------------------
    -- TM reward: find the imported Ice Beam machine by metadata instead of
    -- assuming a particular internal item id.
    -------------------------------------------------------------------------

    local function findIceTM(game)
      local items = game.data and game.data.items or {}

      for itemId, def in pairs(items) do
        local machine = def and def.machine
        if machine
           and machine.kind == "TM"
           and machine.move == "ICE_BEAM"
        then
          return itemId, def, "ICE BEAM"
        end
      end

      -- Defensive fallback if an unusual import omits Ice Beam's TM.
      for itemId, def in pairs(items) do
        local machine = def and def.machine
        if machine
           and machine.kind == "TM"
           and machine.move == "BLIZZARD"
        then
          return itemId, def, "BLIZZARD"
        end
      end

      return nil, nil, nil
    end

    local function giveReward(game, done)
      local flags = game.save.flags or {}
      local itemId, itemDef, moveName = findIceTM(game)

      if not itemId then
        mod.log:error("could not find an ICE BEAM/BLIZZARD TM reward")
        say(
          game,
          "OLD MAN: I seem to have\nmisplaced the TM.\f"
            .. "Please come back in a\nmoment.",
          done
        )
        return
      end

      if not Bag.add(game.save, itemId, 1, game.data) then
        say(game, "_MARS_FROSLASS_TM_FULL", done)
        return
      end

      Sound.play(game.data, "Get_Item1")

      flags[FLAGS.reward] = true
      flags[FLAGS.complete] = true

      local tmName =
        (itemDef and itemDef.name)
        or tostring(itemId)

      say(
        game,
        "You received " .. tmName .. "!\f"
          .. tmName .. " teaches\n" .. tostring(moveName) .. "!",
        done
      )
    end

    -------------------------------------------------------------------------
    -- House / quest-giver flow.
    -------------------------------------------------------------------------

    local function oldManTalk(game, ow, npc, done)
      faceNpc(ow, npc)

      local flags = game.save.flags or {}

      if flags[FLAGS.complete] then
        say(game, "_MARS_FROSLASS_AFTER", done)
        return
      end

      if flags[FLAGS.reunion] then
        say(game, "_MARS_FROSLASS_EPILOGUE", function()
          giveReward(game, done)
        end)
        return
      end

      if not hasSilphScope(game.save) then
        say(game, "_MARS_ALABASTER_HOUSE1_OLD_MAN", done)
        return
      end

      if not flags[FLAGS.started] then
        say(game, "_MARS_FROSLASS_INTRO", function()
          flags[FLAGS.started] = true
          if done then done() end
        end)
        return
      end

      if allClues(flags) and not flags[FLAGS.rush] then
        say(game, "_MARS_FROSLASS_REPORT", function()
          flags[FLAGS.rush] = true

          queueScene(game, ow, {
            { "move_npc_to", 1, 2, 6 },
            {
              "hide_object",
              "ALABASTER_HOUSE_1",
              "ALABASTER_HOUSE1_OLD_MAN",
            },
          }, done)
        end)
        return
      end

      say(
        game,
        "OLD MAN: I know there's\nmore to go on than what\nyou've found so far.\f"
          .. "Keep looking.\f"
          .. "Search ROUTE 26,\naround town, and inside\nALABASTER CAVE.",
        done
      )
    end

    -------------------------------------------------------------------------
    -- First cave confrontation / uncatchable Froslass battle.
    -------------------------------------------------------------------------

    local function prepareGuardianTrainerPic(game)
      local trainer =
        game.data
        and game.data.trainers
        and game.data.trainers.OPP_FROSLASS_GUARDIAN

      if not trainer or not froslassDef then return end

      if mod._marsRuntimePokemonArtPath then
        trainer.pic = mod._marsRuntimePokemonArtPath(
          froslassDef.spriteFront,
          "FROSLASS",
          "front"
        )
      else
        trainer.pic = froslassDef.spriteFront
      end

      trainer.trueColor = true
    end

    local function startFroslassBattle(game, ow, done)
      prepareGuardianTrainerPic(game)

      local battle =
        BattleState.newTrainer(game, "OPP_FROSLASS_GUARDIAN", 1)

      battle.endBattleText = "FROSLASS was driven back!"

      local baseRomText = battle.romText
      battle.romText = function(self, label, fallback, ...)
        if label == "_MoneyForWinningText" then
          return "FROSLASS was\ndriven back!"
        end
        return baseRomText(self, label, fallback, ...)
      end

      battle.onFinish = function(result)
        local flags = game.save.flags or {}

        if result == "win" then
          -- Commit the state before returning to the overworld so onEnter
          -- cannot restart the confrontation.
          flags[FLAGS.firstWon] = true
          flags[FLAGS.deepChase] = true
          flags[FLAGS.retreatPending] = true
        end

        ow:afterBattle(result, battle)

        if result ~= "win" then
          if done then done() end
          return
        end

        local froslassStartX =
          game.marsFroslassQuestBattleX or caveFroslassX
        local froslassStartY =
          game.marsFroslassQuestBattleY or caveFroslassY

        local oldManStartX =
          game.marsFroslassOldManBattleX or caveOldManHitX
        local oldManStartY =
          game.marsFroslassOldManBattleY or caveOldManHitY

        -- IMPORTANT: no place_npc calls here. The actors continue walking from
        -- the positions the player actually saw immediately before the battle.
        local rows = {
          {
            "show_object",
            "ALABASTER_CAVE",
            "MARS_FROSLASS_CAVE_FROSLASS",
          },
          {
            "show_object",
            "ALABASTER_CAVE",
            "MARS_FROSLASS_CAVE_OLD_MAN",
          },
          {
            "hide_object",
            "ALABASTER_CAVE",
            "MARS_FROSLASS_CAVE_MACHOKE",
          },
          { "play_cry", "FROSLASS" },
          { "show_text", "_MARS_FROSLASS_RETREAT" },
        }

        -- FROSLASS makes one direct approach to the stair landing from its
        -- current position, then walks DOWN and LEFT along the bottom passage.
        appendVisibleStairChase(
          rows,
          CAVE_FROSLASS_INDEX,
          froslassStartX,
          froslassStartY
        )

        rows[#rows + 1] = {
          "hide_object",
          "ALABASTER_CAVE",
          "MARS_FROSLASS_CAVE_FROSLASS",
        }
        rows[#rows + 1] = {
          "show_text",
          "_MARS_FROSLASS_OLD_MAN_CHASE",
        }

        -- The OLD MAN does the same from the exact place FROSLASS knocked him to.
        appendVisibleStairChase(
          rows,
          CAVE_OLD_MAN_INDEX,
          oldManStartX,
          oldManStartY
        )

        rows[#rows + 1] = {
          "hide_object",
          "ALABASTER_CAVE",
          "MARS_FROSLASS_CAVE_OLD_MAN",
        }

        -- Stage the final tableau immediately after the chase. These three
        -- actors are already visible when the player reaches the upper-left
        -- chamber; nothing appears only because the trigger was stepped on.
        rows[#rows + 1] = {
          "place_npc",
          DEEP_OLD_MAN_INDEX,
          deepOldManX,
          deepOldManY,
          "up",
        }
        rows[#rows + 1] = {
          "place_npc",
          DEEP_FROSLASS_INDEX,
          deepFroslassX,
          deepFroslassY,
          "down",
        }
        rows[#rows + 1] = {
          "place_npc",
          DEEP_CHILD_INDEX,
          deepChildX,
          deepChildY,
          "left",
        }
        rows[#rows + 1] = {
          "show_object",
          "ALABASTER_CAVE",
          "MARS_FROSLASS_DEEP_OLD_MAN",
        }
        rows[#rows + 1] = {
          "show_object",
          "ALABASTER_CAVE",
          "MARS_FROSLASS_DEEP_FROSLASS",
        }
        rows[#rows + 1] = {
          "show_object",
          "ALABASTER_CAVE",
          "MARS_FROSLASS_DEEP_CHILD",
        }
        -- Keep both SNORUNT hidden at their TRUE right-side entrance cells.
        rows[#rows + 1] = {
          "place_npc",
          DEEP_SNORUNT_1_INDEX,
          deepSnorunt1StartX,
          deepSnorunt1StartY,
          "left",
        }
        rows[#rows + 1] = {
          "place_npc",
          DEEP_SNORUNT_2_INDEX,
          deepSnorunt2StartX,
          deepSnorunt2StartY,
          "left",
        }
        rows[#rows + 1] = {
          "hide_object",
          "ALABASTER_CAVE",
          "MARS_FROSLASS_DEEP_SNORUNT_1",
        }
        rows[#rows + 1] = {
          "hide_object",
          "ALABASTER_CAVE",
          "MARS_FROSLASS_DEEP_SNORUNT_2",
        }

        queueScene(game, ow, rows, function()
          flags[FLAGS.retreatPending] = nil
          game.marsFroslassQuestBattleX = nil
          game.marsFroslassQuestBattleY = nil
          game.marsFroslassOldManBattleX = nil
          game.marsFroslassOldManBattleY = nil
          if done then done() end
        end)
      end

      ow:pushBattle(battle)
    end

    local function queueFirstCaveScene(game, ow)
      local oldFaceFroslass = directionToward(
        caveOldManApproachX,
        caveOldManApproachY,
        caveFroslassX,
        caveFroslassY
      )
      local froslassFaceOld = directionToward(
        caveFroslassX,
        caveFroslassY,
        caveOldManApproachX,
        caveOldManApproachY
      )
      local machokeFaceFroslass = directionToward(
        caveMachokeX, caveMachokeY, caveFroslassX, caveFroslassY
      )

      local player = ow and ow.player or nil
      local playerAfterFourX = player and player.cellX or 22
      local playerAfterFourY = player and (player.cellY - 4) or 13
      local playerBattleX = playerAfterFourX
      local playerBattleY = playerAfterFourY - 1

      local playerFaceOld = directionToward(
        playerAfterFourX,
        playerAfterFourY,
        caveOldManX,
        caveOldManY
      )

      -- FROSLASS approaches from the left if possible, matching the staging
      -- shown in the user's screenshot. Fall back to another adjacent land
      -- cell only if that exact tile is not walkable.
      local battleFroslassX = playerBattleX - 1
      local battleFroslassY = playerBattleY

      if not isLand(
        caveDef,
        caveTileset,
        battleFroslassX,
        battleFroslassY
      ) then
        local candidates = {
          { playerBattleX,     playerBattleY - 1 },
          { playerBattleX + 1, playerBattleY     },
          { playerBattleX,     playerBattleY + 1 },
        }

        for _, cell in ipairs(candidates) do
          if isLand(caveDef, caveTileset, cell[1], cell[2]) then
            battleFroslassX = cell[1]
            battleFroslassY = cell[2]
            break
          end
        end
      end

      game.marsFroslassQuestBattleX = battleFroslassX
      game.marsFroslassQuestBattleY = battleFroslassY

      local froslassApproachPath = findLandPath(
        caveDef,
        caveTileset,
        caveFroslassX,
        caveFroslassY,
        battleFroslassX,
        battleFroslassY
      )

      local playerFaceBattle = directionToward(
        playerBattleX,
        playerBattleY,
        battleFroslassX,
        battleFroslassY
      )
      local froslassFacePlayer = directionToward(
        battleFroslassX,
        battleFroslassY,
        playerBattleX,
        playerBattleY
      )

      local rows = {
        {
          "place_npc",
          CAVE_OLD_MAN_INDEX,
          caveOldManX,
          caveOldManY,
          "left",
        },
        {
          "show_object",
          "ALABASTER_CAVE",
          "MARS_FROSLASS_CAVE_OLD_MAN",
        },
        {
          "hide_object",
          "ALABASTER_CAVE",
          "MARS_FROSLASS_CAVE_FROSLASS",
        },
        {
          "hide_object",
          "ALABASTER_CAVE",
          "MARS_FROSLASS_CAVE_MACHOKE",
        },

        -- Enter far enough to bring the confrontation into view, then watch
        -- the old man search the chamber.
        { "move_player", "up", 4 },
        { "face_player_dir", playerFaceOld },

        { "face_object", CAVE_OLD_MAN_INDEX, "left" },
        { "show_text", "_MARS_FROSLASS_CAVE_CALL_1" },
        { "face_object", CAVE_OLD_MAN_INDEX, "right" },
        { "show_text", "_MARS_FROSLASS_CAVE_CALL_2" },
        { "face_object", CAVE_OLD_MAN_INDEX, "up" },
        { "show_text", "_MARS_FROSLASS_CAVE_CALL_3" },

        {
          "place_npc",
          CAVE_FROSLASS_INDEX,
          caveFroslassX,
          caveFroslassY,
          froslassFaceOld,
        },
        {
          "show_object",
          "ALABASTER_CAVE",
          "MARS_FROSLASS_CAVE_FROSLASS",
        },
        { "play_cry", "FROSLASS" },
        { "wait", 10 },

        { "show_text", "_MARS_FROSLASS_CAVE_SPOTTED" },
        {
          "move_npc_to",
          CAVE_OLD_MAN_INDEX,
          caveOldManApproachX,
          caveOldManApproachY,
        },

        -- As the old man closes in, the player advances one more tile and
        -- turns LEFT to watch him confront FROSLASS.
        { "move_player", "up", 1 },
        { "face_player_dir", "left" },

        { "face_object", CAVE_OLD_MAN_INDEX, oldFaceFroslass },
        { "face_object", CAVE_FROSLASS_INDEX, froslassFaceOld },
        { "show_text", "_MARS_FROSLASS_CAVE_ATTACK" },

        -- MACHOKE materializes directly one tile in front of the OLD MAN,
        -- already in its attack position. It no longer spawns beside/on him
        -- and then walks around the PLAYER to reach FROSLASS.
        {
          "place_npc",
          CAVE_MACHOKE_INDEX,
          caveMachokeX,
          caveMachokeY,
          machokeFaceFroslass,
        },
        {
          "show_object",
          "ALABASTER_CAVE",
          "MARS_FROSLASS_CAVE_MACHOKE",
        },
        { "play_cry", "MACHOKE" },
        { "face_object", CAVE_MACHOKE_INDEX, machokeFaceFroslass },
        { "face_object", CAVE_FROSLASS_INDEX, froslassFaceOld },

        { "play_cry", "FROSLASS" },
        { "wait", 180 },
        { "play_cry", "MACHOKE" },
        {
          "hide_object",
          "ALABASTER_CAVE",
          "MARS_FROSLASS_CAVE_MACHOKE",
        },
        { "show_text", "_MARS_FROSLASS_MACHOKE_LOST" },

        { "play_cry", "FROSLASS" },
        {
          "move_npc_to",
          CAVE_OLD_MAN_INDEX,
          caveOldManHitX,
          caveOldManHitY,
        },
        { "show_text", "_MARS_FROSLASS_OLD_MAN_DOWN" },
      }

      -- Remember the OLD MAN's actual pre-battle cell just like FROSLASS's
      -- adjacent battle position. These are movement starting points only;
      -- neither actor is teleported back to them after the battle.
      game.marsFroslassOldManBattleX = caveOldManHitX
      game.marsFroslassOldManBattleY = caveOldManHitY

      -- FROSLASS now comes to the player rather than starting the battle from
      -- across the room.
      appendNpcPath(rows, CAVE_FROSLASS_INDEX, froslassApproachPath)

      rows[#rows + 1] = {
        "face_object",
        CAVE_FROSLASS_INDEX,
        froslassFacePlayer,
      }
      rows[#rows + 1] = {
        "face_player_dir",
        playerFaceBattle,
      }
      rows[#rows + 1] = {
        "show_text",
        "_MARS_FROSLASS_TURNS_ON_PLAYER",
      }

      queueScene(game, ow, rows, function()
        startFroslassBattle(game, ow)
      end)
    end

    -------------------------------------------------------------------------
    -- Deeper 1F truth/reunion scene.
    -------------------------------------------------------------------------

    local function queueDeepScene(game, ow)
      local rows = {
        -- Everyone is already visible and in position before the trigger.
        -- Reassert facing only; do not place/show the three main actors here.
        { "face_object", DEEP_OLD_MAN_INDEX, "up" },
        { "face_object", DEEP_FROSLASS_INDEX, "down" },
        { "face_object", DEEP_CHILD_INDEX, "left" },

        { "show_text", "_MARS_FROSLASS_DEEP_FOUND" },

        -- GIRL starts right beside FROSLASS and steps into the one cell between
        -- it and the OLD MAN.
        { "move_npc", DEEP_CHILD_INDEX, "down", 1 },
        { "move_npc", DEEP_CHILD_INDEX, "left", 1 },
        { "face_object", DEEP_CHILD_INDEX, "down" },
        { "face_object", DEEP_OLD_MAN_INDEX, "up" },
        { "face_object", DEEP_FROSLASS_INDEX, "down" },

        -- Once the GIRL has stepped in front of FROSLASS, the PLAYER turns UP
        -- to face the confrontation directly.
        { "face_player_dir", "up" },

        { "show_text", "_MARS_FROSLASS_CHILD_STOP" },
        { "show_text", "_MARS_FROSLASS_CHILD_EXPLAINS" },

        -- The two SNORUNT now enter from the RIGHT approach and finish
        -- directly beside FROSLASS.
        {
          "show_object",
          "ALABASTER_CAVE",
          "MARS_FROSLASS_DEEP_SNORUNT_1",
        },
        {
          "show_object",
          "ALABASTER_CAVE",
          "MARS_FROSLASS_DEEP_SNORUNT_2",
        },

        -- Left baby: (9,2) -> (4,2) -> (4,3)
        { "move_npc", DEEP_SNORUNT_1_INDEX, "left", 1 },
        { "move_npc", DEEP_SNORUNT_1_INDEX, "left", 1 },
        { "move_npc", DEEP_SNORUNT_1_INDEX, "left", 1 },
        { "move_npc", DEEP_SNORUNT_1_INDEX, "left", 1 },
        { "move_npc", DEEP_SNORUNT_1_INDEX, "left", 1 },
        { "move_npc", DEEP_SNORUNT_1_INDEX, "down", 1 },

        -- Right baby: (9,4) -> (9,3) -> (6,3)
        { "move_npc", DEEP_SNORUNT_2_INDEX, "up", 1 },
        { "move_npc", DEEP_SNORUNT_2_INDEX, "left", 1 },
        { "move_npc", DEEP_SNORUNT_2_INDEX, "left", 1 },
        { "move_npc", DEEP_SNORUNT_2_INDEX, "left", 1 },

        { "play_cry", "SNORUNT" },
        { "wait", 6 },
        { "play_cry", "SNORUNT" },
        { "show_text", "_MARS_FROSLASS_SNORUNT_REVEAL" },

        { "show_text", "_MARS_FROSLASS_REALIZATION" },

        -- No narration is needed here; FROSLASS visibly turns left toward its
        -- two SNORUNT.
        { "face_object", DEEP_FROSLASS_INDEX, "left" },
        { "play_cry", "FROSLASS" },
        { "show_text", "_MARS_FROSLASS_FAMILY_LEAVES" },

        { "fade", "out", 20 },
        {
          "hide_object",
          "ALABASTER_CAVE",
          "MARS_FROSLASS_DEEP_FROSLASS",
        },
        {
          "hide_object",
          "ALABASTER_CAVE",
          "MARS_FROSLASS_DEEP_SNORUNT_1",
        },
        {
          "hide_object",
          "ALABASTER_CAVE",
          "MARS_FROSLASS_DEEP_SNORUNT_2",
        },
        { "show_text", "_MARS_FROSLASS_CHILD_HOME" },
        {
          "hide_object",
          "ALABASTER_CAVE",
          "MARS_FROSLASS_DEEP_CHILD",
        },
        {
          "hide_object",
          "ALABASTER_CAVE",
          "MARS_FROSLASS_DEEP_OLD_MAN",
        },
        { "set_flag", FLAGS.reunion },
        { "fade", "in", 20 },
      }

      ow:queueScript(rows)
    end

    -------------------------------------------------------------------------
    -- Map state / interactions.
    -------------------------------------------------------------------------

    mod.content.map_scripts:register("ALABASTER_HOUSE_1", {
      priority = 410,

      onEnter = function(game, ow)
        local flags = game.save.flags or {}
        local away =
          flags[FLAGS.rush]
          and not flags[FLAGS.reunion]

        ow:queueScript({
          {
            away and "hide_object" or "show_object",
            "ALABASTER_HOUSE_1",
            "ALABASTER_HOUSE1_OLD_MAN",
          },
        })
      end,

      talk = {
        TEXT_ALABASTER_HOUSE1_OLD_MAN = oldManTalk,
      },
    })

    mod.content.map_scripts:register("ALABASTER_HOUSE_2", {
      priority = 410,

      onEnter = function(game, ow)
        local flags = game.save.flags or {}

        ow:queueScript({
          {
            flags[FLAGS.complete] and "show_object" or "hide_object",
            "ALABASTER_HOUSE_2",
            "MARS_FROSLASS_RESCUED_GIRL",
          },
        })
      end,

      talk = {
        [TEXT_RESCUED_GIRL] = {
          { "face_player" },
          { "show_text", "_MARS_FROSLASS_RESCUED_GIRL_AFTER" },
        },
      },
    })

    mod.content.map_scripts:register("ALABASTER_TOWN", {
      priority = 410,

      onEnter = function(game, ow)
        local flags = game.save.flags or {}

        ow:queueScript({
          {
            clueVisible(flags, FLAGS.townScarf) and "show_object" or "hide_object",
            "ALABASTER_TOWN",
            "MARS_FROSLASS_TOWN_SCARF",
          },
          {
            clueVisible(flags, FLAGS.townTracks) and "show_object" or "hide_object",
            "ALABASTER_TOWN",
            "MARS_FROSLASS_TOWN_TRACKS",
          },
        })
      end,

      talk = {
        [TEXT_TOWN_SCARF] = makeClueTalk(clueInfo[TEXT_TOWN_SCARF]),
        [TEXT_TOWN_TRACKS] = makeClueTalk(clueInfo[TEXT_TOWN_TRACKS]),
      },
    })

    mod.content.map_scripts:register("ROUTE_26", {
      priority = 410,

      onEnter = function(game, ow)
        local flags = game.save.flags or {}

        ow:queueScript({
          {
            clueVisible(flags, FLAGS.routeSled) and "show_object" or "hide_object",
            "ROUTE_26",
            "MARS_FROSLASS_ROUTE_SLED",
          },
          {
            clueVisible(flags, FLAGS.routeMitten) and "show_object" or "hide_object",
            "ROUTE_26",
            "MARS_FROSLASS_ROUTE_MITTEN",
          },
        })
      end,

      talk = {
        [TEXT_ROUTE_SLED] = makeClueTalk(clueInfo[TEXT_ROUTE_SLED]),
        [TEXT_ROUTE_MITTEN] = makeClueTalk(clueInfo[TEXT_ROUTE_MITTEN]),
      },
    })

    mod.content.map_scripts:register("ALABASTER_CAVE", {
      priority = 410,

      onEnter = function(game, ow)
        local flags = game.save.flags or {}
        local battleStage =
          flags[FLAGS.rush]
          and not flags[FLAGS.firstWon]

        local retreatStage =
          flags[FLAGS.retreatPending]
          and flags[FLAGS.firstWon]
          and not flags[FLAGS.reunion]

        local rows = {
          {
            clueVisible(flags, FLAGS.caveBell) and "show_object" or "hide_object",
            "ALABASTER_CAVE",
            "MARS_FROSLASS_CAVE_BELL",
          },
          {
            clueVisible(flags, FLAGS.caveTracks) and "show_object" or "hide_object",
            "ALABASTER_CAVE",
            "MARS_FROSLASS_CAVE_TRACKS",
          },
        }

        if battleStage then
          ow:queueScript(rows)
          queueFirstCaveScene(game, ow)
          return
        end

        -- Returning from the successful battle may invoke onEnter before the
        -- chase rows are queued. Do NOT place/re-anchor either actor here:
        -- preserve the exact positions the player saw before the battle.
        if retreatStage then
          rows[#rows + 1] = {
            "show_object",
            "ALABASTER_CAVE",
            "MARS_FROSLASS_CAVE_OLD_MAN",
          }
          rows[#rows + 1] = {
            "show_object",
            "ALABASTER_CAVE",
            "MARS_FROSLASS_CAVE_FROSLASS",
          }
          rows[#rows + 1] = {
            "hide_object",
            "ALABASTER_CAVE",
            "MARS_FROSLASS_CAVE_MACHOKE",
          }
          rows[#rows + 1] = {
            "hide_object",
            "ALABASTER_CAVE",
            "MARS_FROSLASS_DEEP_OLD_MAN",
          }
          rows[#rows + 1] = {
            "hide_object",
            "ALABASTER_CAVE",
            "MARS_FROSLASS_DEEP_CHILD",
          }
          rows[#rows + 1] = {
            "hide_object",
            "ALABASTER_CAVE",
            "MARS_FROSLASS_DEEP_FROSLASS",
          }
          rows[#rows + 1] = {
            "hide_object",
            "ALABASTER_CAVE",
            "MARS_FROSLASS_DEEP_SNORUNT_1",
          }
          rows[#rows + 1] = {
            "hide_object",
            "ALABASTER_CAVE",
            "MARS_FROSLASS_DEEP_SNORUNT_2",
          }

          ow:queueScript(rows)
          return
        end

        rows[#rows + 1] = {
          "hide_object",
          "ALABASTER_CAVE",
          "MARS_FROSLASS_CAVE_OLD_MAN",
        }
        rows[#rows + 1] = {
          "hide_object",
          "ALABASTER_CAVE",
          "MARS_FROSLASS_CAVE_FROSLASS",
        }
        rows[#rows + 1] = {
          "hide_object",
          "ALABASTER_CAVE",
          "MARS_FROSLASS_CAVE_MACHOKE",
        }

        -- Once the chase is over, OLD MAN/FROSLASS/GIRL are already standing
        -- in the upper-left chamber on every entry until the scene resolves.
        local waitingForDeepScene =
          flags[FLAGS.deepChase]
          and not flags[FLAGS.deepScene]
          and not flags[FLAGS.reunion]

        if waitingForDeepScene then
          rows[#rows + 1] = {
            "place_npc",
            DEEP_OLD_MAN_INDEX,
            deepOldManX,
            deepOldManY,
            "up",
          }
          rows[#rows + 1] = {
            "place_npc",
            DEEP_FROSLASS_INDEX,
            deepFroslassX,
            deepFroslassY,
            "down",
          }
          rows[#rows + 1] = {
            "place_npc",
            DEEP_CHILD_INDEX,
            deepChildX,
            deepChildY,
            "left",
          }
          rows[#rows + 1] = {
            "show_object",
            "ALABASTER_CAVE",
            "MARS_FROSLASS_DEEP_OLD_MAN",
          }
          rows[#rows + 1] = {
            "show_object",
            "ALABASTER_CAVE",
            "MARS_FROSLASS_DEEP_FROSLASS",
          }
          rows[#rows + 1] = {
            "show_object",
            "ALABASTER_CAVE",
            "MARS_FROSLASS_DEEP_CHILD",
          }
        else
          rows[#rows + 1] = {
            "hide_object",
            "ALABASTER_CAVE",
            "MARS_FROSLASS_DEEP_OLD_MAN",
          }
          rows[#rows + 1] = {
            "hide_object",
            "ALABASTER_CAVE",
            "MARS_FROSLASS_DEEP_FROSLASS",
          }
          rows[#rows + 1] = {
            "hide_object",
            "ALABASTER_CAVE",
            "MARS_FROSLASS_DEEP_CHILD",
          }
        end

        if waitingForDeepScene then
          rows[#rows + 1] = {
            "place_npc",
            DEEP_SNORUNT_1_INDEX,
            deepSnorunt1StartX,
            deepSnorunt1StartY,
            "left",
          }
          rows[#rows + 1] = {
            "place_npc",
            DEEP_SNORUNT_2_INDEX,
            deepSnorunt2StartX,
            deepSnorunt2StartY,
            "left",
          }
        end

        rows[#rows + 1] = {
          "hide_object",
          "ALABASTER_CAVE",
          "MARS_FROSLASS_DEEP_SNORUNT_1",
        }
        rows[#rows + 1] = {
          "hide_object",
          "ALABASTER_CAVE",
          "MARS_FROSLASS_DEEP_SNORUNT_2",
        }

        ow:queueScript(rows)
      end,

      onStep = function(game, ow, x, y)
        local flags = game.save.flags or {}

        if not flags[FLAGS.deepChase]
           or flags[FLAGS.deepScene]
           or flags[FLAGS.reunion]
        then
          return false
        end

        -- Any of the THREE walkable cells directly below the OLD MAN starts
        -- the scene: (4,7), (5,7), or (6,7).
        if y == deepTriggerY
           and x >= deepTriggerMinX
           and x <= deepTriggerMaxX
        then
          flags[FLAGS.deepScene] = true

          local rows = {}

          if x == deepTriggerMinX then
            -- (4,7) -> (4,6), immediately left of the OLD MAN.
            rows[#rows + 1] = { "move_player", "up", 1 }
            rows[#rows + 1] = { "face_player_dir", "right" }
          elseif x == deepTriggerMaxX then
            -- (6,7) -> (6,6), immediately right of the OLD MAN.
            rows[#rows + 1] = { "move_player", "up", 1 }
            rows[#rows + 1] = { "face_player_dir", "left" }
          else
            -- (5,7) is directly below the occupied OLD MAN cell. Move left,
            -- then up so the player ends beside him instead of walking into him.
            rows[#rows + 1] = { "move_player", "left", 1 }
            rows[#rows + 1] = { "move_player", "up", 1 }
            rows[#rows + 1] = { "face_player_dir", "right" }
          end

          queueScene(game, ow, rows, function()
            queueDeepScene(game, ow)
          end)

          return true
        end

        return false
      end,

      talk = {
        [TEXT_CAVE_BELL] = makeClueTalk(clueInfo[TEXT_CAVE_BELL]),
        [TEXT_CAVE_TRACKS] = makeClueTalk(clueInfo[TEXT_CAVE_TRACKS]),

        [TEXT_CAVE_OLD_MAN] = {
          { "show_text", "_MARS_FROSLASS_CAVE_OLD_MAN_IDLE" },
        },
        [TEXT_CAVE_FROSLASS] = {
          { "show_text", "_MARS_FROSLASS_CAVE_FROSLASS_IDLE" },
        },

        [TEXT_DEEP_OLD_MAN] = {
          { "show_text", "_MARS_FROSLASS_CAVE_OLD_MAN_IDLE" },
        },
        [TEXT_DEEP_CHILD] = {
          { "show_text", "_MARS_FROSLASS_DEEP_CHILD_IDLE" },
        },
        [TEXT_DEEP_FROSLASS] = {
          { "show_text", "_MARS_FROSLASS_DEEP_FROSLASS_IDLE" },
        },
        [TEXT_DEEP_SNORUNT_1] = {
          { "show_text", "_MARS_FROSLASS_DEEP_SNORUNT_IDLE" },
        },
        [TEXT_DEEP_SNORUNT_2] = {
          { "show_text", "_MARS_FROSLASS_DEEP_SNORUNT_IDLE" },
        },
      },
    })

    mod.log:info(
      "Frozen Footprints installed: Silph Scope gate + 6-clue search + uncatchable Lv32 Froslass confrontation + persistent upper-left 1F family tableau + Ice TM reward"
    )
  end)()


  ---------------------------------------------------------------------------
  -- ROUTE 10 / POWER PLANT — "ROLLING BLACKOUT"
  --
  -- Unlock: possessing HM03 Surf. Rodrigo waits on Route 10, lends the player
  -- an earpiece narratively, and remotely guides three escalating breaker-order puzzles.
  -- Wrong answers at the first two stations trigger uncatchable Electrode
  -- battles (Lv32 / Lv34). A Lv36 Magneton is siphoning power at the final
  -- station. Restoring the grid and returning to Rodrigo awards TM58 CONDUCT
  -- and silently unlocks Rodrigo in the Master's Tournament.
  ---------------------------------------------------------------------------
  ;(function()
    if not mod.content.map_scripts then return end

    local MapDef = require("src.world.Map")
    local BattleState = require("src.battle.BattleState")
    local TextBox = require("src.render.TextBox")
    local Bag = require("src.inventory.Bag")
    local Sound = require("src.core.Sound")
    local Screens = require("src.ui.Screens")
    local Menu = mod.ui and mod.ui.Menu or require("src.ui.Menu")

    local route10Def = mod.content.maps:get("ROUTE_10")
    local powerDef = mod.content.maps:get("POWER_PLANT")
    if not route10Def or not powerDef then
      mod.log:error(
        "ROLLING BLACKOUT requires ROUTE_10 and POWER_PLANT"
      )
      return
    end

    local FLAGS = {
      started = "EVENT_ROLLING_BLACKOUT_STARTED",
      entered = "EVENT_ROLLING_BLACKOUT_ENTERED_PLANT",
      station1 = "EVENT_ROLLING_BLACKOUT_STATION_1",
      station2 = "EVENT_ROLLING_BLACKOUT_STATION_2",
      magneton = "EVENT_ROLLING_BLACKOUT_MAGNETON_DEFEATED",
      stabilized = "EVENT_ROLLING_BLACKOUT_STABILIZED",
      complete = "EVENT_ROLLING_BLACKOUT_COMPLETE",
    }

    local TEXT_RODRIGO = "TEXT_MARS_BLACKOUT_RODRIGO"
    local TEXT_STATION_1 = "TEXT_MARS_BLACKOUT_STATION_1"
    local TEXT_STATION_2 = "TEXT_MARS_BLACKOUT_STATION_2"
    local TEXT_STATION_3 = "TEXT_MARS_BLACKOUT_STATION_3"
    local TEXT_MAGNETON = "TEXT_MARS_BLACKOUT_MAGNETON"

    local OVERLAY_IMAGE = {
      station1 = mod.assets:path("assets/blackout_station_1.png"),
      station2 = mod.assets:path("assets/blackout_station_2.png"),
      station3 = mod.assets:path("assets/blackout_station_3.png"),
    }

    -------------------------------------------------------------------------
    -- Breaker overlay screen. Reuses the same lightweight presentation model
    -- as the tournament bracket: a static screen remains visible underneath
    -- TextBox/Menu UI while the player enters a breaker order.
    -------------------------------------------------------------------------
    if mod.content.screens
       and not mod.content.screens:get("MarsBlackoutBreakerPanel")
    then
      mod.content.screens:register("MarsBlackoutBreakerPanel", {
        new = function(game, opts)
          local self = {
            game = game,
            isOpaque = true,
          }

          local image = nil
          local imagePath = opts and opts.image
          if imagePath then
            local ok, loaded = pcall(love.graphics.newImage, imagePath)
            if ok and loaded then
              image = loaded
              if image.setFilter then
                image:setFilter("nearest", "nearest")
              end
            end
          end

          function self:update(dt)
            -- Presentation only.
          end

          function self:draw()
            love.graphics.setColor(0, 0, 0, 1)
            love.graphics.rectangle("fill", 0, 0, 160, 144)

            if image then
              local iw, ih = image:getDimensions()
              local marginX, marginY = 4, 4
              local scale = math.min(
                (160 - marginX * 2) / iw,
                (144 - marginY * 2) / ih
              )
              local drawW = iw * scale
              local drawH = ih * scale
              local x = math.floor((160 - drawW) / 2 + 0.5)
              local y = math.floor((144 - drawH) / 2 + 0.5)

              love.graphics.setColor(1, 1, 1, 1)
              love.graphics.draw(image, x, y, 0, scale, scale)
            end

            love.graphics.setColor(1, 1, 1, 1)
          end

          return self
        end,
      })
    end

    -------------------------------------------------------------------------
    -- Placement helpers. Rodrigo is deliberately placed near the Route 10
    -- Pokemon Center so the player can meet him before Surf. The plant panels
    -- are spread through the reachable component in increasing depth order.
    -------------------------------------------------------------------------
    local function cellKey(x, y)
      return tostring(x) .. ":" .. tostring(y)
    end

    local function isLand(def, x, y)
      local tileset = def and mod.content.tilesets:get(def.tileset)
      return def
        and tileset
        and x >= 0
        and y >= 0
        and x < def.width * 2
        and y < def.height * 2
        and MapDef.defIsWalkableCell(def, tileset, x, y)
        and not MapDef.defIsWaterCell(def, tileset, x, y)
    end

    local function occupiedCells(def)
      local used = {}
      for _, obj in ipairs(def.objects or {}) do
        if obj.x ~= nil and obj.y ~= nil then
          used[cellKey(obj.x, obj.y)] = true
        end
      end
      for _, warp in ipairs(def.warps or {}) do
        if warp.x ~= nil and warp.y ~= nil then
          used[cellKey(warp.x, warp.y)] = true
        end
      end
      for _, sign in ipairs(def.signs or {}) do
        if sign.x ~= nil and sign.y ~= nil then
          used[cellKey(sign.x, sign.y)] = true
        end
      end
      return used
    end

    local routeUsed = occupiedCells(route10Def)
    local centerX = math.floor(route10Def.width)
    local centerY = math.floor(route10Def.height)
    for _, warp in ipairs(route10Def.warps or {}) do
      local dest = tostring(warp.destMap or "")
      if dest:find("POKECENTER", 1, true)
         or dest:find("POKEMON_CENTER", 1, true)
      then
        centerX, centerY = warp.x, warp.y
        break
      end
    end

    -- One cell down from the earlier position so Rodrigo stands on land
    -- instead of the water tile directly above it.
    local rodrigoX, rodrigoY = 15, 4

    local powerUsed = occupiedCells(powerDef)
    local entranceX = nil
    local entranceY = nil
    for _, warp in ipairs(powerDef.warps or {}) do
      if tostring(warp.destMap or "") == "ROUTE_10" then
        entranceX, entranceY = warp.x, warp.y
        break
      end
    end
    if not entranceX then
      local warp = powerDef.warps and powerDef.warps[1]
      entranceX = warp and warp.x or math.floor(powerDef.width)
      entranceY = warp and warp.y or math.max(1, powerDef.height * 2 - 2)
    end

    local zapdosX, zapdosY = nil, nil
    for _, obj in ipairs(powerDef.objects or {}) do
      if obj.pokemon == "ZAPDOS"
         or tostring(obj.name or ""):find("ZAPDOS", 1, true)
      then
        zapdosX, zapdosY = obj.x, obj.y
        break
      end
    end

    local dirs = {
      { 1, 0 }, { -1, 0 }, { 0, 1 }, { 0, -1 },
    }

    local nodes = {}
    local nodeByKey = {}
    local queue = {}
    local head = 1

    local function seedPower(x, y, distance)
      local key = cellKey(x, y)
      if not nodeByKey[key] and isLand(powerDef, x, y) then
        local node = { x = x, y = y, distance = distance or 0 }
        nodeByKey[key] = node
        nodes[#nodes + 1] = node
        queue[#queue + 1] = node
      end
    end

    seedPower(entranceX, entranceY, 0)
    for _, d in ipairs(dirs) do
      seedPower(entranceX + d[1], entranceY + d[2], 0)
    end

    if #queue == 0 then
      for y = 1, powerDef.height * 2 - 2 do
        for x = 1, powerDef.width * 2 - 2 do
          if isLand(powerDef, x, y) then
            seedPower(x, y, 0)
            break
          end
        end
        if #queue > 0 then break end
      end
    end

    while head <= #queue do
      local node = queue[head]
      head = head + 1
      for _, d in ipairs(dirs) do
        local nx, ny = node.x + d[1], node.y + d[2]
        local key = cellKey(nx, ny)
        if not nodeByKey[key] and isLand(powerDef, nx, ny) then
          local nextNode = {
            x = nx,
            y = ny,
            distance = node.distance + 1,
          }
          nodeByKey[key] = nextNode
          nodes[#nodes + 1] = nextNode
          queue[#queue + 1] = nextNode
        end
      end
    end

    local maxDistance = 1
    for _, node in ipairs(nodes) do
      maxDistance = math.max(maxDistance, node.distance or 0)
    end

    local function openNeighbors(x, y)
      local count = 0
      for _, d in ipairs(dirs) do
        if isLand(powerDef, x + d[1], y + d[2]) then
          count = count + 1
        end
      end
      return count
    end

    local function farFromZapdos(x, y)
      if not zapdosX or not zapdosY then return true end
      return math.abs(x - zapdosX) + math.abs(y - zapdosY) >= 8
    end

    local selected = {}
    local function separated(x, y)
      for _, pos in ipairs(selected) do
        if math.abs(x - pos.x) + math.abs(y - pos.y) < 7 then
          return false
        end
      end
      return true
    end

    local function hasFreeAdjacent(x, y)
      for _, d in ipairs(dirs) do
        local nx, ny = x + d[1], y + d[2]
        if isLand(powerDef, nx, ny)
           and not powerUsed[cellKey(nx, ny)]
        then
          return true
        end
      end
      return false
    end

    local function choosePowerSpot(fraction, requireAdjacent)
      local target = maxDistance * fraction
      local best = nil
      local bestScore = math.huge

      -- Prefer roomy cells so a physical console does not seal a one-tile hall.
      for pass = 1, 2 do
        for _, node in ipairs(nodes) do
          local key = cellKey(node.x, node.y)
          local degree = openNeighbors(node.x, node.y)
          local roomy = degree >= (pass == 1 and 3 or 2)

          if roomy
             and not powerUsed[key]
             and farFromZapdos(node.x, node.y)
             and separated(node.x, node.y)
             and (not requireAdjacent or hasFreeAdjacent(node.x, node.y))
          then
            local score = math.abs((node.distance or 0) - target)
            if score < bestScore then
              best = node
              bestScore = score
            end
          end
        end
        if best then break end
      end

      if not best then
        for _, node in ipairs(nodes) do
          local key = cellKey(node.x, node.y)
          if not powerUsed[key] and farFromZapdos(node.x, node.y) then
            best = node
            break
          end
        end
      end

      best = best or { x = entranceX + 1, y = entranceY, distance = 0 }
      powerUsed[cellKey(best.x, best.y)] = true
      selected[#selected + 1] = { x = best.x, y = best.y }
      return best.x, best.y, best.distance or 0
    end

    local station1X, station1Y = choosePowerSpot(0.28, false)
    local station2X, station2Y = choosePowerSpot(0.56, false)
    local station3X, station3Y, station3Distance = choosePowerSpot(0.82, true)

    -- Keep the station against the wall, but move it one tile RIGHT
    -- from the previous position so it sits in the next cabinet and no longer
    -- blocks the player's path.
    station1X = station1X
    station1Y = station1Y - 2

    local magnetonX, magnetonY = nil, nil
    local bestMagDist = math.huge
    for _, d in ipairs(dirs) do
      local nx, ny = station3X + d[1], station3Y + d[2]
      local key = cellKey(nx, ny)
      local node = nodeByKey[key]
      if node
         and not powerUsed[key]
         and farFromZapdos(nx, ny)
      then
        local score = math.abs((node.distance or 0) - math.max(0, station3Distance - 1))
        if score < bestMagDist then
          bestMagDist = score
          magnetonX, magnetonY = nx, ny
        end
      end
    end

    if not magnetonX then
      for _, node in ipairs(nodes) do
        local key = cellKey(node.x, node.y)
        if not powerUsed[key]
           and farFromZapdos(node.x, node.y)
           and math.abs(node.x - station3X) + math.abs(node.y - station3Y) <= 3
        then
          magnetonX, magnetonY = node.x, node.y
          break
        end
      end
    end

    magnetonX = magnetonX or math.max(1, station3X - 1)
    magnetonY = magnetonY or station3Y
    powerUsed[cellKey(magnetonX, magnetonY)] = true

    -------------------------------------------------------------------------
    -- Quest objects.
    -------------------------------------------------------------------------
    -- Use a high fixed index so Rodrigo can never inherit another Route 10
    -- NPC's persisted object state.
    local rodrigoIndex = 90
    local powerBaseIndex = #(powerDef.objects or {}) + 1
    local station1Index = powerBaseIndex
    local station2Index = powerBaseIndex + 1
    local station3Index = powerBaseIndex + 2
    local magnetonIndex = powerBaseIndex + 3

    mod.content.maps:patch("ROUTE_10", {
      objects = {
        __append = {
          {
            index = rodrigoIndex,
            name = "MARS_BLACKOUT_RODRIGO",
            sprite = "SPRITE_SCIENTIST",
            movement = "STAY",
            range = "ANY_DIR",
            x = rodrigoX,
            y = rodrigoY,
            text = TEXT_RODRIGO,
            hidden = false,
          },
        },
      },
    })

    mod.content.maps:patch("POWER_PLANT", {
      objects = {
        __append = {
          {
            index = station1Index,
            name = "MARS_BLACKOUT_STATION_1",
            sprite = "SPRITE_MARS_AFTERSHOCK_MACHINE",
            movement = "STAY",
            range = "ANY_DIR",
            x = station1X,
            y = station1Y,
            text = TEXT_STATION_1,
          },
          {
            index = station2Index,
            name = "MARS_BLACKOUT_STATION_2",
            sprite = "SPRITE_MARS_AFTERSHOCK_MACHINE",
            movement = "STAY",
            range = "ANY_DIR",
            x = station2X,
            y = station2Y,
            text = TEXT_STATION_2,
          },
          {
            index = station3Index,
            name = "MARS_BLACKOUT_STATION_3",
            sprite = "SPRITE_MARS_AFTERSHOCK_MACHINE",
            movement = "STAY",
            range = "ANY_DIR",
            x = station3X,
            y = station3Y,
            text = TEXT_STATION_3,
          },
          {
            index = magnetonIndex,
            name = "MARS_BLACKOUT_MAGNETON",
            sprite = "SPRITE_MONSTER",
            movement = "STAY",
            range = "ANY_DIR",
            x = magnetonX,
            y = magnetonY,
            text = TEXT_MAGNETON,
            hidden = true,
          },
        },
      },
    })

    -------------------------------------------------------------------------
    -- Scripted Pokemon battles. Trainer-style presentation makes the wild
    -- Pokemon uncatchable and prevents RUN while keeping their own front art.
    -------------------------------------------------------------------------
    local electrodeDef = mod.content.pokemon:get("ELECTRODE")
    local magnetonDef = mod.content.pokemon:get("MAGNETON")

    mod.content.trainers:register("OPP_BLACKOUT_ELECTRODE", {
      id = "OPP_BLACKOUT_ELECTRODE",
      name = "ELECTRODE",
      basePic = "OPP_POKEMANIAC",
      pic = electrodeDef and electrodeDef.spriteFront,
      baseMoney = 0,
      aiClass = (mod.content.trainers:get("OPP_POKEMANIAC") or {}).aiClass,
      aiMods = (mod.content.trainers:get("OPP_POKEMANIAC") or {}).aiMods,
      parties = {
        {
          { level = 32, species = "ELECTRODE" },
        },
        {
          { level = 34, species = "ELECTRODE" },
        },
      },
    })

    mod.content.trainers:register("OPP_BLACKOUT_MAGNETON", {
      id = "OPP_BLACKOUT_MAGNETON",
      name = "MAGNETON",
      basePic = "OPP_POKEMANIAC",
      pic = magnetonDef and magnetonDef.spriteFront,
      baseMoney = 0,
      aiClass = (mod.content.trainers:get("OPP_POKEMANIAC") or {}).aiClass,
      aiMods = (mod.content.trainers:get("OPP_POKEMANIAC") or {}).aiMods,
      parties = {
        {
          { level = 36, species = "MAGNETON" },
        },
      },
    })

    mod.hooks:wrap("trainer.party", function(next, oppClass, partyIndex, partyDef)
      if oppClass == "OPP_BLACKOUT_ELECTRODE" then
        local level = (partyIndex or 1) == 2 and 34 or 32
        local moves = (partyIndex or 1) == 2
          and { "THUNDERBOLT", "SONICBOOM", "SCREECH", "THUNDER_WAVE" }
          or { "TACKLE", "SONICBOOM", "SCREECH", "THUNDER_WAVE" }

        return next(oppClass, partyIndex, {
          {
            level = level,
            species = "ELECTRODE",
            moves = moves,
          },
        })
      end

      if oppClass == "OPP_BLACKOUT_MAGNETON" then
        return next(oppClass, partyIndex, {
          {
            level = 36,
            species = "MAGNETON",
            moves = {
              "THUNDERBOLT",
              "SUPERSONIC",
              "MAGNET_BOMB",
              "SONICBOOM",
            },
          },
        })
      end

      return next(oppClass, partyIndex, partyDef)
    end, 92)

    -- These punishment/boss encounters are quest mechanics, not an EXP farm.
    local blackoutNoExpActive = false
    mod.hooks:wrap("exp.gain", function(next, ctx)
      local amount = next(ctx)
      if blackoutNoExpActive and ctx and ctx.isTrainer then
        return 0
      end
      return amount
    end, 92)

