    mod.content.text:register(
      "_MARS_BLACKOUT_TM_FULL",
      "RODRIGO: Your BAG is too\nfull for the TM.\f"
        .. "Make some room and I'll\nkeep it here for you."
    )

    mod.content.text:register(
      "_MARS_BLACKOUT_REWARD",
      "You received TM58!\f"
        .. "TM58 contains CONDUCT!\f"
        .. "RODRIGO: Thanks again.\nThe grid would've cooked\nitself without you."
    )

    mod.content.text:register(
      "_MARS_BLACKOUT_COMPLETE",
      "RODRIGO: Grid's steady,\nNIDOKING's healing up,\nand I finally slept.\f"
        .. "That's a pretty good\nweek in my book."
    )

    -------------------------------------------------------------------------
    -- Shared text/menu helpers.
    -------------------------------------------------------------------------
    local function blackoutSay(game, idOrText, done, opts)
      game.stack:push(TextBox.new(
        game,
        game.data.text[idOrText] or idOrText,
        done,
        opts
      ))
    end

    local function hasHM03(game)
      local inventory = game.save.inventory or {}

      -- Gen1Recomp's imported HM ids are move-based:
      -- HM01 = HM_CUT, HM02 = HM_FLY, HM03 = HM_SURF, etc.
      local qty = inventory.HM_SURF
      if qty ~= nil and qty ~= false and qty ~= 0 then
        return true
      end

      -- Defensive fallback for future/importer variations: recognize any
      -- owned HM machine whose metadata says it is HM03 / SURF.
      local items = game.data and game.data.items or {}
      for itemId, count in pairs(inventory) do
        if count ~= nil and count ~= false and count ~= 0 then
          local def = items[itemId]
          local machine = def and def.machine
          if machine
             and machine.kind == "HM"
             and (
               machine.number == 3
               or machine.move == "SURF"
             )
          then
            return true
          end
        end
      end

      return false
    end

    local function clearLegacyEarpiece(game)
      local inventory = game
        and game.save
        and game.save.inventory

      if inventory then
        inventory.EARPIECE = nil
      end
    end

    local function faceNpc(ow, npc)
      if npc and npc.facePlayer and ow and ow.player then
        npc:facePlayer(ow.player)
      end
    end

    local blackoutCallbacks = setmetatable({}, { __mode = "k" })
    mod.commands:register("mars_blackout_callback", function(ctx)
      local callback = blackoutCallbacks[ctx.game]
      blackoutCallbacks[ctx.game] = nil
      if callback then callback() end
    end)

    local function queueBlackout(game, ow, rows, callback)
      blackoutCallbacks[game] = callback
      rows[#rows + 1] = { "mars_blackout_callback" }
      ow:queueScript(rows)
    end

    local function closeBreakerOverlay(game)
      local stack = game and game.stack
      local state = game and game.marsBlackoutBreakerOverlay
      if stack and state and stack.states
         and stack.states[#stack.states] == state
      then
        stack:pop()
      end
      if game then
        game.marsBlackoutBreakerOverlay = nil
      end
    end

    local function showBreakerOverlay(game, imagePath)
      closeBreakerOverlay(game)
      if not imagePath then return end
      game.marsBlackoutBreakerOverlay =
        Screens.push(game, "MarsBlackoutBreakerPanel", {
          image = imagePath,
        })
    end

    local function sameSequence(actual, expected)
      if #actual ~= #expected then return false end
      for i = 1, #expected do
        if actual[i] ~= expected[i] then return false end
      end
      return true
    end

    local function pickBreakerOrder(
      game,
      breakers,
      clueId,
      overlayImage,
      onComplete
    )
      local picked = {}

      -- Fit the full initial breaker list + HINT inside the 18-tile-tall
      -- Game Boy screen. Larger stations start the menu higher.
      local menuRows = #breakers + 1
      local breakerMenuY = math.max(2, 17 - (menuRows * 2))

      local function finish()
        closeBreakerOverlay(game)
        onComplete(picked)
      end

      local function openMenu(remaining)
        if #remaining == 0 then
          finish()
          return
        end

        local items = {}
        for _, breaker in ipairs(remaining) do
          local chosen = breaker
          items[#items + 1] = {
            label = chosen,
            onSelect = function()
              picked[#picked + 1] = chosen
              local nextRemaining = {}
              for _, candidate in ipairs(remaining) do
                if candidate ~= chosen then
                  nextRemaining[#nextRemaining + 1] = candidate
                end
              end
              openMenu(nextRemaining)
            end,
          }
        end

        items[#items + 1] = {
          label = "HINT",
          onSelect = function()
            blackoutSay(game, clueId, function()
              openMenu(remaining)
            end)
          end,
        }

        game.stack:push(Menu.new(game, items, {
          tx = 4,
          ty = breakerMenuY,
          tw = 12,
          cancelable = false,
          maxVisible = 6,
        }))
      end

      showBreakerOverlay(game, overlayImage)
      blackoutSay(game, clueId, function()
        openMenu(breakers)
      end)
    end

    -------------------------------------------------------------------------
    -- Battle helpers.
    -------------------------------------------------------------------------
    -------------------------------------------------------------------------
    local function startElectrodeBattle(game, ow, partyIndex, onWin, done)
      blackoutSay(game, "_MARS_BLACKOUT_ELECTRODE_ATTACK", function()
        local battle = BattleState.newTrainer(
          game,
          "OPP_BLACKOUT_ELECTRODE",
          partyIndex
        )
        battle.endBattleText = "ELECTRODE was driven back!"

        local baseRomText = battle.romText
        battle.romText = function(self, label, fallback, ...)
          if label == "_MoneyForWinningText" then
            return "ELECTRODE was\ndefeated!"
          end
          return baseRomText(self, label, fallback, ...)
        end

        battle.onFinish = function(result)
          blackoutNoExpActive = false
          ow:afterBattle(result, battle)

          if result == "win" then
            onWin()
          elseif done then
            done()
          end
        end

        blackoutNoExpActive = true
        ow:pushBattle(battle)
      end)
    end

    local function startMagnetonBattle(game, ow, done)
      local flags = game.save.flags or {}
      if flags[FLAGS.magneton] then
        if done then done() end
        return
      end

      blackoutSay(game, "_MARS_BLACKOUT_MAGNETON_FOUND", function()
        local battle = BattleState.newTrainer(
          game,
          "OPP_BLACKOUT_MAGNETON",
          1
        )
        battle.endBattleText = "MAGNETON released the grid!"

        local baseRomText = battle.romText
        battle.romText = function(self, label, fallback, ...)
          if label == "_MoneyForWinningText" then
            return "MAGNETON was\ndefeated!"
          end
          return baseRomText(self, label, fallback, ...)
        end

        battle.onFinish = function(result)
          blackoutNoExpActive = false
          ow:afterBattle(result, battle)

          if result ~= "win" then
            if done then done() end
            return
          end

          flags[FLAGS.magneton] = true
          queueBlackout(
            game,
            ow,
            {
              {
                "hide_object",
                "POWER_PLANT",
                "MARS_BLACKOUT_MAGNETON",
              },
            },
            function()
              blackoutSay(game, "_MARS_BLACKOUT_MAGNETON_DOWN", done)
            end
          )
        end

        blackoutNoExpActive = true
        ow:pushBattle(battle)
      end)
    end

    -------------------------------------------------------------------------
    -- Breaker puzzles.
    -------------------------------------------------------------------------
    local function runStation1(game, ow, done)
      pickBreakerOrder(
        game,
        { "COOLANT", "TRANSFORMER", "MAIN" },
        "_MARS_BLACKOUT_STATION_1_CLUE",
        OVERLAY_IMAGE.station1,
        function(order)
          if sameSequence(order, { "TRANSFORMER", "COOLANT", "MAIN" }) then
            local flags = game.save.flags or {}
            flags[FLAGS.station1] = true
            blackoutSay(game, "_MARS_BLACKOUT_STATION_1_OK", done)
            return
          end

          blackoutSay(game, "_MARS_BLACKOUT_WRONG", function()
            startElectrodeBattle(
              game,
              ow,
              1,
              function() runStation1(game, ow, done) end,
              done
            )
          end)
        end
      )
    end

    local function runStation2(game, ow, done)
      pickBreakerOrder(
        game,
        { "COOLING", "AUXILIARY", "TRANSFORMER", "OUTPUT" },
        "_MARS_BLACKOUT_STATION_2_CLUE",
        OVERLAY_IMAGE.station2,
        function(order)
          if sameSequence(
            order,
            { "COOLING", "OUTPUT", "AUXILIARY", "TRANSFORMER" }
          ) then
            local flags = game.save.flags or {}
            flags[FLAGS.station2] = true
            blackoutSay(game, "_MARS_BLACKOUT_STATION_2_OK", function()
              ow:queueScript({
                {
                  "show_object",
                  "POWER_PLANT",
                  "MARS_BLACKOUT_MAGNETON",
                },
              })
              if done then done() end
            end)
            return
          end

          blackoutSay(game, "_MARS_BLACKOUT_WRONG", function()
            startElectrodeBattle(
              game,
              ow,
              2,
              function() runStation2(game, ow, done) end,
              done
            )
          end)
        end
      )
    end

    local function runStation3(game, ow, done)
      pickBreakerOrder(
        game,
        { "COOLANT", "AUXILIARY", "INTAKE", "TRANSFORMER", "MAIN" },
        "_MARS_BLACKOUT_STATION_3_CLUE",
        OVERLAY_IMAGE.station3,
        function(order)
          if sameSequence(
            order,
            { "AUXILIARY", "COOLANT", "INTAKE", "TRANSFORMER", "MAIN" }
          ) then
            local flags = game.save.flags or {}
            flags[FLAGS.stabilized] = true

            queueBlackout(
              game,
              ow,
              {
                { "fade", "out", 8 },
                { "wait", 10 },
                { "play_sound", "Heal_HP" },
                { "wait", 8 },
                { "fade", "in", 8 },
                { "show_text", "_MARS_BLACKOUT_STABLE" },
              },
              done
            )
            return
          end

          blackoutSay(game, "_MARS_BLACKOUT_FINAL_WRONG", function()
            runStation3(game, ow, done)
          end)
        end
      )
    end

    -------------------------------------------------------------------------
    -- Interactions.
    -------------------------------------------------------------------------
    local function rodrigoTalk(game, ow, npc, done)
      local flags = game.save.flags or {}
      faceNpc(ow, npc)

      if flags[FLAGS.complete] then
        blackoutSay(game, "_MARS_BLACKOUT_COMPLETE", done)
        return
      end

      if flags[FLAGS.stabilized] then
        blackoutSay(game, "_MARS_BLACKOUT_RETURN", function()
          if not Bag.add(game.save, "TM58", 1, game.data) then
            blackoutSay(game, "_MARS_BLACKOUT_TM_FULL", done)
            return
          end

          clearLegacyEarpiece(game)
          flags[FLAGS.complete] = true
          Sound.play(game.data, "Get_Item1")
          blackoutSay(game, "_MARS_BLACKOUT_REWARD", done)
        end)
        return
      end

      if flags[FLAGS.started] then
        blackoutSay(game, "_MARS_BLACKOUT_IN_PROGRESS", done)
        return
      end

      if not hasHM03(game) then
        blackoutSay(game, "_MARS_BLACKOUT_NO_SURF", done)
        return
      end

      blackoutSay(
        game,
        "_MARS_BLACKOUT_START",
        nil,
        {
          choice = function(yes)
            if not yes then
              blackoutSay(game, "_MARS_BLACKOUT_DECLINE", done)
              return
            end

            clearLegacyEarpiece(game)
            flags[FLAGS.started] = true
            blackoutSay(game, "_MARS_BLACKOUT_EARPIECE", done)
          end,
        }
      )
    end

    local function station1Talk(game, ow, npc, done)
      local flags = game.save.flags or {}
      if flags[FLAGS.station1] then
        blackoutSay(game, "_MARS_BLACKOUT_PANEL_ONLINE", done)
      elseif not flags[FLAGS.started] then
        blackoutSay(game, "_MARS_BLACKOUT_PANEL_DORMANT", done)
      else
        runStation1(game, ow, done)
      end
    end

    local function station2Talk(game, ow, npc, done)
      local flags = game.save.flags or {}
      if flags[FLAGS.station2] then
        blackoutSay(game, "_MARS_BLACKOUT_PANEL_ONLINE", done)
      elseif not flags[FLAGS.station1] then
        blackoutSay(game, "_MARS_BLACKOUT_OUT_OF_ORDER", done)
      else
        runStation2(game, ow, done)
      end
    end

    local function station3Talk(game, ow, npc, done)
      local flags = game.save.flags or {}
      if flags[FLAGS.stabilized] then
        blackoutSay(game, "_MARS_BLACKOUT_PANEL_ONLINE", done)
      elseif not flags[FLAGS.station2] then
        blackoutSay(game, "_MARS_BLACKOUT_OUT_OF_ORDER", done)
      elseif not flags[FLAGS.magneton] then
        startMagnetonBattle(game, ow, done)
      else
        runStation3(game, ow, done)
      end
    end

    local function magnetonTalk(game, ow, npc, done)
      local flags = game.save.flags or {}
      if not flags[FLAGS.station2] then
        blackoutSay(game, "_MARS_BLACKOUT_OUT_OF_ORDER", done)
        return
      end
      startMagnetonBattle(game, ow, done)
    end

    -------------------------------------------------------------------------
    -- Map state.
    -------------------------------------------------------------------------
    mod.content.map_scripts:register("ROUTE_10", {
      priority = 372,

      onEnter = function(game, ow)
        clearLegacyEarpiece(game)

        -- Rodrigo is a permanent Route 10 actor. Explicitly showing him also
        -- clears stale hidden state left by older development builds.
        ow:queueScript({
          { "show_object", "ROUTE_10", "MARS_BLACKOUT_RODRIGO" },
        })
      end,

      talk = {
        [TEXT_RODRIGO] = rodrigoTalk,
      },
    })

    mod.content.map_scripts:register("POWER_PLANT", {
      priority = 372,

      onEnter = function(game, ow)
        local flags = game.save.flags or {}
        local showMagneton = flags[FLAGS.station2]
          and not flags[FLAGS.magneton]
          and not flags[FLAGS.complete]

        local rows = {
          {
            showMagneton and "show_object" or "hide_object",
            "POWER_PLANT",
            "MARS_BLACKOUT_MAGNETON",
          },
        }

        if flags[FLAGS.started]
           and not flags[FLAGS.entered]
           and not flags[FLAGS.stabilized]
        then
          flags[FLAGS.entered] = true
          rows[#rows + 1] = { "show_text", "_MARS_BLACKOUT_ENTER" }
        end

        ow:queueScript(rows)
      end,

      talk = {
        [TEXT_STATION_1] = station1Talk,
        [TEXT_STATION_2] = station2Talk,
        [TEXT_STATION_3] = station3Talk,
        [TEXT_MAGNETON] = magnetonTalk,
      },
    })

    mod.log:info(
      "Rolling Blackout installed: HM03-gated Rodrigo + narrative earpiece + three breaker puzzles + Lv32/34 Electrode penalties + Lv36 Magneton + TM58 CONDUCT + Master's unlock"
    )
  end)()

  ---------------------------------------------------------------------------
  -- Rival display-name fix: all Arceus quest dialogue now uses the engine-native {RIVAL} runtime token rather than hardcoded "RIVAL" text.
-- THE ORIGINAL ONE — ARCEUS CAPSTONE QUEST
  --
  -- Unlock: Champion + all prior major quest resolutions, including the
  -- Faraway Island Mew arc and the one-time Mew/Mewtwo/Fuji epilogue.
  -- Opening: Oak's Lab network anomaly -> Rival/Lance emergency briefing.
  -- Player chooses three of six city wormholes; Rival takes the other three.
  -- Player trials are always TIME -> SPACE -> MATTER regardless of city order.
  -- Finale: Saffron Rival superboss (Lv84-88) -> Ancient Shard becomes Azure
  -- Flute -> Indigo Plateau -> Lv100 catch-only Arceus -> creator credit.
  ---------------------------------------------------------------------------
  ;(function()
    if not mod.content.map_scripts then return end

    local MapDef = require("src.world.Map")
    local MapScripts = require("src.script.MapScripts")
    local TextBox = require("src.render.TextBox")
    local Menu = require("src.ui.Menu")
    local BattleState = require("src.battle.BattleState")
    local TrainerAI = require("src.battle.TrainerAI")
    local Bag = require("src.inventory.Bag")

    local FLAGS = {
      opening = "EVENT_ARCEUS_QUEST_OPENING",
      started = "EVENT_ARCEUS_QUEST_STARTED",
      time = "EVENT_ARCEUS_TRIAL_TIME",
      space = "EVENT_ARCEUS_TRIAL_SPACE",
      matter = "EVENT_ARCEUS_TRIAL_MATTER",
      lancePending = "EVENT_ARCEUS_LANCE_INTERCEPT_PENDING",
      saffronReady = "EVENT_ARCEUS_SAFFRON_READY",
      rivalDefeated = "EVENT_ARCEUS_RIVAL_DEFEATED",
      saffronDone = "EVENT_ARCEUS_SAFFRON_VOID_COMPLETE",
      finalPortal = "EVENT_ARCEUS_FINAL_PORTAL_OPEN",
      caught = "EVENT_CAUGHT_MARS_ARCEUS",
      complete = "EVENT_ARCEUS_QUEST_COMPLETE",
      epilogueSeen = "EVENT_ARCEUS_OAK_EPILOGUE_SEEN",
    }

    local PRIOR_QUEST_FLAGS = {
      "EVENT_PALLET_TAUROS_QUEST_COMPLETE",
      "EVENT_ROUTE2_MERCY_QUEST_COMPLETE",
      "EVENT_FROSLASS_QUEST_COMPLETE",
      "EVENT_MOONFALL_COMPLETE",
      "EVENT_ALABASTER_FESTIVAL_COMPLETE",
      "EVENT_ROUTE5_HAPPINY_RECEIVED",
      "EVENT_SS_ANNE_INVESTIGATION_RESOLVED",
      "EVENT_INDIGO_LAST_TEAM_CHARITY_RECEIVED",
      "EVENT_ROCK_TUNNEL_RESCUE_COMPLETE",
      "EVENT_CELADON_MUNCHLAX_COMPLETE",
      "EVENT_CELADON_WOODS_QUEST_COMPLETE",
      "EVENT_MARS_SPIRITOMB_108_COMPLETE",
      "EVENT_CYCLING_ROAD_RACE_BIKE_UPGRADE",
      "EVENT_SAFARI_ACTIVIST_RESOLVED",
      "EVENT_ROLLING_BLACKOUT_COMPLETE",
      "EVENT_SILPH_DAMAGE_CONTROL_COMPLETE",
      "EVENT_CINNABAR_AFTERSHOCK_COMPLETE",
      "EVENT_CELEBI_ECHOES_COMPLETE",
      "EVENT_GUARDIANS_OF_KANTO_COMPLETE",
      "EVENT_CAUGHT_MARS_MEW",
      "EVENT_MARS_MEW_FUJI_EPILOGUE_SEEN",
    }

    local function questAvailable(save)
      local flags = save and save.flags or {}
      if not flags.EVENT_BEAT_CHAMPION_RIVAL then return false end

      for _, flag in ipairs(PRIOR_QUEST_FLAGS) do
        if flag == "EVENT_SS_ANNE_INVESTIGATION_RESOLVED" then
          -- compatibility: old saves may already have a successful or
          -- failed verdict from before the explicit RESOLVED flag existed.
          local ssAnneResolved =
            flags.EVENT_SS_ANNE_INVESTIGATION_RESOLVED
            or flags.EVENT_SS_ANNE_INVESTIGATION_COMPLETE
            or flags.EVENT_SS_ANNE_INVESTIGATION_FAILED
            or flags.EVENT_SS_ANNE_ROCKET_CAUGHT
          if not ssAnneResolved then return false end
        elseif not flags[flag] then
          return false
        end
      end

      return true
    end

    do
      local NPC = require("src.world.NPC")
      local registry = NPC._marsQuestMarkerRegistry
      if registry then
        registry.OAKS_LAB = registry.OAKS_LAB or {}
        registry.OAKS_LAB[#registry.OAKS_LAB + 1] = {
          textId = "TEXT_OAKSLAB_OAK1",
          active = function(save)
            local flags = save and save.flags or {}
            return questAvailable(save)
              and not flags[FLAGS.started]
              and not flags[FLAGS.complete]
          end,
        }
      end
    end

    local function fmt(game, s)
      local player = game and game.save and game.save.player or {}
      local playerName = player.name or "PLAYER"
      local rivalName = player.rival or "BLUE"
      s = tostring(s or "")
      s = s:gsub("{PLAYER}", playerName)
      s = s:gsub("{RIVAL}", rivalName)
      return s
    end

    -- Game Boy dialogue boxes are three lines tall and do not reliably wrap
    -- long mod-authored prose. Wrap every quest page automatically.
    local function wrapDialogue(text, width, linesPerPage)
      width = width or 18
      linesPerPage = linesPerPage or 3
      text = tostring(text or "")

      local outPages = {}
      for rawPage in (text .. "\f"):gmatch("(.-)\f") do
        local words = {}
        for word in rawPage:gsub("\n", " "):gmatch("%S+") do
          words[#words + 1] = word
        end

        local lines = {}
        local line = ""
        for _, word in ipairs(words) do
          if line == "" then
            line = word
          elseif #line + 1 + #word <= width then
            line = line .. " " .. word
          else
            lines[#lines + 1] = line
            line = word
          end
        end
        if line ~= "" then lines[#lines + 1] = line end
        if #lines == 0 then lines[1] = "" end

        local i = 1
        while i <= #lines do
          local pageLines = {}
          for j = i, math.min(#lines, i + linesPerPage - 1) do
            pageLines[#pageLines + 1] = lines[j]
          end
          outPages[#outPages + 1] = table.concat(pageLines, "\n")
          i = i + linesPerPage
        end
      end

      return table.concat(outPages, "\f")
    end

    local function arceusText(id, text)
      mod.content.text:register(id, wrapDialogue(text))
    end

    local function say(game, textIdOrLiteral, done, opts)
      local registered = game.data.text[textIdOrLiteral]
      local text = registered or wrapDialogue(textIdOrLiteral)
      game.stack:push(TextBox.new(game, fmt(game, text), done, opts))
    end

    local function deepCopy(value, seen)
      if type(value) ~= "table" then return value end
      seen = seen or {}
      if seen[value] then return seen[value] end
      local out = {}
      seen[value] = out
      for k, v in pairs(value) do
        out[deepCopy(k, seen)] = deepCopy(v, seen)
      end
      return out
    end

    local function cellKey(x, y)
      return tostring(x) .. ":" .. tostring(y)
    end

    local function occupiedCells(def)
      local used = {}
      for _, obj in ipairs((def and def.objects) or {}) do
        used[cellKey(obj.x, obj.y)] = true
      end
      for _, warp in ipairs((def and def.warps) or {}) do
        used[cellKey(warp.x, warp.y)] = true
      end
      for _, sign in ipairs((def and def.signs) or {}) do
        used[cellKey(sign.x, sign.y)] = true
      end
      return used
    end

    local function isLand(def, tileset, x, y)
      return def
        and tileset
        and x >= 1
        and y >= 1
        and x < (def.width or 1) * 2 - 1
        and y < (def.height or 1) * 2 - 1
        and MapDef.defIsWalkableCell(def, tileset, x, y)
        and not MapDef.defIsWaterCell(def, tileset, x, y)
    end

    local function nearestLand(def, preferredX, preferredY, used, radius)
      local tileset = def and mod.content.tilesets:get(def.tileset)
      used = used or {}
      radius = radius or 24

      for r = 0, radius do
        for dy = -r, r do
          for dx = -r, r do
            if r == 0 or math.max(math.abs(dx), math.abs(dy)) == r then
              local x = preferredX + dx
              local y = preferredY + dy
              local key = cellKey(x, y)
              if not used[key] and isLand(def, tileset, x, y) then
                used[key] = true
                return x, y
              end
            end
          end
        end
      end

      return preferredX, preferredY
    end

    local function adjacentLand(def, x, y, used)
      local candidates = {
        { x, y + 1 }, { x + 1, y }, { x - 1, y }, { x, y - 1 },
      }
      local tileset = def and mod.content.tilesets:get(def.tileset)
      for _, p in ipairs(candidates) do
        local key = cellKey(p[1], p[2])
        if not (used and used[key]) and isLand(def, tileset, p[1], p[2]) then
          if used then used[key] = true end
          return p[1], p[2]
        end
      end
      return nearestLand(def, x, y + 1, used, 10)
    end

    -- City quest actors must land on the same connected outdoor region the
    -- player can actually reach. A merely walkable center tile can sit behind
    -- fences or other disconnected scenery, so seed a flood fill from a real
    -- map warp and constrain placement to that component.
    local function reachableLand(def)
      local tileset = def and mod.content.tilesets:get(def.tileset)
      if not def or not tileset then return nil end

      local seedX, seedY = nil, nil
      for _, warp in ipairs(def.warps or {}) do
        if isLand(def, tileset, warp.x, warp.y) then
          seedX, seedY = warp.x, warp.y
          break
        end
      end

      if not seedX then
        local px = math.floor((def.width or 10))
        local py = math.floor((def.height or 10))
        seedX, seedY = nearestLand(def, px, py, {}, 40)
        if not isLand(def, tileset, seedX, seedY) then return nil end
      end

      local seen = { [cellKey(seedX, seedY)] = true }
      local queue = { { seedX, seedY } }
      local head = 1
      local dirs = { {1,0}, {-1,0}, {0,1}, {0,-1} }

      while head <= #queue do
        local cur = queue[head]
        head = head + 1
        for _, d in ipairs(dirs) do
          local nx, ny = cur[1] + d[1], cur[2] + d[2]
          local key = cellKey(nx, ny)
          if not seen[key] and isLand(def, tileset, nx, ny) then
            seen[key] = true
            queue[#queue + 1] = { nx, ny }
          end
        end
      end

      return seen
    end

    local function nearestReachableLand(def, preferredX, preferredY, used, radius)
      local reach = reachableLand(def)
      if not reach then
        return nearestLand(def, preferredX, preferredY, used, radius)
      end

      used = used or {}
      radius = radius or 30
      for r = 0, radius do
        for dy = -r, r do
          for dx = -r, r do
            if r == 0 or math.max(math.abs(dx), math.abs(dy)) == r then
              local x, y = preferredX + dx, preferredY + dy
              local key = cellKey(x, y)
              if reach[key] and not used[key] then
                used[key] = true
                return x, y
              end
            end
          end
        end
      end

      return nearestLand(def, preferredX, preferredY, used, radius)
    end

    -- Choose a reachable cell well outside the player's normal camera view.
    -- Prefer roughly cardinal approaches so Lance visibly walks in toward the
    -- player instead of materializing nearby after the third wormhole.
    local function distantReachableLand(def, fromX, fromY, used)
      local reach = reachableLand(def)
      if not reach then
        return nearestLand(def, fromX, fromY + 9, used, 30)
      end

      used = used or {}
      local maxX = math.max(1, (def.width or 1) * 2 - 2)
      local maxY = math.max(1, (def.height or 1) * 2 - 2)
      local bestX, bestY = nil, nil
      local bestScore = nil
      local fallbackX, fallbackY = nil, nil
      local fallbackDist = -1

      for y = 1, maxY do
        for x = 1, maxX do
          local key = cellKey(x, y)
          if reach[key] and not used[key] then
            local dx = math.abs(x - fromX)
            local dy = math.abs(y - fromY)
            local dist = math.max(dx, dy)

            if dist > fallbackDist then
              fallbackDist = dist
              fallbackX, fallbackY = x, y
            end

            if dist >= 7 then
              -- Aim for 8-10 cells away, with a mostly straight approach.
              local alignment = math.min(dx, dy)
              local score = math.abs(dist - 9) * 20 + alignment
              if bestScore == nil or score < bestScore then
                bestScore = score
                bestX, bestY = x, y
              end
            end
          end
        end
      end

      local x, y = bestX or fallbackX, bestY or fallbackY
      if x and y then
        used[cellKey(x, y)] = true
        return x, y
      end

      return nearestLand(def, fromX, fromY + 9, used, 30)
    end

    -------------------------------------------------------------------------
    -- CINEMATIC SCREENS
    -------------------------------------------------------------------------

    local function drawCenteredText(text, y)
      love.graphics.setColor(1, 1, 1, 1)
      love.graphics.printf(text, 10, y, 140, "center")
    end

    -- The Saffron void is drawn by a custom screen rather than a normal
    -- TextBox, so it cannot rely on the textbox renderer's wrapping rules.
    -- Measure the active font every frame and scale ONLY this cinematic text
    -- until the complete wrapped page fits inside a hard 132x76 safe area.
    -- This makes the result robust to Faithful Ratio, UI/font scaling, and any
    -- font state inherited from the screen that opened the cinematic.
    local function drawFittedVoidText(text)
      local left, top = 14, 50
      local width, height = 132, 76
      local font = love.graphics.getFont()
      local scale = 1
      local lineCount = 1
      local lineHeight = 8

      if font then
        if font.getHeight then
          lineHeight = font:getHeight()
        end
        if font.getLineHeight then
          lineHeight = lineHeight * font:getLineHeight()
        end

        -- Start at normal size and reduce in small steps only when necessary.
        -- getWrap is evaluated against the width BEFORE scaling so the final
        -- physical result still occupies at most `width` pixels.
        for pct = 100, 45, -5 do
          local candidate = pct / 100
          local wrapWidth = width / candidate
          local wrapped = nil
          if font.getWrap then
            local _, lines = font:getWrap(text, wrapWidth)
            wrapped = lines
          end
          local count = wrapped and #wrapped or 1
          local needed = count * lineHeight * candidate
          scale = candidate
          lineCount = count
          if needed <= height then
            break
          end
        end
      end

      -- Re-measure at the chosen scale so we can vertically center the page.
      local totalHeight = lineCount * lineHeight * scale
      local drawY = top + math.max(0, (height - totalHeight) / 2)

      love.graphics.setColor(1, 1, 1, 1)
      love.graphics.push()
      love.graphics.scale(scale, scale)
      love.graphics.printf(
        text,
        left / scale,
        drawY / scale,
        width / scale,
        "center"
      )
      love.graphics.pop()
    end

    if not mod.content.screens:get("MarsArceusSaffronVoid") then
      mod.content.screens:register("MarsArceusSaffronVoid", {
        new = function(game)
          -- The wormhole is completely silent. Stop Saffron's map music
          -- as soon as the void screen opens, then restart the map theme only
          -- after the player returns to the overworld.
          local Music = require("src.core.Music")
          Music.stop()

          local playerName = (game.save.player and game.save.player.name) or "PLAYER"
          -- Keep each cinematic page deliberately short so it remains
          -- safe under UI/font scaling. Arceus's judgment also respects
          -- the Route 2 mercy outcome instead of praising mercy unconditionally.
          local route2Mercy =
            game.save.flags
            and game.save.flags.EVENT_ROUTE2_ROCKET_MERCY

          local choicePage
          local judgmentPage
          if route2Mercy then
            choicePage =
              "Even those who gave\nyou little reason to\nshow them kindness."
            judgmentPage =
              "You are a TRAINER\ntruly as kind as you\nare powerful."
          else
            choicePage =
              "You faced difficult\nchoices and carried\ntheir consequences."
            judgmentPage =
              "You are a TRAINER\nas resolute as you\nare powerful."
          end

          local pages = {
            playerName .. ".\nYou've come at last.",
            "I've been observing\nevery action you have taken",
            "since the start of\nyour journey.",
            "Again and again,\nyou stepped forward when",
            "POKEMON and people\nneeded someone.",
            "I have seen the paths\nyou chose.",
            choicePage,
            judgmentPage,
            "It is because of this\nthat I have chosen you.",
            "Take this flute and\nplay it where your journey",
            "has reached its\ngreatest height.",
            "There you will find me,\nmy child.",
          }

          -- The Shard becomes the Azure Flute as the gift is first announced.
          local flutePage = 10
          local flashFrames = 48
          local self = {
            game = game,
            isOpaque = true,
            frame = 0,
            pageFrames = 180,
            pages = pages,
            musicRestored = false,
          }

          local shardImage = nil
          local ok, loaded = pcall(
            love.graphics.newImage,
            mod.assets:path("assets/ancient_shard.png")
          )
          if ok and loaded then
            shardImage = loaded
            if shardImage.setFilter then shardImage:setFilter("nearest", "nearest") end
          end

          function self:restoreMusic()
            if self.musicRestored then return end
            self.musicRestored = true
            Music.restoreMap(game.data, "map")
          end

          function self:update(dt)
            self.frame = self.frame + 1
            if self.frame >= self.pageFrames * #self.pages then
              self:restoreMusic()
              game.stack:pop()
            end
          end

          function self:draw()
            love.graphics.setColor(0, 0, 0, 1)
            love.graphics.rectangle("fill", 0, 0, 160, 144)

            local page = math.min(
              #self.pages,
              math.floor(self.frame / self.pageFrames) + 1
            )
            local localFrame = self.frame % self.pageFrames

            -- The Ancient Shard remains visible through the declaration that
            -- the player has been chosen. The next page is the exact moment it
            -- becomes the Azure Flute.
            if page < flutePage then
              if shardImage then
                local iw, ih = shardImage:getDimensions()
                local scale = math.min(16 / iw, 16 / ih)
                love.graphics.setColor(1, 1, 1, 1)
                love.graphics.draw(
                  shardImage,
                  80 - (iw * scale) / 2,
                  34 - (ih * scale) / 2,
                  0,
                  scale,
                  scale
                )
              else
                love.graphics.setColor(1, 1, 1, 1)
                love.graphics.polygon("fill", 80, 26, 86, 34, 80, 42, 74, 34)
              end
            else
              -- Pixel-sized Azure Flute silhouette; no external art required.
              love.graphics.setColor(1, 1, 1, 1)
              love.graphics.rectangle("fill", 68, 31, 24, 3)
              love.graphics.rectangle("fill", 72, 28, 3, 9)
              love.graphics.rectangle("fill", 84, 28, 3, 9)
              love.graphics.rectangle("fill", 91, 30, 5, 5)
            end

            -- Fit and center each page inside the dedicated safe region.
            -- This does not assume a particular active font size.
            drawFittedVoidText(self.pages[page])

            -- The white flash is drawn LAST so it fully covers the shard, flute,
            -- and text at the exact transformation instead of leaving the text
            -- visible over the flash.
            if page == flutePage - 1
               and localFrame > self.pageFrames - flashFrames
            then
              local alpha =
                (localFrame - (self.pageFrames - flashFrames)) / flashFrames
              love.graphics.setColor(1, 1, 1, math.min(1, alpha))
              love.graphics.rectangle("fill", 0, 0, 160, 144)
            elseif page == flutePage and localFrame < flashFrames then
              local alpha = 1 - (localFrame / flashFrames)
              love.graphics.setColor(1, 1, 1, math.max(0, alpha))
              love.graphics.rectangle("fill", 0, 0, 160, 144)
            end

            love.graphics.setColor(1, 1, 1, 1)
          end

          return self
        end,
      })
    end

