    -- AZURE FLUTE / FINAL CAPTURE TUNING
    -------------------------------------------------------------------------

    -- The quest cannot finish until ARCEUS is actually caught. Gen 1's
    -- capture formula makes a catch rate of 3 disproportionately punishing,
    -- so use the same quest-legend rate already established for Celebi/Ho-Oh/
    -- Lugia while leaving the Lv100 battle itself as the ultimate challenge.
    if mod.content.pokemon:get("ARCEUS") then
      mod.content.pokemon:patch("ARCEUS", { catchRate = 45 })
    end

    if not mod.content.items:get("AZURE_FLUTE") then
      mod.content.items:register("AZURE_FLUTE", {
        id = "AZURE_FLUTE",
        name = "AZURE FLUTE",
        price = 0,
        pocket = "KEY_ITEM",
        keyItem = true,
        tossable = false,
        effect = "MARS_AZURE_FLUTE_USE",
        needsTarget = false,
      })
    end

    local FINAL_PORTAL_NAME = "MARS_ARCEUS_INDIGO_PORTAL"

    mod.content.item_effects:register("MARS_AZURE_FLUTE_USE", {
      field = true,
      battle = false,
      needsTarget = false,

      use = function(ctx)
        local game = ctx and ctx.game
        local ow = (ctx and (ctx.overworld or ctx.ow))
          or (game and game.overworld)
        local save = (ctx and ctx.save) or (game and game.save)
        local map = ow and ow.map
        local flags = save and save.flags or {}

        if not map or map.id ~= "INDIGO_PLATEAU" then
          return "failed", { "The AZURE FLUTE\nmakes no sound." }
        end

        if flags[FLAGS.caught] then
          return "failed", { "The AZURE FLUTE\nis silent." }
        end

        if flags[FLAGS.finalPortal] then
          return "failed", { "A wormhole is\nalready open." }
        end

        flags[FLAGS.finalPortal] = true
        local Sound = require("src.core.Sound")
        pcall(Sound.play, ctx.data, "Pokeflute")
        if ow then
          ow:queueScript({
            { "show_object", "INDIGO_PLATEAU", FINAL_PORTAL_NAME },
          })
        end

        -- Successful Key Item use: keep the flute and let the normal Bag flow
        -- display the resonance text. The portal is visible once the player
        -- closes the Bag and returns to the Plateau.
        return "kept", { "The AZURE FLUTE\nbegan to resonate!" }
      end,
    })

