    local function playerTrialCount(flags)
      local n = 0
      if flags[FLAGS.time] then n = n + 1 end
      if flags[FLAGS.space] then n = n + 1 end
      if flags[FLAGS.matter] then n = n + 1 end
      return n
    end

    local function rivalRank(flags, targetSpec)
      local rank = 0
      for _, spec in ipairs(citySpecs) do
        if not flags[spec.assign] then
          rank = rank + 1
          if spec == targetSpec then return rank end
        end
      end
      return nil
    end

    local function clearActiveCity(flags)
      for _, spec in ipairs(citySpecs) do flags[spec.active] = nil end
    end

    local function activeCity(flags)
      for _, spec in ipairs(citySpecs) do
        if flags[spec.active] then return spec end
      end
      return nil
    end

