    -------------------------------------------------------------------------
    -- TRIAL MAPS
    -------------------------------------------------------------------------

    local function bfs(def, startX, startY)
      local tileset = mod.content.tilesets:get(def.tileset)
      local queue = { { startX, startY } }
      local head = 1
      local dist = { [cellKey(startX, startY)] = 0 }
      local prev = {}
      local farX, farY, farDist = startX, startY, 0
      local dirs = { {1,0}, {-1,0}, {0,1}, {0,-1} }

      while head <= #queue do
        local node = queue[head]
        head = head + 1
        local x, y = node[1], node[2]
        local d = dist[cellKey(x, y)] or 0
        if d > farDist then
          farDist, farX, farY = d, x, y
        end

        for _, dir in ipairs(dirs) do
          local nx, ny = x + dir[1], y + dir[2]
          local key = cellKey(nx, ny)
          if dist[key] == nil and isLand(def, tileset, nx, ny) then
            dist[key] = d + 1
            prev[key] = { x, y }
            queue[#queue + 1] = { nx, ny }
          end
        end
      end

      return farX, farY, dist, prev
    end

